class DomainRuntimeFailure(RuntimeError):
    def __init__(self, payload: Mapping[str, Any]):
        self.payload = dict(payload)
        super().__init__(str(self.payload.get("error") or "VibeScript domain failure."))


def _failure(
    tool_name: str,
    code: str,
    stage: str,
    message: str,
    **details: Any,
) -> dict[str, Any]:
    return tool_failure(
        tool_name,
        code,
        stage,
        message,
        requested=dict(details.pop("requested", {}) or {}),
        observed=dict(details.pop("observed", {}) or {}),
        **details,
    )


def _raise(
    tool_name: str,
    code: str,
    stage: str,
    message: str,
    **details: Any,
) -> None:
    raise DomainRuntimeFailure(_failure(tool_name, code, stage, message, **details))


def _atomic_json(path: Path, payload: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
    try:
        temporary.write_text(
            json.dumps(
                dict(payload),
                ensure_ascii=True,
                sort_keys=True,
                separators=(",", ":"),
                allow_nan=False,
            ),
            encoding="utf-8",
        )
        temporary.replace(path)
    finally:
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass


def _read_json(path: Path, label: str) -> dict[str, Any]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise ValueError(f"Could not read {label} at {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise ValueError(f"{label} at {path} must contain one JSON object.")
    return value


def _stage_worker_bundle(
    module_root: Path, staging: Path, domain: str
) -> tuple[str, ...]:
    """Copy only the isolated runner and the active domain's declared modules."""

    clean_domain = str(domain or "").strip().lower()
    domain_files = _DOMAIN_WORKER_BUNDLES.get(clean_domain)
    if domain_files is None:
        raise ValueError(
            f"VibeScript domain {clean_domain!r} has no isolated worker bundle."
        )
    filenames = (
        "vibescript_domain_api.py",
        "vibescript_worker_progress.py",
        *domain_files,
    )
    if len(filenames) != len(set(filenames)):
        raise RuntimeError(
            f"VibeScript domain {clean_domain!r} has duplicate worker dependencies."
        )
    copied = ("worker.py", *filenames)
    sources = ("vibescript_domain_worker.py", *filenames)
    for source_name, target_name in zip(sources, copied, strict=True):
        source = module_root / source_name
        if source.parent != module_root or not source.is_file():
            raise RuntimeError(
                f"Required VibeScript worker dependency {source_name!r} is missing."
            )
        shutil.copyfile(source, staging / target_name)
    return copied


def parse_domain_tool(
    tool_name: str,
) -> tuple[contracts.VibeScriptWorkbenchPack, str] | None:
    name = str(tool_name or "")
    parts = name.split(".")
    if len(parts) != 3 or parts[0] != "vibescript":
        return None
    domain, operation = parts[1:]
    if operation not in contracts.LIFECYCLE_OPERATIONS:
        return None
    pack = next(
        (
            candidate
            for candidate in contracts.VIBESCRIPT_WORKBENCH_PACKS.values()
            if candidate.domain == domain
        ),
        None,
    )
    return (pack, operation) if pack is not None else None


def _program_directory(project_root: str | Path, domain: str, program_id: str) -> Path:
    root = Path(project_root) / "vibescript"
    canonical = root / domain / program_id
    if canonical.exists() or domain != "partdesign":
        return canonical
    v1_directory = root / program_id
    return v1_directory if v1_directory.is_dir() else canonical


def _manifest_path(project_root: str | Path, domain: str, program_id: str) -> Path:
    return _program_directory(project_root, domain, program_id) / "program.json"


def _program_directories(project_root: str | Path, domain: str) -> list[Path]:
    root = Path(project_root) / "vibescript"
    canonical_root = root / domain
    result = (
        [
            path
            for path in canonical_root.iterdir()
            if path.is_dir() and _PROGRAM_ID.fullmatch(path.name)
        ]
        if canonical_root.is_dir()
        else []
    )
    if domain == "partdesign" and root.is_dir():
        result.extend(
            path
            for path in root.iterdir()
            if path.is_dir() and _PROGRAM_ID.fullmatch(path.name) and path not in result
        )
    return result


def _load_manifest(
    project_root: str | Path,
    pack: contracts.VibeScriptWorkbenchPack,
    program_id: str,
) -> dict[str, Any]:
    path = _manifest_path(project_root, pack.domain, program_id)
    if not path.is_file() and pack.domain == "partdesign":
        v1_path = path.parent / "manifest.json"
        if v1_path.is_file():
            path = v1_path
    if not path.is_file():
        raise FileNotFoundError(
            f"No {pack.title} VibeScript program has id {program_id}."
        )
    manifest = contracts.migrate_program_manifest(
        _read_json(path, "VibeScript program manifest"),
        artifact_directory=path.parent,
    )
    if str(manifest.get("program_id") or "") != program_id:
        raise ValueError(f"Program manifest id does not match directory {program_id}.")
    if str(manifest.get("domain") or "") != pack.domain:
        raise ValueError(
            f"Program {program_id} belongs to domain {manifest.get('domain')!r}, "
            f"not {pack.domain!r}."
        )
    return manifest


def _load_captured_manifest(
    captured: Mapping[str, Any],
    pack: contracts.VibeScriptWorkbenchPack,
    program_id: str,
    *,
    hydrate_document_contract: bool = False,
) -> dict[str, Any]:
    """Prefer a compatible working artifact, falling back to the FCStd contract."""

    document_program = captured.get("document_program")
    portable_manifest: dict[str, Any] | None = None
    portable_error: Exception | None = None
    if isinstance(document_program, Mapping):
        raw = str(document_program.get("contract") or "")
        if raw:
            live = next(
                (
                    item
                    for item in list(captured.get("live_programs") or [])
                    if str(item.get("program_id") or "") == program_id
                ),
                None,
            )
            revisions = (
                list(live.get("revisions") or []) if isinstance(live, Mapping) else []
            )
            expected_revision = str(revisions[0]) if len(revisions) == 1 else ""
            try:
                portable_manifest = contracts.decode_document_program_contract(
                    raw,
                    pack,
                    expected_program_id=program_id,
                    expected_revision=expected_revision,
                )
            except Exception as exc:
                portable_error = exc

    artifact_manifest: dict[str, Any] | None = None
    artifact_error: Exception | None = None
    try:
        artifact_manifest = _load_manifest(
            captured["project_root"],
            pack,
            program_id,
        )
    except Exception as exc:
        artifact_error = exc

    use_portable = bool(
        portable_manifest is not None
        and (
            artifact_manifest is None
            or str(artifact_manifest.get("accepted_revision") or "")
            != str(portable_manifest.get("accepted_revision") or "")
        )
    )
    if use_portable:
        manifest = dict(portable_manifest or {})
        if hydrate_document_contract:
            _atomic_json(
                _manifest_path(captured["project_root"], pack.domain, program_id),
                manifest,
            )
        return manifest
    if artifact_manifest is not None:
        return artifact_manifest
    if portable_manifest is not None:
        return portable_manifest
    if portable_error is not None:
        raise portable_error
    assert artifact_error is not None
    raise artifact_error


def _assembly_live_output_state(obj: Any) -> dict[str, Any]:
    """Capture bounded accepted evidence used by source inspection."""

    output_type = str(getattr(obj, "VibeCADVibeScriptOutputType", "") or "")
    property_names = {
        "joint": ("VibeCADAssemblyJointValidation",),
        "motion": ("VibeCADAssemblyMotionValidation",),
        "simulation": (
            "VibeCADAssemblySimulationValidation",
            "VibeCADSimulationTracePreview",
        ),
        "exploded_view": ("VibeCADAssemblyExplodedViewValidation",),
        "bom": ("VibeCADAssemblyBOMValidation",),
        "solver_diagnostics": ("VibeCADSolverDiagnostics",),
    }.get(output_type, ())
    result: dict[str, Any] = {"output_type": output_type} if output_type else {}
    accepted: dict[str, Any] = {}
    for property_name in property_names:
        raw = str(getattr(obj, property_name, "") or "")
        if not raw:
            continue
        encoded_bytes = len(raw.encode("utf-8", errors="replace"))
        key = (
            "trace_preview"
            if property_name == "VibeCADSimulationTracePreview"
            else "validation"
        )
        if encoded_bytes > 64 * 1024:
            accepted[key] = {
                "omitted": True,
                "json_bytes": encoded_bytes,
                "reason": "Accepted live evidence exceeds the 64 KiB inspection bound.",
            }
            continue
        try:
            accepted[key] = json.loads(raw)
        except (TypeError, ValueError) as exc:
            accepted[f"{key}_error"] = f"{type(exc).__name__}: {exc}"
    if accepted:
        result["accepted_state"] = accepted
    return result


def _live_programs(doc: Any, domain: str) -> list[dict[str, Any]]:
    programs: dict[str, dict[str, Any]] = {}
    design_history: dict[str, dict[str, list[dict[str, str]]]] = {}
    if domain == "partdesign":
        for obj in list(getattr(doc, "Objects", []) or []):
            if str(getattr(obj, "VibeCADScriptedRole", "") or "") != "implementation":
                continue
            program_id = str(getattr(obj, "VibeCADScriptedModelId", "") or "")
            if not program_id:
                continue
            type_id = str(getattr(obj, "TypeId", "") or "")
            if type_id == "PartDesign::DesignScriptOperation":
                kind = "operations"
            elif type_id == "PartDesign::Body":
                kind = "bodies"
            else:
                continue
            design_history.setdefault(
                program_id,
                {"operations": [], "bodies": []},
            )[kind].append(
                {
                    "object_name": str(getattr(obj, "Name", "") or ""),
                    "label": str(getattr(obj, "Label", "") or ""),
                    "type_id": type_id,
                    "output_name": str(
                        getattr(obj, "VibeCADScriptedOutputKey", "") or ""
                    ),
                }
            )
    for obj in list(getattr(doc, "Objects", []) or []):
        properties = set(getattr(obj, "PropertiesList", []) or [])
        if not {contracts.PROP_PROGRAM_ID, contracts.PROP_PROGRAM_DOMAIN} <= properties:
            continue
        if str(getattr(obj, contracts.PROP_PROGRAM_DOMAIN, "") or "") != domain:
            continue
        program_id = str(getattr(obj, contracts.PROP_PROGRAM_ID, "") or "")
        if not program_id:
            continue
        item = programs.setdefault(
            program_id,
            {
                "program_id": program_id,
                "label": str(getattr(obj, contracts.PROP_PROGRAM_LABEL, "") or ""),
                "revisions": set(),
                "outputs": [],
            },
        )
        if not item["label"]:
            item["label"] = str(getattr(obj, contracts.PROP_PROGRAM_LABEL, "") or "")
        revision = str(getattr(obj, contracts.PROP_PROGRAM_REVISION, "") or "")
        if revision:
            item["revisions"].add(revision)
        output = {
            "name": str(getattr(obj, contracts.PROP_PROGRAM_OUTPUT, "") or ""),
            "object_name": str(getattr(obj, "Name", "") or ""),
            "label": str(getattr(obj, "Label", "") or ""),
            "type_id": str(getattr(obj, "TypeId", "") or ""),
            "derived_state": str(getattr(obj, "VibeCADDerivedState", "") or ""),
            "stale_reason": str(getattr(obj, "VibeCADStaleReason", "") or ""),
            "source_revision": str(getattr(obj, "VibeCADSourceRevision", "") or ""),
            "internal": str(getattr(obj, "VibeCADTimelineRole", "") or "")
            == "internal",
        }
        if domain == "assembly":
            output.update(_assembly_live_output_state(obj))
        item["outputs"].append(output)
    result: list[dict[str, Any]] = []
    for program_id in sorted(programs):
        item = programs[program_id]
        item["revisions"] = sorted(item["revisions"])
        item["outputs"] = sorted(item["outputs"], key=lambda output: output["name"])
        if domain == "partdesign":
            history = design_history.get(
                program_id,
                {"operations": [], "bodies": []},
            )
            operations = sorted(
                history["operations"],
                key=lambda operation: operation["object_name"],
            )
            bodies = sorted(
                history["bodies"],
                key=lambda body: (
                    body["output_name"],
                    body["object_name"],
                ),
            )
            body_labels = {
                body["output_name"]: body["label"]
                for body in bodies
                if body["output_name"] and body["label"]
            }
            for output in item["outputs"]:
                authored_label = body_labels.get(str(output.get("name") or ""))
                if authored_label:
                    # Part Design publishes a hidden stable App::Link beside
                    # the visible native Body. FreeCAD may suffix that link's
                    # duplicate label with "001"; source inspection describes
                    # the authored Body, not the hidden carrier.
                    output["label"] = authored_label
            item["native_history"] = {
                "available": len(operations) == 1,
                "strategy": "design_program_operation",
                "operation_count": len(operations),
                "operation": operations[0] if len(operations) == 1 else None,
                "body_count": len(bodies),
                "bodies": bodies,
            }
        result.append(item)
    return result


def _document_objects(doc: Any) -> list[dict[str, str]]:
    return [
        {
            "name": str(getattr(obj, "Name", "") or ""),
            "label": str(getattr(obj, "Label", "") or ""),
            "type_id": str(getattr(obj, "TypeId", "") or ""),
        }
        for obj in list(getattr(doc, "Objects", []) or [])[:10_000]
    ]


def _material_target_snapshots(doc: Any) -> list[dict[str, Any]]:
    """Capture bounded target capabilities without catalog or artifact access."""

    document_uid = str(getattr(doc, "Uid", "") or "")
    snapshots: list[dict[str, Any]] = []
    for obj in list(getattr(doc, "Objects", []) or [])[:10_000]:
        physical_supported = hasattr(obj, "ShapeMaterial")
        view = getattr(obj, "ViewObject", None)
        supported: list[str] = []
        if view is not None:
            if hasattr(view, "ShapeColor") and hasattr(view, "ShapeAppearance"):
                supported.append("ShapeAppearance")
            for name in (
                "LineColor",
                "PointColor",
                "LineWidth",
                "PointSize",
                "DisplayMode",
                "Visibility",
                "Selectable",
            ):
                if hasattr(view, name):
                    supported.append(name)
        if not physical_supported and not supported:
            continue
        display_modes: list[str] = []
        if view is not None and "DisplayMode" in supported:
            getter = getattr(view, "getEnumerationsOfProperty", None)
            if callable(getter):
                try:
                    display_modes = [
                        str(value) for value in list(getter("DisplayMode") or [])
                    ]
                except Exception:
                    display_modes = []
        material = getattr(obj, "ShapeMaterial", None) if physical_supported else None
        snapshots.append(
            {
                "reference": {
                    "document_uid": document_uid,
                    "object_name": str(getattr(obj, "Name", "") or ""),
                },
                "label": str(getattr(obj, "Label", "") or ""),
                "type_id": str(getattr(obj, "TypeId", "") or ""),
                "physical_assignment_supported": physical_supported,
                "current_material": (
                    {
                        "uuid": str(getattr(material, "UUID", "") or ""),
                        "name": str(getattr(material, "Name", "") or ""),
                    }
                    if material is not None
                    else None
                ),
                "appearance_supported_properties": sorted(set(supported)),
                "display_modes": display_modes[:128],
                "display_modes_truncated": len(display_modes) > 128,
                "managed_material_output": str(
                    getattr(obj, contracts.PROP_PROGRAM_DOMAIN, "") or ""
                )
                == "material",
            }
        )
    return snapshots


def capture_operation_state(
    service: Any,
    tool_name: str,
    arguments: Mapping[str, Any],
) -> dict[str, Any]:
    """Capture document-affine state without artifact I/O or geometry work."""

    parsed = parse_domain_tool(tool_name)
    if parsed is None:
        _raise(tool_name, "UNKNOWN_DOMAIN_TOOL", "surface", "Unknown domain tool.")
    pack, operation = parsed
    doc = service._active_document()
    if operation != "describe_api" and doc is None:
        _raise(tool_name, "NO_DOCUMENT", "precondition", "No active FreeCAD document.")
    from VibeCADModelingSurface import resolve_service_surface

    resolution = resolve_service_surface(service, service.active_workbench_name())
    if (
        resolution.engine != "vibescript"
        or resolution.workbench != pack.workbench
        or resolution.domain != pack.domain
        or not resolution.available
    ):
        _raise(
            tool_name,
            "DOMAIN_SURFACE_CHANGED",
            "surface",
            "The active workbench no longer authorizes this API.",
            observed=resolution.summary(),
        )
    scope = service.project_scope_snapshot()
    from VibeCADPreferences import load_settings

    settings = load_settings()
    timeout = float(getattr(settings, "scripted_timeout_seconds", 0.0) or 0.0)
    memory_mb = int(getattr(settings, "scripted_memory_limit_mb", 0) or 0)
    if timeout <= 0.0 or memory_mb <= 0:
        _raise(
            tool_name,
            "INVALID_SCRIPTED_BUDGET",
            "precondition",
            "VibeScript requires positive worker timeout and memory limits.",
            observed={"timeout_seconds": timeout, "memory_limit_mb": memory_mb},
        )
    try:
        import FreeCAD as App

        freecad_home = str(App.getHomePath())
    except Exception as exc:
        _raise(
            tool_name,
            "FREECAD_UNAVAILABLE",
            "precondition",
            f"FreeCAD is unavailable: {exc}",
        )
    live = _live_programs(doc, pack.domain) if doc is not None else []
    target_program_id = str(arguments.get("program_id") or "").strip().lower()
    document_program = (
        contracts.capture_document_program_payload(
            doc,
            pack.domain,
            target_program_id,
        )
        if doc is not None and target_program_id
        else {}
    )
    for item in live:
        if len(item["revisions"]) > 1:
            _raise(
                tool_name,
                "LIVE_PROGRAM_REVISION_SPLIT",
                "precondition",
                f"Live outputs for program {item['program_id']} have different revisions.",
                observed=item,
            )
    return {
        "tool_name": tool_name,
        "operation": operation,
        "arguments": dict(arguments),
        "pack": pack,
        "project_root": str(scope.get("root") or ""),
        "project_id": str(scope.get("project_id") or ""),
        "document_name": str(getattr(doc, "Name", "") or ""),
        "document_uid": str(getattr(doc, "Uid", "") or ""),
        "document_revision": (
            str(service.provider_document_revision()) if doc is not None else ""
        ),
        "document_objects": _document_objects(doc) if doc is not None else [],
        "material_targets": (
            _material_target_snapshots(doc)
            if doc is not None and pack.domain == "material"
            else []
        ),
        "live_programs": live,
        "document_program": document_program,
        "surface": resolution.summary(),
        "freecad_home": freecad_home,
        "timeout_seconds": timeout,
        "memory_limit_bytes": memory_mb * 1024 * 1024,
    }


def _validate_stable_references(
    value: Any, captured: Mapping[str, Any], path: str
) -> None:
    if isinstance(value, list):
        for index, item in enumerate(value):
            _validate_stable_references(item, captured, f"{path}[{index}]")
        return
    if not isinstance(value, dict):
        return
    if not is_document_reference(value):
        for key, item in value.items():
            _validate_stable_references(item, captured, f"{path}.{key}")
        return
    try:
        clean = normalize_document_reference(value)
    except DocumentReferenceError as exc:
        raise ValueError(f"{path} has an invalid stable reference: {exc}") from exc
    document_uid = clean["document_uid"]
    object_name = clean["object_name"]
    domain = str(getattr(captured.get("pack"), "domain", "") or "")
    if domain in {"partdesign", "assembly", "robot"} and document_uid != str(
        captured.get("document_uid") or ""
    ):
        # External identities are authenticated on the document thread during
        # capture. A portable path may load the saved source document there.
        # These are the three domains whose capture path deliberately supports
        # reusable component definitions without copying their topology.
        return
    if document_uid != str(captured.get("document_uid") or ""):
        raise ValueError(f"{path} refers to a different document uid.")
    names = {str(item.get("name") or "") for item in captured["document_objects"]}
    if object_name not in names:
        raise ValueError(f"{path} refers to missing object {object_name!r}.")


def _merge_patch(base: Mapping[str, Any], patch: Any) -> dict[str, Any]:
    if not isinstance(patch, dict) or not patch:
        raise ValueError("patch must be a non-empty object.")
    result = dict(base)
    for key, value in patch.items():
        if value is None:
            result.pop(str(key), None)
        else:
            result[str(key)] = value
    return result


def _partdesign_saved_source_compatibility_methods(source: str) -> frozenset[str]:
    """Find retired calls eligible only when replaying an unchanged saved source."""

    tree = ast.parse(
        str(source or ""),
        filename="<vibecad-partdesign-vibescript>",
        mode="exec",
    )
    compatibility: set[str] = set()
    for node in ast.walk(tree):
        if (
            isinstance(node, ast.Attribute)
            and isinstance(node.value, ast.Name)
            and node.value.id == "api"
            and node.attr in _PARTDESIGN_SAVED_SOURCE_COMPATIBILITY_METHODS
        ):
            compatibility.add(node.attr)
        if (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Attribute)
            and isinstance(node.func.value, ast.Name)
            and node.func.value.id == "api"
            and node.func.attr == "loft"
            and any(keyword.arg == "subtractive" for keyword in node.keywords)
        ):
            compatibility.add(_PARTDESIGN_LOFT_SUBTRACTIVE_COMPATIBILITY)
    return frozenset(compatibility)


def _freecadcmd(freecad_home: str) -> Path:
    names = (
        ("FreeCADCmd.exe", "freecadcmd.exe")
        if sys.platform == "win32"
        else (
            "FreeCADCmd",
            "freecadcmd",
        )
    )
    for name in names:
        path = Path(freecad_home) / "bin" / name
        if path.is_file():
            return path
    raise FileNotFoundError(
        f"No windowless FreeCADCmd executable exists under {freecad_home!r}."
    )


def _new_manifest(
    pack: contracts.VibeScriptWorkbenchPack,
    program_id: str,
    label: str,
) -> dict[str, Any]:
    return {
        "schema": contracts.PROGRAM_SCHEMA,
        "version": contracts.PROGRAM_VERSION,
        "program_id": program_id,
        "domain": pack.domain,
        "workbench": pack.workbench,
        "label": label,
        "source": "",
        "input_schema": {},
        "inputs": {},
        "expected_outputs": [],
        "working_revision": "",
        "accepted_revision": "",
        "accepted_contract": None,
        "live_outputs": {},
        "latest_candidate": None,
        "created_at": time.time(),
    }


def _input_references(value: Any) -> list[dict[str, str]]:
    """Return unique stable references in deterministic input traversal order."""

    result: list[dict[str, str]] = []
    indexes: dict[tuple[str, str], int] = {}

    def walk(item: Any) -> None:
        if isinstance(item, list):
            for child in item:
                walk(child)
            return
        if not isinstance(item, dict):
            return
        if is_document_reference(item):
            reference = normalize_document_reference(item)
            key = (reference["document_uid"], reference["object_name"])
            existing_index = indexes.get(key)
            if existing_index is None:
                indexes[key] = len(result)
                result.append(reference)
                return
            existing = result[existing_index]
            existing_path = existing.get("document_path")
            incoming_path = reference.get("document_path")
            if existing_path and incoming_path and existing_path != incoming_path:
                raise ValueError(
                    f"Document object {key[1]!r} in {key[0]!r} is referenced with "
                    "conflicting document_path locators."
                )
            if not existing_path and incoming_path:
                existing["document_path"] = incoming_path
            return
        for child in item.values():
            walk(child)

    walk(value)
    if len(result) > _MAX_REFERENCE_SHAPES:
        raise ValueError(
            f"A program may reference at most {_MAX_REFERENCE_SHAPES} document objects."
        )
    return result


def _partdesign_reference_capture_mode(
    source: str,
    expected_outputs: Sequence[Mapping[str, Any]],
) -> str:
    """Choose exact identity capture only for pure linked-occurrence programs."""

    if not expected_outputs or any(
        str(output.get("type") or "") != "component_link"
        for output in expected_outputs
    ):
        return "geometry"
    tree = ast.parse(
        str(source or ""),
        filename="<vibecad-partdesign-vibescript>",
        mode="exec",
    )
    api_members = {
        node.attr
        for node in ast.walk(tree)
        if isinstance(node, ast.Attribute)
        and isinstance(node.value, ast.Name)
        and node.value.id == "api"
    }
    if api_members and api_members <= {"component", "instances"}:
        # These APIs publish native App::Link occurrences. Their exact source
        # object identity is the contract; they neither read nor copy source
        # topology. Any geometry-reading API keeps the full BREP path.
        return "component_identity"
    return "geometry"


def _input_point_artifacts(value: Any) -> list[str]:
    """Return unique approved point artifact ids in input traversal order."""

    result: list[str] = []
    seen: set[str] = set()

    def walk(item: Any) -> None:
        if isinstance(item, list):
            for child in item:
                walk(child)
            return
        if not isinstance(item, dict):
            return
        if set(item) == {"artifact_id"}:
            artifact_id = item.get("artifact_id")
            if not isinstance(artifact_id, str) or not _PROGRAM_ID.fullmatch(
                artifact_id
            ):
                raise ValueError(
                    "Point artifact references require one 32-character lowercase "
                    "hexadecimal artifact_id."
                )
            if artifact_id not in seen:
                seen.add(artifact_id)
                result.append(artifact_id)
            return
        for child in item.values():
            walk(child)

    walk(value)
    if len(result) > 64:
        raise ValueError(
            "A Points program may reference at most 64 approved artifacts."
        )
    return result


def _stage_point_artifacts(
    project_root: Path,
    staging: Path,
    artifact_ids: Sequence[str],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Copy approved cloud inputs into candidate-local authenticated staging."""

    if not artifact_ids:
        return [], []
    from VibeCADPointArtifacts import resolve_point_artifacts

    resolved = resolve_point_artifacts(project_root, artifact_ids)
    artifact_root = staging / "point-artifacts"
    artifact_root.mkdir(parents=True, exist_ok=False)
    worker_entries = []
    revision_entries = []
    total_bytes = 0
    for index, entry in enumerate(resolved):
        source = Path(str(entry["path"]))
        original_format = str(entry["format"])
        worker_format = "asc" if original_format == "xyz" else original_format
        relative = Path("point-artifacts") / (f"artifact-{index:03d}.{worker_format}")
        target = staging / relative
        shutil.copyfile(source, target)
        size_bytes = target.stat().st_size
        total_bytes += size_bytes
        if total_bytes > _MAX_REFERENCE_BREP_BYTES:
            raise ValueError(
                "Approved point artifacts exceed the 256 MiB candidate input limit."
            )
        digest = _sha256_file(target)
        if size_bytes != int(entry["size_bytes"]) or digest != str(entry["sha256"]):
            raise ValueError(
                f"Approved point artifact {entry['artifact_id']!r} changed while staging."
            )
        worker_entries.append(
            {
                "artifact_id": str(entry["artifact_id"]),
                "name": str(entry["name"]),
                "label": str(entry["label"]),
                "format": original_format,
                "worker_format": worker_format,
                "artifact_path": str(relative),
                "artifact_bytes": size_bytes,
                "artifact_sha256": digest,
            }
        )
        revision_entries.append(
            {
                "reference_kind": "point_artifact",
                "artifact_id": str(entry["artifact_id"]),
                "name": str(entry["name"]),
                "label": str(entry["label"]),
                "format": original_format,
                "artifact_bytes": size_bytes,
                "artifact_sha256": digest,
            }
        )
    return worker_entries, revision_entries


def abandon_prepared_candidate(prepared: Mapping[str, Any]) -> None:
    """Remove unpublished staging for a candidate that could not be finalized."""

    staging = Path(str(prepared.get("staging") or ""))
    if staging.name and staging.parent.name == ".staging" and staging.is_dir():
        shutil.rmtree(staging)


def _assembly_reference_contract(service: Any, obj: Any) -> dict[str, Any]:
    """Capture bounded identity/semantic metadata without traversing geometry."""

    import VibeCADReferenceContracts as reference_contracts
    import VibeCADScriptedPublication as scripted_publication

    properties = set(getattr(obj, "PropertiesList", []) or [])
    program_id = str(getattr(obj, contracts.PROP_PROGRAM_ID, "") or "")
    program_domain = str(getattr(obj, contracts.PROP_PROGRAM_DOMAIN, "") or "")
    published = reference_contracts.published_object(obj)
    source_kind = "shape"
    if bool(
        getattr(obj, "isDerivedFrom", lambda _type: False)("Assembly::AssemblyObject")
    ):
        source_kind = "assembly"
    elif str(getattr(obj, "TypeId", "") or "") == "PartDesign::Body":
        source_kind = "partdesign_body"
    elif bool(
        getattr(obj, "isDerivedFrom", lambda _type: False)("App::Part")
    ) and not bool(getattr(obj, "isDerivedFrom", lambda _type: False)("Part::Feature")):
        source_kind = "part"
    elif program_id:
        source_kind = f"vibescript_{program_domain or 'output'}"
    elif published is not None:
        source_kind = "scripted_publication"
    transient_topology = bool(program_id or published is not None)
    semantic_only = published is not None
    interfaces: dict[str, Any] = {}
    source_revision = ""
    if published is not None:
        source_revision = str(
            getattr(published, scripted_publication.PROP_REVISION, "") or ""
        )
        try:
            root = scripted_publication.model_root_for(published)
            raw_interfaces = json.loads(
                str(getattr(root, scripted_publication.PROP_INTERFACES, "{}") or "{}")
            )
        except (scripted_publication.PublicationError, ValueError) as exc:
            raise RuntimeError(
                f"Scripted component {getattr(obj, 'Name', '')!r} has invalid "
                f"published-interface metadata: {exc}"
            ) from exc
        if not isinstance(raw_interfaces, dict):
            raise RuntimeError(
                f"Scripted component {getattr(obj, 'Name', '')!r} has a non-object "
                "published-interface table."
            )
        output_key = str(
            getattr(published, scripted_publication.PROP_OUTPUT_KEY, "") or ""
        )
        definitions = reference_contracts.interface_definitions_for_output(
            raw_interfaces,
            output_key,
        )
        names = list(definitions)
        if len(names) > 64:
            raise RuntimeError(
                f"Scripted component {getattr(obj, 'Name', '')!r} exposes more than "
                "64 published interfaces."
            )
        for name in sorted(names):
            try:
                resolved = reference_contracts.resolve_interface(service, obj, name)
            except reference_contracts.ReferenceContractError as exc:
                raise RuntimeError(
                    f"Published interface {name!r} on component "
                    f"{getattr(obj, 'Name', '')!r} is invalid: {exc}"
                ) from exc
            interfaces[name] = {
                "model_id": str(resolved.get("model_id") or ""),
                "publication_name": str(resolved.get("publication_name") or ""),
                "output_key": str(resolved.get("output_key") or ""),
                "selection": dict(resolved.get("selection") or {}),
                "subelements": list(resolved.get("subelements") or []),
                "geometry": list(resolved.get("geometry") or []),
                "connector_frame": dict(resolved.get("connector_frame") or {}),
                **(
                    {"connector": dict(resolved["connector"])}
                    if isinstance(resolved.get("connector"), Mapping)
                    else {}
                ),
            }
    else:
        native_definitions = reference_contracts.native_interface_definitions(obj)
        semantic_only = bool(native_definitions)
        for name, definition in sorted(native_definitions.items()):
            resolved = dict(definition.get("resolved") or {})
            interfaces[str(name)] = {
                "model_id": "",
                "publication_name": str(getattr(obj, "Name", "") or ""),
                "output_key": str(getattr(obj, "Name", "") or ""),
                "selection": dict(definition.get("selection") or {}),
                "subelements": list(resolved.get("subelements") or []),
                "geometry": list(resolved.get("geometry") or []),
                "connector_frame": dict(resolved.get("connector_frame") or {}),
                "connector": dict(definition.get("connector") or {}),
                "native_lcs": str(
                    dict(definition.get("selection") or {}).get("native_lcs") or ""
                ),
            }
    if published is None and program_id:
        source_revision = str(getattr(obj, contracts.PROP_PROGRAM_REVISION, "") or "")
    return {
        "source_kind": source_kind,
        "source_program_id": program_id
        if contracts.PROP_PROGRAM_ID in properties
        else "",
        "source_program_domain": program_domain,
        "source_revision": source_revision,
        "transient_topology": transient_topology,
        "requires_semantic_interfaces": semantic_only,
        "published_interfaces": interfaces,
    }


def capture_reference_inputs(
    service: Any, prepared: Mapping[str, Any]
) -> list[dict[str, Any]]:
    """Copy validated shape or mesh inputs on the document thread.

    No BREP/BMS serialization, artifact I/O, geometry generation, or solver work
    is performed here. The detached kernels are serialized and validated by the
    background lifecycle after this callback returns.
    """

    requirements = list(prepared.get("reference_requirements") or [])
    if not requirements:
        return []
    domain = prepared["pack"].domain
    if domain not in {
        "partdesign",
        "part",
        "assembly",
        "sketcher",
        "draft",
        "surface",
        "mesh",
        "meshpart",
        "points",
        "reverse_engineering",
        "inspection",
        "fem",
        "cam",
        "techdraw",
        "robot",
    }:
        return []
    from VibeCADModelingSurface import resolve_service_surface

    live = resolve_service_surface(service, service.active_workbench_name())
    expected = prepared["surface"]
    if (live.workbench, live.engine, live.surface_id) != (
        str(expected.get("workbench") or ""),
        str(expected.get("engine") or ""),
        str(expected.get("surface_id") or ""),
    ):
        raise RuntimeError("The active workbench changed before reference capture.")
    doc = service._active_document()
    if doc is None or str(getattr(doc, "Name", "") or "") != prepared["document_name"]:
        raise RuntimeError("The active document changed before reference capture.")
    if str(getattr(doc, "Uid", "") or "") != prepared["document_uid"]:
        raise RuntimeError(
            "The active document identity changed before reference capture."
        )
    if str(service.provider_document_revision()) != prepared["document_revision"]:
        raise RuntimeError(
            "The document changed before reference capture; retry on live state."
        )
    snapshots: list[dict[str, Any]] = []
    for index, reference in enumerate(requirements):
        object_name = str(reference["object_name"])
        if domain in {"partdesign", "assembly", "robot"}:
            try:
                obj = resolve_reference_target(
                    doc,
                    reference,
                    f"{prepared['pack'].title} input reference {object_name!r}",
                )
            except DocumentReferenceError as exc:
                raise RuntimeError(str(exc)) from exc
        else:
            obj = doc.getObject(object_name)
        if obj is None:
            raise RuntimeError(
                f"{prepared['pack'].title} input reference {object_name!r} "
                "disappeared before capture."
            )
        if domain in {"partdesign", "assembly", "robot"} and getattr(
            obj, "Document", None
        ) is not doc:
            if not str(getattr(doc, "FileName", "") or "").strip():
                raise RuntimeError(
                    f"External {prepared['pack'].title} components require the active document "
                    "to be saved before building."
                )
            if not str(
                getattr(getattr(obj, "Document", None), "FileName", "") or ""
            ).strip():
                raise RuntimeError(
                    f"External component {object_name!r} belongs to an "
                    "unsaved source document."
                )
        if domain in {
            "partdesign",
            "assembly",
            "draft",
            "surface",
            "mesh",
            "meshpart",
            "points",
            "reverse_engineering",
            "inspection",
            "fem",
            "cam",
            "techdraw",
            "robot",
        } and str(getattr(obj, contracts.PROP_PROGRAM_ID, "") or "") == str(
            prepared.get("program_id") or ""
        ):
            raise RuntimeError(
                f"{prepared['pack'].title} input reference {object_name!r} is an "
                "output of the same program and would create a cyclic dependency."
            )
        if domain == "assembly":
            owner_resolver = getattr(service, "_partdesign_body_for_feature", None)
            owner = owner_resolver(obj) if callable(owner_resolver) else None
            if owner is not None and owner is not obj:
                raise RuntimeError(
                    f"Assembly input reference {object_name!r} is a feature inside "
                    f"Part Design Body {getattr(owner, 'Name', '')!r}; reference the "
                    "Body itself as the standalone component."
                )
            if str(getattr(obj, "TypeId", "") or "") == "App::Link":
                import VibeCADReferenceContracts as reference_contracts

                managed_occurrence = (
                    str(getattr(obj, contracts.PROP_PROGRAM_DOMAIN, "") or "")
                    in {"partdesign", "robot"}
                    and str(
                        getattr(obj, "VibeCADVibeScriptOutputType", "") or ""
                    )
                    == "component_link"
                    and bool(
                        str(getattr(obj, contracts.PROP_PROGRAM_ID, "") or "")
                    )
                )
                if (
                    reference_contracts.published_object(obj) is None
                    and not managed_occurrence
                ):
                    target = getattr(obj, "LinkedObject", None)
                    raise RuntimeError(
                        f"Assembly input reference {object_name!r} is a generic App::Link. "
                        "Reference its exact LinkedObject instead so the program owns one "
                        f"unambiguous occurrence (suggested object: "
                        f"{getattr(target, 'Name', '<missing>')!r})."
                    )
        type_id = str(getattr(obj, "TypeId", "") or "")
        try:
            is_points_object = bool(obj.isDerivedFrom("Points::Feature"))
        except Exception:
            is_points_object = type_id.startswith("Points::")
        if domain == "points" or (
            domain in {"reverse_engineering", "inspection"} and is_points_object
        ):
            try:
                is_points = bool(obj.isDerivedFrom("Points::Feature"))
            except Exception:
                is_points = type_id.startswith("Points::")
            if not is_points or not hasattr(obj, "Points"):
                raise RuntimeError(
                    f"Points input reference {object_name!r} ({type_id}) is not a "
                    "native Points::Feature."
                )
            kernel = obj.Points
            point_count = int(getattr(kernel, "CountPoints", 0) or 0)
            if not 1 <= point_count <= _MAX_REFERENCE_POINTS:
                raise RuntimeError(
                    f"Points input reference {object_name!r} contains {point_count} "
                    f"points; the accepted range is 1-{_MAX_REFERENCE_POINTS}."
                )
            try:
                detached_points = kernel.copy()
            except Exception as exc:
                raise RuntimeError(
                    f"Could not detach Points from input reference {object_name!r}: {exc}"
                ) from exc
            attributes = {}
            for property_name, key_name in (
                ("Color", "colors"),
                ("Intensity", "intensities"),
                ("Normal", "normals"),
            ):
                if not hasattr(obj, property_name):
                    continue
                values = list(getattr(obj, property_name) or [])
                if values and len(values) != point_count:
                    raise RuntimeError(
                        f"Points input reference {object_name!r} property "
                        f"{property_name!r} has {len(values)} values for "
                        f"{point_count} points."
                    )
                if not values:
                    continue
                if key_name == "colors":
                    attributes[key_name] = [
                        tuple(float(component) for component in value)
                        for value in values
                    ]
                elif key_name == "normals":
                    attributes[key_name] = [
                        (float(value.x), float(value.y), float(value.z))
                        for value in values
                    ]
                else:
                    attributes[key_name] = [float(value) for value in values]
            width = int(getattr(obj, "Width", 0) or 0)
            height = int(getattr(obj, "Height", 0) or 0)
            structured = (
                {"width": width, "height": height}
                if width > 0 and height > 0 and width * height == point_count
                else None
            )
            reference_contract = _assembly_reference_contract(service, obj)
            snapshots.append(
                {
                    **dict(reference),
                    "label": str(getattr(obj, "Label", "") or ""),
                    "type_id": type_id,
                    "reference_artifact_kind": "points_asc",
                    "detached_points": detached_points,
                    "point_attributes": attributes,
                    "structured": structured,
                    "snapshot_index": index,
                    **reference_contract,
                }
            )
            continue
        if domain in {
            "mesh",
            "meshpart",
            "reverse_engineering",
            "inspection",
        } and type_id.startswith("Mesh::"):
            mesh = getattr(obj, "Mesh", None)
            if mesh is None:
                raise RuntimeError(
                    f"{prepared['pack'].title} input reference {object_name!r} "
                    f"({type_id}) does not "
                    "expose a native Mesh."
                )
            facet_count = int(getattr(mesh, "CountFacets", 0) or 0)
            if facet_count <= 0:
                raise RuntimeError(
                    f"{prepared['pack'].title} input reference {object_name!r} "
                    "has no mesh facets."
                )
            try:
                detached_mesh = mesh.copy()
            except Exception as exc:
                raise RuntimeError(
                    f"Could not detach Mesh from {prepared['pack'].title} input reference "
                    f"{object_name!r}: {exc}"
                ) from exc
            segment_count = int(detached_mesh.countSegments())
            if segment_count > _MAX_REFERENCE_MESH_SEGMENTS:
                raise RuntimeError(
                    f"{prepared['pack'].title} input reference {object_name!r} "
                    f"has {segment_count} "
                    f"segments; the limit is {_MAX_REFERENCE_MESH_SEGMENTS}."
                )
            mesh_segments = [
                [int(item) for item in list(detached_mesh.getSegment(index) or [])]
                for index in range(segment_count)
            ]
            segment_memberships = sum(len(segment) for segment in mesh_segments)
            if segment_memberships > max(facet_count * 4, facet_count + 1024):
                raise RuntimeError(
                    f"{prepared['pack'].title} input reference {object_name!r} "
                    "has excessive segment "
                    "membership data."
                )
            mesh_contract = _assembly_reference_contract(service, obj)
            snapshots.append(
                {
                    **dict(reference),
                    "label": str(getattr(obj, "Label", "") or ""),
                    "type_id": type_id,
                    "reference_artifact_kind": "mesh_bms",
                    "detached_mesh": detached_mesh,
                    "mesh_segments": mesh_segments,
                    "snapshot_index": index,
                    **mesh_contract,
                }
            )
            continue
        if domain == "reverse_engineering":
            raise RuntimeError(
                f"Reverse Engineering input reference {object_name!r} ({type_id}) "
                "must be a native Points::Feature or Mesh::Feature."
            )
        shape = getattr(obj, "Shape", None)
        if shape is None:
            raise RuntimeError(
                f"{prepared['pack'].title} input reference {object_name!r} "
                f"({getattr(obj, 'TypeId', '')}) "
                "does not expose a Shape."
            )
        if bool(shape.isNull()):
            raise RuntimeError(
                f"{prepared['pack'].title} input reference {object_name!r} has a null Shape."
            )
        shape_capture_object = obj
        shape_placement_matrix = None
        linked_object = getattr(obj, "LinkedObject", None)
        linked_shape = getattr(linked_object, "Shape", None)
        if linked_shape is not None:
            try:
                if not bool(linked_shape.isNull()):
                    # isPartner is OCCT's exact shared-TShape test: unlike isSame,
                    # it deliberately ignores only top-level Location and
                    # Orientation. Matching Orientation then proves that this
                    # App::Link is its linked definition under exactly the native
                    # Shape placement returned by FreeCAD. Stage the definition
                    # once and replace its placement in the worker for each
                    # occurrence. No geometric fingerprint or tolerance decides
                    # whether definitions may be shared.
                    if bool(shape.isPartner(linked_shape)) and (
                        str(getattr(shape, "Orientation", ""))
                        == str(getattr(linked_shape, "Orientation", ""))
                    ):
                        shape_capture_object = linked_object
                        shape_placement_matrix = _placement_matrix_values(
                            shape.Placement
                        )
            except Exception:
                shape_capture_object = obj
                shape_placement_matrix = None
        if prepared.get("reference_capture_mode") == "component_identity":
            reference_contract = _assembly_reference_contract(service, obj)
            snapshots.append(
                {
                    **dict(reference),
                    "label": str(getattr(obj, "Label", "") or ""),
                    "type_id": type_id,
                    "shape_type": str(getattr(shape, "ShapeType", "") or ""),
                    "reference_artifact_kind": "component_identity",
                    "snapshot_index": index,
                    **reference_contract,
                }
            )
            continue
        cache_token = ""
        cached_artifact = None
        artifact_store = None
        capture_cached = getattr(service, "capture_vibescript_reference_shape", None)
        try:
            if callable(capture_cached):
                cached = capture_cached(shape_capture_object)
                detached = cached["detached_shape"]
                cache_token = str(cached.get("cache_token") or "")
                cached_artifact = cached.get("artifact")
                artifact_store = getattr(
                    service, "store_vibescript_reference_artifact", None
                )
            else:
                detached = shape.copy()
        except Exception as exc:
            raise RuntimeError(
                f"Could not detach Shape from {prepared['pack'].title} input "
                f"reference {object_name!r}: {exc}"
            ) from exc
        assembly_contract = (
            _assembly_reference_contract(service, obj)
            if domain
            in {
                "partdesign",
                "assembly",
                "sketcher",
                "surface",
                "mesh",
                "meshpart",
                "points",
                "reverse_engineering",
                "inspection",
                "fem",
                "cam",
                "techdraw",
                "robot",
            }
            else {}
        )
        if domain == "assembly":
            from VibeCADAssemblyHierarchy import capture_bom_identity

            assembly_contract.update(capture_bom_identity(obj))
        assembly_hierarchy = None
        if domain == "assembly" and assembly_contract.get("source_kind") in {
            "assembly",
            "part",
        }:
            from VibeCADAssemblyHierarchy import capture_assembly_hierarchy

            assembly_hierarchy = capture_assembly_hierarchy(
                obj,
                detach_shapes=True,
                leaf_contract=lambda source: _assembly_reference_contract(
                    service, source
                ),
            )
        snapshots.append(
            {
                **dict(reference),
                "label": str(getattr(obj, "Label", "") or ""),
                "type_id": str(getattr(obj, "TypeId", "") or ""),
                "shape_type": str(getattr(shape, "ShapeType", "") or ""),
                "reference_artifact_kind": "brep",
                "detached_shape": detached,
                "snapshot_index": index,
                **(
                    {"_reference_shape_placement_matrix": shape_placement_matrix}
                    if shape_placement_matrix is not None
                    else {}
                ),
                **(
                    {
                        "_reference_cache_token": cache_token,
                        "_reference_cached_artifact": cached_artifact,
                        "_reference_artifact_store": artifact_store,
                    }
                    if cache_token
                    else {}
                ),
                **(
                    {"assembly_hierarchy": assembly_hierarchy}
                    if assembly_hierarchy is not None
                    else {}
                ),
                **assembly_contract,
            }
        )
    if str(service.provider_document_revision()) != prepared["document_revision"]:
        raise RuntimeError(
            "The document changed during reference capture; retry on live state."
        )
    return snapshots


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _finalize_assembly_hierarchy(
    hierarchy: Mapping[str, Any],
    *,
    staging: Path,
    reference_index: int,
) -> tuple[dict[str, Any], int]:
    """Serialize detached hierarchy shapes away from the document thread."""

    from VibeCADAssemblyHierarchy import ASSEMBLY_HIERARCHY_SCHEMA
    from vibescript_part_worker import part_shape_facts

    if str(hierarchy.get("schema") or "") != ASSEMBLY_HIERARCHY_SCHEMA:
        raise ValueError("An Assembly source hierarchy has an unsupported schema.")
    raw_nodes = hierarchy.get("nodes")
    detached_shapes = hierarchy.get("_detached_shapes")
    if not isinstance(raw_nodes, list) or not isinstance(detached_shapes, dict):
        raise ValueError("An Assembly source hierarchy snapshot is malformed.")
    nodes = [dict(node) for node in raw_nodes]
    node_ids = [str(node.get("node_id") or "") for node in nodes]
    if not node_ids or len(node_ids) != len(set(node_ids)):
        raise ValueError("An Assembly source hierarchy has invalid node identities.")
    unexpected_shapes = set(str(key) for key in detached_shapes) - set(node_ids)
    if unexpected_shapes:
        raise ValueError(
            "An Assembly source hierarchy contains detached shapes for unknown nodes."
        )
    relative_root = Path("references") / f"reference-{reference_index:03d}-hierarchy"
    target_root = staging / relative_root
    if detached_shapes:
        target_root.mkdir(parents=True, exist_ok=False)
    total_bytes = 0
    for node in nodes:
        node_id = str(node["node_id"])
        shape = detached_shapes.get(node_id)
        expected = bool(node.pop("has_shape_artifact", False))
        if expected is not (shape is not None):
            raise ValueError(
                f"Assembly hierarchy node {node_id!r} changed its detached-shape state."
            )
        if shape is None:
            continue
        if bool(shape.isNull()) or not bool(shape.isValid()):
            raise ValueError(
                f"Assembly hierarchy node {node_id!r} has an invalid detached Shape."
            )
        relative = relative_root / f"{node_id}.brep"
        target = staging / relative
        shape.exportBrep(str(target))
        if not target.is_file() or target.stat().st_size <= 0:
            raise RuntimeError(
                f"Could not serialize Assembly hierarchy node {node_id!r} as BREP."
            )
        artifact_bytes = int(target.stat().st_size)
        total_bytes += artifact_bytes
        digest = _sha256_file(target)
        node["shape_artifact"] = {
            "artifact_path": str(relative),
            "artifact_sha256": digest,
            "artifact_bytes": artifact_bytes,
            "shape_type": str(getattr(shape, "ShapeType", "") or ""),
            "facts": part_shape_facts(
                shape,
                max_subelements=_MAX_REFERENCE_FACT_SUBELEMENTS,
            ),
        }
    descriptor = {
        key: value
        for key, value in hierarchy.items()
        if key not in {"nodes", "_detached_shapes"}
    }
    descriptor["nodes"] = nodes
    encoded = json.dumps(
        descriptor,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    if len(encoded) > _MAX_ASSEMBLY_HIERARCHY_JSON_BYTES:
        raise ValueError(
            "The authenticated Assembly source hierarchy exceeds the 8 MiB metadata limit. "
            "Remove unrelated scalar properties or split the source into smaller modules."
        )
    return descriptor, total_bytes


def finalize_candidate(
    prepared: dict[str, Any],
    snapshots: list[dict[str, Any]],
) -> dict[str, Any]:
    """Stage detached inputs, bind the revision, and persist the working candidate."""

    if prepared.get("finalized"):
        return prepared
    requirements = list(prepared.get("reference_requirements") or [])
    if len(snapshots) != len(requirements):
        abandon_prepared_candidate(prepared)
        raise ValueError(
            f"Reference capture returned {len(snapshots)} shapes; expected {len(requirements)}."
        )
    by_key = {
        (str(item.get("document_uid") or ""), str(item.get("object_name") or "")): item
        for item in snapshots
    }
    if len(by_key) != len(snapshots):
        abandon_prepared_candidate(prepared)
        raise ValueError("Reference capture returned duplicate object identities.")
    staging = Path(str(prepared["staging"]))
    worker_references: list[dict[str, Any]] = []
    resolved_references: list[dict[str, Any]] = list(
        prepared.get("resolved_point_artifacts") or []
    )
    total_bytes = 0
    staged_breps_by_cache_token: dict[str, dict[str, Any]] = {}
    try:
        if requirements:
            reference_root = staging / "references"
            reference_root.mkdir(parents=True, exist_ok=False)
            for index, requirement in enumerate(requirements):
                key = (
                    str(requirement["document_uid"]),
                    str(requirement["object_name"]),
                )
                snapshot = by_key.get(key)
                if snapshot is None:
                    raise ValueError(
                        f"Reference capture omitted document object {key[1]!r}."
                    )
                hierarchy_descriptor = None
                if snapshot.get("assembly_hierarchy") is not None:
                    hierarchy_descriptor, hierarchy_bytes = (
                        _finalize_assembly_hierarchy(
                            snapshot["assembly_hierarchy"],
                            staging=staging,
                            reference_index=index,
                        )
                    )
                    total_bytes += hierarchy_bytes
                    if total_bytes > _MAX_REFERENCE_BREP_BYTES:
                        raise ValueError(
                            "Referenced Assembly hierarchy artifacts exceed the 256 MiB "
                            "detached-input limit."
                        )
                reference_contract = {
                    name: snapshot.get(name)
                    for name in (
                        "source_kind",
                        "source_program_id",
                        "source_program_domain",
                        "source_revision",
                        "transient_topology",
                        "requires_semantic_interfaces",
                        "published_interfaces",
                        "document_file_name",
                        "bom_properties",
                    )
                    if snapshot.get(name) not in (None, "", {}, [])
                }
                if hierarchy_descriptor is not None:
                    reference_contract["assembly_hierarchy"] = hierarchy_descriptor
                reference_contract_sha256 = ""
                if reference_contract:
                    reference_contract_sha256 = hashlib.sha256(
                        json.dumps(
                            reference_contract,
                            ensure_ascii=True,
                            sort_keys=True,
                            separators=(",", ":"),
                            allow_nan=False,
                        ).encode("utf-8")
                    ).hexdigest()
                artifact_kind = str(snapshot.get("reference_artifact_kind") or "brep")
                if artifact_kind == "component_identity":
                    if prepared["pack"].domain != "partdesign":
                        raise ValueError(
                            f"Referenced object {key[1]!r} produced a component "
                            f"identity for domain {prepared['pack'].domain!r}."
                        )
                    metadata = {
                        "document_uid": key[0],
                        "object_name": key[1],
                        "label": str(snapshot.get("label") or ""),
                        "type_id": str(snapshot.get("type_id") or ""),
                        "shape_type": str(snapshot.get("shape_type") or ""),
                        "artifact_kind": "component_identity",
                        **reference_contract,
                    }
                    worker_reference = dict(metadata)
                elif artifact_kind == "points_asc":
                    if prepared["pack"].domain not in {
                        "points",
                        "reverse_engineering",
                        "inspection",
                    }:
                        raise ValueError(
                            f"Referenced object {key[1]!r} produced a Points snapshot "
                            f"for domain {prepared['pack'].domain!r}."
                        )
                    kernel = snapshot.get("detached_points")
                    if (
                        kernel is None
                        or not 1 <= int(kernel.CountPoints) <= _MAX_REFERENCE_POINTS
                    ):
                        raise ValueError(
                            f"Referenced object {key[1]!r} did not produce a valid "
                            "detached point cloud."
                        )
                    from vibescript_points_worker import (
                        bake_point_reference,
                        point_facts,
                        write_point_attribute_artifacts,
                    )

                    baked, point_attributes, structured = bake_point_reference(
                        kernel,
                        dict(snapshot.get("point_attributes") or {}),
                        snapshot.get("structured"),
                    )
                    relative = Path("references") / f"reference-{index:03d}.asc"
                    target = staging / relative
                    baked.write(str(target))
                    if not target.is_file() or target.stat().st_size <= 0:
                        raise RuntimeError(
                            f"Could not serialize referenced object {key[1]!r} as Points ASCII."
                        )
                    coordinate_bytes = target.stat().st_size
                    total_bytes += coordinate_bytes
                    descriptors = write_point_attribute_artifacts(
                        staging,
                        f"reference-{index:03d}",
                        point_attributes,
                        point_count=int(baked.CountPoints),
                        relative_directory="references",
                    )
                    total_bytes += sum(
                        int(item["artifact_bytes"]) for item in descriptors
                    )
                    if total_bytes > _MAX_REFERENCE_BREP_BYTES:
                        raise ValueError(
                            "Referenced point artifacts exceed the 256 MiB "
                            "detached-input limit."
                        )
                    digest = _sha256_file(target)
                    facts = point_facts(
                        baked,
                        attributes=point_attributes,
                        structured=structured,
                    )
                    metadata = {
                        "document_uid": key[0],
                        "object_name": key[1],
                        "label": str(snapshot.get("label") or ""),
                        "type_id": str(snapshot.get("type_id") or ""),
                        "artifact_kind": "points_asc",
                        "artifact_sha256": digest,
                        "artifact_bytes": coordinate_bytes,
                        "attribute_artifacts": descriptors,
                        "structured": structured,
                        "facts": facts,
                        **reference_contract,
                    }
                    worker_reference = {
                        "document_uid": key[0],
                        "object_name": key[1],
                        "label": metadata["label"],
                        "type_id": metadata["type_id"],
                        "artifact_kind": "points_asc",
                        "artifact_path": str(relative),
                        "artifact_sha256": digest,
                        "attribute_artifacts": descriptors,
                        "structured": structured,
                        "facts": facts,
                        **reference_contract,
                    }
                elif artifact_kind == "mesh_bms":
                    if prepared["pack"].domain not in {
                        "mesh",
                        "meshpart",
                        "reverse_engineering",
                        "inspection",
                    }:
                        raise ValueError(
                            f"Referenced object {key[1]!r} produced a Mesh snapshot "
                            f"for domain {prepared['pack'].domain!r}."
                        )
                    mesh = snapshot.get("detached_mesh")
                    if mesh is None or int(mesh.CountFacets) <= 0:
                        raise ValueError(
                            f"Referenced object {key[1]!r} did not produce a valid "
                            "detached Mesh."
                        )
                    import FreeCAD as App
                    from vibescript_mesh_worker import mesh_diagnostics

                    detached_mesh = mesh.copy()
                    placement = detached_mesh.Placement
                    placement_matrix = placement.toMatrix()
                    detached_mesh.transform(placement_matrix)
                    detached_mesh.Placement = App.Placement()
                    relative = Path("references") / f"reference-{index:03d}.bms"
                    target = staging / relative
                    detached_mesh.write(str(target))
                    if not target.is_file() or target.stat().st_size <= 0:
                        raise RuntimeError(
                            f"Could not serialize referenced object {key[1]!r} as BMS."
                        )
                    total_bytes += target.stat().st_size
                    if total_bytes > _MAX_REFERENCE_BREP_BYTES:
                        raise ValueError(
                            "Referenced BREP/mesh artifacts exceed the 256 MiB "
                            "detached-input limit."
                        )
                    digest = _sha256_file(target)
                    facts = mesh_diagnostics(detached_mesh)
                    segments = [
                        [int(item) for item in list(segment)]
                        for segment in list(snapshot.get("mesh_segments") or [])
                    ]
                    matrix_values = [
                        float(getattr(placement_matrix, name))
                        for name in (
                            "A11",
                            "A12",
                            "A13",
                            "A14",
                            "A21",
                            "A22",
                            "A23",
                            "A24",
                            "A31",
                            "A32",
                            "A33",
                            "A34",
                            "A41",
                            "A42",
                            "A43",
                            "A44",
                        )
                    ]
                    metadata = {
                        "document_uid": key[0],
                        "object_name": key[1],
                        "label": str(snapshot.get("label") or ""),
                        "type_id": str(snapshot.get("type_id") or ""),
                        "artifact_kind": "mesh_bms",
                        "mesh_sha256": digest,
                        "mesh_bytes": int(target.stat().st_size),
                        "mesh_segments": segments,
                        "mesh_source_placement_matrix": matrix_values,
                        "facts": facts,
                        **reference_contract,
                    }
                    worker_reference = {
                        "document_uid": key[0],
                        "object_name": key[1],
                        "artifact_kind": "mesh_bms",
                        "mesh_sha256": digest,
                        "artifact_path": str(relative),
                        "label": metadata["label"],
                        "type_id": metadata["type_id"],
                        "mesh_segments": segments,
                        "mesh_source_placement_matrix": matrix_values,
                        "facts": facts,
                        **reference_contract,
                    }
                elif artifact_kind == "brep":
                    from vibescript_part_worker import (
                        part_shape_facts,
                        part_shape_reference_facts,
                    )

                    shape = snapshot.get("detached_shape")
                    if shape is None or shape.isNull():
                        raise ValueError(
                            f"Referenced object {key[1]!r} did not produce a valid "
                            "detached Shape."
                        )
                    shape_type = str(getattr(shape, "ShapeType", "") or "")
                    cache_token = str(
                        snapshot.get("_reference_cache_token") or ""
                    )
                    staged = (
                        staged_breps_by_cache_token.get(cache_token)
                        if cache_token
                        else None
                    )
                    if staged is not None:
                        if staged["shape_type"] != shape_type:
                            raise ValueError(
                                f"Referenced object {key[1]!r} changed the shape "
                                "behind its shared cache identity."
                            )
                        relative = Path(str(staged["artifact_path"]))
                        target = staging / relative
                        digest = str(staged["brep_sha256"])
                        facts = dict(staged["facts"])
                        brep_bytes = int(staged["brep_bytes"])
                    else:
                        # Assembly's isolated worker authenticates and validates
                        # every staged BREP before it can solve or publish. Do
                        # not run the same expensive OCCT validity traversal on
                        # the GUI-side snapshot first, especially for imported
                        # STEP definitions with thousands of surfaces.
                        if (
                            prepared["pack"].domain != "assembly"
                            and not shape.isValid()
                        ):
                            raise ValueError(
                                f"Referenced object {key[1]!r} did not produce a "
                                "valid detached Shape."
                            )
                        relative = (
                            Path("references") / f"reference-{index:03d}.brep"
                        )
                        target = staging / relative
                        cached_artifact = snapshot.get(
                            "_reference_cached_artifact"
                        )
                        cached_bytes = (
                            cached_artifact.get("brep_bytes")
                            if isinstance(cached_artifact, Mapping)
                            else None
                        )
                        cached_facts = (
                            cached_artifact.get("facts")
                            if isinstance(cached_artifact, Mapping)
                            else None
                        )
                        cached_digest = (
                            str(cached_artifact.get("brep_sha256") or "")
                            if isinstance(cached_artifact, Mapping)
                            else ""
                        )
                        cached_shape_type = (
                            str(cached_artifact.get("shape_type") or "")
                            if isinstance(cached_artifact, Mapping)
                            else ""
                        )
                        cached_facts_profile = (
                            str(cached_artifact.get("facts_profile") or "full")
                            if isinstance(cached_artifact, Mapping)
                            else ""
                        )
                        reuse_artifact = (
                            isinstance(cached_bytes, bytes)
                            and bool(cached_bytes)
                            and len(cached_digest) == 64
                            and cached_shape_type == shape_type
                            and cached_artifact.get("includes_triangulation")
                            is False
                        )
                        if reuse_artifact:
                            target.write_bytes(cached_bytes)
                        else:
                            shape.exportBrep(str(target))
                        if not target.is_file() or target.stat().st_size <= 0:
                            raise RuntimeError(
                                f"Could not serialize referenced object {key[1]!r} "
                                "as BREP."
                            )
                        brep_bytes = int(target.stat().st_size)
                        total_bytes += brep_bytes
                        if total_bytes > _MAX_REFERENCE_BREP_BYTES:
                            raise ValueError(
                                "Referenced shapes exceed the 256 MiB "
                                "detached-input limit."
                            )
                        digest = (
                            cached_digest
                            if reuse_artifact
                            else _sha256_file(target)
                        )
                        reusable_full_facts = (
                            isinstance(cached_facts, Mapping)
                            and cached_facts_profile == "full"
                        )
                        if prepared["pack"].domain == "assembly":
                            facts = part_shape_reference_facts(
                                shape,
                                assume_valid=True,
                            )
                            facts_profile = "assembly_reference"
                        elif reuse_artifact and reusable_full_facts:
                            facts = dict(cached_facts)
                            facts_profile = "full"
                        else:
                            facts = part_shape_facts(
                                shape,
                                max_subelements=_MAX_REFERENCE_FACT_SUBELEMENTS,
                                assume_valid=True,
                            )
                            facts_profile = "full"
                        artifact_store = snapshot.get(
                            "_reference_artifact_store"
                        )
                        should_store = (
                            not reuse_artifact
                            or (
                                facts_profile == "full"
                                and not reusable_full_facts
                            )
                        )
                        if callable(artifact_store) and cache_token and should_store:
                            artifact_store(
                                cache_token,
                                {
                                    "brep_bytes": (
                                        cached_bytes
                                        if reuse_artifact
                                        else target.read_bytes()
                                    ),
                                    "brep_sha256": digest,
                                    "shape_type": shape_type,
                                    "facts": dict(facts),
                                    "facts_profile": facts_profile,
                                    "includes_triangulation": False,
                                },
                            )
                        if cache_token:
                            staged_breps_by_cache_token[cache_token] = {
                                "artifact_path": str(relative),
                                "brep_sha256": digest,
                                "brep_bytes": brep_bytes,
                                "shape_type": shape_type,
                                "facts": dict(facts),
                            }
                    metadata = {
                        "document_uid": key[0],
                        "object_name": key[1],
                        "label": str(snapshot.get("label") or ""),
                        "type_id": str(snapshot.get("type_id") or ""),
                        "shape_type": shape_type,
                        "brep_sha256": digest,
                        "brep_bytes": brep_bytes,
                        "facts": facts,
                        **(
                            {
                                "shape_placement_matrix": list(
                                    snapshot["_reference_shape_placement_matrix"]
                                )
                            }
                            if "_reference_shape_placement_matrix" in snapshot
                            else {}
                        ),
                        **reference_contract,
                    }
                    if prepared["pack"].domain in {
                        "meshpart",
                        "inspection",
                        "fem",
                        "cam",
                        "techdraw",
                    }:
                        metadata["artifact_kind"] = "brep"
                    worker_reference = {
                        "document_uid": key[0],
                        "object_name": key[1],
                        "shape_type": metadata["shape_type"],
                        "brep_sha256": digest,
                        "artifact_path": str(relative),
                        "label": metadata["label"],
                        "type_id": metadata["type_id"],
                        "facts": facts,
                        **(
                            {
                                "shape_placement_matrix": list(
                                    snapshot["_reference_shape_placement_matrix"]
                                )
                            }
                            if "_reference_shape_placement_matrix" in snapshot
                            else {}
                        ),
                        **reference_contract,
                    }
                    if prepared["pack"].domain in {
                        "meshpart",
                        "inspection",
                        "fem",
                        "cam",
                        "techdraw",
                    }:
                        worker_reference["artifact_kind"] = "brep"
                else:
                    raise ValueError(
                        f"Reference capture returned unsupported artifact kind "
                        f"{artifact_kind!r}."
                    )
                if snapshot.get("document_path"):
                    metadata["document_path"] = str(snapshot["document_path"])
                    worker_reference["document_path"] = str(snapshot["document_path"])
                if reference_contract_sha256:
                    metadata["reference_contract_sha256"] = reference_contract_sha256
                resolved_references.append(metadata)
                worker_references.append(worker_reference)
        contract_revision = str(prepared["contract_revision"])
        revision = (
            contracts.program_revision_with_references(
                contract_revision=contract_revision,
                references=resolved_references,
            )
            if resolved_references
            else contract_revision
        )
        if (
            prepared["base_revision"]
            and revision == prepared["base_revision"]
            and not prepared.get("native_history_repair_required")
            and not prepared.get("allow_unchanged_revision")
        ):
            _raise(
                str(prepared["tool_name"]),
                "PROGRAM_REVISION_UNCHANGED",
                "precondition",
                "The requested update and all referenced document shapes match the "
                "existing working revision.",
                observed={"current_revision": revision},
            )
        document_program_contract = contracts.encode_document_program_contract(
            prepared["pack"],
            program_id=str(prepared["program_id"]),
            label=str(prepared["program_name"]),
            revision=revision,
            source=str(prepared["source"]),
            input_schema=prepared["input_schema"],
            inputs=prepared["inputs"],
            expected_outputs=prepared["expected_outputs"],
        )
        request = dict(prepared["worker_request"])
        request["revision"] = revision
        request["document_references"] = worker_references
        _atomic_json(staging / "request.json", request)
        candidate = {
            "attempt_id": str(prepared["attempt_id"]),
            "revision": revision,
            "base_revision": str(prepared["base_revision"]),
            "status": "prepared",
            "created_at": time.time(),
        }
        if resolved_references:
            candidate["resolved_references"] = resolved_references
        manifest = dict(prepared["manifest"])
        manifest.update(
            {
                "source": prepared["source"],
                "input_schema": prepared["input_schema"],
                "inputs": prepared["inputs"],
                "expected_outputs": prepared["expected_outputs"],
                "working_revision": revision,
                "latest_candidate": candidate,
                "updated_at": time.time(),
            }
        )
        _atomic_json(
            Path(str(prepared["program_directory"])) / "program.json", manifest
        )
        prepared.update(
            {
                "revision": revision,
                "resolved_references": resolved_references,
                "manifest": manifest,
                "worker_request": request,
                "document_program_contract": document_program_contract,
                "finalized": True,
            }
        )
        return prepared
    except Exception:
        if not prepared.get("finalized"):
            abandon_prepared_candidate(prepared)
        raise


def prepare_candidate(captured: Mapping[str, Any]) -> dict[str, Any]:
    """Validate and stage one candidate away from the document thread."""

    pack: contracts.VibeScriptWorkbenchPack = captured["pack"]
    operation = str(captured["operation"])
    tool_name = str(captured["tool_name"])
    arguments = dict(captured["arguments"])
    project_root = Path(str(captured["project_root"]))
    staging: Path | None = None
    try:
        if operation == "create_program":
            label = str(arguments.get("program_name") or "").strip()
            if not _PROGRAM_NAME.fullmatch(label):
                raise ValueError(
                    "program_name must start with a letter and contain at most 120 "
                    "letters, numbers, spaces, dots, underscores, or hyphens."
                )
            for directory in _program_directories(project_root, pack.domain):
                for path in (directory / "program.json", directory / "manifest.json"):
                    if not path.is_file():
                        continue
                    try:
                        other = contracts.migrate_program_manifest(
                            _read_json(path, "VibeScript program manifest"),
                            artifact_directory=directory,
                        )
                    except ValueError:
                        continue
                    if str(other.get("label") or "") == label:
                        raise ValueError(
                            f"A {pack.title} VibeScript program named {label!r} already exists."
                        )
            if any(
                str(item.get("label") or "") == label
                for item in list(captured.get("live_programs") or [])
                if isinstance(item, Mapping)
            ):
                raise ValueError(
                    f"A {pack.title} VibeScript program named {label!r} "
                    "already exists in this document."
                )
            program_id = uuid.uuid4().hex
            manifest = _new_manifest(pack, program_id, label)
            source = str(arguments.get("source") or "")
            input_schema = arguments.get("input_schema")
            inputs = arguments.get("inputs")
            expected_outputs = arguments.get("expected_outputs")
            base_revision = ""
            previous_source = ""
        else:
            program_id = str(arguments.get("program_id") or "").strip().lower()
            if not _PROGRAM_ID.fullmatch(program_id):
                raise ValueError(
                    "program_id must be a 32-character lowercase hexadecimal id."
                )
            manifest = _load_captured_manifest(
                captured,
                pack,
                program_id,
                hydrate_document_contract=True,
            )
            base_revision = str(manifest.get("working_revision") or "")
            expected_revision = str(arguments.get("expected_revision") or "")
            if expected_revision != base_revision:
                _raise(
                    tool_name,
                    "STALE_PROGRAM_REVISION",
                    "precondition",
                    f"The {pack.title} VibeScript program changed after inspection.",
                    requested={"expected_revision": expected_revision},
                    observed={"current_revision": base_revision},
                    required_changes=[
                        {
                            "tool": "vibescript.read_source",
                            "arguments": {"source_id": program_id},
                        }
                    ],
                )
            complete_contract_replacement = operation == "reconfigure_program" or (
                operation == "edit_source"
                and all(
                    name in arguments
                    for name in ("input_schema", "inputs", "expected_outputs")
                )
            )
            if manifest.get("migration_required") and not complete_contract_replacement:
                action = "vibescript.edit_source"
                _raise(
                    tool_name,
                    "PROGRAM_RECONFIGURATION_REQUIRED",
                    "precondition",
                    "This saved program uses a source contract that is not executable "
                    "by the active VibeScript domain runtime. Replace its complete v2 "
                    "source, input contract, inputs, and outputs before editing or "
                    "regenerating it.",
                    requested={"program_id": program_id},
                    observed={
                        "working_revision": base_revision,
                        "accepted_revision": str(
                            manifest.get("accepted_revision") or ""
                        ),
                        "accepted_live_state_preserved": bool(
                            manifest.get("accepted_revision")
                        ),
                        "imported_from_schema": str(
                            manifest.get("imported_from_schema") or ""
                        ),
                    },
                    required_changes=[
                        {
                            "tool": action,
                            "arguments": {
                                "source_id": program_id,
                                "expected_revision": base_revision,
                            },
                            "expected_revision": base_revision,
                            "replace": [
                                "source",
                                "input_schema",
                                "inputs",
                                "expected_outputs",
                            ],
                        }
                    ],
                )
            previous_source = str(manifest.get("source") or "")
            source = previous_source
            input_schema = manifest.get("input_schema")
            inputs = manifest.get("inputs")
            expected_outputs = manifest.get("expected_outputs")
            if operation == "edit_source":
                source = str(arguments.get("source") or "")
                if "inputs" in arguments:
                    inputs = arguments.get("inputs")
                    input_schema = (
                        arguments.get("input_schema")
                        if "input_schema" in arguments
                        else contracts.synchronize_input_schema(
                            dict(input_schema or {}),
                            dict(inputs or {}),
                        )
                    )
                elif "input_schema" in arguments:
                    input_schema = arguments.get("input_schema")
                if "expected_outputs" in arguments:
                    expected_outputs = arguments.get("expected_outputs")
                if complete_contract_replacement:
                    for key in (
                        "migration_required",
                        "migration_reason",
                        "migration_action",
                    ):
                        manifest.pop(key, None)
            elif operation == "set_inputs":
                inputs = _merge_patch(dict(inputs or {}), arguments.get("patch"))
            elif operation == "reconfigure_program":
                source = str(arguments.get("source") or "")
                input_schema = arguments.get("input_schema")
                inputs = arguments.get("inputs")
                expected_outputs = arguments.get("expected_outputs")
                for key in (
                    "migration_required",
                    "migration_reason",
                    "migration_action",
                ):
                    manifest.pop(key, None)
            else:
                raise ValueError(
                    f"Operation {operation!r} does not prepare a candidate."
                )
        native_history_repair_required = False
        if pack.domain == "partdesign" and operation != "create_program":
            expected_history_bodies = sum(
                1
                for item in dict(manifest.get("live_outputs") or {}).values()
                if str(
                    dict(item.get("partdesign_data") or {}).get(
                        "representation",
                        "",
                    )
                    or ""
                )
                == "body"
            )
            live_program = next(
                (
                    item
                    for item in list(captured.get("live_programs") or [])
                    if str(item.get("program_id") or "") == program_id
                ),
                None,
            )
            live_history = (
                dict(live_program.get("native_history") or {})
                if isinstance(live_program, Mapping)
                else {}
            )
            native_history_repair_required = live_program is not None and (
                int(live_history.get("operation_count") or 0) != 1
                or int(live_history.get("body_count") or 0) < expected_history_bodies
            )

        clean = contracts.validate_program_contract(
            pack,
            source=source,
            input_schema=input_schema,
            inputs=inputs,
            expected_outputs=expected_outputs,
        )
        compatibility_methods: tuple[str, ...] = ()
        if pack.domain == "partdesign":
            retired_calls = _partdesign_saved_source_compatibility_methods(
                clean["source"]
            )
            if retired_calls and (
                operation == "create_program" or clean["source"] != previous_source
            ):
                _raise(
                    tool_name,
                    "LEGACY_PARTDESIGN_API_NOT_AVAILABLE",
                    "schema",
                    "New or edited Part Design source must use the canonical operation "
                    "vocabulary. Use operation='add_material' or 'remove_material' "
                    "with api.extrude, api.revolve, api.loft, or api.sweep.",
                    requested={
                        "canonical_operations": [
                            "extrude",
                            "revolve",
                            "loft",
                            "sweep",
                        ],
                    },
                    observed={
                        "retired_api_members": sorted(retired_calls),
                        "unchanged_saved_source": False,
                    },
                    required_changes=[
                        {
                            "replace_retired_calls": sorted(retired_calls),
                            "with": [
                                "api.extrude",
                                "api.revolve",
                                "api.loft",
                                "api.sweep",
                            ],
                        }
                    ],
                )
            if retired_calls:
                compatibility_methods = tuple(sorted(retired_calls))
        _validate_stable_references(clean["inputs"], captured, "inputs")
        # Resolve the worker before changing persisted program state. A missing
        # FreeCADCmd is a precondition failure, not a durable working revision.
        freecadcmd_executable = _freecadcmd(str(captured["freecad_home"]))
        contract_revision = contracts.program_revision(domain=pack.domain, **clean)
        reference_requirements = (
            _input_references(clean["inputs"])
            if pack.domain
            in {
                "partdesign",
                "part",
                "assembly",
                "sketcher",
                "draft",
                "surface",
                "mesh",
                "meshpart",
                "points",
                "reverse_engineering",
                "inspection",
                "fem",
                "cam",
                "techdraw",
                "robot",
            }
            else []
        )
        reference_capture_mode = (
            _partdesign_reference_capture_mode(
                clean["source"],
                clean["expected_outputs"],
            )
            if pack.domain == "partdesign"
            else "geometry"
        )
        point_artifact_ids = (
            _input_point_artifacts(clean["inputs"])
            if pack.domain in {"points", "reverse_engineering"}
            else []
        )
        attempt_id = f"{int(time.time() * 1000):013d}-{uuid.uuid4().hex}"
        program_directory = _program_directory(project_root, pack.domain, program_id)
        staging = project_root / "vibescript" / pack.domain / ".staging" / attempt_id
        staging.mkdir(parents=True, exist_ok=False)
        worker_point_artifacts, resolved_point_artifacts = _stage_point_artifacts(
            project_root,
            staging,
            point_artifact_ids,
        )
        module_root = Path(__file__).resolve().parent
        _stage_worker_bundle(module_root, staging, pack.domain)
        request = {
            "schema": WORKER_SCHEMA,
            "program_schema": contracts.PROGRAM_SCHEMA,
            "program_id": program_id,
            "revision": "",
            "domain": pack.domain,
            "workbench": pack.workbench,
            "document_name": str(captured["document_name"]),
            "document_uid": str(captured["document_uid"]),
            "document_objects": list(captured["document_objects"]),
            "material_targets": list(captured.get("material_targets") or []),
            "source": clean["source"],
            "inputs": clean["inputs"],
            "expected_outputs": clean["expected_outputs"],
            "api_exports": list(pack.api_exports),
            "output_types": list(pack.output_types),
            "compatibility_methods": list(compatibility_methods),
            "max_operations": 200_000,
            "max_seconds": float(captured["timeout_seconds"]),
            "memory_limit_bytes": int(captured["memory_limit_bytes"]),
            "cpu_limit_seconds": max(1, int(float(captured["timeout_seconds"]))),
            "output_limit_bytes": 256 * 1024 * 1024,
            "point_artifacts": worker_point_artifacts,
        }
        prepared = {
            "tool_name": tool_name,
            "operation": operation,
            "pack": pack,
            "program_id": program_id,
            "program_name": str(manifest["label"]),
            "revision": "",
            "contract_revision": contract_revision,
            "base_revision": base_revision,
            "accepted_revision_before": str(manifest.get("accepted_revision") or ""),
            "accepted_contract_before": manifest.get("accepted_contract"),
            "live_outputs_before": dict(manifest.get("live_outputs") or {}),
            "source": clean["source"],
            "input_schema": clean["input_schema"],
            "inputs": clean["inputs"],
            "expected_outputs": clean["expected_outputs"],
            "manifest": manifest,
            "program_directory": str(program_directory),
            "staging": str(staging),
            "attempt_id": attempt_id,
            "freecadcmd_executable": str(freecadcmd_executable),
            "timeout_seconds": float(captured["timeout_seconds"]),
            "memory_limit_bytes": int(captured["memory_limit_bytes"]),
            "document_name": str(captured["document_name"]),
            "document_uid": str(captured["document_uid"]),
            "document_revision": str(captured["document_revision"]),
            "document_objects": list(captured["document_objects"]),
            "material_targets": list(captured.get("material_targets") or []),
            "surface": dict(captured["surface"]),
            "reference_requirements": reference_requirements,
            "reference_capture_mode": reference_capture_mode,
            "point_artifact_ids": point_artifact_ids,
            "resolved_point_artifacts": resolved_point_artifacts,
            "worker_request": request,
            "native_history_repair_required": native_history_repair_required,
            "allow_unchanged_revision": bool(captured.get("allow_unchanged_revision")),
            "finalized": False,
        }
        return prepared if reference_requirements else finalize_candidate(prepared, [])
    except DomainRuntimeFailure:
        raise
    except Exception as exc:
        if staging is not None and staging.is_dir():
            shutil.rmtree(staging)
        _raise(
            tool_name,
            "PROGRAM_CONTRACT_INVALID",
            "schema",
            str(exc),
            requested=arguments,
            observed={"domain": pack.domain, "operation": operation},
        )


def _worker_environment(prepared: Mapping[str, Any]) -> dict[str, str]:
    staging = str(prepared["staging"])
    preserved = (
        "COMSPEC",
        "LANG",
        "LC_ALL",
        "LD_LIBRARY_PATH",
        "PATH",
        "PATHEXT",
        "SystemRoot",
        "WINDIR",
    )
    environment = {
        name: os.environ[name]
        for name in preserved
        if str(os.environ.get(name) or "").strip()
    }
    environment.update(
        {
            "HOME": staging,
            "PYTHONHASHSEED": "0",
            "PYTHONNOUSERSITE": "1",
            "TEMP": staging,
            "TMP": staging,
            "TMPDIR": staging,
            "VIBECAD_VIBESCRIPT_DOMAIN_REQUEST": str(Path(staging) / "request.json"),
            "VIBECAD_VIBESCRIPT_DOMAIN_RESULT": str(Path(staging) / "result.json"),
        }
    )
    if sys.platform == "win32":
        drive, tail = os.path.splitdrive(staging)
        environment["USERPROFILE"] = staging
        if drive:
            environment["HOMEDRIVE"] = drive
            environment["HOMEPATH"] = tail or "\\"
    return environment


def _worker_progress(prepared: Mapping[str, Any]) -> dict[str, Any] | None:
    path = Path(str(prepared["staging"])) / "progress.json"
    if not path.is_file():
        return None
    try:
        value = _read_json(path, "domain worker progress")
    except ValueError as exc:
        return {"unavailable": True, "error": str(exc)}
    return value


def execute_candidate(
    prepared: Mapping[str, Any],
    *,
    cancellation_check: Callable[[], bool] | None,
) -> dict[str, Any]:
    from VibeCADScriptedProcess import run_process

    code = (
        "import os,runpy,sys;"
        "sys.path.insert(0,os.getcwd());"
        "runpy.run_path('worker.py',run_name='__main__')"
    )
    process = run_process(
        [str(prepared["freecadcmd_executable"]), "--safe-mode", "-c", code],
        cwd=str(prepared["staging"]),
        environment=_worker_environment(prepared),
        cancellation_check=cancellation_check,
        timeout_seconds=float(prepared["timeout_seconds"]),
        memory_limit_bytes=int(prepared["memory_limit_bytes"]),
    )
    progress = _worker_progress(prepared)
    if progress is not None:
        process["worker_progress"] = progress
    if not process.get("started"):
        return _failure(
            str(prepared["tool_name"]),
            "DOMAIN_WORKER_START_FAILED",
            "external_process",
            f"The isolated domain worker could not start: {process.get('error')}",
            observed=process,
        )
    if process.get("cancelled"):
        return _failure(
            str(prepared["tool_name"]),
            "RUN_CANCELLED",
            "external_process",
            "VibeScript domain execution was cancelled.",
            observed={
                **process,
                "accepted_live_outputs_preserved": bool(
                    prepared.get("live_outputs_before")
                ),
                "partial_candidate_outputs_published": False,
            },
            cancelled=True,
        )
    if process.get("timed_out"):
        return _failure(
            str(prepared["tool_name"]),
            "DOMAIN_EXECUTION_TIMEOUT",
            "external_process",
            f"VibeScript domain execution exceeded {prepared['timeout_seconds']:g} seconds.",
            observed={
                **process,
                "accepted_live_outputs_preserved": bool(
                    prepared.get("live_outputs_before")
                ),
                "partial_candidate_outputs_published": False,
            },
        )
    if process.get("memory_exceeded"):
        return _failure(
            str(prepared["tool_name"]),
            "DOMAIN_MEMORY_LIMIT_EXCEEDED",
            "external_process",
            "VibeScript domain execution exceeded its memory limit.",
            observed={
                **process,
                "accepted_live_outputs_preserved": bool(
                    prepared.get("live_outputs_before")
                ),
                "partial_candidate_outputs_published": False,
            },
        )
    if process.get("cpu_exceeded"):
        return _failure(
            str(prepared["tool_name"]),
            "DOMAIN_CPU_LIMIT_EXCEEDED",
            "external_process",
            "VibeScript domain execution exhausted its isolated CPU-time limit.",
            observed={
                **process,
                "accepted_live_outputs_preserved": bool(
                    prepared.get("live_outputs_before")
                ),
                "partial_candidate_outputs_published": False,
            },
        )
    result_path = Path(str(prepared["staging"])) / "result.json"
    if not result_path.is_file():
        return _failure(
            str(prepared["tool_name"]),
            "DOMAIN_WORKER_NO_RESULT",
            "external_process",
            "The isolated domain worker exited without a result.",
            observed={
                **process,
                "accepted_live_outputs_preserved": bool(
                    prepared.get("live_outputs_before")
                ),
                "partial_candidate_outputs_published": False,
            },
        )
    try:
        report = _read_json(result_path, "domain worker result")
    except ValueError as exc:
        return _failure(
            str(prepared["tool_name"]),
            "DOMAIN_WORKER_RESULT_INVALID",
            "external_process",
            str(exc),
            observed=process,
        )
    if not report.get("ok"):
        domain_details = (
            dict(report.get("details") or {})
            if isinstance(report.get("details"), Mapping)
            else {}
        )
        domain_failure_stage = str(domain_details.get("stage") or "").strip()
        correction = str(domain_details.get("correction") or "").strip()
        return _failure(
            str(prepared["tool_name"]),
            "DOMAIN_CANDIDATE_FAILED",
            "external_process",
            str(report.get("error") or "The domain worker rejected the candidate."),
            observed={
                "exception_type": report.get("exception_type"),
                "details": report.get("details"),
                "traceback": report.get("traceback"),
                "stdout": report.get("stdout") or process.get("stdout"),
                "stderr": process.get("stderr"),
                "elapsed_seconds": process.get("elapsed_seconds"),
                "worker_progress": progress,
                "termination_reason": process.get("termination_reason"),
                "limit_reached": process.get("limit_reached"),
                "accepted_live_outputs_preserved": bool(
                    prepared.get("live_outputs_before")
                ),
                "partial_candidate_outputs_published": False,
            },
            **(
                {"domain_failure_stage": domain_failure_stage}
                if domain_failure_stage
                else {}
            ),
            required_changes=[correction] if correction else [],
        )
    report["process"] = process
    return report


_BREP_OUTPUT_TYPES = frozenset(
    {
        "solid",
        "shell",
        "face",
        "wire",
        "compound",
        "surface",
        "fill",
        "blend",
        "extension",
        "loft",
        "brep",
        "curve",
    }
)


def _validate_shape_class(output_type: str, facts: Mapping[str, Any]) -> None:
    shape_type = str(facts.get("shape_type") or "")
    counts = {
        "solid": int(facts.get("solids") or 0),
        "shell": int(facts.get("shells") or 0),
        "face": int(facts.get("faces") or 0),
        "wire": int(facts.get("wires") or 0),
    }
    expected_shape_types = {
        "solid": "Solid",
        "shell": "Shell",
        "face": "Face",
        "wire": "Wire",
    }
    if (
        output_type in expected_shape_types
        and shape_type != expected_shape_types[output_type]
    ):
        raise ValueError(
            f"A {output_type} output must have exact OCC ShapeType "
            f"{expected_shape_types[output_type]}, not {shape_type or '<missing>'}."
        )
    if output_type in counts and counts[output_type] != 1:
        raise ValueError(
            f"A {output_type} output must contain exactly one {output_type}."
        )
    if output_type == "compound" and shape_type != "Compound":
        raise ValueError("A compound output must have OCC ShapeType Compound.")
    if output_type in {"surface", "fill", "blend", "extension", "loft"} and not (
        counts["face"] or counts["shell"] or counts["solid"]
    ):
        raise ValueError(
            f"A {output_type} output must contain a face, shell, or solid."
        )


def _detached_shape_facts(shape: Any, *, max_subelements: int) -> dict[str, Any]:
    from vibescript_part_worker import part_shape_facts

    return part_shape_facts(shape, max_subelements=max_subelements)


def _finite_vector(value: Any, label: str) -> list[float]:
    if not isinstance(value, (list, tuple)) or len(value) != 3:
        raise ValueError(f"{label} must be [x, y, z].")
    if any(isinstance(item, bool) for item in value):
        raise ValueError(f"{label} must contain numbers, not booleans.")
    result = [float(item) for item in value]
    if not all(math.isfinite(item) for item in result):
        raise ValueError(f"{label} must contain finite coordinates.")
    return result


def _validate_sheet_output(item: Mapping[str, Any]) -> dict[str, Any]:
    definition = item.get("definition")
    properties = (
        dict(definition.get("properties") or {}) if isinstance(definition, dict) else {}
    )
    cells = properties.get("cells", {})
    if not isinstance(cells, dict):
        raise ValueError("Spreadsheet cells must be an object keyed by cell address.")
    if len(cells) > 10_000:
        raise ValueError("A VibeScript spreadsheet may contain at most 10000 cells.")
    aliases: dict[str, str] = {}
    for raw_address, raw in cells.items():
        address = str(raw_address or "").strip().upper()
        if not _SPREADSHEET_CELL.fullmatch(address):
            raise ValueError(f"Invalid spreadsheet cell address {raw_address!r}.")
        if not isinstance(raw, (str, int, float, bool, dict)) or raw is None:
            raise ValueError(f"Spreadsheet cell {address} has an unsupported value.")
        cell = dict(raw) if isinstance(raw, dict) else {"value": raw}
        alias = str(cell.get("alias") or "")
        if alias:
            if not _SPREADSHEET_ALIAS.fullmatch(alias):
                raise ValueError(
                    f"Spreadsheet cell {address} has invalid alias {alias!r}."
                )
            if alias in aliases and aliases[alias] != address:
                raise ValueError(f"Spreadsheet alias {alias!r} is duplicated.")
            aliases[alias] = address
        expression = cell.get("expression")
        if expression is not None and not str(expression).strip():
            raise ValueError(f"Spreadsheet cell {address} has an empty expression.")
    return {"cell_count": len(cells), "aliases": aliases}


def _validate_spreadsheet_sample_color(
    value: Any,
    *,
    path: str,
) -> list[float] | None:
    if value is None:
        return None
    if not isinstance(value, list) or len(value) != 4:
        raise ValueError(f"{path} must be null or native RGBA [r, g, b, a].")
    channels = [float(channel) for channel in value]
    if not all(
        math.isfinite(channel) and 0.0 <= channel <= 1.0 for channel in channels
    ):
        raise ValueError(f"{path} channels must be finite and between zero and one.")
    if abs(channels[3] - 1.0) > 1.0e-6:
        raise ValueError(
            f"{path} must retain the opaque alpha channel used by the API."
        )
    return channels


def _spreadsheet_contents_match(
    cell: Mapping[str, Any] | None,
    observed: str,
) -> bool:
    """Compare native content exactly except for equivalent numeric serialization."""

    if cell is None:
        return observed == ""
    expression = cell.get("expression")
    if expression is not None:
        return observed == f"={expression}"
    value = cell.get("value")
    if value is None:
        return observed == ""
    if isinstance(value, bool):
        return observed == ("=True" if value else "=False")
    if isinstance(value, str):
        expected = value if value.startswith("'") else f"'{value}"
        return observed == expected
    unit = str(cell.get("unit") or "")
    numeric_text = observed
    if unit:
        suffix = f" {unit}"
        if not observed.startswith("=") or not observed.endswith(suffix):
            return False
        numeric_text = observed[1 : -len(suffix)]
    elif observed.startswith("="):
        return False
    try:
        native_value = float(numeric_text)
    except ValueError:
        return False
    return math.isfinite(native_value) and math.isclose(
        native_value,
        float(value),
        rel_tol=1.0e-12,
        abs_tol=1.0e-15,
    )


def _validate_spreadsheet_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    """Reauthorize exact Spreadsheet graphs and bounded native worker readback."""

    from vibescript_spreadsheet_worker import (
        EVALUATED_SAMPLE_LIMIT,
        READBACK_SAMPLE_LIMIT,
        VALIDATION_SCHEMA,
        affected_addresses,
        definition_sha256,
        merged_range_specs,
        validate_spreadsheet_definition,
    )

    global_validation = execution.get("spreadsheet_validation")
    if not isinstance(global_validation, dict):
        raise ValueError(
            "The Spreadsheet worker returned no native validation summary."
        )
    global_fields = {"schema", "output_count", "native_object_count", "outputs"}
    if set(global_validation) != global_fields:
        raise ValueError(
            "The Spreadsheet worker validation summary has malformed fields."
        )
    if global_validation.get("schema") != VALIDATION_SCHEMA:
        raise ValueError("The Spreadsheet worker validation schema is unsupported.")
    if (
        type(global_validation.get("output_count")) is not int
        or type(global_validation.get("native_object_count")) is not int
        or int(global_validation["output_count"]) != len(outputs)
        or int(global_validation["native_object_count"]) != len(outputs)
    ):
        raise ValueError("The Spreadsheet worker native output count is inconsistent.")
    summaries = global_validation.get("outputs")
    if not isinstance(summaries, list) or len(summaries) != len(outputs):
        raise ValueError("The Spreadsheet worker output summary is inconsistent.")

    validation_fields = {
        "schema",
        "output_name",
        "native_type",
        "definition_sha256",
        "readback_sha256",
        "cell_count",
        "formula_count",
        "quantity_literal_count",
        "alias_count",
        "range_style_count",
        "merged_range_count",
        "affected_cell_count",
        "column_width_count",
        "row_height_count",
        "used_range",
        "nonempty_cell_count",
        "merged_ranges",
        "native_state",
        "native_status",
        "recompute_result",
        "readback_sample",
        "readback_sample_limit",
        "readback_sample_truncated",
        "evaluated_sample",
        "evaluated_sample_limit",
        "evaluated_sample_truncated",
    }
    sample_fields = {
        "address",
        "contents",
        "alias",
        "display_unit",
        "style",
        "alignment",
        "foreground",
        "background",
    }
    evaluated_fields = {"address", "type", "value"}
    sha256_pattern = re.compile(r"^[0-9a-f]{64}$")
    expected_global: list[dict[str, Any]] = []
    for item, raw_global in zip(outputs, summaries):
        name = str(item.get("name") or "")
        if set(item) != {"name", "type", "definition", "sheet_validation"}:
            raise ValueError(
                f"Spreadsheet output {name!r} has undeclared worker fields."
            )
        if str(item.get("type") or "") != "sheet":
            raise ValueError(f"Spreadsheet output {name!r} must have type 'sheet'.")
        definition = validate_spreadsheet_definition(
            item.get("definition"), context=f"outputs.{name}.definition"
        )
        _validate_definition_value(
            definition,
            prepared,
            f"outputs.{name}.definition",
        )
        encoded_definition = json.dumps(
            definition,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
        if len(encoded_definition) > _STRUCTURED_DEFINITION_LIMIT:
            raise ValueError(f"Spreadsheet output {name!r} definition is too large.")

        validation = item.get("sheet_validation")
        if not isinstance(validation, dict) or set(validation) != validation_fields:
            raise ValueError(
                f"Spreadsheet output {name!r} native validation has malformed fields."
            )
        if validation.get("schema") != VALIDATION_SCHEMA:
            raise ValueError(
                f"Spreadsheet output {name!r} has an unsupported validation schema."
            )
        if (
            str(validation.get("output_name") or "") != name
            or str(validation.get("native_type") or "") != "Spreadsheet::Sheet"
        ):
            raise ValueError(
                f"Spreadsheet output {name!r} changed its native object identity contract."
            )
        expected_definition_digest = definition_sha256(definition)
        if validation.get("definition_sha256") != expected_definition_digest:
            raise ValueError(
                f"Spreadsheet output {name!r} definition digest is inconsistent."
            )
        if not isinstance(
            validation.get("readback_sha256"), str
        ) or not sha256_pattern.fullmatch(validation["readback_sha256"]):
            raise ValueError(
                f"Spreadsheet output {name!r} has an invalid readback digest."
            )

        raw_cells = list(definition["arguments"])[0]
        properties = dict(definition["properties"])
        raw_ranges = list(properties["range_styles"])
        expected_merged_ranges = merged_range_specs(definition)
        cells = [
            {
                "address": str(raw["arguments"][0]),
                **dict(raw["properties"]),
            }
            for raw in raw_cells
        ]
        expected_addresses = affected_addresses(definition)
        expected_counts = {
            "cell_count": len(cells),
            "formula_count": sum(cell.get("expression") is not None for cell in cells),
            "quantity_literal_count": sum(bool(cell.get("unit")) for cell in cells),
            "alias_count": sum(bool(cell.get("alias")) for cell in cells),
            "range_style_count": len(raw_ranges),
            "merged_range_count": len(expected_merged_ranges),
            "affected_cell_count": len(expected_addresses),
            "column_width_count": len(dict(properties["column_widths"])),
            "row_height_count": len(dict(properties["row_heights"])),
        }
        for field, expected_value in expected_counts.items():
            if (
                type(validation.get(field)) is not int
                or validation[field] != expected_value
            ):
                raise ValueError(
                    f"Spreadsheet output {name!r} reported inconsistent {field}."
                )
        if validation.get("merged_ranges") != expected_merged_ranges:
            raise ValueError(
                f"Spreadsheet output {name!r} native merged-range readback is inconsistent."
            )
        if type(validation.get("nonempty_cell_count")) is not int or not 0 <= int(
            validation["nonempty_cell_count"]
        ) <= len(expected_addresses):
            raise ValueError(
                f"Spreadsheet output {name!r} reported an invalid non-empty cell count."
            )
        used_range = validation.get("used_range")
        if (
            not isinstance(used_range, list)
            or len(used_range) not in {0, 2}
            or any(
                not isinstance(address, str) or not _SPREADSHEET_CELL.fullmatch(address)
                for address in used_range
            )
        ):
            raise ValueError(
                f"Spreadsheet output {name!r} has an invalid native used range."
            )
        state = validation.get("native_state")
        if (
            not isinstance(state, list)
            or not state
            or any(not isinstance(value, str) or not value for value in state)
            or {"Invalid", "Error"}.intersection(state)
            or validation.get("native_status") != "Valid"
            or validation.get("recompute_result") is not True
        ):
            raise ValueError(
                f"Spreadsheet output {name!r} did not retain valid native recompute state."
            )

        samples = validation.get("readback_sample")
        sample_count = min(len(expected_addresses), READBACK_SAMPLE_LIMIT)
        if (
            type(validation.get("readback_sample_limit")) is not int
            or validation["readback_sample_limit"] != READBACK_SAMPLE_LIMIT
            or type(validation.get("readback_sample_truncated")) is not bool
            or validation["readback_sample_truncated"]
            != (len(expected_addresses) > READBACK_SAMPLE_LIMIT)
            or not isinstance(samples, list)
            or len(samples) != sample_count
        ):
            raise ValueError(
                f"Spreadsheet output {name!r} has inconsistent bounded readback sampling."
            )

        expected_format = {
            address: {
                "style": [],
                "alignment": [],
                "foreground": None,
                "background": None,
                "alias": "",
                "display_unit": "",
                "cell": None,
            }
            for address in expected_addresses
        }
        from vibescript_spreadsheet_worker import range_addresses

        for raw in raw_ranges:
            range_properties = dict(raw["properties"])
            for address in range_addresses(str(raw["arguments"][0])):
                target = expected_format[address]
                for field in ("style", "alignment", "foreground", "background"):
                    if range_properties[field] is not None:
                        target[field] = list(range_properties[field])
        for cell in cells:
            address = str(cell["address"])
            target = expected_format[address]
            target["cell"] = cell
            target["alias"] = str(cell.get("alias") or "")
            target["display_unit"] = str(cell.get("display_unit") or "")
            for field in ("style", "alignment", "foreground", "background"):
                if cell[field] is not None:
                    target[field] = list(cell[field])
        for merged in expected_merged_ranges:
            merged_addresses = range_addresses(str(merged["range_address"]))
            for address in merged_addresses[1:]:
                if address in expected_format:
                    expected_format[address] = {
                        "style": [],
                        "alignment": [],
                        "foreground": None,
                        "background": None,
                        "alias": "",
                        "display_unit": "",
                        "cell": None,
                    }

        for index, (sample, expected_address) in enumerate(
            zip(samples, expected_addresses[:READBACK_SAMPLE_LIMIT])
        ):
            path = f"outputs.{name}.sheet_validation.readback_sample[{index}]"
            if not isinstance(sample, dict) or set(sample) != sample_fields:
                raise ValueError(f"{path} has malformed fields.")
            if sample.get("address") != expected_address:
                raise ValueError(f"{path} is out of native row-major address order.")
            if any(
                not isinstance(sample.get(field), str)
                for field in ("contents", "alias", "display_unit")
            ):
                raise ValueError(f"{path} text readback fields must be strings.")
            if len(sample["contents"]) > 32_768 or len(sample["alias"]) > 64:
                raise ValueError(f"{path} text readback exceeds its bounded contract.")
            expected = expected_format[expected_address]
            if sample["alias"] != expected["alias"]:
                raise ValueError(
                    f"{path}.alias disagrees with its accepted cell definition."
                )
            if bool(expected["display_unit"]) != bool(sample["display_unit"]):
                raise ValueError(
                    f"{path}.display_unit disagrees with its accepted cell definition."
                )
            for field in ("style", "alignment"):
                value = sample.get(field)
                if (
                    not isinstance(value, list)
                    or any(not isinstance(token, str) for token in value)
                    or sorted(value) != sorted(expected[field])
                ):
                    raise ValueError(
                        f"{path}.{field} disagrees with final formatting precedence."
                    )
            for field in ("foreground", "background"):
                observed_color = _validate_spreadsheet_sample_color(
                    sample.get(field), path=f"{path}.{field}"
                )
                requested_color = expected[field]
                if requested_color is None:
                    if observed_color is not None:
                        raise ValueError(
                            f"{path}.{field} was not declared by the batch."
                        )
                elif observed_color is None or any(
                    abs(observed_color[channel] - float(requested_color[channel]))
                    > 2.0e-6
                    for channel in range(3)
                ):
                    raise ValueError(
                        f"{path}.{field} disagrees with final formatting precedence."
                    )
            cell = expected["cell"]
            if not _spreadsheet_contents_match(cell, sample["contents"]):
                raise ValueError(
                    f"{path}.contents disagrees with its accepted literal, formula, or quantity definition."
                )

        evaluated_cells = [
            cell
            for cell in cells
            if cell.get("value") is not None or cell.get("expression") is not None
        ]
        evaluated = validation.get("evaluated_sample")
        if (
            type(validation.get("evaluated_sample_limit")) is not int
            or validation["evaluated_sample_limit"] != EVALUATED_SAMPLE_LIMIT
            or type(validation.get("evaluated_sample_truncated")) is not bool
            or validation["evaluated_sample_truncated"]
            != (len(evaluated_cells) > EVALUATED_SAMPLE_LIMIT)
            or not isinstance(evaluated, list)
            or len(evaluated) != min(len(evaluated_cells), EVALUATED_SAMPLE_LIMIT)
        ):
            raise ValueError(
                f"Spreadsheet output {name!r} has inconsistent evaluated-value sampling."
            )
        expected_evaluated_addresses = [
            str(cell["address"]) for cell in evaluated_cells[:EVALUATED_SAMPLE_LIMIT]
        ]
        for index, (sample, expected_address) in enumerate(
            zip(evaluated, expected_evaluated_addresses)
        ):
            path = f"outputs.{name}.sheet_validation.evaluated_sample[{index}]"
            if (
                not isinstance(sample, dict)
                or set(sample) != evaluated_fields
                or sample.get("address") != expected_address
                or not isinstance(sample.get("type"), str)
                or not sample["type"]
            ):
                raise ValueError(
                    f"{path} has malformed or out-of-order native evaluation data."
                )
            _validate_definition_value(sample["value"], prepared, f"{path}.value")

        encoded_validation = json.dumps(
            validation,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
        if len(encoded_validation) > _STRUCTURED_DEFINITION_LIMIT:
            raise ValueError(
                f"Spreadsheet output {name!r} native validation is too large."
            )
        expected_global_item = {
            "name": name,
            "type": "sheet",
            "native_type": "Spreadsheet::Sheet",
            "cell_count": expected_counts["cell_count"],
            "formula_count": expected_counts["formula_count"],
            "alias_count": expected_counts["alias_count"],
            "merged_range_count": expected_counts["merged_range_count"],
            "definition_sha256": expected_definition_digest,
            "readback_sha256": validation["readback_sha256"],
        }
        if raw_global != expected_global_item:
            raise ValueError(
                f"Spreadsheet output {name!r} global worker summary is inconsistent."
            )
        expected_global.append(expected_global_item)
    if summaries != expected_global:
        raise ValueError("The Spreadsheet worker output order is inconsistent.")
    return dict(global_validation)


def _validate_material_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    """Reauthorize targets and independently resolve every catalog card off-thread."""

    from vibescript_material_worker import (
        MATERIAL_CATALOG_LOCK,
        VALIDATION_SCHEMA,
        appearance_controlled_properties,
        definition_sha256,
        material_card_appearance,
        material_card_record,
        resolve_material_appearance,
        validate_material_definition,
    )

    global_validation = execution.get("material_validation")
    global_fields = {
        "schema",
        "output_count",
        "assignment_count",
        "appearance_count",
        "unique_target_count",
        "resolved_card_count",
        "outputs",
    }
    if (
        not isinstance(global_validation, dict)
        or set(global_validation) != global_fields
    ):
        raise ValueError("The Material worker validation summary has malformed fields.")
    if global_validation.get("schema") != VALIDATION_SCHEMA:
        raise ValueError("The Material worker validation schema is unsupported.")
    if type(global_validation.get("output_count")) is not int or int(
        global_validation["output_count"]
    ) != len(outputs):
        raise ValueError("The Material worker output count is inconsistent.")

    target_snapshots: dict[tuple[str, str], dict[str, Any]] = {}
    for raw in list(prepared.get("material_targets") or []):
        if not isinstance(raw, dict) or not isinstance(raw.get("reference"), dict):
            raise ValueError("A captured Material target snapshot is malformed.")
        reference = raw["reference"]
        key = (
            str(reference.get("document_uid") or ""),
            str(reference.get("object_name") or ""),
        )
        if key in target_snapshots:
            raise ValueError("Captured Material target identities are duplicated.")
        target_snapshots[key] = raw
    authenticated_references = {
        (str(item["document_uid"]), str(item["object_name"]))
        for item in _input_references(prepared.get("inputs"))
    }

    expected_summaries: list[dict[str, Any]] = []
    ownership: set[tuple[str, str]] = set()
    resolved_cards: set[tuple[str, tuple[str, ...], tuple[str, ...]]] = set()
    assignment_count = 0
    appearance_count = 0
    target_names: set[str] = set()
    base_validation_fields = {
        "schema",
        "output_name",
        "output_type",
        "definition_sha256",
        "target",
        "target_type_id",
        "channel",
    }
    host_manager = None
    native_card_cache: dict[str, Any] = {}
    card_record_cache: dict[
        tuple[str, tuple[str, ...], tuple[str, ...]], dict[str, Any]
    ] = {}

    def resolve_host_card(
        card_definition: Mapping[str, Any],
        *,
        output_name: str,
    ) -> tuple[str, tuple[str, ...], tuple[str, ...], Any, dict[str, Any]]:
        nonlocal host_manager
        material_uuid = str(list(card_definition["arguments"])[0])
        card_properties = dict(card_definition["properties"])
        required_physical = tuple(card_properties["require_physical_properties"])
        required_appearance = tuple(card_properties["require_appearance_properties"])
        cache_key = (material_uuid, required_physical, required_appearance)
        native_material = native_card_cache.get(material_uuid)
        expected_card = card_record_cache.get(cache_key)
        try:
            import Materials

            with MATERIAL_CATALOG_LOCK:
                if host_manager is None:
                    host_manager = Materials.MaterialManager()
                if native_material is None:
                    native_material = host_manager.getMaterial(material_uuid)
                    if native_material is not None:
                        native_card_cache[material_uuid] = native_material
                if native_material is not None and expected_card is None:
                    expected_card = material_card_record(
                        native_material,
                        required_physical_properties=required_physical,
                        required_appearance_properties=required_appearance,
                    )
                    card_record_cache[cache_key] = expected_card
        except Exception as exc:
            raise ValueError(
                f"Host Material catalog resolution failed for output {output_name!r}, "
                f"card {material_uuid!r}: {type(exc).__name__}: {exc}"
            ) from exc
        if native_material is None or expected_card is None:
            raise ValueError(
                f"Material card {material_uuid!r} disappeared after worker validation."
            )
        resolved_cards.add(cache_key)
        return (
            material_uuid,
            required_physical,
            required_appearance,
            native_material,
            expected_card,
        )

    for declaration, item in zip(prepared["expected_outputs"], outputs):
        name = str(declaration["name"])
        output_type = str(declaration["type"])
        if set(item) != {"name", "type", "definition", "material_validation"}:
            raise ValueError(f"Material output {name!r} has undeclared worker fields.")
        if item.get("name") != name or item.get("type") != output_type:
            raise ValueError(f"Material output {name!r} changed its declared identity.")
        definition = validate_material_definition(
            item.get("definition"),
            expected_output_type=output_type,
            context=f"outputs.{name}.definition",
        )
        _validate_definition_value(definition, prepared, f"outputs.{name}.definition")
        encoded_definition = json.dumps(
            definition,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
        if len(encoded_definition) > _STRUCTURED_DEFINITION_LIMIT:
            raise ValueError(f"Material output {name!r} definition is too large.")

        validation = item.get("material_validation")
        specific_fields = (
            {"material_card"}
            if output_type == "material_assignment"
            else {
                "requested",
                "resolved",
                "controlled_properties",
                "material_card",
                "card_appearance",
            }
        )
        if not isinstance(validation, dict) or set(validation) != (
            base_validation_fields | specific_fields
        ):
            raise ValueError(
                f"Material output {name!r} validation fields are malformed."
            )
        channel = "physical" if output_type == "material_assignment" else "appearance"
        target = dict(list(definition["arguments"])[0])
        target_key = (str(target["document_uid"]), str(target["object_name"]))
        expected_base = {
            "schema": VALIDATION_SCHEMA,
            "output_name": name,
            "output_type": output_type,
            "definition_sha256": definition_sha256(definition),
            "target": target,
            "target_type_id": str(
                (target_snapshots.get(target_key) or {}).get("type_id") or ""
            ),
            "channel": channel,
        }
        if any(validation.get(key) != value for key, value in expected_base.items()):
            raise ValueError(
                f"Material output {name!r} validation identity is inconsistent."
            )
        if target_key not in authenticated_references:
            raise ValueError(
                f"Material output {name!r} target is not an authenticated stable reference "
                "persisted in program inputs."
            )
        snapshot = target_snapshots.get(target_key)
        if snapshot is None:
            raise ValueError(
                f"Material output {name!r} target snapshot is unavailable."
            )
        if snapshot.get("managed_material_output") is True:
            raise ValueError(
                f"Material output {name!r} cannot target another managed Material carrier."
            )
        ownership_key = (target_key[1], channel)
        if ownership_key in ownership:
            raise ValueError(
                f"Material candidate duplicates {channel} ownership of target {target_key[1]!r}."
            )
        ownership.add(ownership_key)
        target_names.add(target_key[1])

        if output_type == "material_assignment":
            if snapshot.get("physical_assignment_supported") is not True:
                raise ValueError(
                    f"Material target {target_key[1]!r} has no native ShapeMaterial property."
                )
            card_definition = dict(list(definition["arguments"])[1])
            (
                material_uuid,
                _required_physical,
                _required_appearance,
                native_material,
                expected_card,
            ) = resolve_host_card(card_definition, output_name=name)
            if validation["material_card"] != expected_card:
                raise ValueError(
                    f"Material card {material_uuid!r} differs between worker and host catalogs."
                )
            item["native_material"] = native_material
            item["material_validation"] = validation
            assignment_count += 1
            summary = {
                "output_name": name,
                "output_type": output_type,
                "target": target,
                "channel": channel,
                "material_uuid": material_uuid,
                "card_sha256": expected_card["card_sha256"],
            }
        else:
            requested = dict(definition["properties"])
            requested.pop("label")
            card_definition = list(definition["arguments"])[1]
            expected_card = None
            expected_card_appearance = None
            material_uuid = ""
            if card_definition is not None:
                (
                    material_uuid,
                    _required_physical,
                    _required_appearance,
                    native_material,
                    expected_card,
                ) = resolve_host_card(dict(card_definition), output_name=name)
                with MATERIAL_CATALOG_LOCK:
                    expected_card_appearance = material_card_appearance(native_material)
            resolved = resolve_material_appearance(requested, expected_card_appearance)
            controlled = appearance_controlled_properties(resolved)
            if (
                validation["requested"] != requested
                or validation["resolved"] != resolved
                or validation["controlled_properties"] != controlled
                or validation["material_card"] != expected_card
                or validation["card_appearance"] != expected_card_appearance
            ):
                raise ValueError(
                    f"Material appearance output {name!r} resolved-state validation differs."
                )
            supported = list(snapshot.get("appearance_supported_properties") or [])
            missing = sorted(set(controlled) - set(supported))
            if missing:
                raise ValueError(
                    f"Material appearance target {target_key[1]!r} no longer supports "
                    f"{', '.join(missing)}."
                )
            display_mode = resolved.get("display_mode")
            if display_mode is not None and display_mode not in list(
                snapshot.get("display_modes") or []
            ):
                raise ValueError(
                    f"Material appearance target {target_key[1]!r} does not support "
                    f"display mode {display_mode!r}."
                )
            appearance_count += 1
            item["material_validation"] = validation
            summary = {
                "output_name": name,
                "output_type": output_type,
                "target": target,
                "channel": channel,
                "controlled_properties": controlled,
                "material_uuid": material_uuid,
                "card_sha256": str((expected_card or {}).get("card_sha256") or ""),
            }
        expected_summaries.append(summary)

    expected_counts = {
        "assignment_count": assignment_count,
        "appearance_count": appearance_count,
        "unique_target_count": len(target_names),
        "resolved_card_count": len(resolved_cards),
    }
    for field, expected in expected_counts.items():
        if (
            type(global_validation.get(field)) is not int
            or global_validation[field] != expected
        ):
            raise ValueError(f"The Material worker reported inconsistent {field}.")
    if global_validation.get("outputs") != expected_summaries:
        raise ValueError("The Material worker global output summary is inconsistent.")
    encoded_validation = json.dumps(
        global_validation,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    if len(encoded_validation) > _STRUCTURED_DEFINITION_LIMIT:
        raise ValueError("The Material worker validation summary is too large.")
    return dict(global_validation)


def _finite_float(value: Any, *, path: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{path} must be a finite number.")
    result = float(value)
    if not math.isfinite(result):
        raise ValueError(f"{path} must be finite.")
    return result


def _mesh_values_match(reported: Any, observed: Any, *, path: str) -> None:
    if isinstance(observed, bool):
        if type(reported) is not bool or reported is not observed:
            raise ValueError(f"{path} differs from the imported native Mesh.")
        return
    if isinstance(observed, int):
        if type(reported) is not int or reported != observed:
            raise ValueError(f"{path} differs from the imported native Mesh.")
        return
    if isinstance(observed, float):
        value = _finite_float(reported, path=path)
        absolute_tolerance = (
            _REVERSE_FIT_METRIC_ABSOLUTE_TOLERANCE
            if "fit_metrics" in path.split(".")
            else 1.0e-9
        )
        if not math.isclose(
            value,
            observed,
            rel_tol=1.0e-9,
            abs_tol=absolute_tolerance,
        ):
            raise ValueError(
                f"{path} differs: worker={value!r}, imported={observed!r}."
            )
        return
    if isinstance(observed, str) or observed is None:
        if reported != observed:
            raise ValueError(f"{path} differs from the imported native Mesh.")
        return
    if isinstance(observed, list):
        if not isinstance(reported, list) or len(reported) != len(observed):
            raise ValueError(f"{path} has the wrong array length.")
        for index, (left, right) in enumerate(zip(reported, observed)):
            _mesh_values_match(left, right, path=f"{path}[{index}]")
        return
    if isinstance(observed, dict):
        if not isinstance(reported, dict) or set(reported) != set(observed):
            raise ValueError(f"{path} has malformed fields.")
        for key, value in observed.items():
            _mesh_values_match(reported[key], value, path=f"{path}.{key}")
        return
    raise ValueError(f"{path} contains unsupported value {type(observed).__name__}.")


def _mesh_definition_chain(definition: Mapping[str, Any]) -> list[Mapping[str, Any]]:
    operation = str(definition.get("operation") or "")
    if operation in {"mesh", "from_object"}:
        return [definition]
    arguments = list(definition.get("arguments") or [])
    if operation in {"union", "difference", "intersection"}:
        if len(arguments) != 2 or any(
            not isinstance(argument, dict) for argument in arguments
        ):
            raise ValueError(f"Mesh api.{operation} lost its operand definitions.")
        return [
            *_mesh_definition_chain(arguments[0]),
            *_mesh_definition_chain(arguments[1]),
            definition,
        ]
    if len(arguments) != 1 or not isinstance(arguments[0], dict):
        raise ValueError(f"Mesh api.{operation} lost its source definition.")
    return [*_mesh_definition_chain(arguments[0]), definition]


def _mesh_definition_operations(definition: Mapping[str, Any]) -> list[str]:
    return [
        str(item.get("operation") or "") for item in _mesh_definition_chain(definition)
    ]


def _validate_mesh_trace(
    trace: Any,
    definition: Mapping[str, Any],
    *,
    output_name: str,
    observed: Mapping[str, Any],
    source_references: Mapping[tuple[str, str], Mapping[str, Any]],
) -> None:
    if not isinstance(trace, list) or not 1 <= len(trace) <= _MAX_MESH_TRACE_OPERATIONS:
        raise ValueError(f"Mesh output {output_name!r} operation trace is malformed.")
    definitions = _mesh_definition_chain(definition)
    operations = _mesh_definition_operations(definition)
    if [
        str(item.get("operation") or "") for item in trace if isinstance(item, dict)
    ] != operations:
        raise ValueError(f"Mesh output {output_name!r} operation trace changed order.")
    fields = {
        "mesh": {"operation", "input_facets", "result"},
        "from_object": {
            "operation",
            "source",
            "source_diagnostics",
            "result",
        },
        "transform": {
            "operation",
            "translation",
            "rotation",
            "scale",
            "before",
            "after",
        },
        "repair": {"operation", "applied", "before", "after"},
        "diagnostics": {"operation", "requirements", "result"},
        "union": {
            "operation",
            "first_definition_sha256",
            "second_definition_sha256",
            "first",
            "second",
            "tessellation",
            "backend",
            "result",
        },
        "difference": {
            "operation",
            "first_definition_sha256",
            "second_definition_sha256",
            "first",
            "second",
            "tessellation",
            "backend",
            "result",
        },
        "intersection": {
            "operation",
            "first_definition_sha256",
            "second_definition_sha256",
            "first",
            "second",
            "tessellation",
            "backend",
            "result",
        },
    }
    quick_fields = {
        "points",
        "facets",
        "open_edges",
        "degenerated_facets",
        "duplicated_facets",
        "duplicated_points",
        "components",
    }
    for index, item in enumerate(trace):
        if not isinstance(item, dict):
            raise ValueError(
                f"Mesh output {output_name!r} trace item {index} is not an object."
            )
        operation = operations[index]
        operation_definition = definitions[index]
        properties = dict(operation_definition.get("properties") or {})
        if set(item) != fields[operation]:
            raise ValueError(
                f"Mesh output {output_name!r} trace item {index} has malformed fields."
            )
        for key in ("result", "before", "after"):
            if (
                key not in item
                or operation == "diagnostics"
                or operation in {"union", "difference", "intersection"}
            ):
                continue
            counts = item[key]
            if (
                not isinstance(counts, dict)
                or set(counts) != quick_fields
                or any(type(value) is not int or value < 0 for value in counts.values())
            ):
                raise ValueError(
                    f"Mesh output {output_name!r} trace {index}.{key} is malformed."
                )
        if operation == "mesh":
            arguments = list(operation_definition.get("arguments") or [])
            if (
                type(item["input_facets"]) is not int
                or len(arguments) != 1
                or not isinstance(arguments[0], list)
                or item["input_facets"] != len(arguments[0])
            ):
                raise ValueError(
                    f"Mesh output {output_name!r} trace {index} changed its input count."
                )
        elif operation == "from_object":
            arguments = list(operation_definition.get("arguments") or [])
            reference = arguments[0] if len(arguments) == 1 else None
            if not isinstance(reference, Mapping):
                raise ValueError(
                    f"Mesh output {output_name!r} trace {index} lost its source reference."
                )
            key = (
                str(reference.get("document_uid") or ""),
                str(reference.get("object_name") or ""),
            )
            authenticated = source_references.get(key)
            if authenticated is None:
                raise ValueError(
                    f"Mesh output {output_name!r} uses unauthenticated source {key[1]!r}."
                )
            raw_identity = {
                "document_uid": key[0],
                "object_name": key[1],
                "label": str(authenticated.get("label") or ""),
                "type_id": str(authenticated.get("type_id") or ""),
                "artifact_kind": str(authenticated.get("artifact_kind") or ""),
                "artifact_sha256": str(authenticated.get("mesh_sha256") or ""),
                "source_kind": str(authenticated.get("source_kind") or ""),
                "source_program_id": str(authenticated.get("source_program_id") or ""),
                "source_program_domain": str(
                    authenticated.get("source_program_domain") or ""
                ),
                "source_revision": str(authenticated.get("source_revision") or ""),
                "transient_topology": bool(authenticated.get("transient_topology")),
                "source_placement_matrix": list(
                    authenticated.get("mesh_source_placement_matrix") or []
                ),
            }
            expected_identity = {
                key_name: value
                for key_name, value in raw_identity.items()
                if value not in (None, "", [])
            }
            if item["source"] != expected_identity:
                raise ValueError(
                    f"Mesh output {output_name!r} trace {index} changed its source identity."
                )
            facts = authenticated.get("facts")
            if not isinstance(facts, Mapping):
                raise ValueError(
                    f"Mesh source {key[1]!r} has no authenticated native diagnostics."
                )
            _mesh_values_match(
                item["source_diagnostics"],
                facts,
                path=(
                    f"outputs.{output_name}.operation_trace[{index}].source_diagnostics"
                ),
            )
            expected_counts = {
                field: int(facts[field])
                for field in (
                    "points",
                    "facets",
                    "open_edges",
                    "degenerated_facets",
                    "duplicated_facets",
                    "duplicated_points",
                    "components",
                )
            }
            if item["result"] != expected_counts:
                raise ValueError(
                    f"Mesh output {output_name!r} trace {index} changed source counts."
                )
        elif operation == "transform":
            for key in ("translation", "rotation", "scale"):
                _mesh_values_match(
                    item[key],
                    properties[key],
                    path=f"outputs.{output_name}.operation_trace[{index}].{key}",
                )
            if item["before"] != item["after"]:
                raise ValueError(
                    f"Mesh output {output_name!r} transform changed topology counts."
                )
        elif operation in {"union", "difference", "intersection"}:
            arguments = list(operation_definition.get("arguments") or [])
            if len(arguments) != 2 or any(
                not isinstance(argument, Mapping) for argument in arguments
            ):
                raise ValueError(
                    f"Mesh output {output_name!r} trace {index} lost its operands."
                )

            def definition_sha256(value: Mapping[str, Any]) -> str:
                encoded = json.dumps(
                    value,
                    ensure_ascii=True,
                    sort_keys=True,
                    separators=(",", ":"),
                    allow_nan=False,
                ).encode("utf-8")
                return hashlib.sha256(encoded).hexdigest()

            if item["first_definition_sha256"] != definition_sha256(
                arguments[0]
            ) or item["second_definition_sha256"] != definition_sha256(arguments[1]):
                raise ValueError(
                    f"Mesh output {output_name!r} trace {index} changed an operand."
                )
            expected_tessellation = {
                "linear_deflection": float(properties["linear_deflection"]),
                "angular_deflection_degrees": float(
                    properties["angular_deflection_degrees"]
                ),
                "relative": bool(properties["relative"]),
            }
            _mesh_values_match(
                item["tessellation"],
                expected_tessellation,
                path=f"outputs.{output_name}.operation_trace[{index}].tessellation",
            )
            if item["backend"] != "MeshPart::Boolean/OpenCASCADE":
                raise ValueError(
                    f"Mesh output {output_name!r} trace {index} changed its OCC backend."
                )
            boolean_fact_fields = {
                "points",
                "facets",
                "open_edges",
                "components",
                "is_solid",
                "volume_mm3",
                "bounds",
            }
            for operand_name in ("first", "second", "result"):
                facts = item[operand_name]
                if not isinstance(facts, dict) or set(facts) != boolean_fact_fields:
                    raise ValueError(
                        f"Mesh output {output_name!r} trace "
                        f"{index}.{operand_name} is malformed."
                    )
                for field in ("points", "facets", "open_edges", "components"):
                    if type(facts[field]) is not int or facts[field] < 0:
                        raise ValueError(
                            f"Mesh output {output_name!r} trace "
                            f"{index}.{operand_name}.{field} is malformed."
                        )
                if type(facts["is_solid"]) is not bool:
                    raise ValueError(
                        f"Mesh output {output_name!r} trace "
                        f"{index}.{operand_name}.is_solid is malformed."
                    )
                _finite_float(
                    facts["volume_mm3"],
                    path=(
                        f"outputs.{output_name}.operation_trace"
                        f"[{index}].{operand_name}.volume_mm3"
                    ),
                )
                bounds = facts["bounds"]
                if not isinstance(bounds, dict) or set(bounds) != {
                    "minimum",
                    "maximum",
                }:
                    raise ValueError(
                        f"Mesh output {output_name!r} trace "
                        f"{index}.{operand_name}.bounds is malformed."
                    )
                for bound_name in ("minimum", "maximum"):
                    vector = bounds[bound_name]
                    if not isinstance(vector, list) or len(vector) != 3:
                        raise ValueError(
                            f"Mesh output {output_name!r} trace "
                            f"{index}.{operand_name}.bounds.{bound_name} is malformed."
                        )
                    for coordinate, value in enumerate(vector):
                        _finite_float(
                            value,
                            path=(
                                f"outputs.{output_name}.operation_trace"
                                f"[{index}].{operand_name}.bounds.{bound_name}"
                                f"[{coordinate}]"
                            ),
                        )
                if (
                    facts["points"] <= 0
                    or facts["facets"] <= 0
                    or facts["components"] <= 0
                    or facts["open_edges"] != 0
                    or facts["is_solid"] is not True
                    or abs(float(facts["volume_mm3"])) <= 1.0e-12
                    or any(
                        minimum > maximum
                        for minimum, maximum in zip(
                            bounds["minimum"],
                            bounds["maximum"],
                        )
                    )
                ):
                    raise ValueError(
                        f"Mesh output {output_name!r} trace "
                        f"{index}.{operand_name} is not a valid solid mesh."
                    )

            first_definitions = _mesh_definition_chain(arguments[0])
            second_definitions = _mesh_definition_chain(arguments[1])
            first_terminal_index = index - len(second_definitions) - 1
            second_terminal_index = index - 1
            if (
                first_terminal_index < 0
                or second_terminal_index < 0
                or first_terminal_index >= len(trace)
                or second_terminal_index >= len(trace)
            ):
                raise ValueError(
                    f"Mesh output {output_name!r} trace {index} has invalid branches."
                )

            def terminal_quick_counts(
                trace_item: Mapping[str, Any],
                terminal_definition: Mapping[str, Any],
            ) -> dict[str, int]:
                terminal_operation = str(terminal_definition.get("operation") or "")
                key = (
                    "result"
                    if terminal_operation
                    in {
                        "mesh",
                        "from_object",
                        "diagnostics",
                        "union",
                        "difference",
                        "intersection",
                    }
                    else "after"
                )
                raw_counts = trace_item.get(key)
                if not isinstance(raw_counts, Mapping):
                    raise ValueError(
                        f"Mesh output {output_name!r} boolean branch lost its "
                        "terminal topology."
                    )
                return {
                    field: int(raw_counts[field])
                    for field in (
                        "points",
                        "facets",
                        "open_edges",
                        "components",
                    )
                }

            for operand_name, terminal_index, branch_definitions in (
                ("first", first_terminal_index, first_definitions),
                ("second", second_terminal_index, second_definitions),
            ):
                expected_counts = terminal_quick_counts(
                    trace[terminal_index],
                    branch_definitions[-1],
                )
                reported_counts = {
                    field: item[operand_name][field] for field in expected_counts
                }
                if reported_counts != expected_counts:
                    raise ValueError(
                        f"Mesh output {output_name!r} trace {index} changed its "
                        f"{operand_name} operand topology."
                    )
        elif operation == "repair":
            expected_applied = [
                name
                for name, enabled in (
                    ("remove_duplicate_points", properties["remove_duplicate_points"]),
                    ("remove_duplicate_facets", properties["remove_duplicate_facets"]),
                    ("fix_degenerations", properties["fix_degenerations"]),
                    ("remove_non_manifolds", properties["remove_non_manifolds"]),
                    (
                        "remove_non_manifold_points",
                        properties["remove_non_manifolds"],
                    ),
                    (
                        "fix_self_intersections",
                        properties["fix_self_intersections"],
                    ),
                    ("fill_holes", int(properties["fill_holes_max_edges"]) > 0),
                    ("decimate", float(properties["decimate_reduction"]) > 0.0),
                    ("harmonize_normals", properties["harmonize_normals"]),
                )
                if enabled
            ]
            if item["applied"] != expected_applied:
                raise ValueError(
                    f"Mesh output {output_name!r} trace {index} changed repair passes."
                )
        elif operation == "diagnostics":
            expected_requirements = {
                key: properties[key]
                for key in (
                    "require_solid",
                    "require_closed",
                    "require_manifold",
                    "require_consistent_orientation",
                    "require_no_self_intersections",
                    "max_components",
                    "max_open_edges",
                )
            }
            if item["requirements"] != expected_requirements:
                raise ValueError(
                    f"Mesh output {output_name!r} trace {index} changed requirements."
                )
    terminal = trace[-1]
    terminal_operation = operations[-1]
    quick_observed = {
        key: int(observed[key])
        for key in (
            "points",
            "facets",
            "open_edges",
            "degenerated_facets",
            "duplicated_facets",
            "duplicated_points",
            "components",
        )
    }
    if terminal_operation == "diagnostics":
        _mesh_values_match(
            terminal["result"],
            observed,
            path=f"outputs.{output_name}.operation_trace[-1].result",
        )
    elif terminal_operation in {"union", "difference", "intersection"}:
        expected_result = {
            "points": int(observed["points"]),
            "facets": int(observed["facets"]),
            "open_edges": int(observed["open_edges"]),
            "components": int(observed["components"]),
            "is_solid": bool(observed["is_solid"]),
            "volume_mm3": float(observed["volume_mm3"]),
            "bounds": dict(observed["bounds"]),
        }
        _mesh_values_match(
            terminal["result"],
            expected_result,
            path=f"outputs.{output_name}.operation_trace[-1].result",
        )
    else:
        terminal_key = (
            "result" if terminal_operation in {"mesh", "from_object"} else "after"
        )
        if terminal[terminal_key] != quick_observed:
            raise ValueError(
                f"Mesh output {output_name!r} terminal trace differs from its artifact."
            )


def _validate_mesh_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    """Validate imported native Mesh artifacts and their bounded diagnostics."""

    from vibescript_mesh_worker import (
        VALIDATION_SCHEMA,
        mesh_diagnostics,
        validate_mesh_definition,
    )

    validation = execution.get("mesh_validation")
    fields = {"schema", "output_count", "total_points", "total_facets", "outputs"}
    if not isinstance(validation, dict) or set(validation) != fields:
        raise ValueError("The Mesh worker validation summary has malformed fields.")
    if validation.get("schema") != VALIDATION_SCHEMA:
        raise ValueError("The Mesh worker validation schema is unsupported.")
    source_references = {
        (str(item.get("document_uid") or ""), str(item.get("object_name") or "")): item
        for item in list(prepared.get("resolved_references") or [])
        if isinstance(item, Mapping)
        and str(item.get("artifact_kind") or "") == "mesh_bms"
    }
    expected_summaries = []
    total_points = 0
    total_facets = 0
    for declaration, item in zip(prepared["expected_outputs"], outputs):
        name = str(declaration["name"])
        if item.get("artifact_kind") != "mesh_bms":
            raise ValueError(f"Mesh output {name!r} is not a native BMS artifact.")
        definition = validate_mesh_definition(
            item.get("definition"),
            require_domain_value=False,
            context=f"outputs.{name}.definition",
        )
        data = item.get("mesh_data")
        data_fields = {
            "schema",
            "operation",
            "label",
            "artifact_sha256",
            "operation_trace",
            "diagnostics",
        }
        if not isinstance(data, dict) or set(data) != data_fields:
            raise ValueError(f"Mesh output {name!r} native data has malformed fields.")
        if data["schema"] != VALIDATION_SCHEMA:
            raise ValueError(f"Mesh output {name!r} native data schema is unsupported.")
        if data["operation"] != definition["operation"]:
            raise ValueError(f"Mesh output {name!r} changed its terminal operation.")
        expected_label = str(dict(definition["properties"]).get("label") or name)
        if data["label"] != expected_label:
            raise ValueError(f"Mesh output {name!r} changed its label.")
        if data["artifact_sha256"] != item.get("artifact_sha256"):
            raise ValueError(
                f"Mesh output {name!r} artifact digest changed in transfer."
            )
        detached = item.get("detached_mesh")
        if detached is None:
            raise ValueError(f"Mesh output {name!r} has no detached native Mesh.")
        observed = mesh_diagnostics(detached)
        if any(
            operation in {"union", "difference", "intersection"}
            for operation in _mesh_definition_operations(definition)
        ) and (
            not observed["is_solid"]
            or int(observed["open_edges"]) != 0
            or observed["has_non_manifolds"]
            or observed["has_invalid_neighbourhood"]
            or observed["has_non_uniform_orientation"]
            or observed["has_self_intersections"]
            or abs(float(observed["volume_mm3"])) <= 1.0e-12
        ):
            raise ValueError(
                f"Mesh output {name!r} is not a valid closed manifold boolean solid."
            )
        _validate_mesh_trace(
            data["operation_trace"],
            definition,
            output_name=name,
            observed=observed,
            source_references=source_references,
        )
        _mesh_values_match(
            data["diagnostics"],
            observed,
            path=f"outputs.{name}.mesh_data.diagnostics",
        )
        _validate_definition_value(
            data,
            prepared,
            f"outputs.{name}.mesh_data",
        )
        encoded_data = json.dumps(
            data,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
        if len(encoded_data) > _STRUCTURED_DEFINITION_LIMIT:
            raise ValueError(f"Mesh output {name!r} native readback is too large.")
        item["definition"] = definition
        item["mesh_data"] = data
        item["facts"] = observed
        total_points += int(observed["points"])
        total_facets += int(observed["facets"])
        expected_summaries.append(
            {
                "name": name,
                "operation": str(definition["operation"]),
                "artifact_sha256": str(item["artifact_sha256"]),
                "points": int(observed["points"]),
                "facets": int(observed["facets"]),
                "open_edges": int(observed["open_edges"]),
                "components": int(observed["components"]),
                "is_solid": bool(observed["is_solid"]),
            }
        )
    if (
        type(validation.get("output_count")) is not int
        or validation["output_count"] != len(outputs)
        or type(validation.get("total_points")) is not int
        or validation["total_points"] != total_points
        or type(validation.get("total_facets")) is not int
        or validation["total_facets"] != total_facets
        or validation.get("outputs") != expected_summaries
    ):
        raise ValueError("The Mesh worker global validation summary is inconsistent.")
    return dict(validation)


def _validate_meshpart_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
    *,
    definition_domain: str = "meshpart",
) -> dict[str, Any]:
    """Reauthorize MeshPart artifacts, source snapshots, and conversion reports."""

    import Mesh
    import Part

    from vibescript_mesh_worker import mesh_diagnostics
    from vibescript_meshpart_worker import (
        VALIDATION_SCHEMA,
        _bounded_segments,
        _select_shape,
        _selected_mesh,
        validate_meshpart_definition,
    )
    from vibescript_part_worker import part_shape_facts

    validation = execution.get("meshpart_validation")
    validation_fields = {
        "schema",
        "output_count",
        "mesh_output_count",
        "shape_output_count",
        "total_input_facets",
        "total_output_facets",
        "outputs",
    }
    if not isinstance(validation, dict) or set(validation) != validation_fields:
        raise ValueError("The MeshPart worker validation summary has malformed fields.")
    if validation.get("schema") != VALIDATION_SCHEMA:
        raise ValueError("The MeshPart worker validation schema is unsupported.")

    references = {
        (str(item.get("document_uid") or ""), str(item.get("object_name") or "")): item
        for item in list(prepared.get("resolved_references") or [])
        if isinstance(item, Mapping)
    }
    worker_references = {
        (str(item.get("document_uid") or ""), str(item.get("object_name") or "")): item
        for item in list(
            dict(prepared.get("worker_request") or {}).get("document_references") or []
        )
        if isinstance(item, Mapping)
    }
    staging = Path(str(prepared["staging"])).resolve()

    def source_identity(reference: Mapping[str, Any]) -> dict[str, Any]:
        artifact_kind = str(reference.get("artifact_kind") or "brep")
        digest = str(
            reference.get("mesh_sha256")
            if artifact_kind == "mesh_bms"
            else reference.get("brep_sha256") or ""
        )
        raw = {
            "document_uid": str(reference.get("document_uid") or ""),
            "object_name": str(reference.get("object_name") or ""),
            "label": str(reference.get("label") or ""),
            "type_id": str(reference.get("type_id") or ""),
            "artifact_kind": artifact_kind,
            "artifact_sha256": digest,
            "source_kind": str(reference.get("source_kind") or ""),
            "source_program_id": str(reference.get("source_program_id") or ""),
            "source_program_domain": str(reference.get("source_program_domain") or ""),
            "source_revision": str(reference.get("source_revision") or ""),
            "transient_topology": bool(reference.get("transient_topology")),
        }
        return {key: value for key, value in raw.items() if value not in (None, "")}

    def artifact_path(reference_key: tuple[str, str]) -> Path:
        worker = worker_references.get(reference_key)
        if worker is None:
            raise ValueError(
                f"MeshPart source {reference_key[1]!r} has no staged worker artifact."
            )
        path = (staging / str(worker.get("artifact_path") or "")).resolve()
        if staging not in path.parents or not path.is_file():
            raise ValueError(
                f"MeshPart source artifact {reference_key[1]!r} is missing."
            )
        return path

    expected_summaries = []
    mesh_output_count = 0
    shape_output_count = 0
    total_input_facets = 0
    total_output_facets = 0
    for declaration, item in zip(prepared["expected_outputs"], outputs):
        name = str(declaration["name"])
        output_type = str(declaration["type"])
        definition = validate_meshpart_definition(
            item.get("definition"),
            expected_output_type=output_type,
            require_domain_value=False,
            context=f"outputs.{name}.definition",
            definition_domain=definition_domain,
        )
        operation = str(definition["operation"])
        properties = dict(definition["properties"])
        reference = dict(definition["arguments"][0])
        key = (
            str(reference.get("document_uid") or ""),
            str(reference.get("object_name") or ""),
        )
        resolved = references.get(key)
        if resolved is None:
            raise ValueError(
                f"MeshPart output {name!r} uses unauthenticated source {key[1]!r}."
            )
        data = item.get("meshpart_data")
        if not isinstance(data, dict):
            raise ValueError(f"MeshPart output {name!r} has no native conversion data.")
        base_fields = {
            "schema",
            "operation",
            "label",
            "source",
            "artifact_sha256",
        }
        mesh_fields = {
            "source_shape_facts",
            "subelements",
            "method",
            "parameters",
            "mesher_backend",
            "segments",
            "diagnostics",
        }
        shape_fields = {
            "source_mesh_diagnostics",
            "selection",
            "selected_mesh_diagnostics",
            "parameters",
            "conversion",
            "shape_facts",
        }
        expected_fields = base_fields | (
            mesh_fields if operation == "mesh_from_shape" else shape_fields
        )
        if set(data) != expected_fields:
            raise ValueError(
                f"MeshPart output {name!r} conversion data has malformed fields."
            )
        if (
            data.get("schema") != VALIDATION_SCHEMA
            or data.get("operation") != operation
            or data.get("label") != str(properties["label"])
            or data.get("source") != source_identity(resolved)
        ):
            raise ValueError(
                f"MeshPart output {name!r} changed its conversion identity."
            )
        path = (staging / str(item.get("artifact_path") or "")).resolve()
        if staging not in path.parents or not path.is_file():
            raise ValueError(f"MeshPart output {name!r} artifact is missing.")
        digest = _sha256_file(path)
        if (
            data.get("artifact_sha256") != digest
            or item.get("artifact_sha256") != digest
        ):
            raise ValueError(
                f"MeshPart output {name!r} artifact digest changed during transfer."
            )

        source_path = artifact_path(key)
        source_digest = _sha256_file(source_path)
        if source_digest != source_identity(resolved)["artifact_sha256"]:
            raise ValueError(
                f"MeshPart source {key[1]!r} changed after revision binding."
            )
        if operation == "mesh_from_shape":
            if str(resolved.get("artifact_kind") or "brep") != "brep":
                raise ValueError(
                    f"MeshPart mesh_from_shape source {key[1]!r} is not BREP."
                )
            if item.get("artifact_kind") != "mesh_bms" or output_type != "mesh":
                raise ValueError(
                    f"MeshPart output {name!r} is not an authenticated BMS mesh."
                )
            source_shape = Part.Shape()
            source_shape.importBrep(str(source_path))
            if source_shape.isNull() or not source_shape.isValid():
                raise ValueError(
                    f"MeshPart source BREP {key[1]!r} is invalid after transfer."
                )
            selected_shape = _select_shape(
                source_shape,
                list(properties["subelements"]),
            )
            detail_limit = int(
                dict(data.get("source_shape_facts") or {}).get(
                    "subelement_detail_limit", -1
                )
            )
            if not 0 <= detail_limit <= 32:
                raise ValueError(
                    f"MeshPart output {name!r} source detail limit is invalid."
                )
            expected_source_facts = part_shape_facts(
                selected_shape,
                max_subelements=detail_limit,
            )
            _mesh_values_match(
                data["source_shape_facts"],
                expected_source_facts,
                path=f"outputs.{name}.meshpart_data.source_shape_facts",
            )
            if data["subelements"] != list(properties["subelements"]):
                raise ValueError(
                    f"MeshPart output {name!r} changed its BREP subelement selection."
                )
            if data["method"] != properties["method"]:
                raise ValueError(
                    f"MeshPart output {name!r} changed its meshing method."
                )
            expected_parameters = {
                key: properties[key]
                for key in (
                    "linear_deflection",
                    "angular_deflection_degrees",
                    "relative",
                    "preserve_face_groups",
                    "max_length",
                    "max_area",
                    "local_length",
                    "deflection",
                    "min_length",
                    "fineness",
                    "growth_rate",
                    "segments_per_edge",
                    "segments_per_radius",
                    "second_order",
                    "optimize",
                    "allow_quad",
                )
            }
            if data["parameters"] != expected_parameters:
                raise ValueError(
                    f"MeshPart output {name!r} changed normalized mesher parameters."
                )
            expected_backend = (
                "opencascade"
                if properties["method"] == "standard"
                else "netgen"
                if str(properties["method"]).startswith("netgen_")
                else "mefisto"
            )
            if data["mesher_backend"] != expected_backend:
                raise ValueError(
                    f"MeshPart output {name!r} reported an inconsistent mesher backend."
                )
            detached = item.get("detached_mesh")
            if detached is None:
                raise ValueError(
                    f"MeshPart output {name!r} has no detached native Mesh."
                )
            observed = mesh_diagnostics(detached)
            _mesh_values_match(
                data["diagnostics"],
                observed,
                path=f"outputs.{name}.meshpart_data.diagnostics",
            )
            segments = _bounded_segments(
                data["segments"],
                facet_count=int(detached.CountFacets),
                context=f"outputs.{name}.meshpart_data.segments",
            )
            if bool(segments) is not bool(properties["preserve_face_groups"]):
                raise ValueError(
                    f"MeshPart output {name!r} did not preserve its declared face groups."
                )
            for segment in segments:
                detached.addSegment(segment)
            item["facts"] = observed
            item["meshpart_data"] = data
            total_output_facets += int(observed["facets"])
            mesh_output_count += 1
            expected_summary = {
                "name": name,
                "type": "mesh",
                "operation": operation,
                "source_object": key[1],
                "artifact_sha256": digest,
                "points": int(observed["points"]),
                "facets": int(observed["facets"]),
                "segments": len(segments),
                "method": str(properties["method"]),
            }
        else:
            if resolved.get("artifact_kind") != "mesh_bms":
                raise ValueError(
                    f"MeshPart shape_from_mesh source {key[1]!r} is not a mesh."
                )
            if item.get("artifact_kind") != "brep" or output_type == "mesh":
                raise ValueError(
                    f"MeshPart output {name!r} is not an authenticated typed BREP."
                )
            source_mesh = Mesh.Mesh(str(source_path))
            if int(source_mesh.CountFacets) <= 0:
                raise ValueError(f"MeshPart source mesh {key[1]!r} contains no facets.")
            source_segments = _bounded_segments(
                list(resolved.get("mesh_segments") or []),
                facet_count=int(source_mesh.CountFacets),
                context=f"sources.{key[1]}.mesh_segments",
            )
            for segment in source_segments:
                source_mesh.addSegment(segment)
            source_observed = mesh_diagnostics(source_mesh)
            _mesh_values_match(
                data["source_mesh_diagnostics"],
                source_observed,
                path=f"outputs.{name}.meshpart_data.source_mesh_diagnostics",
            )
            selected, selection = _selected_mesh(
                source_mesh,
                {"mesh_segments": source_segments},
                properties,
            )
            selected_observed = mesh_diagnostics(selected)
            if data["selection"] != selection:
                raise ValueError(
                    f"MeshPart output {name!r} changed its mesh selection."
                )
            _mesh_values_match(
                data["selected_mesh_diagnostics"],
                selected_observed,
                path=f"outputs.{name}.meshpart_data.selected_mesh_diagnostics",
            )
            expected_parameters = {
                key: properties[key]
                for key in (
                    "representation",
                    "tolerance",
                    "harmonize_normals",
                    "refine",
                    "require_closed",
                )
            }
            if data["parameters"] != expected_parameters:
                raise ValueError(
                    f"MeshPart output {name!r} changed normalized conversion parameters."
                )
            conversion = data["conversion"]
            common_conversion_fields = {
                "representation",
                "boundary_count",
                "boundary_edge_counts",
                "boundary_lengths_mm",
                "normal_harmonized",
                "refined",
                "safe_native_stages",
            }
            surface_fields = {
                "before_refine_shape_type",
                "before_refine_face_count",
            }
            expected_conversion_fields = common_conversion_fields | (
                surface_fields if properties["representation"] == "surface" else set()
            )
            if not isinstance(conversion, dict) or set(conversion) != (
                expected_conversion_fields
            ):
                raise ValueError(
                    f"MeshPart output {name!r} conversion trace has malformed fields."
                )
            stages = conversion["safe_native_stages"]
            allowed_stages = {
                "MeshPart.wireFromMesh",
                "Mesh.harmonizeNormals",
                "Part.Shape.makeShapeFromMesh(sew=False)",
                "TopoShape.sewShape",
                "BREP topology normalization",
                "Part.makeSolid",
                "BREP solid normalization",
                "TopoShape.removeSplitter",
            }
            if (
                not isinstance(stages, list)
                or not stages
                or any(stage not in allowed_stages for stage in stages)
                or "makeShapeFromMesh(sew=True)" in " ".join(stages)
            ):
                raise ValueError(
                    f"MeshPart output {name!r} conversion trace is unsupported."
                )
            if (
                conversion["representation"] != properties["representation"]
                or conversion["normal_harmonized"]
                is not bool(properties["harmonize_normals"])
                or conversion["refined"] is not bool(properties["refine"])
            ):
                raise ValueError(
                    f"MeshPart output {name!r} conversion trace changed its options."
                )
            detached_shape = item.get("detached_shape")
            if detached_shape is None:
                raise ValueError(
                    f"MeshPart output {name!r} has no detached native Shape."
                )
            # A generic Part.Shape wrapper produced by importBrep can omit mass
            # properties even though its topology is valid. Copying converts it
            # to the detached typed TopoShape used by the worker and publisher.
            detached_shape = detached_shape.copy()
            item["detached_shape"] = detached_shape
            detail_limit = int(
                dict(data.get("shape_facts") or {}).get("subelement_detail_limit", -1)
            )
            if not 0 <= detail_limit <= 256:
                raise ValueError(
                    f"MeshPart output {name!r} shape detail limit is invalid."
                )
            observed_facts = part_shape_facts(
                detached_shape,
                max_subelements=detail_limit,
            )
            _mesh_values_match(
                data["shape_facts"],
                observed_facts,
                path=f"outputs.{name}.meshpart_data.shape_facts",
            )
            if bool(properties["require_closed"]) and not bool(
                detached_shape.isClosed()
            ):
                raise ValueError(
                    f"MeshPart output {name!r} lost its closed-shape requirement."
                )
            if properties["representation"] == "boundary":
                wires = list(detached_shape.Wires)
                expected_boundary_count = len(wires)
                expected_edge_counts = [len(wire.Edges) for wire in wires]
                expected_lengths = [float(wire.Length) for wire in wires]
                if (
                    conversion["boundary_count"] != expected_boundary_count
                    or conversion["boundary_edge_counts"] != expected_edge_counts
                ):
                    raise ValueError(
                        f"MeshPart output {name!r} boundary topology changed in transfer."
                    )
                _mesh_values_match(
                    conversion["boundary_lengths_mm"],
                    expected_lengths,
                    path=f"outputs.{name}.meshpart_data.conversion.boundary_lengths_mm",
                )
            elif any(
                conversion[field] != expected
                for field, expected in (
                    ("boundary_count", 0),
                    ("boundary_edge_counts", []),
                    ("boundary_lengths_mm", []),
                )
            ):
                raise ValueError(
                    f"MeshPart surface output {name!r} reported boundary-only state."
                )
            item["facts"] = observed_facts
            item["meshpart_data"] = data
            total_input_facets += int(selected_observed["facets"])
            shape_output_count += 1
            expected_summary = {
                "name": name,
                "type": output_type,
                "operation": operation,
                "source_object": key[1],
                "artifact_sha256": digest,
                "selected_facets": int(selected_observed["facets"]),
                "shape_type": str(observed_facts["shape_type"]),
                "faces": int(observed_facts["faces"]),
                "representation": str(properties["representation"]),
            }
        _validate_definition_value(
            data,
            prepared,
            f"outputs.{name}.meshpart_data",
        )
        encoded = json.dumps(
            data,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
        if len(encoded) > _STRUCTURED_DEFINITION_LIMIT:
            raise ValueError(
                f"MeshPart output {name!r} native conversion data is too large."
            )
        item["definition"] = definition
        expected_summaries.append(expected_summary)
    expected_counts = {
        "output_count": len(outputs),
        "mesh_output_count": mesh_output_count,
        "shape_output_count": shape_output_count,
        "total_input_facets": total_input_facets,
        "total_output_facets": total_output_facets,
    }
    if (
        any(
            type(validation.get(field)) is not int or validation[field] != value
            for field, value in expected_counts.items()
        )
        or validation.get("outputs") != expected_summaries
    ):
        raise ValueError(
            "The MeshPart worker global validation summary is inconsistent."
        )
    return dict(validation)


def _validate_mesh_workbench_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    """Validate both operation families exposed by the shipped Mesh surface."""

    expected = list(prepared["expected_outputs"])
    if len(expected) != len(outputs):
        raise ValueError("The Mesh worker changed the declared output count.")

    native_expected: list[dict[str, Any]] = []
    native_outputs: list[dict[str, Any]] = []
    conversion_expected: list[dict[str, Any]] = []
    conversion_outputs: list[dict[str, Any]] = []
    for declaration, item in zip(expected, outputs, strict=True):
        has_mesh_data = isinstance(item.get("mesh_data"), dict)
        has_conversion_data = isinstance(item.get("meshpart_data"), dict)
        if has_mesh_data is has_conversion_data:
            raise ValueError(
                f"Mesh output {declaration['name']!r} must contain exactly one "
                "native-operation or conversion validation record."
            )
        if has_mesh_data:
            native_expected.append(declaration)
            native_outputs.append(item)
        else:
            conversion_expected.append(declaration)
            conversion_outputs.append(item)

    mesh_validation = None
    if native_outputs:
        mesh_validation = _validate_mesh_execution(
            {**dict(prepared), "expected_outputs": native_expected},
            execution,
            native_outputs,
        )
    elif execution.get("mesh_validation") is not None:
        raise ValueError("The Mesh worker reported native outputs that do not exist.")

    meshpart_validation = None
    if conversion_outputs:
        meshpart_validation = _validate_meshpart_execution(
            {**dict(prepared), "expected_outputs": conversion_expected},
            execution,
            conversion_outputs,
            definition_domain="mesh",
        )
    elif execution.get("meshpart_validation") is not None:
        raise ValueError(
            "The Mesh worker reported conversion outputs that do not exist."
        )

    return mesh_validation, meshpart_validation


def _point_facts_match(left: Mapping[str, Any], right: Mapping[str, Any]) -> bool:
    """Compare independently computed float32 point facts with tight tolerance."""

    if set(left) != {
        "points",
        "bounds",
        "centroid",
        "sample",
        "sample_indices",
        "attributes",
        "structured",
    } or set(right) != set(left):
        return False
    if (
        left.get("points") != right.get("points")
        or left.get("sample_indices") != right.get("sample_indices")
        or left.get("attributes") != right.get("attributes")
        or left.get("structured") != right.get("structured")
    ):
        return False

    def close(first: Any, second: Any) -> bool:
        try:
            return math.isclose(
                float(first),
                float(second),
                rel_tol=1.0e-7,
                abs_tol=1.0e-6,
            )
        except (TypeError, ValueError):
            return False

    left_bounds = left.get("bounds")
    right_bounds = right.get("bounds")
    if (
        not isinstance(left_bounds, Mapping)
        or not isinstance(right_bounds, Mapping)
        or set(left_bounds) != {"minimum", "maximum", "size"}
        or set(right_bounds) != set(left_bounds)
    ):
        return False
    for name in ("minimum", "maximum", "size"):
        first = left_bounds.get(name)
        second = right_bounds.get(name)
        if (
            not isinstance(first, list)
            or not isinstance(second, list)
            or len(first) != len(second)
            or len(first) != 3
            or not all(close(a, b) for a, b in zip(first, second))
        ):
            return False
    for name in ("centroid",):
        first = left.get(name)
        second = right.get(name)
        if (
            not isinstance(first, list)
            or not isinstance(second, list)
            or len(first) != len(second)
            or len(first) != 3
            or not all(close(a, b) for a, b in zip(first, second))
        ):
            return False
    left_sample = left.get("sample")
    right_sample = right.get("sample")
    if (
        not isinstance(left_sample, list)
        or not isinstance(right_sample, list)
        or len(left_sample) != len(right_sample)
    ):
        return False
    return all(
        isinstance(first, list)
        and isinstance(second, list)
        and len(first) == len(second) == 3
        and all(close(a, b) for a, b in zip(first, second))
        for first, second in zip(left_sample, right_sample)
    )


def _validate_points_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    """Reauthorize point sources, processing traces, and native artifacts."""

    from vibescript_points_worker import (
        VALIDATION_SCHEMA,
        validate_points_definition,
    )

    validation = execution.get("points_validation")
    fields = {
        "schema",
        "output_count",
        "total_input_points",
        "total_output_points",
        "outputs",
    }
    if not isinstance(validation, dict) or set(validation) != fields:
        raise ValueError("The Points worker validation summary has malformed fields.")
    if validation.get("schema") != VALIDATION_SCHEMA:
        raise ValueError("The Points worker validation schema is unsupported.")
    resolved = [
        item
        for item in list(prepared.get("resolved_references") or [])
        if isinstance(item, Mapping)
    ]
    document_references = {
        (str(item.get("document_uid") or ""), str(item.get("object_name") or "")): item
        for item in resolved
        if item.get("document_uid") and item.get("object_name")
    }
    artifact_references = {
        str(item.get("artifact_id") or ""): item
        for item in resolved
        if item.get("reference_kind") == "point_artifact"
    }
    expected_summaries = []
    total_input_points = 0
    total_output_points = 0
    for declaration, item in zip(prepared["expected_outputs"], outputs):
        name = str(declaration["name"])
        definition = validate_points_definition(
            item.get("definition"),
            require_domain_value=False,
            context=f"outputs.{name}.definition",
        )
        properties = dict(definition["properties"])
        source = dict(definition["arguments"][0])
        data = item.get("points_data")
        expected_data_fields = {
            "schema",
            "operation",
            "label",
            "source",
            "input_point_count",
            "output_point_count",
            "invalid_points_policy",
            "invalid_points_removed",
            "preserve_attributes",
            "pipeline",
            "operation_trace",
            "artifact_sha256",
            "attribute_artifacts",
            "facts",
        }
        if not isinstance(data, dict) or set(data) != expected_data_fields:
            raise ValueError(
                f"Points output {name!r} native validation has malformed fields."
            )
        facts = item.get("facts")
        if not isinstance(facts, dict) or not _point_facts_match(data["facts"], facts):
            raise ValueError(
                f"Points output {name!r} facts changed during artifact transfer."
            )
        if (
            data.get("schema") != VALIDATION_SCHEMA
            or data.get("operation") != "point_cloud"
            or data.get("label") != str(properties["label"])
            or data.get("invalid_points_policy") != properties["invalid_points"]
            or data.get("preserve_attributes")
            is not bool(properties["preserve_attributes"])
            or data.get("pipeline") != list(properties["pipeline"])
            or data.get("artifact_sha256") != item.get("artifact_sha256")
            or data.get("attribute_artifacts") != item.get("attribute_artifacts")
            or data.get("output_point_count") != facts["points"]
        ):
            raise ValueError(
                f"Points output {name!r} changed its canonical processing contract."
            )
        input_count = data.get("input_point_count")
        removed_invalid = data.get("invalid_points_removed")
        if (
            isinstance(input_count, bool)
            or type(input_count) is not int
            or input_count < 1
            or isinstance(removed_invalid, bool)
            or type(removed_invalid) is not int
            or not 0 <= removed_invalid < input_count
        ):
            raise ValueError(f"Points output {name!r} reported invalid source counts.")
        expected_source: dict[str, Any]
        source_kind = str(source.get("kind") or "")
        if source_kind == "inline":
            inline_points = list(source.get("points") or [])
            expected_source = {"kind": "inline", "point_count": len(inline_points)}
            if input_count != len(inline_points):
                raise ValueError(
                    f"Points output {name!r} changed its inline source count."
                )
        elif source_kind == "document":
            reference = dict(source.get("reference") or {})
            key = (
                str(reference.get("document_uid") or ""),
                str(reference.get("object_name") or ""),
            )
            authenticated = document_references.get(key)
            if (
                authenticated is None
                or authenticated.get("artifact_kind") != "points_asc"
            ):
                raise ValueError(
                    f"Points output {name!r} uses an unauthenticated document source."
                )
            expected_source = {
                "kind": "document",
                **{
                    key_name: authenticated.get(key_name)
                    for key_name in (
                        "document_uid",
                        "object_name",
                        "label",
                        "type_id",
                        "artifact_kind",
                        "artifact_sha256",
                        "source_kind",
                        "source_program_id",
                        "source_program_domain",
                        "source_revision",
                        "transient_topology",
                    )
                    if authenticated.get(key_name) not in (None, "")
                },
            }
            reference_facts = authenticated.get("facts")
            if isinstance(reference_facts, Mapping) and input_count != int(
                reference_facts.get("points") or -1
            ):
                raise ValueError(
                    f"Points output {name!r} changed its document source count."
                )
        elif source_kind == "artifact":
            artifact_id = str(source.get("artifact_id") or "")
            authenticated = artifact_references.get(artifact_id)
            if authenticated is None:
                raise ValueError(
                    f"Points output {name!r} uses an unauthenticated project artifact."
                )
            expected_source = {
                "kind": "artifact",
                "artifact_id": artifact_id,
                "name": str(authenticated.get("name") or ""),
                "label": str(authenticated.get("label") or ""),
                "format": str(authenticated.get("format") or ""),
                "artifact_sha256": str(authenticated.get("artifact_sha256") or ""),
                "artifact_bytes": int(authenticated.get("artifact_bytes") or 0),
            }
        else:
            raise ValueError(f"Points output {name!r} has an unsupported source kind.")
        if data.get("source") != expected_source:
            raise ValueError(
                f"Points output {name!r} source identity changed after revision binding."
            )
        trace = data.get("operation_trace")
        pipeline = list(properties["pipeline"])
        if not isinstance(trace, list) or len(trace) != len(pipeline):
            raise ValueError(
                f"Points output {name!r} has an inconsistent operation trace."
            )
        running_count = input_count - removed_invalid
        for index, (observed, stage) in enumerate(zip(trace, pipeline)):
            if (
                not isinstance(observed, dict)
                or set(observed)
                != {
                    "index",
                    "op",
                    "method",
                    "input_count",
                    "output_count",
                    "removed_count",
                }
                or observed.get("index") != index
                or observed.get("op") != stage["op"]
                or observed.get("method") != stage.get("method")
                or observed.get("input_count") != running_count
                or isinstance(observed.get("output_count"), bool)
                or type(observed.get("output_count")) is not int
                or not 1 <= observed["output_count"] <= running_count
                or observed.get("removed_count")
                != running_count - observed["output_count"]
            ):
                raise ValueError(
                    f"Points output {name!r} trace stage {index} is inconsistent."
                )
            running_count = observed["output_count"]
        if running_count != facts["points"]:
            raise ValueError(
                f"Points output {name!r} trace does not reach its published count."
            )
        _validate_definition_value(data, prepared, f"outputs.{name}.points_data")
        item["definition"] = definition
        item["points_data"] = data
        expected_summaries.append(
            {
                "name": name,
                "source_kind": source_kind,
                "input_points": input_count,
                "output_points": int(facts["points"]),
                "attributes": sorted(facts["attributes"]),
                "artifact_sha256": str(item["artifact_sha256"]),
            }
        )
        total_input_points += input_count
        total_output_points += int(facts["points"])
    if (
        validation.get("output_count") != len(outputs)
        or validation.get("total_input_points") != total_input_points
        or validation.get("total_output_points") != total_output_points
        or validation.get("outputs") != expected_summaries
    ):
        raise ValueError("The Points worker global validation summary is inconsistent.")
    return dict(validation)


def _reverse_definition_key(value: Any) -> str:
    return _definition_sha256(value)


def _definition_sha256(value: Any) -> str:
    encoded = json.dumps(
        value,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _staged_artifact_path(
    prepared: Mapping[str, Any],
    relative: Any,
    *,
    context: str,
    maximum_bytes: int = 256 * 1024 * 1024,
) -> Path:
    root = Path(str(prepared["staging"])).resolve()
    raw = str(relative or "")
    candidate = root / raw
    path = candidate.resolve()
    if (
        not raw
        or root not in path.parents
        or not path.is_file()
        or candidate.is_symlink()
    ):
        raise ValueError(f"{context} does not resolve to a staged artifact.")
    try:
        relative_parts = candidate.relative_to(root).parts
    except ValueError as exc:
        raise ValueError(f"{context} is outside candidate staging.") from exc
    cursor = root
    for part in relative_parts[:-1]:
        cursor /= part
        if cursor.is_symlink():
            raise ValueError(f"{context} traverses a staged symlink.")
    size = path.stat().st_size
    if not 1 <= size <= maximum_bytes:
        raise ValueError(f"{context} must contain 1-{maximum_bytes} artifact bytes.")
    return path


def _reverse_source_points(
    prepared: Mapping[str, Any],
    definition: Mapping[str, Any],
    outputs_by_definition: Mapping[str, Mapping[str, Any]],
) -> list[list[float]] | None:
    operation = str(definition.get("operation") or "")
    arguments = list(definition.get("arguments") or [])
    if not arguments:
        return None
    source = None
    if operation == "segment":
        target = arguments[0]
        if isinstance(target, Mapping) and target.get("kind") == "document":
            source = target
        else:
            target_item = outputs_by_definition.get(_reverse_definition_key(target))
            mesh = target_item.get("detached_mesh") if target_item is not None else None
            if mesh is None:
                return None
            points, _facets = mesh.Topology
            return [
                [float(point.x), float(point.y), float(point.z)] for point in points
            ]
    else:
        source = arguments[0]
    if not isinstance(source, Mapping):
        return None
    kind = str(source.get("kind") or "")
    if kind == "inline":
        values = source.get("points")
        if not isinstance(values, list):
            return None
        return [_finite_vector(point, "reverse source point") for point in values]
    request = prepared.get("worker_request")
    if not isinstance(request, Mapping):
        return None
    entry = None
    if kind == "document":
        reference = source.get("reference")
        if not isinstance(reference, Mapping):
            return None
        key = (
            str(reference.get("document_uid") or ""),
            str(reference.get("object_name") or ""),
        )
        entry = next(
            (
                item
                for item in list(request.get("document_references") or [])
                if isinstance(item, Mapping)
                and (
                    str(item.get("document_uid") or ""),
                    str(item.get("object_name") or ""),
                )
                == key
            ),
            None,
        )
    elif kind == "artifact":
        artifact_id = str(source.get("artifact_id") or "")
        entry = next(
            (
                item
                for item in list(request.get("point_artifacts") or [])
                if isinstance(item, Mapping)
                and str(item.get("artifact_id") or "") == artifact_id
            ),
            None,
        )
    if not isinstance(entry, Mapping):
        return None
    artifact_kind = str(entry.get("artifact_kind") or "")
    path = _staged_artifact_path(
        prepared,
        entry.get("artifact_path"),
        context="Reverse Engineering source",
    )
    if artifact_kind == "mesh_bms":
        import Mesh

        mesh = Mesh.Mesh(str(path))
        points, _facets = mesh.Topology
        return [[float(point.x), float(point.y), float(point.z)] for point in points]
    if artifact_kind == "points_asc" or str(entry.get("worker_format") or "") == "asc":
        import Points

        cloud = Points.Points(str(path))
        return [
            [float(point.x), float(point.y), float(point.z)]
            for point in list(cloud.Points)
        ]
    # PCD, PLY, and E57 require native document import. The worker already
    # authenticates and imports them; host validation still independently
    # checks the source artifact digest and all detached output facts.
    return None


def _validate_reverse_metrics(value: Any, *, context: str) -> dict[str, Any]:
    from vibescript_reverse_engineering_worker import VALIDATION_SCHEMA

    fields = {
        "schema",
        "source_point_count",
        "evaluated_point_count",
        "sampled",
        "minimum_distance",
        "mean_distance",
        "rms_distance",
        "maximum_distance",
        "tolerance",
        "within_tolerance_count",
        "within_tolerance_fraction",
        "source_facet_count",
        "retained_facets",
        "segment_count",
    }
    if not isinstance(value, dict) or set(value) != fields:
        raise ValueError(f"{context} has malformed fit-metric fields.")
    if value.get("schema") != VALIDATION_SCHEMA:
        raise ValueError(f"{context} has an unsupported fit-metric schema.")
    source_count = value.get("source_point_count")
    evaluated = value.get("evaluated_point_count")
    within = value.get("within_tolerance_count")
    if (
        isinstance(source_count, bool)
        or type(source_count) is not int
        or source_count < 1
        or isinstance(evaluated, bool)
        or type(evaluated) is not int
        or not 1 <= evaluated <= source_count
        or isinstance(within, bool)
        or type(within) is not int
        or not 0 <= within <= evaluated
        or value.get("sampled") is not (evaluated < source_count)
    ):
        raise ValueError(f"{context} has inconsistent sample counts.")
    numeric = {}
    for name in (
        "minimum_distance",
        "mean_distance",
        "rms_distance",
        "maximum_distance",
        "tolerance",
        "within_tolerance_fraction",
    ):
        raw = value.get(name)
        if isinstance(raw, bool) or not isinstance(raw, (int, float)):
            raise ValueError(f"{context}.{name} must be a finite number.")
        number = float(raw)
        if not math.isfinite(number):
            raise ValueError(f"{context}.{name} must be finite.")
        numeric[name] = number
    if (
        numeric["minimum_distance"] < 0.0
        or not numeric["minimum_distance"]
        <= numeric["mean_distance"]
        <= numeric["maximum_distance"]
        or not numeric["minimum_distance"]
        <= numeric["rms_distance"]
        <= numeric["maximum_distance"]
        or numeric["tolerance"] <= 0.0
        or not 0.0 <= numeric["within_tolerance_fraction"] <= 1.0
        or not math.isclose(
            numeric["within_tolerance_fraction"],
            within / evaluated,
            rel_tol=1.0e-12,
            abs_tol=1.0e-12,
        )
    ):
        raise ValueError(f"{context} has inconsistent distance metrics.")
    for name in ("source_facet_count", "retained_facets", "segment_count"):
        raw = value.get(name)
        if isinstance(raw, bool) or type(raw) is not int or raw < 0:
            raise ValueError(f"{context}.{name} must be a non-negative integer.")
    return dict(value)


def _validate_reverse_trace(
    definition: Mapping[str, Any],
    trace: Any,
    *,
    output_name: str,
    geometry: Any,
    source_point_count: int | None,
) -> list[list[int]]:
    """Validate one algorithm trace and return authenticated output segments."""

    operation = str(definition.get("operation") or "")
    properties = dict(definition.get("properties") or {})
    context = f"outputs.{output_name}.operation_trace"
    fields = {
        "fit_curve": {"operation", "native_function", "input_points"},
        "fit_surface": {"operation", "native_function", "input_points"},
        "reconstruct": {
            "operation",
            "method",
            "input_points",
            "output_type",
            "method_trace",
        },
        "segment": {
            "operation",
            "method",
            "source_facets",
            "segment_count",
            "segment_sizes",
            "segment_sizes_truncated",
            "published_segments",
            "selected_segment",
            "retained_facets",
        },
    }
    expected_fields = fields.get(operation)
    if (
        expected_fields is None
        or not isinstance(trace, dict)
        or set(trace) != expected_fields
        or trace.get("operation") != operation
    ):
        raise ValueError(f"{context} has malformed fields.")
    if operation in {"fit_curve", "fit_surface"}:
        expected_native = (
            "ReverseEngineering.approxCurve"
            if operation == "fit_curve"
            else "ReverseEngineering.approxSurface"
        )
        input_points = trace.get("input_points")
        if (
            trace.get("native_function") != expected_native
            or isinstance(input_points, bool)
            or type(input_points) is not int
            or input_points < 2
            or (source_point_count is not None and input_points != source_point_count)
        ):
            raise ValueError(f"{context} changed its native fitting contract.")
        return []
    if operation == "reconstruct":
        method = str(properties.get("method") or "")
        input_points = trace.get("input_points")
        method_trace = trace.get("method_trace")
        if (
            trace.get("method") != method
            or trace.get("output_type") != definition.get("output_type")
            or isinstance(input_points, bool)
            or type(input_points) is not int
            or input_points < 2
            or (source_point_count is not None and input_points != source_point_count)
            or not isinstance(method_trace, dict)
        ):
            raise ValueError(f"{context} changed its reconstruction contract.")
        parameters = dict(properties.get("parameters") or {})
        if method == "structured_grid":
            if set(method_trace) != {
                "grid_size",
                "diagonal",
                "forward_cells",
                "backward_cells",
            }:
                raise ValueError(f"{context}.method_trace has malformed fields.")
            grid_size = method_trace.get("grid_size")
            if (
                not isinstance(grid_size, list)
                or len(grid_size) != 2
                or any(type(value) is not int or value < 2 for value in grid_size)
                or input_points != grid_size[0] * grid_size[1]
                or method_trace.get("diagonal") != parameters.get("diagonal")
                or (
                    parameters.get("grid_size") is not None
                    and grid_size != parameters["grid_size"]
                )
            ):
                raise ValueError(f"{context}.method_trace changed its grid contract.")
            forward = method_trace.get("forward_cells")
            backward = method_trace.get("backward_cells")
            cell_count = (grid_size[0] - 1) * (grid_size[1] - 1)
            if (
                isinstance(forward, bool)
                or type(forward) is not int
                or forward < 0
                or isinstance(backward, bool)
                or type(backward) is not int
                or backward < 0
                or forward + backward != cell_count
            ):
                raise ValueError(f"{context}.method_trace changed its cell counts.")
        elif (
            set(method_trace) != {"method", "used_source_normals", "parameters"}
            or method_trace.get("method") != method
            or type(method_trace.get("used_source_normals")) is not bool
            or method_trace.get("parameters") != parameters
        ):
            raise ValueError(f"{context}.method_trace changed its native method.")
        return []

    from vibescript_meshpart_worker import _bounded_segments

    method = str(properties.get("method") or "")
    facet_count = int(geometry.CountFacets)
    integers = {}
    for name in ("source_facets", "segment_count", "retained_facets"):
        value = trace.get(name)
        if isinstance(value, bool) or type(value) is not int or value < 0:
            raise ValueError(f"{context}.{name} must be a non-negative integer.")
        integers[name] = value
    sizes = trace.get("segment_sizes")
    truncated = trace.get("segment_sizes_truncated")
    if (
        trace.get("method") != method
        or not isinstance(sizes, list)
        or len(sizes) > 256
        or any(type(value) is not int or value < 1 for value in sizes)
        or type(truncated) is not bool
        or len(sizes) != min(integers["segment_count"], 256)
        or truncated is not (integers["segment_count"] > 256)
        or integers["retained_facets"] != facet_count
        or integers["source_facets"] < facet_count
    ):
        raise ValueError(f"{context} changed its segmentation counts.")
    published = _bounded_segments(
        trace.get("published_segments"),
        facet_count=facet_count,
        context=f"{context}.published_segments",
    )
    flattened = [facet for segment in published for facet in segment]
    if len(flattened) != len(set(flattened)) or set(flattened) != set(
        range(facet_count)
    ):
        raise ValueError(
            f"{context}.published_segments must partition every output facet exactly once."
        )
    selector = dict(properties.get("parameters") or {}).get("segment")
    selected = trace.get("selected_segment")
    expected_published_count = integers["segment_count"] if selector == "all" else 1
    if (
        selected != selector
        or len(published) != expected_published_count
        or (
            selector == "all" and [len(segment) for segment in published[:256]] != sizes
        )
        or (
            isinstance(selector, int)
            and selector < len(sizes)
            and len(published[0]) != sizes[selector]
        )
    ):
        raise ValueError(f"{context} changed its segment selection.")
    return published


def _validate_reverse_engineering_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    """Reauthorize native algorithms, artifacts, facts, and fit reports."""

    from vibescript_reverse_engineering_worker import (
        VALIDATION_SCHEMA,
        compute_fit_metrics,
        mesh_fingerprint,
        native_capabilities,
        validate_reverse_definition,
    )

    validation = execution.get("reverse_engineering_validation")
    fields = {"schema", "output_count", "native_capabilities", "outputs"}
    if not isinstance(validation, dict) or set(validation) != fields:
        raise ValueError(
            "The Reverse Engineering worker validation summary has malformed fields."
        )
    if validation.get("schema") != VALIDATION_SCHEMA:
        raise ValueError("The Reverse Engineering validation schema is unsupported.")
    capabilities = validation.get("native_capabilities")
    observed_capabilities = native_capabilities()
    if capabilities != observed_capabilities:
        raise ValueError(
            "Reverse Engineering native capabilities changed between worker and host."
        )
    definitions = []
    outputs_by_definition: dict[str, Mapping[str, Any]] = {}
    for declaration, item in zip(prepared["expected_outputs"], outputs):
        name = str(declaration["name"])
        definition = validate_reverse_definition(
            item.get("definition"),
            expected_output_type=str(declaration["type"]),
            require_domain_value=False,
            context=f"outputs.{name}.definition",
        )
        item["definition"] = definition
        definitions.append(definition)
        outputs_by_definition[_reverse_definition_key(definition)] = item
    expected_summaries = []
    for declaration, definition, item in zip(
        prepared["expected_outputs"], definitions, outputs
    ):
        name = str(declaration["name"])
        output_type = str(declaration["type"])
        operation = str(definition["operation"])
        data = item.get("reverse_data")
        if output_type == "fit_metrics":
            data_fields = {
                "schema",
                "operation",
                "label",
                "target_output",
                "target_operation",
                "target_output_type",
                "fit_metrics",
            }
            if not isinstance(data, dict) or set(data) != data_fields:
                raise ValueError(
                    f"Reverse Engineering metrics output {name!r} has malformed data."
                )
            target_definition = definition["arguments"][0]
            target_item = outputs_by_definition.get(
                _reverse_definition_key(target_definition)
            )
            if target_item is None or target_item is item:
                raise ValueError(
                    f"Reverse Engineering metrics output {name!r} has no returned target."
                )
            target_name = str(target_item.get("name") or "")
            target_operation = str(target_definition.get("operation") or "")
            target_type = str(target_definition.get("output_type") or "")
            metrics = _validate_reverse_metrics(
                data.get("fit_metrics"),
                context=f"outputs.{name}.fit_metrics",
            )
            if (
                data.get("schema") != VALIDATION_SCHEMA
                or data.get("operation") != "fit_metrics"
                or data.get("label")
                != str(definition["properties"].get("label") or name)
                or data.get("target_output") != target_name
                or data.get("target_operation") != target_operation
                or data.get("target_output_type") != target_type
                or not math.isclose(
                    float(metrics["tolerance"]),
                    float(definition["properties"]["tolerance"]),
                    rel_tol=0.0,
                    abs_tol=1.0e-12,
                )
            ):
                raise ValueError(
                    f"Reverse Engineering metrics output {name!r} changed its target contract."
                )
            source_points = _reverse_source_points(
                prepared,
                target_definition,
                outputs_by_definition,
            )
            geometry = target_item.get("detached_mesh")
            if geometry is None:
                geometry = target_item.get("detached_shape")
            if source_points is not None and geometry is not None:
                target_data = target_item.get("reverse_data")
                trace = (
                    target_data.get("operation_trace")
                    if isinstance(target_data, Mapping)
                    else {}
                )
                if not isinstance(trace, Mapping):
                    trace = {}
                recomputed = compute_fit_metrics(
                    geometry,
                    "mesh" if target_type == "mesh" else "brep",
                    source_points,
                    tolerance=float(metrics["tolerance"]),
                    source_facet_count=int(trace.get("source_facets") or 0),
                    retained_facets=int(
                        trace.get("retained_facets")
                        or (int(geometry.CountFacets) if target_type == "mesh" else 0)
                    ),
                    segment_count=int(trace.get("segment_count") or 0),
                )
                _mesh_values_match(
                    metrics,
                    recomputed,
                    path=f"outputs.{name}.fit_metrics",
                )
            expected_summary = {
                "name": name,
                "type": output_type,
                "operation": "fit_metrics",
                "target_output": target_name,
                "geometry_fingerprint": "",
                "fit_metrics": metrics,
            }
        else:
            data_fields = {
                "schema",
                "operation",
                "label",
                "source",
                "artifact_sha256",
                "geometry_fingerprint",
                "operation_trace",
                "fit_metrics",
                "facts",
            }
            if not isinstance(data, dict) or set(data) != data_fields:
                raise ValueError(
                    f"Reverse Engineering output {name!r} has malformed native data."
                )
            expected_label = str(definition["properties"].get("label") or name)
            if (
                data.get("schema") != VALIDATION_SCHEMA
                or data.get("operation") != operation
                or data.get("label") != expected_label
            ):
                raise ValueError(
                    f"Reverse Engineering output {name!r} changed its operation or label."
                )
            _validate_definition_value(
                data.get("source"), prepared, f"outputs.{name}.source"
            )
            trace = data.get("operation_trace")
            if not isinstance(trace, dict) or trace.get("operation") != operation:
                raise ValueError(
                    f"Reverse Engineering output {name!r} has an inconsistent trace."
                )
            metrics = _validate_reverse_metrics(
                data.get("fit_metrics"),
                context=f"outputs.{name}.fit_metrics",
            )
            if output_type == "mesh":
                from vibescript_mesh_worker import mesh_diagnostics

                geometry = item.get("detached_mesh")
                if geometry is None:
                    raise ValueError(
                        f"Reverse Engineering mesh output {name!r} has no native Mesh."
                    )
                facts = mesh_diagnostics(geometry)
                fingerprint = mesh_fingerprint(geometry)
                artifact_digest = str(item.get("artifact_sha256") or "")
            else:
                geometry = item.get("detached_shape")
                if geometry is None:
                    raise ValueError(
                        f"Reverse Engineering BREP output {name!r} has no native Shape."
                    )
                facts = dict(item.get("facts") or {})
                path = _staged_artifact_path(
                    prepared,
                    item.get("artifact_path"),
                    context=f"Reverse Engineering output {name!r}",
                )
                artifact_digest = _sha256_file(path)
                fingerprint = artifact_digest
                if output_type == "curve" and (
                    int(facts.get("edges") or 0) < 1
                    or int(facts.get("faces") or 0) != 0
                ):
                    raise ValueError(
                        f"Reverse Engineering curve output {name!r} is not edge topology."
                    )
                if output_type == "surface" and int(facts.get("faces") or 0) < 1:
                    raise ValueError(
                        f"Reverse Engineering surface output {name!r} has no face."
                    )
            if (
                data.get("artifact_sha256") != artifact_digest
                or data.get("geometry_fingerprint") != fingerprint
            ):
                raise ValueError(
                    f"Reverse Engineering output {name!r} artifact identity changed."
                )
            _mesh_values_match(
                data.get("facts"),
                {
                    key: value
                    for key, value in facts.items()
                    if key != "artifact_shape_type"
                },
                path=f"outputs.{name}.facts",
            )
            source_points = _reverse_source_points(
                prepared,
                definition,
                outputs_by_definition,
            )
            published_segments = _validate_reverse_trace(
                definition,
                trace,
                output_name=name,
                geometry=geometry,
                source_point_count=(
                    len(source_points) if source_points is not None else None
                ),
            )
            if output_type == "mesh" and published_segments:
                existing_segments = [
                    [int(value) for value in list(geometry.getSegment(index) or [])]
                    for index in range(int(geometry.countSegments()))
                ]
                if existing_segments and existing_segments != published_segments:
                    raise ValueError(
                        f"Reverse Engineering output {name!r} artifact segment groups changed."
                    )
                if not existing_segments:
                    for segment in published_segments:
                        geometry.addSegment(segment)
                restored_segments = [
                    [int(value) for value in list(geometry.getSegment(index) or [])]
                    for index in range(int(geometry.countSegments()))
                ]
                if restored_segments != published_segments:
                    raise ValueError(
                        f"Reverse Engineering output {name!r} could not restore "
                        "authenticated segment groups."
                    )
            if source_points is not None:
                recomputed = compute_fit_metrics(
                    geometry,
                    "mesh" if output_type == "mesh" else "brep",
                    source_points,
                    tolerance=float(metrics["tolerance"]),
                    source_facet_count=int(trace.get("source_facets") or 0),
                    retained_facets=int(
                        trace.get("retained_facets")
                        or (int(geometry.CountFacets) if output_type == "mesh" else 0)
                    ),
                    segment_count=int(trace.get("segment_count") or 0),
                )
                _mesh_values_match(
                    metrics,
                    recomputed,
                    path=f"outputs.{name}.fit_metrics",
                )
            item["facts"] = facts
            expected_summary = {
                "name": name,
                "type": output_type,
                "operation": operation,
                "target_output": "",
                "geometry_fingerprint": fingerprint,
                "fit_metrics": metrics,
            }
        _validate_definition_value(data, prepared, f"outputs.{name}.reverse_data")
        item["reverse_data"] = data
        expected_summaries.append(expected_summary)
    _mesh_values_match(
        validation.get("outputs"),
        expected_summaries,
        path="reverse_engineering_validation.outputs",
    )
    if validation.get("output_count") != len(outputs):
        raise ValueError(
            "The Reverse Engineering worker reported an inconsistent output count."
        )
    return dict(validation)


def _inspection_source_identity(
    prepared: Mapping[str, Any],
    reference: Any,
    *,
    context: str,
) -> dict[str, Any]:
    if not isinstance(reference, Mapping) or set(reference) != {
        "document_uid",
        "object_name",
    }:
        raise ValueError(f"{context} must be one stable document reference.")
    key = (
        str(reference.get("document_uid") or ""),
        str(reference.get("object_name") or ""),
    )
    metadata = next(
        (
            item
            for item in list(prepared.get("resolved_references") or [])
            if (
                str(item.get("document_uid") or ""),
                str(item.get("object_name") or ""),
            )
            == key
        ),
        None,
    )
    if not isinstance(metadata, Mapping):
        raise ValueError(f"{context} uses unauthenticated object {key[1]!r}.")
    artifact_kind = str(metadata.get("artifact_kind") or "")
    digest_field = {
        "brep": "brep_sha256",
        "mesh_bms": "mesh_sha256",
        "points_asc": "artifact_sha256",
    }.get(artifact_kind)
    native_type = {
        "brep": "Part::Feature",
        "mesh_bms": "Mesh::Feature",
        "points_asc": "Points::Feature",
    }.get(artifact_kind)
    if digest_field is None or native_type is None:
        raise ValueError(
            f"{context} has unsupported authenticated artifact kind {artifact_kind!r}."
        )
    digest = str(metadata.get(digest_field) or "")
    if not re.fullmatch(r"[0-9a-f]{64}", digest):
        raise ValueError(f"{context} has no authenticated artifact digest.")
    return {
        "document_uid": key[0],
        "object_name": key[1],
        "artifact_kind": artifact_kind,
        "artifact_sha256": digest,
        "source_type_id": str(metadata.get("type_id") or ""),
        "worker_native_type": native_type,
    }


def _inspection_distances(
    prepared: Mapping[str, Any],
    item: Mapping[str, Any],
    *,
    output_name: str,
) -> list[float]:
    from vibescript_inspection_worker import DISTANCE_SCHEMA

    count = item.get("distance_count")
    artifact_bytes = item.get("artifact_bytes")
    if (
        isinstance(count, bool)
        or type(count) is not int
        or not 1 <= count <= _MAX_REFERENCE_POINTS
        or isinstance(artifact_bytes, bool)
        or type(artifact_bytes) is not int
        or artifact_bytes != count * 4
        or item.get("artifact_kind") != "inspection_distances_f32le"
        or item.get("artifact_schema") != DISTANCE_SCHEMA
    ):
        raise ValueError(
            f"Inspection output {output_name!r} has malformed distance metadata."
        )
    path = _staged_artifact_path(
        prepared,
        item.get("artifact_path"),
        context=f"Inspection output {output_name!r} distances",
        maximum_bytes=_MAX_REFERENCE_POINTS * 4,
    )
    if path.stat().st_size != artifact_bytes:
        raise ValueError(
            f"Inspection output {output_name!r} distance artifact changed size."
        )
    digest = _sha256_file(path)
    if digest != item.get("artifact_sha256"):
        raise ValueError(f"Inspection output {output_name!r} distance SHA-256 changed.")
    values = array("f")
    try:
        with path.open("rb") as handle:
            values.fromfile(handle, count)
            if handle.read(1):
                raise ValueError(
                    f"Inspection output {output_name!r} has trailing distance bytes."
                )
    except EOFError as exc:
        raise ValueError(
            f"Inspection output {output_name!r} distance artifact ended early."
        ) from exc
    if len(values) != count:
        raise ValueError(
            f"Inspection output {output_name!r} has the wrong distance count."
        )
    if sys.byteorder != "little":
        values.byteswap()
    result = [float(value) for value in values]
    if any(not math.isfinite(value) for value in result):
        raise ValueError(
            f"Inspection output {output_name!r} contains non-finite distances."
        )
    return result


def _inspection_measurement_value(
    summary: Mapping[str, Any], metric: str
) -> tuple[float, str]:
    if metric in {"measured_count", "unmeasured_count"}:
        return float(int(summary[metric])), "count"
    value = summary.get(metric)
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"Inspection metric {metric!r} is unavailable or invalid.")
    return (
        float(value),
        "ratio" if metric == "within_tolerance_fraction" else "mm",
    )


def _validate_inspection_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    """Reauthorize native Inspection graphs, artifacts, and summaries."""

    from vibescript_inspection_worker import (
        VALIDATION_SCHEMA,
        summarize_distances,
        validate_inspection_definition,
    )

    validation = execution.get("inspection_validation")
    if not isinstance(validation, dict) or set(validation) != {
        "schema",
        "output_count",
        "reference_count",
        "outputs",
    }:
        raise ValueError(
            "The Inspection worker validation summary has malformed fields."
        )
    if validation.get("schema") != VALIDATION_SCHEMA:
        raise ValueError("The Inspection worker validation schema is unsupported.")
    definitions: dict[str, dict[str, Any]] = {}
    output_by_key: dict[str, dict[str, Any]] = {}
    for declaration, item in zip(prepared["expected_outputs"], outputs):
        name = str(declaration["name"])
        definition = validate_inspection_definition(
            item.get("definition"),
            expected_output_type=str(declaration["type"]),
            require_domain_value=False,
            context=f"outputs.{name}.definition",
        )
        key = _definition_sha256(definition)
        if key in output_by_key:
            raise ValueError(
                f"Inspection outputs {output_by_key[key]['name']!r} and {name!r} "
                "have duplicate definitions."
            )
        item["definition"] = definition
        definitions[name] = definition
        output_by_key[key] = item

    expected_summaries = []
    for declaration, item in zip(prepared["expected_outputs"], outputs):
        name = str(declaration["name"])
        output_type = str(declaration["type"])
        definition = definitions[name]
        operation = str(definition["operation"])
        properties = dict(definition["properties"])
        data = item.get("inspection_data")
        if not isinstance(data, dict):
            raise ValueError(f"Inspection output {name!r} has no native data.")
        label = str(properties.get("label") or name)
        if (
            data.get("schema") != VALIDATION_SCHEMA
            or data.get("operation") != operation
        ):
            raise ValueError(f"Inspection output {name!r} changed schema or operation.")
        if data.get("label") != label:
            raise ValueError(f"Inspection output {name!r} changed its label.")
        artifact_digest = ""
        if operation == "comparison":
            expected_item_fields = {
                "name",
                "type",
                "definition",
                "inspection_data",
                "artifact_kind",
                "artifact_schema",
                "artifact_path",
                "artifact_sha256",
                "artifact_bytes",
                "distance_count",
            }
            data_fields = {
                "schema",
                "operation",
                "label",
                "actual",
                "nominals",
                "search_radius",
                "thickness",
                "tolerance",
                "require_complete",
                "distance_summary",
                "passed",
                "native_trace",
            }
            if set(item) != expected_item_fields or set(data) != data_fields:
                raise ValueError(
                    f"Inspection comparison {name!r} has malformed fields."
                )
            actual = _inspection_source_identity(
                prepared,
                definition["arguments"][0],
                context=f"outputs.{name}.actual",
            )
            nominals = [
                _inspection_source_identity(
                    prepared,
                    reference,
                    context=f"outputs.{name}.nominals[{index}]",
                )
                for index, reference in enumerate(definition["arguments"][1])
            ]
            tolerance = [float(value) for value in properties["tolerance"]]
            if (
                data.get("actual") != actual
                or data.get("nominals") != nominals
                or data.get("search_radius") != float(properties["search_radius"])
                or data.get("thickness") != float(properties["thickness"])
                or data.get("tolerance") != tolerance
                or data.get("require_complete")
                is not bool(properties["require_complete"])
            ):
                raise ValueError(
                    f"Inspection comparison {name!r} changed its reference or tolerance contract."
                )
            distances = _inspection_distances(prepared, item, output_name=name)
            summary = summarize_distances(
                distances,
                tolerance=tolerance,
                require_complete=bool(properties["require_complete"]),
            )
            if data.get("distance_summary") != summary or data.get(
                "passed"
            ) is not bool(summary["passed"]):
                raise ValueError(
                    f"Inspection comparison {name!r} distance summary is inconsistent."
                )
            trace = data.get("native_trace")
            if not isinstance(trace, dict) or set(trace) != {
                "engine",
                "type_id",
                "actual_type",
                "nominal_types",
                "distance_count",
                "recomputed_object_count",
            }:
                raise ValueError(
                    f"Inspection comparison {name!r} native trace is malformed."
                )
            recomputed = trace.get("recomputed_object_count")
            if (
                trace.get("engine") != "Inspection::Feature"
                or trace.get("type_id") != "Inspection::Feature"
                or trace.get("actual_type") != actual["worker_native_type"]
                or trace.get("nominal_types")
                != [value["worker_native_type"] for value in nominals]
                or trace.get("distance_count") != len(distances)
                or isinstance(recomputed, bool)
                or type(recomputed) is not int
                or recomputed < 1
            ):
                raise ValueError(
                    f"Inspection comparison {name!r} native trace changed."
                )
            artifact_digest = str(item["artifact_sha256"])
            item["detached_distances"] = distances
        elif operation == "group":
            if set(item) != {"name", "type", "definition", "inspection_data"} or set(
                data
            ) != {
                "schema",
                "operation",
                "label",
                "member_outputs",
                "comparison_count",
                "passed_count",
                "failed_count",
                "passed",
                "native_trace",
            }:
                raise ValueError(f"Inspection group {name!r} has malformed fields.")
            members = []
            for member in definition["arguments"][0]:
                target = output_by_key.get(_definition_sha256(member))
                if target is None or target.get("type") != "inspection_feature":
                    raise ValueError(
                        f"Inspection group {name!r} has an undeclared comparison member."
                    )
                members.append(target)
            member_names = [str(member["name"]) for member in members]
            member_passes = [
                bool(member["inspection_data"]["distance_summary"]["passed"])
                for member in members
            ]
            passed_count = sum(member_passes)
            expected = {
                "member_outputs": member_names,
                "comparison_count": len(members),
                "passed_count": passed_count,
                "failed_count": len(members) - passed_count,
                "passed": passed_count == len(members),
            }
            if any(data.get(key) != value for key, value in expected.items()):
                raise ValueError(f"Inspection group {name!r} aggregate changed.")
            trace = data.get("native_trace")
            if trace != {
                "engine": "Inspection::Group",
                "type_id": "Inspection::Group",
                "member_count": len(members),
            }:
                raise ValueError(f"Inspection group {name!r} native trace changed.")
        elif operation == "measurement":
            if set(item) != {"name", "type", "definition", "inspection_data"} or set(
                data
            ) != {
                "schema",
                "operation",
                "label",
                "target_output",
                "metric",
                "value",
                "unit",
                "passed",
                "native_trace",
            }:
                raise ValueError(
                    f"Inspection measurement {name!r} has malformed fields."
                )
            target = output_by_key.get(_definition_sha256(definition["arguments"][0]))
            if target is None or target.get("type") != "inspection_feature":
                raise ValueError(
                    f"Inspection measurement {name!r} has an undeclared comparison target."
                )
            metric = str(properties["metric"])
            target_summary = target["inspection_data"]["distance_summary"]
            value, unit = _inspection_measurement_value(target_summary, metric)
            if (
                data.get("target_output") != target["name"]
                or data.get("metric") != metric
                or data.get("value") != value
                or data.get("unit") != unit
                or data.get("passed") is not bool(target_summary["passed"])
                or data.get("native_trace")
                != {
                    "engine": "App::FeaturePython",
                    "type_id": "App::FeaturePython",
                    "metric": metric,
                    "value": value,
                    "unit": unit,
                }
            ):
                raise ValueError(
                    f"Inspection measurement {name!r} native value changed."
                )
        else:
            if set(item) != {"name", "type", "definition", "inspection_data"} or set(
                data
            ) != {
                "schema",
                "operation",
                "label",
                "group_output",
                "comparison_count",
                "passed_count",
                "failed_count",
                "passed",
                "entries",
                "native_trace",
            }:
                raise ValueError(f"Inspection report {name!r} has malformed fields.")
            group = output_by_key.get(_definition_sha256(definition["arguments"][0]))
            if group is None or group.get("type") != "inspection_group":
                raise ValueError(
                    f"Inspection report {name!r} has an undeclared group target."
                )
            group_data = group["inspection_data"]
            entries = []
            for member_name in group_data["member_outputs"]:
                member = next(
                    value for value in outputs if value["name"] == member_name
                )
                member_data = member["inspection_data"]
                entries.append(
                    {
                        "output": member_name,
                        "label": member_data["label"],
                        "passed": bool(member_data["distance_summary"]["passed"]),
                        "distance_summary": dict(member_data["distance_summary"]),
                    }
                )
            expected = {
                "group_output": group["name"],
                "comparison_count": group_data["comparison_count"],
                "passed_count": group_data["passed_count"],
                "failed_count": group_data["failed_count"],
                "passed": group_data["passed"],
                "entries": entries,
            }
            if any(data.get(key) != value for key, value in expected.items()):
                raise ValueError(f"Inspection report {name!r} aggregate changed.")
            if data.get("native_trace") != {
                "engine": "App::FeaturePython",
                "type_id": "App::FeaturePython",
                "comparison_count": group_data["comparison_count"],
                "passed": group_data["passed"],
            }:
                raise ValueError(f"Inspection report {name!r} native trace changed.")
        _validate_definition_value(data, prepared, f"outputs.{name}.inspection_data")
        item["inspection_data"] = data
        expected_summaries.append(
            {
                "name": name,
                "type": output_type,
                "operation": operation,
                "definition_sha256": _definition_sha256(definition),
                "artifact_sha256": artifact_digest,
                "passed": bool(data.get("passed", True)),
            }
        )
    if (
        validation.get("output_count") != len(outputs)
        or validation.get("reference_count")
        != len(list(prepared.get("resolved_references") or []))
        or validation.get("outputs") != expected_summaries
    ):
        raise ValueError(
            "The Inspection worker global validation summary is inconsistent."
        )
    return dict(validation)


def _finite_matrix(value: Any, label: str) -> list[float]:
    if not isinstance(value, list) or len(value) != 16:
        raise ValueError(f"{label} must contain exactly 16 matrix values.")
    if any(isinstance(item, bool) for item in value):
        raise ValueError(f"{label} must contain numbers, not booleans.")
    try:
        result = [float(item) for item in value]
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{label} must contain only finite matrix values.") from exc
    if not all(math.isfinite(item) for item in result):
        raise ValueError(f"{label} must contain only finite matrix values.")
    return result


def _assembly_placement_fact(value: Any, label: str) -> dict[str, Any]:
    fields = {
        "position_mm",
        "rotation_axis",
        "rotation_angle_degrees",
        "matrix",
    }
    if not isinstance(value, dict) or set(value) != fields:
        raise ValueError(
            f"{label} must contain exactly position_mm, rotation_axis, "
            "rotation_angle_degrees, and matrix."
        )
    position = _finite_vector(value.get("position_mm"), f"{label}.position_mm")
    axis = _finite_vector(value.get("rotation_axis"), f"{label}.rotation_axis")
    raw_angle = value.get("rotation_angle_degrees")
    if isinstance(raw_angle, bool):
        raise ValueError(f"{label}.rotation_angle_degrees must be finite.")
    try:
        angle = float(raw_angle)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{label}.rotation_angle_degrees must be finite.") from exc
    if not math.isfinite(angle):
        raise ValueError(f"{label}.rotation_angle_degrees must be finite.")
    return {
        "position_mm": position,
        "rotation_axis": axis,
        "rotation_angle_degrees": angle,
        "matrix": _finite_matrix(value.get("matrix"), f"{label}.matrix"),
    }


def _assembly_native_placement_from_matrix(value: Any, label: str) -> Any:
    """Build a detached FreeCAD placement from one authenticated matrix."""

    import FreeCAD as App

    values = _finite_matrix(value, label)
    matrix = App.Matrix()
    for name, number in zip(
        (
            "A11",
            "A12",
            "A13",
            "A14",
            "A21",
            "A22",
            "A23",
            "A24",
            "A31",
            "A32",
            "A33",
            "A34",
            "A41",
            "A42",
            "A43",
            "A44",
        ),
        values,
        strict=True,
    ):
        setattr(matrix, name, number)
    return App.Placement(matrix)


def _assembly_native_declared_placement(value: Any, label: str) -> Any:
    """Reauthorize the normalized placement form exported by the Assembly API."""

    import FreeCAD as App

    if not isinstance(value, dict) or set(value) != {"position", "rotation"}:
        raise ValueError(f"{label} must contain exactly position and rotation.")
    if not isinstance(value.get("position"), list) or any(
        isinstance(item, bool) for item in value["position"]
    ):
        raise ValueError(f"{label}.position must contain three finite numbers.")
    position = _finite_vector(value.get("position"), f"{label}.position")
    rotation = value.get("rotation")
    if (
        not isinstance(rotation, list)
        or len(rotation) != 4
        or any(isinstance(item, bool) for item in rotation)
    ):
        raise ValueError(f"{label}.rotation must contain four numbers.")
    try:
        quaternion = [float(item) for item in rotation]
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{label}.rotation must contain finite numbers.") from exc
    if not all(math.isfinite(item) for item in quaternion):
        raise ValueError(f"{label}.rotation must contain finite numbers.")
    magnitude = math.sqrt(sum(item * item for item in quaternion))
    if not math.isclose(magnitude, 1.0, rel_tol=0.0, abs_tol=1.0e-12):
        raise ValueError(f"{label}.rotation must be a normalized quaternion.")
    return App.Placement(App.Vector(*position), App.Rotation(*quaternion))


def _assembly_native_matrix(value: Any) -> list[float]:
    matrix = value.toMatrix()
    return [
        float(getattr(matrix, name))
        for name in (
            "A11",
            "A12",
            "A13",
            "A14",
            "A21",
            "A22",
            "A23",
            "A24",
            "A31",
            "A32",
            "A33",
            "A34",
            "A41",
            "A42",
            "A43",
            "A44",
        )
    ]


def _assembly_close_numbers(
    observed: Sequence[Any],
    expected: Sequence[Any],
    label: str,
    *,
    absolute_tolerance: float = 1.0e-8,
) -> list[float]:
    if any(isinstance(item, bool) for item in (*observed, *expected)):
        raise ValueError(f"{label} must contain numbers, not booleans.")
    try:
        actual = [float(item) for item in observed]
        wanted = [float(item) for item in expected]
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{label} must contain finite numbers.") from exc
    if len(actual) != len(wanted) or not all(
        math.isfinite(item) for item in (*actual, *wanted)
    ):
        raise ValueError(f"{label} has invalid numeric cardinality or values.")
    if any(
        not math.isclose(
            left,
            right,
            rel_tol=1.0e-10,
            abs_tol=absolute_tolerance,
        )
        for left, right in zip(actual, wanted, strict=True)
    ):
        raise ValueError(f"{label} disagrees with independently derived native state.")
    return actual


def _assembly_placement_delta(
    initial: Mapping[str, Any],
    solved: Mapping[str, Any],
    value: Any,
    label: str,
) -> dict[str, Any]:
    """Reauthorize an exact authored-to-solved Assembly placement delta."""

    fields = {
        "translation_mm",
        "translation_distance_mm",
        "rotation_degrees",
    }
    if not isinstance(value, dict) or set(value) != fields:
        raise ValueError(
            f"{label} must contain exactly translation_mm, "
            "translation_distance_mm, and rotation_degrees."
        )
    initial_native = _assembly_native_placement_from_matrix(
        initial["matrix"], f"{label} initial matrix"
    )
    solved_native = _assembly_native_placement_from_matrix(
        solved["matrix"], f"{label} solved matrix"
    )
    expected_translation = [
        float(solved_native.Base[index] - initial_native.Base[index])
        for index in range(3)
    ]
    translation = _assembly_close_numbers(
        value.get("translation_mm"),
        expected_translation,
        f"{label}.translation_mm",
    )
    expected_distance = math.sqrt(sum(number * number for number in expected_translation))
    distance = _assembly_close_numbers(
        [value.get("translation_distance_mm")],
        [expected_distance],
        f"{label}.translation_distance_mm",
    )[0]
    initial_quaternion = [float(number) for number in initial_native.Rotation.Q]
    solved_quaternion = [float(number) for number in solved_native.Rotation.Q]
    dot = abs(
        sum(
            initial_quaternion[index] * solved_quaternion[index]
            for index in range(4)
        )
    )
    expected_rotation = math.degrees(2.0 * math.acos(max(-1.0, min(1.0, dot))))
    rotation = _assembly_close_numbers(
        [value.get("rotation_degrees")],
        [expected_rotation],
        f"{label}.rotation_degrees",
        absolute_tolerance=1.0e-7,
    )[0]
    return {
        "translation_mm": translation,
        "translation_distance_mm": distance,
        "rotation_degrees": rotation,
    }


def _assembly_validate_placement_fact(
    value: Any,
    expected: Any,
    label: str,
) -> dict[str, Any]:
    fact = _assembly_placement_fact(value, label)
    _assembly_close_numbers(
        fact["matrix"],
        _assembly_native_matrix(expected),
        f"{label}.matrix",
    )
    _assembly_close_numbers(
        fact["position_mm"],
        [expected.Base.x, expected.Base.y, expected.Base.z],
        f"{label}.position_mm",
    )
    _assembly_close_numbers(
        fact["rotation_axis"],
        [
            expected.Rotation.Axis.x,
            expected.Rotation.Axis.y,
            expected.Rotation.Axis.z,
        ],
        f"{label}.rotation_axis",
    )
    _assembly_close_numbers(
        [fact["rotation_angle_degrees"]],
        [math.degrees(float(expected.Rotation.Angle))],
        f"{label}.rotation_angle_degrees",
    )
    return fact


def _assembly_compatibility(
    kind: str, connector_contracts: Sequence[Mapping[str, Any] | None]
) -> dict[str, Any]:
    from vibescript_assembly_api import explicit_connector_compatibility

    return explicit_connector_compatibility(kind, connector_contracts)


def _assembly_frame_z_axis(frame: Mapping[str, Any]) -> tuple[float, float, float]:
    matrix = _finite_matrix(frame.get("matrix"), "Assembly connector local frame")
    return (matrix[2], matrix[6], matrix[10])


def _assembly_parallel_axes(
    first: Mapping[str, Any], second: Mapping[str, Any]
) -> bool:
    axis1 = _assembly_frame_z_axis(first)
    axis2 = _assembly_frame_z_axis(second)
    norm1 = math.sqrt(sum(item * item for item in axis1))
    norm2 = math.sqrt(sum(item * item for item in axis2))
    if norm1 <= 1.0e-12 or norm2 <= 1.0e-12:
        return False
    dot = sum(a * b for a, b in zip(axis1, axis2, strict=True)) / (norm1 * norm2)
    return abs(dot) >= 1.0 - 1.0e-7


def _assembly_joint_dependency_issues(
    joint_data: Mapping[str, Mapping[str, Any]],
) -> list[dict[str, Any]]:
    sliders = [
        (name, data)
        for name, data in joint_data.items()
        if data.get("kind") == "slider" and not bool(data.get("suppressed"))
    ]
    issues: list[dict[str, Any]] = []
    for name, data in joint_data.items():
        kind = str(data.get("kind") or "")
        if kind not in {"rack_pinion", "screw"} or bool(data.get("suppressed")):
            continue
        connectors = list(data.get("connectors") or [])
        compatible_slider = None
        for slider_name, slider_data in sliders:
            slider_connectors = list(slider_data.get("connectors") or [])
            if any(
                connector.get("component_output")
                == slider_connector.get("component_output")
                and _assembly_parallel_axes(
                    dict(connector.get("local_frame") or {}),
                    dict(slider_connector.get("local_frame") or {}),
                )
                for connector in connectors
                for slider_connector in slider_connectors
            ):
                compatible_slider = slider_name
                break
        if compatible_slider is None:
            issues.append(
                {
                    "code": "missing_collinear_slider",
                    "joint_output": name,
                    "joint_type": kind,
                    "component_outputs": [
                        str(item.get("component_output") or "") for item in connectors
                    ],
                    "available_slider_outputs": [item[0] for item in sliders],
                    "requirement": (
                        "FreeCAD's native RackPinion and Screw joints require a "
                        "non-suppressed Slider joint sharing one component with a "
                        "collinear local connector +Z axis."
                    ),
                    "suggestion": (
                        "Create and return an api.joint('slider', ...) for the rack "
                        "or screw component, align both connector +Z axes, and include "
                        "both joints in api.assembly."
                    ),
                }
            )
    return issues


def _assembly_limits(value: Any, label: str) -> list[float | None] | None:
    if value is None:
        return None
    if not isinstance(value, list) or len(value) != 2:
        raise ValueError(f"{label} must be null or a two-endpoint array.")
    result: list[float | None] = []
    for index, item in enumerate(value):
        if item is None:
            result.append(None)
            continue
        if isinstance(item, bool):
            raise ValueError(f"{label}[{index}] must be a finite number or null.")
        number = float(item)
        if not math.isfinite(number):
            raise ValueError(f"{label}[{index}] must be finite.")
        result.append(number)
    if result == [None, None]:
        raise ValueError(f"{label} cannot disable both endpoints; use null instead.")
    if result[0] is not None and result[1] is not None and result[0] > result[1]:
        raise ValueError(f"{label} minimum must not exceed maximum.")
    return result


def _assembly_motion_formula(value: Any, label: str) -> str:
    if (
        not isinstance(value, str)
        or not value
        or len(value) > 512
        or not value.isascii()
    ):
        raise ValueError(
            f"{label} must be a non-empty ASCII expression of at most 512 characters."
        )
    if "**" in value:
        raise ValueError(f"{label} must use canonical native '^' power syntax.")
    try:
        tree = ast.parse(value.replace("^", "**"), mode="eval")
    except SyntaxError as exc:
        raise ValueError(f"{label} has invalid expression syntax.") from exc
    nodes = list(ast.walk(tree))
    if len(nodes) > 128:
        raise ValueError(f"{label} exceeds the expression complexity limit.")
    functions = {"abs", "asin", "arcsin", "arctan", "cos", "sin"}
    names = {"time", "initialValue", "pi"} | functions
    allowed = (
        ast.Expression,
        ast.BinOp,
        ast.UnaryOp,
        ast.Call,
        ast.Name,
        ast.Load,
        ast.Constant,
        ast.Add,
        ast.Sub,
        ast.Mult,
        ast.Div,
        ast.Pow,
        ast.UAdd,
        ast.USub,
    )
    for node in nodes:
        if not isinstance(node, allowed):
            raise ValueError(
                f"{label} contains unsupported expression element "
                f"{type(node).__name__}."
            )
        if isinstance(node, ast.Constant) and (
            isinstance(node.value, bool)
            or not isinstance(node.value, (int, float))
            or not math.isfinite(float(node.value))
        ):
            raise ValueError(f"{label} contains an invalid numeric constant.")
        if isinstance(node, ast.Name) and node.id not in names:
            raise ValueError(f"{label} contains unknown name {node.id!r}.")
        if isinstance(node, ast.Call) and (
            not isinstance(node.func, ast.Name)
            or node.func.id not in functions
            or len(node.args) != 1
            or node.keywords
        ):
            raise ValueError(f"{label} contains an unsupported function call.")
    return value


def _assembly_compact_placement(value: Any, label: str) -> dict[str, list[float]]:
    if not isinstance(value, dict) or set(value) != {
        "position_mm",
        "rotation_xyzw",
    }:
        raise ValueError(f"{label} must contain exactly position_mm and rotation_xyzw.")
    position = value.get("position_mm")
    rotation = value.get("rotation_xyzw")
    if not isinstance(position, list) or len(position) != 3:
        raise ValueError(f"{label}.position_mm must contain three numbers.")
    if not isinstance(rotation, list) or len(rotation) != 4:
        raise ValueError(f"{label}.rotation_xyzw must contain four numbers.")
    try:
        clean_position = [float(item) for item in position]
        clean_rotation = [float(item) for item in rotation]
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{label} must contain only finite numbers.") from exc
    if not all(math.isfinite(item) for item in (*clean_position, *clean_rotation)):
        raise ValueError(f"{label} must contain only finite numbers.")
    magnitude = math.sqrt(sum(item * item for item in clean_rotation))
    if not math.isclose(magnitude, 1.0, rel_tol=1.0e-10, abs_tol=1.0e-10):
        raise ValueError(f"{label}.rotation_xyzw must be normalized.")
    return {"position_mm": clean_position, "rotation_xyzw": clean_rotation}


def _assembly_quaternion_multiply(
    first: list[float], second: list[float]
) -> list[float]:
    x1, y1, z1, w1 = first
    x2, y2, z2, w2 = second
    return [
        w1 * x2 + x1 * w2 + y1 * z2 - z1 * y2,
        w1 * y2 - x1 * z2 + y1 * w2 + z1 * x2,
        w1 * z2 + x1 * y2 - y1 * x2 + z1 * w2,
        w1 * w2 - x1 * x2 - y1 * y2 - z1 * z2,
    ]


def _assembly_quaternion_rotate(
    quaternion: list[float], vector: list[float]
) -> list[float]:
    rotated = _assembly_quaternion_multiply(
        _assembly_quaternion_multiply(quaternion, [*vector, 0.0]),
        [-quaternion[0], -quaternion[1], -quaternion[2], quaternion[3]],
    )
    return rotated[:3]


def _assembly_relative_compact_placement(
    first: Mapping[str, Any], second: Mapping[str, Any]
) -> tuple[list[float], list[float]]:
    first_position = list(first["position_mm"])
    second_position = list(second["position_mm"])
    first_rotation = list(first["rotation_xyzw"])
    second_rotation = list(second["rotation_xyzw"])
    inverse = [
        -first_rotation[0],
        -first_rotation[1],
        -first_rotation[2],
        first_rotation[3],
    ]
    relative_position = _assembly_quaternion_rotate(
        inverse,
        [second_position[index] - first_position[index] for index in range(3)],
    )
    relative_rotation = _assembly_quaternion_multiply(inverse, second_rotation)
    magnitude = math.sqrt(sum(value * value for value in relative_rotation))
    return relative_position, [value / magnitude for value in relative_rotation]


def _assembly_motion_observations(
    frames: list[dict[str, Any]],
    motion_records: list[dict[str, Any]],
    joint_records: Mapping[str, Mapping[str, Any]],
) -> list[dict[str, Any]]:
    observations: list[dict[str, Any]] = []
    for record in motion_records:
        connectors = list(joint_records[str(record["joint_output"])]["connectors"])
        first_component = str(connectors[0]["component_output"])
        second_component = str(connectors[1]["component_output"])
        initial_position, initial_rotation = _assembly_relative_compact_placement(
            frames[0]["component_placements"][first_component],
            frames[0]["component_placements"][second_component],
        )
        maximum_translation = 0.0
        maximum_rotation = 0.0
        for frame in frames[1:]:
            position, rotation = _assembly_relative_compact_placement(
                frame["component_placements"][first_component],
                frame["component_placements"][second_component],
            )
            maximum_translation = max(
                maximum_translation,
                math.sqrt(
                    sum(
                        (position[index] - initial_position[index]) ** 2
                        for index in range(3)
                    )
                ),
            )
            dot = abs(
                sum(initial_rotation[index] * rotation[index] for index in range(4))
            )
            maximum_rotation = max(
                maximum_rotation,
                math.degrees(2.0 * math.acos(max(-1.0, min(1.0, dot)))),
            )
        observations.append(
            {
                **record,
                "component_outputs": [first_component, second_component],
                "time_dependent": bool(re.search(r"\btime\b", str(record["formula"]))),
                "maximum_relative_translation_mm": maximum_translation,
                "maximum_relative_rotation_degrees": maximum_rotation,
            }
        )
    return observations


def _validate_assembly_exploded_views(
    prepared: Mapping[str, Any],
    views: Sequence[dict[str, Any]],
    *,
    assembly_item: Mapping[str, Any],
    assembly_definition: Mapping[str, Any],
    by_name: Mapping[str, dict[str, Any]],
    component_names: Sequence[str],
    component_placements: Mapping[str, Mapping[str, Any]],
    component_sources: Mapping[str, Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Independently derive every native exploded move from authenticated BREPs."""

    if not views:
        return []

    import FreeCAD as App
    import Part

    worker_references = {
        (
            str(item.get("document_uid") or ""),
            str(item.get("object_name") or ""),
        ): item
        for item in list(
            dict(prepared.get("worker_request") or {}).get("document_references") or []
        )
        if isinstance(item, Mapping)
    }
    source_shapes: dict[tuple[str, str], Any] = {}
    native_placements: dict[str, Any] = {}
    component_centers: dict[str, list[float]] = {}
    bounds_minimum = [math.inf, math.inf, math.inf]
    bounds_maximum = [-math.inf, -math.inf, -math.inf]
    for component_name in component_names:
        component_item = by_name[component_name]
        component_data = component_item.get("assembly_data")
        if not isinstance(component_data, Mapping):
            raise ValueError(
                f"Component output {component_name!r} has no exploded-view source data."
            )
        source = component_data.get("source")
        if not isinstance(source, Mapping):
            raise ValueError(
                f"Component output {component_name!r} has no exploded-view source identity."
            )
        key = (
            str(source.get("document_uid") or ""),
            str(source.get("object_name") or ""),
        )
        resolved = component_sources.get(component_name)
        definition = component_item.get("definition")
        operation = (
            str(definition.get("operation") or "")
            if isinstance(definition, Mapping)
            else ""
        )
        descriptor = (
            component_data.get("source_brep")
            if operation == "fastener"
            else worker_references.get(key)
        )
        if resolved is None or not isinstance(descriptor, Mapping):
            raise ValueError(
                f"Component output {component_name!r} has no authenticated staged BREP."
            )
        path = _staged_artifact_path(
            prepared,
            descriptor.get("artifact_path"),
            context=f"Component output {component_name!r} exploded-view source",
        )
        digest = _sha256_file(path)
        descriptor_digest = str(
            descriptor.get(
                "artifact_sha256" if operation == "fastener" else "brep_sha256"
            )
            or ""
        )
        resolved_digest = (
            descriptor_digest
            if operation == "fastener"
            else str(resolved.get("brep_sha256") or "")
        )
        if digest != descriptor_digest or digest != resolved_digest:
            raise ValueError(
                f"Component output {component_name!r} source BREP changed after "
                "revision binding."
            )
        shape = source_shapes.get(key)
        if shape is None:
            shape = Part.Shape()
            shape.importBrep(str(path))
            if shape.isNull() or not shape.isValid():
                raise ValueError(
                    f"Component output {component_name!r} staged BREP is invalid."
                )
            source_shapes[key] = shape
        placement = _assembly_native_placement_from_matrix(
            component_placements[component_name]["matrix"],
            f"Component output {component_name!r} solved placement",
        )
        placed_shape = shape.copy()
        # App::Link occurrences apply their own Placement to the linked
        # topological shape and deliberately do not compound the source
        # object's Placement. Mirror that native occurrence behavior exactly.
        placed_shape.Placement = placement
        bounds = placed_shape.BoundBox
        if not bool(bounds.isValid()):
            raise ValueError(
                f"Component output {component_name!r} has invalid solved bounds."
            )
        minimum = [float(bounds.XMin), float(bounds.YMin), float(bounds.ZMin)]
        maximum = [float(bounds.XMax), float(bounds.YMax), float(bounds.ZMax)]
        center = [(minimum[index] + maximum[index]) / 2.0 for index in range(3)]
        for index in range(3):
            bounds_minimum[index] = min(bounds_minimum[index], minimum[index])
            bounds_maximum[index] = max(bounds_maximum[index], maximum[index])
        native_placements[component_name] = placement
        component_centers[component_name] = center
    assembly_center = [
        (bounds_minimum[index] + bounds_maximum[index]) / 2.0 for index in range(3)
    ]
    assembly_diagonal = math.sqrt(
        sum((bounds_maximum[index] - bounds_minimum[index]) ** 2 for index in range(3))
    )
    if not math.isfinite(assembly_diagonal) or assembly_diagonal <= 1.0e-12:
        raise ValueError("The authenticated Assembly source bounds are degenerate.")

    component_index = {name: index for index, name in enumerate(component_names)}
    summaries: list[dict[str, Any]] = []
    for view_item in views:
        view_name = str(view_item["name"])
        definition = view_item.get("definition")
        if (
            not isinstance(definition, dict)
            or definition.get("domain") != "assembly"
            or definition.get("operation") != "exploded_view"
            or definition.get("output_type") != "exploded_view"
            or definition.get("arguments") != [assembly_definition]
        ):
            raise ValueError(
                f"Exploded-view output {view_name!r} does not consume the returned "
                "assembly graph."
            )
        properties = definition.get("properties")
        if (
            not isinstance(properties, dict)
            or set(properties) - {"moves", "label"}
            or "moves" not in properties
        ):
            raise ValueError(
                f"Exploded-view output {view_name!r} has malformed properties."
            )
        if "label" in properties and (
            not isinstance(properties["label"], str)
            or not properties["label"]
            or properties["label"] != properties["label"].strip()
            or len(properties["label"]) > 120
        ):
            raise ValueError(
                f"Exploded-view output {view_name!r} has an invalid normalized label."
            )
        definition_moves = properties["moves"]
        if (
            not isinstance(definition_moves, list)
            or not 1 <= len(definition_moves) <= 4096
        ):
            raise ValueError(
                f"Exploded-view output {view_name!r} must contain 1-4096 moves."
            )
        data = view_item.get("assembly_data")
        required_data_fields = {
            "schema",
            "assembly_output",
            "moves",
            "assembly_bounds",
            "final_component_placements",
            "line_count",
            "native_readback",
        }
        if not isinstance(data, dict) or set(data) != required_data_fields:
            raise ValueError(
                f"Exploded-view output {view_name!r} has malformed native evidence."
            )
        if data.get("schema") != _ASSEMBLY_EXPLODED_VIEW_SCHEMA or str(
            data.get("assembly_output") or ""
        ) != str(assembly_item["name"]):
            raise ValueError(
                f"Exploded-view output {view_name!r} has the wrong schema or assembly."
            )
        reported_bounds = data.get("assembly_bounds")
        if not isinstance(reported_bounds, dict) or set(reported_bounds) != {
            "center_mm",
            "diagonal_mm",
        }:
            raise ValueError(
                f"Exploded-view output {view_name!r} has malformed assembly bounds."
            )
        _assembly_close_numbers(
            reported_bounds["center_mm"],
            assembly_center,
            f"Exploded-view output {view_name!r} assembly center",
        )
        _assembly_close_numbers(
            [reported_bounds["diagonal_mm"]],
            [assembly_diagonal],
            f"Exploded-view output {view_name!r} assembly diagonal",
        )
        move_records = data.get("moves")
        if not isinstance(move_records, list) or len(move_records) != len(
            definition_moves
        ):
            raise ValueError(
                f"Exploded-view output {view_name!r} move evidence is incomplete."
            )
        current_placements = {
            name: placement.copy() for name, placement in native_placements.items()
        }
        expected_move_types: list[str] = []
        expected_reference_paths: list[list[str]] = []
        moved_names: list[str] = []
        reference_count = 0
        for move_index, (definition_move, record) in enumerate(
            zip(definition_moves, move_records, strict=True)
        ):
            context = f"Exploded-view output {view_name!r} move {move_index}"
            if not isinstance(definition_move, dict) or not isinstance(record, dict):
                raise ValueError(f"{context} must be an object.")
            kind = str(definition_move.get("kind") or "")
            definition_fields = (
                {"kind", "components", "transform"}
                if kind == "normal"
                else {"kind", "components", "radial_distance_mm"}
                if kind == "radial"
                else set()
            )
            record_fields = (
                {
                    "move_index",
                    "kind",
                    "component_outputs",
                    "transform",
                    "movement_transform",
                    "changed_component_outputs",
                    "final_placements",
                    "line_segments",
                }
                if kind == "normal"
                else {
                    "move_index",
                    "kind",
                    "component_outputs",
                    "radial_distance_mm",
                    "movement_transform",
                    "changed_component_outputs",
                    "final_placements",
                    "line_segments",
                }
                if kind == "radial"
                else set()
            )
            if (
                set(definition_move) != definition_fields
                or set(record) != record_fields
            ):
                raise ValueError(f"{context} has malformed fields or move type.")
            component_outputs = record.get("component_outputs")
            if (
                not isinstance(component_outputs, list)
                or not component_outputs
                or any(not isinstance(name, str) for name in component_outputs)
                or len(component_outputs) != len(set(component_outputs))
                or any(name not in component_index for name in component_outputs)
            ):
                raise ValueError(f"{context} has invalid component outputs.")
            component_definitions = definition_move.get("components")
            if component_definitions != [
                by_name[name].get("definition") for name in component_outputs
            ]:
                raise ValueError(
                    f"{context} does not reference the exact declared components in order."
                )
            if (
                type(record.get("move_index")) is not int
                or record.get("move_index") != move_index
                or record.get("kind") != kind
            ):
                raise ValueError(f"{context} changed its index or kind.")
            reference_count += len(component_outputs)
            if reference_count > 16384:
                raise ValueError(
                    f"Exploded-view output {view_name!r} exceeds 16384 component references."
                )
            movement = None
            radial_distance = None
            if kind == "normal":
                declared_transform = definition_move["transform"]
                if record.get("transform") != declared_transform:
                    raise ValueError(f"{context} changed its declared transform.")
                movement = _assembly_native_declared_placement(
                    declared_transform,
                    f"{context} transform",
                )
            else:
                raw_distance = definition_move["radial_distance_mm"]
                if isinstance(raw_distance, bool):
                    raise ValueError(f"{context} radial distance must be numeric.")
                try:
                    radial_distance = float(raw_distance)
                except (TypeError, ValueError) as exc:
                    raise ValueError(
                        f"{context} radial distance must be numeric."
                    ) from exc
                if (
                    not math.isfinite(radial_distance)
                    or not 0.0 < radial_distance <= 1.0e6
                    or record.get("radial_distance_mm") != raw_distance
                ):
                    raise ValueError(f"{context} has an invalid radial distance.")
                movement = App.Placement(
                    App.Vector(radial_distance, 0.0, 0.0), App.Rotation()
                )
            _assembly_validate_placement_fact(
                record.get("movement_transform"),
                movement,
                f"{context} native movement",
            )
            final_placements = record.get("final_placements")
            line_segments = record.get("line_segments")
            if (
                not isinstance(final_placements, dict)
                or set(final_placements) != set(component_outputs)
                or not isinstance(line_segments, list)
                or len(line_segments) != len(component_outputs)
                or record.get("changed_component_outputs") != component_outputs
            ):
                raise ValueError(
                    f"{context} has incomplete placement or explosion-line evidence."
                )
            expected_reference_paths.append(
                [
                    f"CandidateComponent{component_index[name]}."
                    for name in component_outputs
                ]
            )
            expected_move_types.append("Normal" if kind == "normal" else "Radial")
            for component_name, line in zip(
                component_outputs, line_segments, strict=True
            ):
                previous = current_placements[component_name]
                if kind == "normal":
                    updated = movement * previous
                else:
                    assert radial_distance is not None
                    factor = 4.0 * radial_distance / assembly_diagonal
                    displacement = [
                        (
                            component_centers[component_name][axis]
                            - assembly_center[axis]
                        )
                        * factor
                        for axis in range(3)
                    ]
                    updated = previous.copy()
                    updated.Base = updated.Base + App.Vector(*displacement)
                previous_matrix = _assembly_native_matrix(previous)
                updated_matrix = _assembly_native_matrix(updated)
                if all(
                    math.isclose(left, right, rel_tol=1.0e-10, abs_tol=1.0e-10)
                    for left, right in zip(previous_matrix, updated_matrix, strict=True)
                ):
                    raise ValueError(
                        f"{context} component {component_name!r} has no measurable move."
                    )
                _assembly_validate_placement_fact(
                    final_placements[component_name],
                    updated,
                    f"{context} component {component_name!r} final placement",
                )
                if not isinstance(line, dict) or set(line) != {
                    "component_output",
                    "start_mm",
                    "end_mm",
                    "length_mm",
                }:
                    raise ValueError(
                        f"{context} component {component_name!r} line is malformed."
                    )
                if line.get("component_output") != component_name:
                    raise ValueError(
                        f"{context} explosion line belongs to the wrong component."
                    )
                start = component_centers[component_name]
                delta = updated * previous.inverse()
                end_vector = delta.multVec(App.Vector(*start))
                end = [float(end_vector.x), float(end_vector.y), float(end_vector.z)]
                _assembly_close_numbers(
                    line.get("start_mm"),
                    start,
                    f"{context} component {component_name!r} line start",
                )
                _assembly_close_numbers(
                    line.get("end_mm"),
                    end,
                    f"{context} component {component_name!r} line end",
                )
                length = math.dist(start, end)
                _assembly_close_numbers(
                    [line.get("length_mm")],
                    [length],
                    f"{context} component {component_name!r} line length",
                )
                if length <= 1.0e-10:
                    raise ValueError(
                        f"{context} component {component_name!r} line has zero length."
                    )
                current_placements[component_name] = updated
                if component_name not in moved_names:
                    moved_names.append(component_name)
        final_component_placements = data.get("final_component_placements")
        if not isinstance(final_component_placements, dict) or set(
            final_component_placements
        ) != set(component_names):
            raise ValueError(
                f"Exploded-view output {view_name!r} final component graph is incomplete."
            )
        for component_name in component_names:
            _assembly_validate_placement_fact(
                final_component_placements[component_name],
                current_placements[component_name],
                f"Exploded-view output {view_name!r} component "
                f"{component_name!r} complete final placement",
            )
        if (
            type(data.get("line_count")) is not int
            or data.get("line_count") != reference_count
        ):
            raise ValueError(
                f"Exploded-view output {view_name!r} line count is inconsistent."
            )
        readback = data.get("native_readback")
        expected_readback = {
            "view_group_type": "Assembly::ViewGroup",
            "view_proxy_class": "ExplodedView",
            "step_proxy_classes": ["ExplodedViewStep"] * len(definition_moves),
            "move_types": expected_move_types,
            "reference_paths": expected_reference_paths,
        }
        if readback != expected_readback:
            raise ValueError(
                f"Exploded-view output {view_name!r} native object readback changed."
            )
        summaries.append(
            {
                "exploded_view_output": view_name,
                "move_count": len(definition_moves),
                "component_reference_count": reference_count,
                "moved_component_outputs": moved_names,
                "line_count": reference_count,
                "assembly_bounds": dict(reported_bounds),
            }
        )
    return summaries


def _validate_assembly_boms(
    boms: Sequence[dict[str, Any]],
    *,
    assembly_item: Mapping[str, Any],
    assembly_definition: Mapping[str, Any],
    component_names: Sequence[str],
    component_sources: Mapping[str, Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Replan every BOM from host-authenticated references and compare evidence."""

    if not boms:
        return []
    if len(boms) > 8:
        raise ValueError("An Assembly candidate may contain at most eight BOM outputs.")
    from VibeCADAssemblyBOM import (
        ASSEMBLY_BOM_SCHEMA,
        AssemblyBOMError,
        bom_summary,
        plan_assembly_bom,
    )

    planner_sources = [
        {
            "output_name": name,
            "reference": dict(component_sources[name]),
        }
        for name in component_names
    ]
    summaries: list[dict[str, Any]] = []
    for item in boms:
        output_name = str(item["name"])
        definition = item.get("definition")
        if (
            not isinstance(definition, dict)
            or definition.get("domain") != "assembly"
            or definition.get("operation") != "bill_of_materials"
            or definition.get("output_type") != "bom"
            or definition.get("arguments") != [assembly_definition]
        ):
            raise ValueError(
                f"BOM output {output_name!r} does not consume the exact returned "
                "assembly graph."
            )
        properties = definition.get("properties")
        required_properties = {
            "columns",
            "detail_subassemblies",
            "detail_parts",
            "only_parts",
            "row_overrides",
        }
        if (
            not isinstance(properties, dict)
            or not required_properties <= set(properties)
            or set(properties) - required_properties not in (set(), {"label"})
        ):
            raise ValueError(
                f"BOM output {output_name!r} has malformed definition properties."
            )
        if "label" in properties and (
            not isinstance(properties["label"], str)
            or not properties["label"]
            or properties["label"] != properties["label"].strip()
            or len(properties["label"]) > 120
        ):
            raise ValueError(f"BOM output {output_name!r} has an invalid label.")
        try:
            contract = plan_assembly_bom(
                planner_sources,
                columns=properties["columns"],
                detail_subassemblies=properties["detail_subassemblies"],
                detail_parts=properties["detail_parts"],
                only_parts=properties["only_parts"],
                row_overrides=properties["row_overrides"],
            )
        except AssemblyBOMError as exc:
            raise ValueError(
                f"BOM output {output_name!r} cannot be replanned from the "
                f"authenticated host snapshot: {exc}"
            ) from exc
        data = item.get("assembly_data")
        required_data = {
            *contract,
            "assembly_output",
            "native_readback",
        }
        if not isinstance(data, dict) or set(data) != required_data:
            raise ValueError(
                f"BOM output {output_name!r} has malformed native evidence fields."
            )
        if str(data.get("assembly_output") or "") != str(assembly_item["name"]):
            raise ValueError(f"BOM output {output_name!r} belongs to another assembly.")
        for field, expected in contract.items():
            if data.get(field) != expected:
                raise ValueError(
                    f"BOM output {output_name!r} field {field!r} changed after "
                    "host-authenticated planning."
                )
        if data.get("schema") != ASSEMBLY_BOM_SCHEMA:
            raise ValueError(f"BOM output {output_name!r} has an unsupported schema.")
        native = data.get("native_readback")
        native_fields = {
            "group_type_id",
            "object_type_id",
            "auto_generate",
            "columns_names",
            "settings",
            "used_range",
            "row_count",
            "normalized_cells",
            "substituted_headings",
            "mirrored_names_normalized",
            "sha256",
        }
        if not isinstance(native, dict) or set(native) != native_fields:
            raise ValueError(
                f"BOM output {output_name!r} has malformed native readback."
            )
        columns = list(contract["columns"])
        substituted = [
            str(column["heading"])
            for column in columns
            if column["kind"] == "custom"
            or (column["kind"] == "builtin" and column.get("key") == "file_name")
        ]
        normalized_cells = []
        for row in list(contract["rows"]):
            cells = {}
            for column in columns:
                heading = str(column["heading"])
                cells[heading] = (
                    "" if heading in substituted else str(row["cells"][heading])
                )
            normalized_cells.append(cells)
        expected_native = {
            "group_type_id": "Assembly::BomGroup",
            "object_type_id": "Assembly::BomObject",
            "auto_generate": True,
            "columns_names": [str(column["native_name"]) for column in columns],
            "settings": dict(contract["settings"]),
            "used_range": list(contract["used_range"]),
            "row_count": int(contract["row_count"]),
            "normalized_cells": normalized_cells,
            "substituted_headings": substituted,
            "mirrored_names_normalized": any(
                bool(row["mirrored"]) for row in list(contract["rows"])
            ),
        }
        if any(
            native.get(field) != expected for field, expected in expected_native.items()
        ):
            raise ValueError(
                f"BOM output {output_name!r} native readback disagrees with its "
                "authenticated table."
            )
        digest_payload = {key: native[key] for key in native_fields - {"sha256"}}
        digest = hashlib.sha256(
            json.dumps(
                digest_payload,
                ensure_ascii=True,
                sort_keys=True,
                separators=(",", ":"),
                allow_nan=False,
            ).encode("utf-8")
        ).hexdigest()
        if str(native.get("sha256") or "") != digest:
            raise ValueError(
                f"BOM output {output_name!r} native readback digest changed."
            )
        summaries.append(bom_summary(contract, output_name=output_name))
    return summaries


def _assembly_hierarchy_contract(
    resolved_reference: Mapping[str, Any], *, context: str
) -> tuple[dict[str, Any], dict[str, dict[str, Any]]]:
    descriptor = resolved_reference.get("assembly_hierarchy")
    if not isinstance(descriptor, dict) or descriptor.get("schema") != (
        "vibecad-assembly-source-hierarchy-v1"
    ):
        raise ValueError(f"{context} has no authenticated Assembly hierarchy.")
    nodes = descriptor.get("nodes")
    if not isinstance(nodes, list) or not nodes:
        raise ValueError(f"{context} Assembly hierarchy has no nodes.")
    node_by_id = {
        str(node.get("node_id") or ""): node for node in nodes if isinstance(node, dict)
    }
    if len(node_by_id) != len(nodes) or "" in node_by_id:
        raise ValueError(f"{context} Assembly hierarchy has duplicate node identities.")
    root = node_by_id.get(str(descriptor.get("root_node_id") or ""))
    if root is None or str(root.get("kind") or "") not in {"assembly", "part"}:
        raise ValueError(
            f"{context} Assembly hierarchy has an invalid container root node."
        )
    paths = descriptor.get("occurrence_paths")
    if not isinstance(paths, list) or any(
        not isinstance(item, dict) or not str(item.get("path") or "") for item in paths
    ):
        raise ValueError(f"{context} Assembly hierarchy has invalid occurrence paths.")
    return descriptor, node_by_id


def _assembly_hierarchy_path(
    resolved_reference: Mapping[str, Any],
    stable_path: str,
    *,
    context: str,
) -> tuple[dict[str, Any], list[tuple[dict[str, Any], dict[str, Any]]]]:
    descriptor, node_by_id = _assembly_hierarchy_contract(
        resolved_reference, context=context
    )
    declared_paths = {
        str(item.get("path") or "")
        for item in list(descriptor.get("occurrence_paths") or [])
    }
    if stable_path not in declared_paths:
        raise ValueError(
            f"{context} uses occurrence_path {stable_path!r}, which is not in the "
            "authenticated source hierarchy."
        )
    current = node_by_id[str(descriptor["root_node_id"])]
    chain: list[tuple[dict[str, Any], dict[str, Any]]] = []
    for segment in stable_path.split("/"):
        occurrences = list(current.get("occurrences") or [])
        occurrence = next(
            (
                item
                for item in occurrences
                if isinstance(item, dict) and str(item.get("name") or "") == segment
            ),
            None,
        )
        if occurrence is None:
            raise ValueError(
                f"{context} occurrence_path {stable_path!r} disagrees with its node graph."
            )
        source = node_by_id.get(str(occurrence.get("source_node_id") or ""))
        if source is None:
            raise ValueError(
                f"{context} occurrence_path reaches a missing source node."
            )
        chain.append((occurrence, source))
        current = source
    return descriptor, chain


def _assembly_hierarchy_leaf_metadata(node: Mapping[str, Any]) -> dict[str, Any]:
    contract = node.get("reference_contract")
    result = dict(contract) if isinstance(contract, dict) else {}
    artifact = node.get("shape_artifact")
    result["facts"] = (
        dict(artifact.get("facts") or {}) if isinstance(artifact, dict) else {}
    )
    result["type_id"] = str(node.get("type_id") or "")
    result["source_kind"] = str(node.get("kind") or "")
    return result


def _assembly_expected_native_reference(
    component_data: Mapping[str, Any],
    chain: list[tuple[dict[str, Any], dict[str, Any]]],
    worker_chain: Any,
    *,
    stable_path: str,
    element: str,
    anchor: str,
    context: str,
) -> tuple[str, list[str], str]:
    if not isinstance(worker_chain, list) or len(worker_chain) != len(chain):
        raise ValueError(f"{context} has malformed native hierarchy evidence.")
    component_native_name = str(component_data.get("native_name") or "")
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", component_native_name):
        raise ValueError(f"{context} component has no valid native object identity.")
    target_name = component_native_name
    prefix_names: list[str] = []
    locked = False
    previous_native_type = str(component_data.get("native_type_id") or "")
    if previous_native_type not in {"Assembly::AssemblyLink", "App::Link"}:
        raise ValueError(
            f"{context} component has unsupported native hierarchy root type "
            f"{previous_native_type!r}."
        )
    previous_rigid = (
        not bool(component_data.get("flexible"))
        if previous_native_type == "Assembly::AssemblyLink"
        else True
    )
    for index, ((occurrence, source), evidence) in enumerate(
        zip(chain, worker_chain, strict=True)
    ):
        if not isinstance(evidence, dict):
            raise ValueError(f"{context} native hierarchy step {index} is malformed.")
        expected_type = (
            "Assembly::AssemblyLink"
            if str(occurrence.get("link_mode") or "") == "assembly_link"
            else "App::Link"
        )
        native_name = str(evidence.get("native_name") or "")
        expected_live = previous_native_type in {
            "Assembly::AssemblyLink",
            "Assembly::AssemblyObject",
        }
        expected = {
            "stable_name": str(occurrence.get("name") or ""),
            "source_node_id": str(source.get("node_id") or ""),
            "source_kind": str(source.get("kind") or ""),
            "native_type_id": expected_type,
            "container_type_id": previous_native_type,
            "container_rigid": (
                previous_rigid
                if previous_native_type == "Assembly::AssemblyLink"
                else None
            ),
            "live_occurrence": expected_live,
        }
        for field, expected_value in expected.items():
            if evidence.get(field) != expected_value:
                raise ValueError(
                    f"{context} native hierarchy step {index} changed {field!r}."
                )
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", native_name):
            raise ValueError(
                f"{context} native hierarchy step {index} has an invalid object name."
            )
        if locked:
            prefix_names.append(native_name)
        elif previous_native_type == "Assembly::AssemblyLink":
            if previous_rigid:
                locked = True
                prefix_names.append(native_name)
            else:
                target_name = native_name
                prefix_names = []
        else:
            locked = True
            prefix_names.append(native_name)
        previous_native_type = expected_type
        previous_rigid = bool(occurrence.get("rigid", True))
    prefix = ".".join(prefix_names)
    subelements = [
        (f"{prefix}.{value}" if prefix and value else f"{prefix}." if prefix else value)
        for value in (element, anchor)
    ]
    mode = "prefixed_rigid_boundary" if prefix else "direct_exposed_occurrence"
    return target_name, subelements, mode


def _assembly_catalog_fastener_contract(
    prepared: Mapping[str, Any],
    definition: Mapping[str, Any],
    data: Mapping[str, Any],
    *,
    context: str,
) -> tuple[dict[str, Any], dict[str, str], dict[str, Any]]:
    """Independently validate one worker-generated catalog occurrence."""

    arguments = definition.get("arguments")
    properties = definition.get("properties")
    required_properties = {
        "length_mm",
        "model_thread",
        "left_handed",
        "options",
        "placement",
        "grounded",
    }
    if (
        not isinstance(arguments, list)
        or len(arguments) != 2
        or not isinstance(properties, dict)
        or not required_properties <= set(properties)
        or set(properties) - required_properties not in (set(), {"label"})
    ):
        raise ValueError(f"{context} has a malformed api.fastener definition.")
    try:
        from VibeCADFasteners import (
            assembly_component_contract,
            catalog_component_reference,
            resolve_fastener,
        )

        identity = resolve_fastener(
            standard=arguments[0],
            nominal_thread=arguments[1],
            length_mm=properties.get("length_mm"),
            model_thread=properties["model_thread"],
            left_handed=properties.get("left_handed"),
            options=properties.get("options"),
        )
        source = catalog_component_reference(identity)
    except Exception as exc:
        raise ValueError(
            f"{context} does not resolve to one exact bundled catalog item: {exc}"
        ) from exc
    if data.get("catalog_fastener") != identity:
        raise ValueError(f"{context} catalog identity changed in the worker.")
    if data.get("source") != source:
        raise ValueError(f"{context} catalog source identity changed in the worker.")
    brep = data.get("source_brep")
    if not isinstance(brep, dict) or set(brep) != {
        "artifact_kind",
        "artifact_path",
        "artifact_sha256",
        "artifact_bytes",
    }:
        raise ValueError(f"{context} has malformed generated-BREP evidence.")
    if brep.get("artifact_kind") != "brep":
        raise ValueError(f"{context} has the wrong generated artifact kind.")
    path = _staged_artifact_path(
        prepared,
        brep.get("artifact_path"),
        context=f"{context} generated BREP",
    )
    size = path.stat().st_size
    digest = _sha256_file(path)
    if size != brep.get("artifact_bytes") or digest != brep.get("artifact_sha256"):
        raise ValueError(f"{context} generated BREP changed during transfer.")
    import Part

    shape = Part.Shape()
    shape.importBrep(str(path))
    if shape.isNull() or not shape.isValid() or len(shape.Solids) != 1:
        raise ValueError(f"{context} generated BREP is not one valid solid.")
    try:
        contract = assembly_component_contract(shape, identity)
    except Exception as exc:
        raise ValueError(
            f"{context} generated BREP does not satisfy its catalog contract: {exc}"
        ) from exc
    if data.get("source_contract") != contract:
        raise ValueError(
            f"{context} standard interfaces or BOM identity changed in the worker."
        )
    return identity, source, {**source, **contract}


def _assembly_shared_mechanism_scenario(
    *,
    assembly_item: Mapping[str, Any],
    diagnostics_item: Mapping[str, Any],
    component_names: Sequence[str],
    joint_names: Sequence[str],
    motion_names: Sequence[str],
    simulation_item: Mapping[str, Any] | None,
    by_name: Mapping[str, Mapping[str, Any]],
    joint_records: Mapping[str, Mapping[str, Any]],
) -> dict[str, Any]:
    """Independently adapt serialized Assembly outputs to the shared contract."""

    assembly_definition = dict(assembly_item["definition"])
    assembly_properties = dict(assembly_definition["properties"])
    components = []
    for name in component_names:
        definition = dict(by_name[name]["definition"])
        operation = str(definition["operation"])
        arguments = list(definition["arguments"])
        properties = dict(definition["properties"])
        if operation == "component":
            source = {"kind": "document_object", **dict(arguments[0])}
            flexible = bool(properties.get("flexible", False))
        elif operation == "fastener":
            source = {
                "kind": "standard_fastener",
                "standard": str(arguments[0]),
                "nominal_thread": str(arguments[1]),
                "length_mm": properties.get("length_mm"),
                "model_thread": bool(properties.get("model_thread")),
                "left_handed": bool(properties.get("left_handed")),
                "options": dict(properties.get("options") or {}),
            }
            flexible = False
        else:
            raise ValueError(
                f"Component output {name!r} cannot enter the shared mechanism scenario."
            )
        components.append(
            {
                "id": name,
                "label": str(properties.get("label") or ""),
                "source": source,
                "initial_placement": dict(properties.get("placement") or {}),
                "grounded": bool(properties.get("grounded")),
                "flexible": flexible,
            }
        )

    joints = []
    for name in joint_names:
        definition = dict(by_name[name]["definition"])
        properties = dict(definition["properties"])
        connectors = []
        for connector in list(joint_records[name]["connectors"]):
            connector_index = int(connector["index"]) - 1
            connector_definition = dict(list(definition["arguments"])[connector_index])
            connector_properties = dict(connector_definition["properties"])
            connectors.append(
                {
                    "component_id": str(connector["component_output"]),
                    "selection": dict(connector_properties.get("selection") or {}),
                    "occurrence_path": connector_properties.get("occurrence_path"),
                    "anchor": connector_properties.get("anchor"),
                    "offset": dict(connector_properties.get("offset") or {}),
                }
            )
        joints.append(
            {
                "id": name,
                "label": str(properties.get("label") or ""),
                "kind": str(properties.get("kind") or ""),
                "connectors": connectors,
                "parameters": dict(properties.get("parameters") or {}),
                "length_limits_mm": properties.get("length_limits_mm"),
                "angle_limits_degrees": properties.get("angle_limits_degrees"),
                "suppressed": bool(properties.get("suppressed")),
            }
        )

    motions = []
    for name in motion_names:
        definition = dict(by_name[name]["definition"])
        properties = dict(definition["properties"])
        data = dict(by_name[name]["assembly_data"])
        motions.append(
            {
                "id": name,
                "label": str(properties.get("label") or ""),
                "joint_id": str(data["joint_output"]),
                "motion_type": str(properties["motion_type"]),
                "formula": str(properties["formula"]),
            }
        )
    simulation = None
    if simulation_item is not None:
        definition = dict(simulation_item["definition"])
        properties = dict(definition["properties"])
        simulation = {
            "id": str(simulation_item["name"]),
            "label": str(properties.get("label") or ""),
            "motion_ids": list(motion_names),
            "start_time_s": properties.get("start_time_s"),
            "end_time_s": properties.get("end_time_s"),
            "time_step_s": properties.get("time_step_s"),
            "error_tolerance": properties.get("error_tolerance"),
            "frames_per_second": properties.get("frames_per_second"),
        }
    diagnostics_definition = dict(diagnostics_item["definition"])
    diagnostics_properties = dict(diagnostics_definition["properties"])
    return normalize_mechanism_scenario(
        {
            "schema": MECHANISM_SCENARIO_SCHEMA,
            "assembly": {
                "id": str(assembly_item["name"]),
                "label": str(assembly_properties.get("label") or ""),
            },
            "components": components,
            "joints": joints,
            "solve": {
                "id": str(diagnostics_item["name"]),
                "label": str(diagnostics_properties.get("label") or ""),
                "require_solved": bool(
                    diagnostics_properties.get("require_solved", True)
                ),
            },
            "motions": motions,
            "simulation": simulation,
        }
    )


def _validate_assembly_mechanism_verifications(
    prepared: Mapping[str, Any],
    verifications: Sequence[dict[str, Any]],
    *,
    scenario: Mapping[str, Any],
    solve_report: Mapping[str, Any],
    assembly_item: Mapping[str, Any],
    assembly_definition: Mapping[str, Any],
    by_name: Mapping[str, dict[str, Any]],
    component_names: Sequence[str],
    component_placements: Mapping[str, Mapping[str, Any]],
    component_sources: Mapping[str, Mapping[str, Any]],
    component_metadata: Mapping[str, Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Recompute exact static reports from authenticated host-side BREPs."""

    if not verifications:
        return []

    import Part

    worker_references = {
        (
            str(item.get("document_uid") or ""),
            str(item.get("object_name") or ""),
        ): item
        for item in list(
            dict(prepared.get("worker_request") or {}).get("document_references") or []
        )
        if isinstance(item, Mapping)
    }
    source_shapes: dict[tuple[str, str], Any] = {}
    geometry_components: dict[str, dict[str, Any]] = {}
    geometry_interfaces: dict[str, dict[str, list[str]]] = {}
    for component_name in component_names:
        component_item = by_name[component_name]
        data = component_metadata[component_name]
        source = data.get("source")
        definition = component_item.get("definition")
        if not isinstance(source, Mapping) or not isinstance(definition, Mapping):
            raise ValueError(
                f"Component output {component_name!r} has no static-verification source."
            )
        key = (
            str(source.get("document_uid") or ""),
            str(source.get("object_name") or ""),
        )
        operation = str(definition.get("operation") or "")
        descriptor = (
            data.get("source_brep")
            if operation == "fastener"
            else worker_references.get(key)
        )
        resolved = component_sources.get(component_name)
        if not isinstance(descriptor, Mapping) or not isinstance(
            resolved,
            Mapping,
        ):
            raise ValueError(
                f"Component output {component_name!r} has no authenticated static BREP."
            )
        path = _staged_artifact_path(
            prepared,
            descriptor.get("artifact_path"),
            context=f"Component output {component_name!r} static-verification source",
        )
        digest = _sha256_file(path)
        descriptor_digest = str(
            descriptor.get(
                "artifact_sha256" if operation == "fastener" else "brep_sha256"
            )
            or ""
        )
        resolved_digest = (
            descriptor_digest
            if operation == "fastener"
            else str(resolved.get("brep_sha256") or "")
        )
        if digest != descriptor_digest or digest != resolved_digest:
            raise ValueError(
                f"Component output {component_name!r} static BREP changed after "
                "revision binding."
            )
        shape = source_shapes.get(key)
        if shape is None:
            shape = Part.Shape()
            shape.importBrep(str(path))
            if shape.isNull() or not shape.isValid() or len(list(shape.Solids)) < 1:
                raise ValueError(
                    f"Component output {component_name!r} static BREP is invalid."
                )
            source_shapes[key] = shape
        placement = _assembly_native_placement_from_matrix(
            component_placements[component_name]["matrix"],
            f"Component output {component_name!r} solved placement",
        )
        geometry_components[component_name] = {
            "shape": shape,
            "placement": {
                "position": [
                    float(placement.Base.x),
                    float(placement.Base.y),
                    float(placement.Base.z),
                ],
                "rotation": [float(value) for value in placement.Rotation.Q],
            },
        }
        published = dict(resolved.get("published_interfaces") or {})
        geometry_interfaces[component_name] = {
            str(name): [
                str(subelement) for subelement in list(raw.get("subelements") or [])
            ]
            for name, raw in published.items()
            if isinstance(raw, Mapping) and list(raw.get("subelements") or [])
        }

    summaries: list[dict[str, Any]] = []
    for verification_item in verifications:
        output_name = str(verification_item["name"])
        definition = verification_item.get("definition")
        data = verification_item.get("assembly_data")
        if (
            not isinstance(definition, dict)
            or definition.get("domain") != "assembly"
            or definition.get("operation") != "mechanism_check"
            or definition.get("output_type") != "mechanism_verification"
            or definition.get("arguments") != [assembly_definition]
        ):
            raise ValueError(
                f"Mechanism verification output {output_name!r} has an invalid "
                "declarative definition."
            )
        if not isinstance(data, dict) or set(data) != {
            "assembly_output",
            "static_check",
            "report",
        }:
            raise ValueError(
                f"Mechanism verification output {output_name!r} has malformed "
                "native evidence."
            )
        if str(data.get("assembly_output") or "") != str(assembly_item["name"]):
            raise ValueError(
                f"Mechanism verification output {output_name!r} belongs to the "
                "wrong assembly."
            )
        properties = definition.get("properties")
        if (
            not isinstance(properties, dict)
            or not {"requirements", "contacts"} <= set(properties)
            or set(properties) - {"requirements", "contacts", "label"}
        ):
            raise ValueError(
                f"Mechanism verification output {output_name!r} has malformed "
                "properties."
            )
        static_check = normalize_mechanism_static_check(
            scenario,
            data.get("static_check"),
        )
        if (
            static_check["schema"] != MECHANISM_STATIC_CHECK_SCHEMA
            or static_check["id"] != output_name
            or static_check["label"] != str(properties.get("label") or "")
            or static_check["scenario_sha256"] != mechanism_scenario_sha256(scenario)
        ):
            raise ValueError(
                f"Mechanism verification output {output_name!r} changed its "
                "static-check identity."
            )
        definition_requirements = properties.get("requirements")
        definition_contacts = properties.get("contacts")
        if (
            not isinstance(definition_requirements, list)
            or not isinstance(definition_contacts, list)
            or len(definition_requirements) != len(static_check["requirements"])
            or len(definition_contacts) != len(static_check["contacts"])
        ):
            raise ValueError(
                f"Mechanism verification output {output_name!r} changed its "
                "declaration counts."
            )
        for kind, definitions, declarations in (
            (
                "requirement",
                definition_requirements,
                static_check["requirements"],
            ),
            ("contact", definition_contacts, static_check["contacts"]),
        ):
            for index, (raw_definition, declaration) in enumerate(
                zip(definitions, declarations, strict=True)
            ):
                context = (
                    f"Mechanism verification output {output_name!r} {kind} {index}"
                )
                if not isinstance(raw_definition, dict):
                    raise ValueError(f"{context} is malformed.")
                first_name = str(declaration["first_component"])
                second_name = str(declaration["second_component"])
                if (
                    first_name not in by_name
                    or second_name not in by_name
                    or raw_definition.get("first")
                    != by_name[first_name].get("definition")
                    or raw_definition.get("second")
                    != by_name[second_name].get("definition")
                ):
                    raise ValueError(
                        f"{context} changed its exact component graph values."
                    )
                expected_scalar = {
                    key: value
                    for key, value in declaration.items()
                    if key
                    not in {
                        "id",
                        "first_component",
                        "second_component",
                    }
                }
                observed_scalar = {
                    key: value
                    for key, value in raw_definition.items()
                    if key not in {"first", "second"}
                }
                if observed_scalar != expected_scalar:
                    raise ValueError(
                        f"{context} changed its declared policy or tolerance."
                    )
                if bool(component_metadata[first_name].get("flexible")) or bool(
                    component_metadata[second_name].get("flexible")
                ):
                    raise ValueError(
                        f"{context} cannot certify a flexible component as one "
                        "rigid static shape."
                    )

        geometry_declarations = []
        for declaration in [
            *static_check["requirements"],
            *[item for item in static_check["contacts"] if item["policy"] != "ignored"],
        ]:
            policy = str(declaration.get("policy") or "")
            first_interface = (
                str(declaration["first_interface"])
                if policy in {"allowed", "required"}
                else None
            )
            second_interface = (
                str(declaration["second_interface"])
                if policy in {"allowed", "required"}
                else None
            )
            if first_interface is not None:
                for component_name, interface_name in (
                    (
                        str(declaration["first_component"]),
                        first_interface,
                    ),
                    (
                        str(declaration["second_component"]),
                        second_interface,
                    ),
                ):
                    if interface_name not in geometry_interfaces.get(
                        component_name,
                        {},
                    ):
                        raise ValueError(
                            f"Mechanism verification output {output_name!r} names "
                            f"interface {interface_name!r} without authenticated "
                            "contact subelements."
                        )
            geometry_declarations.append(
                {
                    "declaration_id": str(declaration["id"]),
                    "first_component": str(declaration["first_component"]),
                    "second_component": str(declaration["second_component"]),
                    "tolerance_mm": float(declaration["tolerance_mm"]),
                    "first_interface": first_interface,
                    "second_interface": second_interface,
                }
            )
        geometry_evidence = measure_static_mechanism_pairs(
            geometry_components,
            geometry_declarations,
            interfaces=geometry_interfaces,
        )
        expected_report = evaluate_static_mechanism_check(
            scenario,
            solve_report,
            static_check,
            geometry_evidence,
        )
        reported = normalize_mechanism_verification_report(
            scenario,
            solve_report,
            static_check,
            data.get("report"),
        )
        if reported != expected_report:
            raise ValueError(
                f"Mechanism verification output {output_name!r} does not match "
                "the independently recomputed exact BREP evidence."
            )
        summary = {
            "verification_output": output_name,
            "verdict": str(reported["verdict"]),
            "declaration_count": int(reported["summary"]["declaration_count"]),
            "pass_count": int(reported["summary"]["pass_count"]),
            "fail_count": int(reported["summary"]["fail_count"]),
            "indeterminate_count": int(reported["summary"]["indeterminate_count"]),
            "ignored_count": int(reported["summary"]["ignored_count"]),
            "static_check_sha256": str(reported["static_check_sha256"]),
        }
        summaries.append(summary)
    return summaries


def _validate_assembly_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    """Reauthorize a worker-produced native Assembly graph and diagnostics."""

    validation = execution.get("assembly_validation")
    if not isinstance(validation, dict):
        raise ValueError("The Assembly worker returned no native validation summary.")
    by_type: dict[str, list[dict[str, Any]]] = {}
    by_name: dict[str, dict[str, Any]] = {}
    for item in outputs:
        by_type.setdefault(str(item.get("type") or ""), []).append(item)
        by_name[str(item.get("name") or "")] = item
    if len(by_type.get("assembly", [])) != 1:
        raise ValueError(
            "An Assembly candidate must contain exactly one assembly output."
        )
    if len(by_type.get("solver_diagnostics", [])) != 1:
        raise ValueError(
            "An Assembly candidate must contain exactly one solver_diagnostics output."
        )
    components = by_type.get("component_link", [])
    joints = by_type.get("joint", [])
    motions = by_type.get("motion", [])
    simulations = by_type.get("simulation", [])
    verifications = by_type.get("mechanism_verification", [])
    exploded_views = by_type.get("exploded_view", [])
    boms = by_type.get("bom", [])
    if not components:
        raise ValueError(
            "An Assembly candidate must contain at least one component_link."
        )
    if bool(motions) != bool(simulations) or len(simulations) > 1:
        raise ValueError(
            "Assembly motion outputs require exactly one simulation output, and a "
            "simulation requires at least one motion output."
        )
    if len(verifications) > 8:
        raise ValueError(
            "An Assembly candidate may contain at most eight "
            "mechanism_verification outputs."
        )
    assembly_item = by_type["assembly"][0]
    diagnostics_item = by_type["solver_diagnostics"][0]
    assembly_definition = assembly_item.get("definition")
    if (
        not isinstance(assembly_definition, dict)
        or assembly_definition.get("domain") != "assembly"
        or assembly_definition.get("operation") != "assembly"
        or assembly_definition.get("output_type") != "assembly"
    ):
        raise ValueError("The assembly output has an invalid declarative definition.")
    assembly_properties = assembly_definition.get("properties")
    if not isinstance(assembly_properties, dict):
        raise ValueError("The assembly output definition has no graph properties.")
    assembly_data = assembly_item.get("assembly_data")
    if not isinstance(assembly_data, dict):
        raise ValueError("The assembly output has no validated graph metadata.")
    returned_component_names = [str(item["name"]) for item in components]
    returned_joint_names = [str(item["name"]) for item in joints]
    returned_motion_names = [str(item["name"]) for item in motions]
    component_names = [
        str(item) for item in list(assembly_data.get("component_outputs") or [])
    ]
    joint_names = [str(item) for item in list(assembly_data.get("joint_outputs") or [])]
    if len(component_names) != len(set(component_names)) or set(component_names) != set(
        returned_component_names
    ):
        raise ValueError(
            "The assembly graph components do not exactly match returned component outputs."
        )
    if len(joint_names) != len(set(joint_names)) or set(joint_names) != set(
        returned_joint_names
    ):
        raise ValueError(
            "The assembly graph joints do not exactly match returned joint outputs."
        )
    if str(assembly_data.get("diagnostics_output") or "") != str(
        diagnostics_item["name"]
    ):
        raise ValueError("The assembly graph points to the wrong diagnostics output.")
    graph_motion_names: list[str] = []
    if simulations:
        graph_motion_names = [
            str(item) for item in list(assembly_data.get("motion_outputs") or [])
        ]
        if len(graph_motion_names) != len(set(graph_motion_names)) or set(
            graph_motion_names
        ) != set(returned_motion_names):
            raise ValueError(
                "The assembly graph motions do not exactly match returned motion outputs."
            )
        if str(assembly_data.get("simulation_output") or "") != str(
            simulations[0]["name"]
        ):
            raise ValueError(
                "The assembly graph points to the wrong simulation output."
            )
    elif "motion_outputs" in assembly_data or "simulation_output" in assembly_data:
        raise ValueError("The assembly graph reports an undeclared simulation.")
    returned_exploded_view_names = [str(item["name"]) for item in exploded_views]
    if exploded_views:
        graph_exploded_view_names = [
            str(item) for item in list(assembly_data.get("exploded_view_outputs") or [])
        ]
        if (
            len(graph_exploded_view_names) != len(set(graph_exploded_view_names))
            or graph_exploded_view_names != returned_exploded_view_names
        ):
            raise ValueError(
                "The assembly graph exploded views do not exactly match returned "
                "exploded_view outputs in declaration order."
            )
    elif "exploded_view_outputs" in assembly_data:
        raise ValueError("The assembly graph reports an undeclared exploded view.")
    returned_bom_names = [str(item["name"]) for item in boms]
    if boms:
        graph_bom_names = [
            str(item) for item in list(assembly_data.get("bom_outputs") or [])
        ]
        if (
            len(graph_bom_names) != len(set(graph_bom_names))
            or graph_bom_names != returned_bom_names
        ):
            raise ValueError(
                "The assembly graph BOMs do not exactly match returned bom outputs "
                "in declaration order."
            )
    elif "bom_outputs" in assembly_data:
        raise ValueError("The assembly graph reports an undeclared BOM.")
    returned_verification_names = [str(item["name"]) for item in verifications]
    if verifications:
        graph_verification_names = [
            str(item)
            for item in list(assembly_data.get("mechanism_verification_outputs") or [])
        ]
        if (
            len(graph_verification_names) != len(set(graph_verification_names))
            or graph_verification_names != returned_verification_names
        ):
            raise ValueError(
                "The assembly graph mechanism verifications do not exactly match "
                "returned outputs in declaration order."
            )
    elif "mechanism_verification_outputs" in assembly_data:
        raise ValueError(
            "The assembly graph reports an undeclared mechanism verification."
        )
    graph_component_definitions = assembly_properties.get("components")
    graph_joint_definitions = assembly_properties.get("joints")
    if not isinstance(graph_component_definitions, list) or len(
        graph_component_definitions
    ) != len(component_names):
        raise ValueError("The assembly definition has the wrong component graph.")
    if not isinstance(graph_joint_definitions, list) or len(
        graph_joint_definitions
    ) != len(joint_names):
        raise ValueError("The assembly definition has the wrong joint graph.")
    for index, output_name in enumerate(component_names):
        if graph_component_definitions[index] != by_name[output_name].get("definition"):
            raise ValueError(
                f"The assembly graph component {output_name!r} does not match its "
                "returned definition."
            )
    for index, output_name in enumerate(joint_names):
        if graph_joint_definitions[index] != by_name[output_name].get("definition"):
            raise ValueError(
                f"The assembly graph joint {output_name!r} does not match its "
                "returned definition."
            )

    diagnostics_definition = diagnostics_item.get("definition")
    if (
        not isinstance(diagnostics_definition, dict)
        or diagnostics_definition.get("domain") != "assembly"
        or diagnostics_definition.get("operation") != "solve"
        or diagnostics_definition.get("output_type") != "solver_diagnostics"
        or diagnostics_definition.get("arguments") != [assembly_definition]
    ):
        raise ValueError(
            "The solver_diagnostics output does not solve the returned assembly graph."
        )
    diagnostics_properties = diagnostics_definition.get("properties")
    if not isinstance(diagnostics_properties, dict) or not isinstance(
        diagnostics_properties.get("require_solved"), bool
    ):
        raise ValueError(
            "The solver_diagnostics definition has no boolean require_solved policy."
        )
    diagnostics_assembly_data = diagnostics_item.get("assembly_data")
    if diagnostics_assembly_data != {"assembly_output": str(assembly_item["name"])}:
        raise ValueError("The solver_diagnostics output belongs to the wrong assembly.")

    references = {
        (str(item.get("document_uid") or ""), str(item.get("object_name") or "")): item
        for item in list(prepared.get("resolved_references") or [])
    }
    grounded_set: set[str] = set()
    component_placements: dict[str, dict[str, Any]] = {}
    component_placement_deltas: dict[str, dict[str, Any]] = {}
    component_sources: dict[str, dict[str, Any]] = {}
    component_metadata: dict[str, dict[str, Any]] = {}
    for item in components:
        name = str(item["name"])
        data = item.get("assembly_data")
        if not isinstance(data, dict):
            raise ValueError(f"Component output {name!r} has no assembly metadata.")
        if str(data.get("assembly_output") or "") != str(assembly_item["name"]):
            raise ValueError(
                f"Component output {name!r} belongs to the wrong assembly."
            )
        definition = item.get("definition")
        if (
            not isinstance(definition, dict)
            or definition.get("domain") != "assembly"
            or definition.get("operation") not in {"component", "fastener"}
            or definition.get("output_type") != "component_link"
        ):
            raise ValueError(f"Component output {name!r} has an invalid definition.")
        operation = str(definition["operation"])
        arguments = definition.get("arguments")
        properties = definition.get("properties")
        if not isinstance(arguments, list) or not isinstance(properties, dict):
            raise ValueError(f"Component output {name!r} has a malformed definition.")
        source = data.get("source")
        if (
            not isinstance(source, dict)
            or (
                operation == "fastener"
                and set(source) != {"document_uid", "object_name"}
            )
            or (operation == "component" and not is_document_reference(source))
        ):
            raise ValueError(
                f"Component output {name!r} has an invalid source identity."
            )
        if operation == "fastener":
            _identity, expected_source, resolved = _assembly_catalog_fastener_contract(
                prepared,
                definition,
                data,
                context=f"Component output {name!r}",
            )
            if source != expected_source:
                raise ValueError(
                    f"Component output {name!r} changed its catalog source identity."
                )
        else:
            source = normalize_document_reference(source)
            if len(arguments) != 1 or source != arguments[0]:
                raise ValueError(
                    f"Component output {name!r} source changed after source evaluation."
                )
            key = (str(source["document_uid"]), str(source["object_name"]))
            resolved = references.get(key)
            if resolved is None:
                raise ValueError(
                    f"Component output {name!r} uses an unauthenticated source "
                    f"{key[1]!r}."
                )
            if (
                source.get("document_path")
                and str(resolved.get("document_path") or "") != source["document_path"]
            ):
                raise ValueError(
                    f"Component output {name!r} changed its authenticated "
                    "document_path."
                )
        facts = data.get("source_facts")
        if not isinstance(facts, dict) or int(facts.get("solids") or 0) < 1:
            raise ValueError(
                f"Component output {name!r} source must contain at least one solid."
            )
        reported = dict(resolved.get("facts") or {})
        for field in ("solids", "faces", "edges", "vertices"):
            if int(facts.get(field, -1)) != int(reported.get(field, -2)):
                raise ValueError(
                    f"Component output {name!r} source topology disagrees with the "
                    f"host snapshot ({field})."
                )
        if str(data.get("source_type_id") or "") != str(
            resolved.get("type_id") or ""
        ) or str(data.get("source_kind") or "") != str(
            resolved.get("source_kind") or "shape"
        ):
            raise ValueError(
                f"Component output {name!r} source type metadata disagrees with "
                "the authenticated host snapshot."
            )
        for field in (
            "source_program_id",
            "source_program_domain",
            "source_revision",
        ):
            if str(data.get(field) or "") != str(resolved.get(field) or ""):
                raise ValueError(
                    f"Component output {name!r} {field} disagrees with the "
                    "authenticated host snapshot."
                )
        if bool(data.get("placement_authored")) is not bool(
            properties.get("placement_authored")
        ):
            raise ValueError(
                f"Component output {name!r} placement authorship metadata was altered."
            )
        if (
            not isinstance(properties.get("grounded"), bool)
            or bool(data.get("grounded")) is not properties["grounded"]
        ):
            raise ValueError(
                f"Component output {name!r} grounding metadata was altered."
            )
        declared_flexible = properties.get("flexible", False)
        if (
            not isinstance(declared_flexible, bool)
            or bool(data.get("flexible", False)) is not declared_flexible
        ):
            raise ValueError(
                f"Component output {name!r} flexible-subassembly metadata was altered."
            )
        if declared_flexible and bool(properties["grounded"]):
            raise ValueError(
                f"Component output {name!r} cannot be both flexible and grounded."
            )
        source_kind = str(resolved.get("source_kind") or "shape")
        if declared_flexible and source_kind != "assembly":
            raise ValueError(
                f"Component output {name!r} marked a non-Assembly source as flexible."
            )
        native_name = str(data.get("native_name") or "")
        native_type_id = str(data.get("native_type_id") or "")
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", native_name):
            raise ValueError(
                f"Component output {name!r} has no native object identity."
            )
        hierarchy_descriptor = resolved.get("assembly_hierarchy")
        if hierarchy_descriptor is not None:
            descriptor, _node_by_id = _assembly_hierarchy_contract(
                resolved, context=f"Component output {name!r} source"
            )
            root_node = _node_by_id[str(descriptor["root_node_id"])]
            root_kind = str(root_node.get("kind") or "")
            expected_paths = [
                str(item["path"]) for item in list(descriptor["occurrence_paths"])
            ]
            hierarchy_digest = hashlib.sha256(
                json.dumps(
                    descriptor,
                    ensure_ascii=True,
                    sort_keys=True,
                    separators=(",", ":"),
                    allow_nan=False,
                ).encode("utf-8")
            ).hexdigest()
            expected_native_type = (
                "Assembly::AssemblyLink" if source_kind == "assembly" else "App::Link"
            )
            if (
                source_kind not in {"assembly", "part"}
                or root_kind != source_kind
                or native_type_id != expected_native_type
                or str(data.get("hierarchy_sha256") or "") != hierarchy_digest
                or int(data.get("occurrence_path_count", -1)) != len(expected_paths)
                or data.get("occurrence_paths") != expected_paths
            ):
                raise ValueError(
                    f"Component output {name!r} hierarchy metadata disagrees with "
                    "the authenticated host snapshot."
                )
            solved_occurrences = data.get("solved_occurrences")
            if not isinstance(solved_occurrences, list) or len(
                solved_occurrences
            ) != len(expected_paths):
                raise ValueError(
                    f"Component output {name!r} has incomplete stable-path solve evidence."
                )
            for path, occurrence_state in zip(
                expected_paths, solved_occurrences, strict=True
            ):
                if (
                    not isinstance(occurrence_state, dict)
                    or str(occurrence_state.get("occurrence_path") or "") != path
                ):
                    raise ValueError(
                        f"Component output {name!r} changed occurrence solve order."
                    )
                _descriptor, path_chain = _assembly_hierarchy_path(
                    resolved,
                    path,
                    context=f"Component output {name!r}",
                )
                occurrence, leaf = path_chain[-1]
                expected_leaf_type = (
                    "Assembly::AssemblyLink"
                    if str(occurrence.get("link_mode") or "") == "assembly_link"
                    else "App::Link"
                )
                expected_live = (
                    all(
                        str(parent_occurrence.get("link_mode") or "") == "assembly_link"
                        for parent_occurrence, _source in path_chain[:-1]
                    )
                    and source_kind == "assembly"
                )
                if (
                    str(occurrence_state.get("source_node_id") or "")
                    != str(leaf.get("node_id") or "")
                    or str(occurrence_state.get("source_kind") or "")
                    != str(leaf.get("kind") or "")
                    or str(occurrence_state.get("source_label") or "")
                    != str(leaf.get("label") or "")
                    or str(occurrence_state.get("native_type_id") or "")
                    != expected_leaf_type
                    or occurrence_state.get("live_occurrence") is not expected_live
                    or str(occurrence_state.get("native_target_mode") or "")
                    not in {
                        "component_root",
                        "prefixed_rigid_boundary",
                        "direct_exposed_occurrence",
                    }
                ):
                    raise ValueError(
                        f"Component output {name!r} occurrence {path!r} solve "
                        "evidence disagrees with its authenticated hierarchy."
                    )
                if expected_live:
                    _assembly_placement_fact(
                        occurrence_state.get("local_placement"),
                        f"Component output {name!r} occurrence {path!r} local placement",
                    )
                    _assembly_placement_fact(
                        occurrence_state.get("global_placement"),
                        f"Component output {name!r} occurrence {path!r} global placement",
                    )
                elif (
                    occurrence_state.get("local_placement") is not None
                    or occurrence_state.get("global_placement") is not None
                ):
                    raise ValueError(
                        f"Component output {name!r} occurrence {path!r} claimed a "
                        "live placement behind an App::Link boundary."
                    )
        else:
            if declared_flexible:
                raise ValueError(
                    f"Component output {name!r} is flexible without an authenticated hierarchy."
                )
            if (
                str(data.get("hierarchy_sha256") or "")
                or int(data.get("occurrence_path_count", -1)) != 0
                or data.get("occurrence_paths") != []
                or "solved_occurrences" in data
            ):
                raise ValueError(
                    f"Component output {name!r} reported an undeclared hierarchy."
                )
            if native_type_id != "App::Link":
                raise ValueError(
                    f"Component output {name!r} has the wrong native link type."
                )
        initial = _assembly_placement_fact(
            data.get("initial_placement"),
            f"Component output {name!r} initial placement",
        )
        declared_placement = properties.get("placement")
        if not isinstance(declared_placement, dict) or initial["position_mm"] != list(
            declared_placement.get("position") or []
        ):
            raise ValueError(
                f"Component output {name!r} initial placement disagrees with its "
                "definition."
            )
        solved = _assembly_placement_fact(
            data.get("solved_placement"),
            f"Component output {name!r} solved placement",
        )
        component_placement_deltas[name] = _assembly_placement_delta(
            initial,
            solved,
            data.get("authored_to_solved_delta"),
            f"Component output {name!r} authored-to-solved delta",
        )
        if (
            _finite_matrix(
                item.get("solved_placement_matrix"),
                f"Component output {name!r} publication placement",
            )
            != solved["matrix"]
        ):
            raise ValueError(
                f"Component output {name!r} has inconsistent solved placement data."
            )
        component_placements[name] = solved
        component_sources[name] = resolved
        component_metadata[name] = data
        if bool(data.get("grounded")):
            grounded_set.add(name)

    joint_records: dict[str, dict[str, Any]] = {}
    for item in joints:
        name = str(item["name"])
        data = item.get("assembly_data")
        if not isinstance(data, dict):
            raise ValueError(f"Joint output {name!r} has no assembly metadata.")
        if str(data.get("assembly_output") or "") != str(assembly_item["name"]):
            raise ValueError(f"Joint output {name!r} belongs to the wrong assembly.")
        definition = item.get("definition")
        if (
            not isinstance(definition, dict)
            or definition.get("domain") != "assembly"
            or definition.get("operation") != "joint"
            or definition.get("output_type") != "joint"
        ):
            raise ValueError(f"Joint output {name!r} has an invalid definition.")
        properties = definition.get("properties")
        if not isinstance(properties, dict):
            raise ValueError(f"Joint output {name!r} has no definition properties.")
        kind = str(properties.get("kind") or "")
        native_types = {
            "fixed": "Fixed",
            "revolute": "Revolute",
            "cylindrical": "Cylindrical",
            "slider": "Slider",
            "ball": "Ball",
            "distance": "Distance",
            "parallel": "Parallel",
            "perpendicular": "Perpendicular",
            "angle": "Angle",
            "rack_pinion": "RackPinion",
            "screw": "Screw",
            "gears": "Gears",
            "belt": "Belt",
        }
        native_type = native_types.get(kind)
        if native_type is None:
            raise ValueError(f"Joint output {name!r} has unsupported kind {kind!r}.")
        if str(data.get("kind") or "") != kind:
            raise ValueError(
                f"Joint output {name!r} changed kind after source evaluation."
            )
        if str(data.get("native_type") or "") != native_type:
            raise ValueError(
                f"Joint output {name!r} reports the wrong native joint type."
            )
        parameters = properties.get("parameters")
        if not isinstance(parameters, dict) or data.get("parameters") != parameters:
            raise ValueError(f"Joint output {name!r} parameter metadata was altered.")
        parameter_names = {
            "distance": {"distance_mm"},
            "angle": {"angle_degrees"},
            "rack_pinion": {"pitch_radius_mm"},
            "screw": {"thread_pitch_mm"},
            "gears": {"radius1_mm", "radius2_mm"},
            "belt": {"radius1_mm", "radius2_mm"},
        }.get(kind, set())
        if set(parameters) != parameter_names:
            raise ValueError(
                f"Joint output {name!r} parameters must be exactly "
                f"{sorted(parameter_names)} for {kind}."
            )
        for parameter_name, value in parameters.items():
            if isinstance(value, bool) or not math.isfinite(float(value)):
                raise ValueError(
                    f"Joint output {name!r} parameter {parameter_name!r} must be finite."
                )
            number = float(value)
            if parameter_name in {"radius1_mm", "radius2_mm"} and number <= 0.0:
                raise ValueError(
                    f"Joint output {name!r} physical radii must be greater than zero."
                )
            if (
                parameter_name in {"pitch_radius_mm", "thread_pitch_mm"}
                and abs(number) <= 1.0e-12
            ):
                raise ValueError(
                    f"Joint output {name!r} signed motion parameter must be non-zero."
                )
        length_limits = _assembly_limits(
            properties.get("length_limits_mm"),
            f"Joint output {name!r} length_limits_mm",
        )
        angle_limits = _assembly_limits(
            properties.get("angle_limits_degrees"),
            f"Joint output {name!r} angle_limits_degrees",
        )
        if data.get("length_limits_mm") != length_limits:
            raise ValueError(f"Joint output {name!r} length limits were altered.")
        if data.get("angle_limits_degrees") != angle_limits:
            raise ValueError(f"Joint output {name!r} angle limits were altered.")
        if length_limits is not None and kind not in {"slider", "cylindrical"}:
            raise ValueError(f"Joint output {name!r} has inapplicable length limits.")
        if angle_limits is not None and kind not in {"revolute", "cylindrical"}:
            raise ValueError(f"Joint output {name!r} has inapplicable angle limits.")
        suppressed = properties.get("suppressed")
        if (
            not isinstance(suppressed, bool)
            or bool(data.get("suppressed")) != suppressed
        ):
            raise ValueError(f"Joint output {name!r} suppression metadata was altered.")
        compatibility = data.get("compatibility")
        if (
            not isinstance(compatibility, dict)
            or compatibility.get("ok") is not True
            or str(compatibility.get("joint_type") or "") != kind
        ):
            raise ValueError(
                f"Joint output {name!r} has invalid compatibility metadata."
            )
        readback = data.get("native_readback")
        if not isinstance(readback, dict):
            raise ValueError(f"Joint output {name!r} has no native property readback.")
        if (
            str(readback.get("native_type") or "") != native_type
            or readback.get("suppressed") is not suppressed
            or readback.get("length_limits_mm") != length_limits
            or readback.get("angle_limits_degrees") != angle_limits
        ):
            raise ValueError(
                f"Joint output {name!r} native property readback disagrees."
            )
        for parameter_name, value in parameters.items():
            try:
                readback_value = float(readback.get(parameter_name))
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    f"Joint output {name!r} native readback for "
                    f"{parameter_name!r} is not a finite number."
                ) from exc
            if not math.isfinite(readback_value) or readback_value != float(value):
                raise ValueError(
                    f"Joint output {name!r} native readback for "
                    f"{parameter_name!r} disagrees."
                )
        connectors = data.get("connectors")
        if not isinstance(connectors, list) or len(connectors) != 2:
            raise ValueError(
                f"Joint output {name!r} must contain two connector frames."
            )
        if connectors != item.get("connector_frames"):
            raise ValueError(
                f"Joint output {name!r} connector metadata is inconsistent."
            )
        definition_connectors = definition.get("arguments")
        if (
            not isinstance(definition_connectors, list)
            or len(definition_connectors) != 2
        ):
            raise ValueError(
                f"Joint output {name!r} definition must contain two connectors."
            )
        connector_contracts: list[dict[str, Any] | None] = []
        for index, connector in enumerate(connectors, start=1):
            if not isinstance(connector, dict):
                raise ValueError(
                    f"Joint output {name!r} connector {index} must be an object."
                )
            component_name = str(connector.get("component_output") or "")
            if component_name not in component_names:
                raise ValueError(
                    f"Joint output {name!r} connector {index} refers to unknown "
                    f"component {component_name!r}."
                )
            connector_definition = definition_connectors[index - 1]
            if (
                not isinstance(connector_definition, dict)
                or connector_definition.get("domain") != "assembly"
                or connector_definition.get("operation") != "connector"
                or connector_definition.get("output_type") != "connector"
            ):
                raise ValueError(
                    f"Joint output {name!r} connector {index} has an invalid definition."
                )
            if connector_definition.get("arguments") != [
                by_name[component_name].get("definition")
            ]:
                raise ValueError(
                    f"Joint output {name!r} connector {index} does not consume "
                    f"component output {component_name!r}."
                )
            connector_properties = connector_definition.get("properties")
            if not isinstance(connector_properties, dict):
                raise ValueError(
                    f"Joint output {name!r} connector {index} has no properties."
                )
            selection = connector_properties.get("selection")
            if connector.get("selection") != selection or not isinstance(
                selection, dict
            ):
                raise ValueError(
                    f"Joint output {name!r} connector {index} selection was altered."
                )
            mode = str(selection.get("type") or "")
            source_metadata = component_sources[component_name]
            occurrence_path_value = connector_properties.get("occurrence_path")
            if occurrence_path_value is not None and (
                not isinstance(occurrence_path_value, str) or not occurrence_path_value
            ):
                raise ValueError(
                    f"Joint output {name!r} connector {index} has an invalid "
                    "occurrence_path declaration."
                )
            occurrence_path = str(occurrence_path_value or "")
            hierarchy_path_chain = None
            if occurrence_path:
                _descriptor, hierarchy_path_chain = _assembly_hierarchy_path(
                    source_metadata,
                    occurrence_path,
                    context=f"Joint output {name!r} connector {index}",
                )
                source_metadata = _assembly_hierarchy_leaf_metadata(
                    hierarchy_path_chain[-1][1]
                )
            elif bool(component_metadata[component_name].get("flexible")):
                raise ValueError(
                    f"Joint output {name!r} connector {index} targets a flexible "
                    "subassembly without one stable internal occurrence_path."
                )
            if connector.get("occurrence_path") != (
                occurrence_path if occurrence_path else None
            ):
                raise ValueError(
                    f"Joint output {name!r} connector {index} occurrence path was altered."
                )
            expected_standard_frame: Mapping[str, Any] | None = None
            expected_semantic_frame: Mapping[str, Any] | None = None
            expected_connector_contract: dict[str, Any] | None = None
            if mode == "component_origin":
                if selection != {"type": "component_origin"}:
                    raise ValueError(
                        f"Joint output {name!r} connector {index} has a malformed "
                        "component-origin selection."
                    )
                if source_metadata.get("requires_semantic_interfaces"):
                    raise ValueError(
                        f"Joint output {name!r} connector {index} bypassed a required "
                        "published interface."
                    )
                expected_element = ""
                expected_geometry_type = "component_origin"
            elif mode == "exact_subelement":
                expected_element = str(selection.get("subelement") or "")
                match = re.fullmatch(
                    r"(Face|Edge|Vertex)([1-9][0-9]*)", expected_element
                )
                if match is None:
                    raise ValueError(
                        f"Joint output {name!r} connector {index} has an invalid exact "
                        "subelement."
                    )
                if source_metadata.get("transient_topology"):
                    raise ValueError(
                        f"Joint output {name!r} connector {index} uses transient topology "
                        "instead of a semantic interface."
                    )
                count_name = {
                    "Face": "faces",
                    "Edge": "edges",
                    "Vertex": "vertices",
                }[match.group(1)]
                available = int(
                    dict(source_metadata.get("facts") or {}).get(count_name, 0)
                )
                if int(match.group(2)) > available:
                    raise ValueError(
                        f"Joint output {name!r} connector {index} selects "
                        f"{expected_element}, but the authenticated source has only "
                        f"{available} {count_name}."
                    )
                expected_geometry_type = str(connector.get("geometry_type") or "")
                if not expected_geometry_type:
                    raise ValueError(
                        f"Joint output {name!r} connector {index} has no resolved "
                        "geometry type."
                    )
            elif mode == "query":
                try:
                    from vibescript_partdesign_api import normalize_geometry_selection

                    normalized_query = normalize_geometry_selection(
                        "connector",
                        selection,
                    )
                except (TypeError, ValueError) as exc:
                    raise ValueError(
                        f"Joint output {name!r} connector {index} has an invalid "
                        "geometry query."
                    ) from exc
                if normalized_query.get("expected_count") != 1:
                    raise ValueError(
                        f"Joint output {name!r} connector {index} geometry query must "
                        "resolve exactly one element."
                    )
                if source_metadata.get("requires_semantic_interfaces"):
                    raise ValueError(
                        f"Joint output {name!r} connector {index} bypassed a required "
                        "published interface."
                    )
                expected_semantic = {
                    "type": "geometry_query",
                    "query": normalized_query,
                }
                if connector.get("semantic_selection") != expected_semantic:
                    raise ValueError(
                        f"Joint output {name!r} connector {index} lost its measured "
                        "geometry identity."
                    )
                expected_element = str(connector.get("element") or "")
                match = re.fullmatch(
                    r"(Face|Edge)([1-9][0-9]*)",
                    expected_element,
                )
                if match is None:
                    raise ValueError(
                        f"Joint output {name!r} connector {index} resolved an invalid "
                        "geometry-query element."
                    )
                count_name = {"Face": "faces", "Edge": "edges"}[match.group(1)]
                available = int(
                    dict(source_metadata.get("facts") or {}).get(count_name, 0)
                )
                if int(match.group(2)) > available:
                    raise ValueError(
                        f"Joint output {name!r} connector {index} resolved outside "
                        "the authenticated source topology."
                    )
                expected_geometry_type = str(connector.get("geometry_type") or "")
                if not expected_geometry_type:
                    raise ValueError(
                        f"Joint output {name!r} connector {index} has no resolved "
                        "geometry type."
                    )
            elif mode == "published_interface":
                interface_name = str(selection.get("interface_name") or "")
                interface = dict(
                    dict(source_metadata.get("published_interfaces") or {}).get(
                        interface_name
                    )
                    or {}
                )
                subelements = list(interface.get("subelements") or [])
                geometry = list(interface.get("geometry") or [])
                if not interface or len(subelements) > 1 or len(geometry) > 1:
                    raise ValueError(
                        f"Joint output {name!r} connector {index} does not resolve one "
                        "authenticated published interface."
                    )
                expected_element = str(subelements[0]) if subelements else ""
                interface_selection = dict(interface.get("selection") or {})
                expected_geometry_type = str(
                    (geometry[0] if geometry else {}).get("geometry_type")
                    or (
                        "component_frame"
                        if interface_selection.get("type") == "frame"
                        else "component_origin"
                        if not expected_element
                        else ""
                    )
                )
                raw_standard_frame = interface.get("standard_frame")
                if raw_standard_frame is not None:
                    if not isinstance(raw_standard_frame, Mapping):
                        raise ValueError(
                            f"Joint output {name!r} connector {index} has a malformed "
                            "standard-component frame."
                        )
                    expected_standard_frame = raw_standard_frame
                raw_semantic_frame = interface.get("connector_frame")
                if interface_selection.get("type") == "frame":
                    if not isinstance(raw_semantic_frame, Mapping):
                        raise ValueError(
                            f"Joint output {name!r} connector {index} has no "
                            "authenticated semantic frame."
                        )
                    expected_semantic_frame = raw_semantic_frame
                raw_connector_contract = interface.get("connector")
                if raw_connector_contract is not None:
                    if not isinstance(raw_connector_contract, Mapping):
                        raise ValueError(
                            f"Joint output {name!r} connector {index} has a malformed "
                            "explicit connector contract."
                        )
                    expected_connector_contract = dict(raw_connector_contract)
                expected_semantic = {
                    "type": "published_interface",
                    "interface_name": interface_name,
                    "model_id": str(interface.get("model_id") or ""),
                    "publication_name": str(interface.get("publication_name") or ""),
                    "output_key": str(interface.get("output_key") or ""),
                }
                if connector.get("semantic_selection") != expected_semantic:
                    raise ValueError(
                        f"Joint output {name!r} connector {index} lost its "
                        "authenticated semantic identity."
                    )
            else:
                raise ValueError(
                    f"Joint output {name!r} connector {index} uses unsupported "
                    f"selection type {mode!r}."
                )
            if mode == "published_interface":
                semantic = connector.get("semantic_selection")
                if (
                    not isinstance(semantic, dict)
                    or semantic.get("type") != "published_interface"
                    or semantic.get("interface_name") != selection.get("interface_name")
                ):
                    raise ValueError(
                        f"Joint output {name!r} connector {index} lost its semantic identity."
                    )
            if str(connector.get("element") or "") != expected_element:
                raise ValueError(
                    f"Joint output {name!r} connector {index} resolved the wrong element."
                )
            requested_anchor = connector_properties.get("anchor")
            if requested_anchor is not None and mode != "exact_subelement":
                raise ValueError(
                    f"Joint output {name!r} connector {index} applies an anchor to "
                    "a non-exact selection."
                )
            expected_anchor = str(requested_anchor or expected_element)
            if str(connector.get("anchor") or "") != expected_anchor:
                raise ValueError(
                    f"Joint output {name!r} connector {index} resolved the wrong anchor."
                )
            if hierarchy_path_chain is not None:
                (
                    expected_native_component,
                    expected_native_subelements,
                    expected_target_mode,
                ) = _assembly_expected_native_reference(
                    component_metadata[component_name],
                    hierarchy_path_chain,
                    connector.get("native_hierarchy_chain"),
                    stable_path=occurrence_path,
                    element=expected_element,
                    anchor=expected_anchor,
                    context=f"Joint output {name!r} connector {index}",
                )
            else:
                expected_native_component = str(
                    component_metadata[component_name].get("native_name") or ""
                )
                expected_native_subelements = [expected_element, expected_anchor]
                expected_target_mode = "component_root"
                if connector.get("native_hierarchy_chain") != []:
                    raise ValueError(
                        f"Joint output {name!r} connector {index} reported an "
                        "undeclared native hierarchy."
                    )
            if str(connector.get("native_target_mode") or "") != expected_target_mode:
                raise ValueError(
                    f"Joint output {name!r} connector {index} changed native target mode."
                )
            native_reference = connector.get("native_reference")
            if (
                not isinstance(native_reference, dict)
                or str(native_reference.get("component") or "")
                != expected_native_component
                or list(native_reference.get("subelements") or [])
                != expected_native_subelements
            ):
                raise ValueError(
                    f"Joint output {name!r} connector {index} native reference disagrees."
                )
            declared_offset = _assembly_native_declared_placement(
                connector_properties.get("offset"),
                f"Joint output {name!r} connector {index} declared offset",
            )
            if expected_standard_frame is None and expected_semantic_frame is None:
                if connector.get("interface_frame") is not None:
                    raise ValueError(
                        f"Joint output {name!r} connector {index} invented a "
                        "standard-component frame."
                    )
                expected_offset = declared_offset
            elif expected_standard_frame is not None:
                interface_frame = _assembly_native_declared_placement(
                    dict(expected_standard_frame),
                    f"Joint output {name!r} connector {index} standard frame",
                )
                _assembly_validate_placement_fact(
                    connector.get("interface_frame"),
                    interface_frame,
                    f"Joint output {name!r} connector {index} interface_frame",
                )
                expected_offset = interface_frame.multiply(declared_offset)
            else:
                interface_frame = _assembly_native_placement_from_matrix(
                    expected_semantic_frame.get("matrix"),
                    f"Joint output {name!r} connector {index} semantic frame",
                )
                _assembly_validate_placement_fact(
                    connector.get("interface_frame"),
                    interface_frame,
                    f"Joint output {name!r} connector {index} interface_frame",
                )
                expected_offset = interface_frame.multiply(declared_offset)
            _assembly_validate_placement_fact(
                connector.get("offset"),
                expected_offset,
                f"Joint output {name!r} connector {index} offset",
            )
            for frame_name in ("local_frame", "global_frame"):
                _assembly_placement_fact(
                    connector.get(frame_name),
                    f"Joint output {name!r} connector {index} {frame_name}",
                )
            if str(connector.get("geometry_type") or "") != expected_geometry_type:
                raise ValueError(
                    f"Joint output {name!r} connector {index} reports the wrong "
                    "geometry type."
                )
            connector_contracts.append(expected_connector_contract)

        expected_compatibility = _assembly_compatibility(kind, connector_contracts)
        if compatibility != expected_compatibility:
            raise ValueError(
                f"Joint output {name!r} compatibility metadata was altered."
            )
        joint_records[name] = data

    exploded_view_summaries = _validate_assembly_exploded_views(
        prepared,
        exploded_views,
        assembly_item=assembly_item,
        assembly_definition=assembly_definition,
        by_name=by_name,
        component_names=component_names,
        component_placements=component_placements,
        component_sources=component_sources,
    )
    bom_summaries = _validate_assembly_boms(
        boms,
        assembly_item=assembly_item,
        assembly_definition=assembly_definition,
        component_names=component_names,
        component_sources=component_sources,
    )

    simulation_summary = None
    motion_records: list[dict[str, Any]] = []
    if simulations:
        simulation_item = simulations[0]
        simulation_name = str(simulation_item["name"])
        simulation_definition = simulation_item.get("definition")
        if (
            not isinstance(simulation_definition, dict)
            or simulation_definition.get("domain") != "assembly"
            or simulation_definition.get("operation") != "simulation"
            or simulation_definition.get("output_type") != "simulation"
            or simulation_definition.get("arguments") != [assembly_definition]
        ):
            raise ValueError(
                f"Simulation output {simulation_name!r} has an invalid definition."
            )
        simulation_properties = simulation_definition.get("properties")
        required_simulation_properties = {
            "motions",
            "start_time_s",
            "end_time_s",
            "time_step_s",
            "error_tolerance",
            "frames_per_second",
            "estimated_frame_limit",
        }
        optional_simulation_properties = {"label", "motion_names"}
        if (
            not isinstance(simulation_properties, dict)
            or not required_simulation_properties <= set(simulation_properties)
            or set(simulation_properties) - required_simulation_properties
            - optional_simulation_properties
        ):
            raise ValueError(
                f"Simulation output {simulation_name!r} has malformed properties."
            )
        graph_motion_names = [
            str(item) for item in list(assembly_data.get("motion_outputs") or [])
        ]
        declared_motion_names = simulation_properties.get("motion_names")
        if declared_motion_names is not None and list(declared_motion_names) != (
            graph_motion_names
        ):
            raise ValueError(
                f"Simulation output {simulation_name!r} changed its stable motion "
                "member identities."
            )
        motion_definitions = simulation_properties.get("motions")
        if not isinstance(motion_definitions, list) or motion_definitions != [
            by_name[name].get("definition") for name in graph_motion_names
        ]:
            raise ValueError(
                f"Simulation output {simulation_name!r} does not consume the exact "
                "returned motion graph in declared order."
            )
        try:
            start_time = float(simulation_properties["start_time_s"])
            end_time = float(simulation_properties["end_time_s"])
            time_step = float(simulation_properties["time_step_s"])
            error_tolerance = float(simulation_properties["error_tolerance"])
        except (TypeError, ValueError) as exc:
            raise ValueError(
                f"Simulation output {simulation_name!r} has nonnumeric parameters."
            ) from exc
        numeric_parameters = (start_time, end_time, time_step, error_tolerance)
        if (
            any(not math.isfinite(value) for value in numeric_parameters)
            or end_time <= start_time
            or time_step <= 0.0
            or not 1.0e-12 <= error_tolerance <= 1.0
        ):
            raise ValueError(
                f"Simulation output {simulation_name!r} has invalid time or tolerance "
                "parameters."
            )
        frames_per_second = simulation_properties["frames_per_second"]
        estimated_frame_limit = simulation_properties["estimated_frame_limit"]
        if (
            type(frames_per_second) is not int
            or not 1 <= frames_per_second <= 240
            or type(estimated_frame_limit) is not int
            or estimated_frame_limit
            != math.ceil((end_time - start_time) / time_step) + 2
            or not 2 <= estimated_frame_limit <= 10_000
            or estimated_frame_limit * len(components) > 100_000
        ):
            raise ValueError(
                f"Simulation output {simulation_name!r} changed its bounded frame "
                "schedule."
            )

        seen_drives: set[tuple[str, str]] = set()
        for motion_name in graph_motion_names:
            item = by_name[motion_name]
            definition = item.get("definition")
            data = item.get("assembly_data")
            if (
                not isinstance(definition, dict)
                or definition.get("domain") != "assembly"
                or definition.get("operation") != "motion"
                or definition.get("output_type") != "motion"
                or not isinstance(data, dict)
            ):
                raise ValueError(f"Motion output {motion_name!r} is malformed.")
            arguments = definition.get("arguments")
            properties = definition.get("properties")
            if (
                not isinstance(arguments, list)
                or len(arguments) != 1
                or not isinstance(properties, dict)
                or not {"formula", "motion_type"} <= set(properties)
                or set(properties) - {"formula", "motion_type"}
                not in (set(), {"label"})
            ):
                raise ValueError(
                    f"Motion output {motion_name!r} has a malformed definition."
                )
            joint_name = str(data.get("joint_output") or "")
            if joint_name not in joint_records or arguments != [
                by_name[joint_name].get("definition")
            ]:
                raise ValueError(
                    f"Motion output {motion_name!r} does not drive its declared "
                    "returned joint."
                )
            joint_type = str(joint_records[joint_name]["kind"])
            motion_type = str(properties.get("motion_type") or "")
            allowed_motion_types = {
                "revolute": {"angular"},
                "slider": {"linear"},
                "cylindrical": {"angular", "linear"},
            }.get(joint_type, set())
            if motion_type not in allowed_motion_types or bool(
                joint_records[joint_name]["suppressed"]
            ):
                raise ValueError(
                    f"Motion output {motion_name!r} cannot drive the declared "
                    f"{joint_type!r} joint."
                )
            drive = (joint_name, motion_type)
            if drive in seen_drives:
                raise ValueError(
                    f"Motion output {motion_name!r} duplicates the {motion_type} "
                    f"drive on joint {joint_name!r}."
                )
            seen_drives.add(drive)
            formula = _assembly_motion_formula(
                properties.get("formula"), f"Motion output {motion_name!r} formula"
            )
            record = {
                "motion_output": motion_name,
                "joint_output": joint_name,
                "joint_type": joint_type,
                "motion_type": motion_type,
                "native_motion_type": (
                    "Angular" if motion_type == "angular" else "Linear"
                ),
                "formula": formula,
            }
            expected_motion_data = {
                "assembly_output": str(assembly_item["name"]),
                "simulation_output": simulation_name,
                **record,
            }
            if data != expected_motion_data:
                raise ValueError(
                    f"Motion output {motion_name!r} metadata was altered after native "
                    "execution."
                )
            motion_records.append(record)

        context = f"Simulation output {simulation_name!r} trace"
        trace_path = _staged_artifact_path(
            prepared,
            simulation_item.get("artifact_path"),
            context=context,
            maximum_bytes=_MAX_ASSEMBLY_SIMULATION_TRACE_BYTES,
        )
        artifact_bytes = trace_path.stat().st_size
        artifact_digest = _sha256_file(trace_path)
        if (
            simulation_item.get("artifact_kind") != "assembly_simulation_json"
            or simulation_item.get("artifact_schema")
            != _ASSEMBLY_SIMULATION_TRACE_SCHEMA
            or simulation_item.get("artifact_sha256") != artifact_digest
            or simulation_item.get("artifact_bytes") != artifact_bytes
        ):
            raise ValueError(
                f"Simulation output {simulation_name!r} trace identity changed."
            )
        try:
            trace = json.loads(trace_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            raise ValueError(f"{context} is not valid UTF-8 JSON.") from exc
        if not isinstance(trace, dict) or set(trace) != {
            "schema",
            "assembly_output",
            "simulation_output",
            "component_outputs",
            "motion_outputs",
            "parameters",
            "motion_observations",
            "collision_summary",
            "collision_warnings",
            "frames",
        }:
            raise ValueError(f"{context} has the wrong schema fields.")
        parameters = {
            "start_time_s": start_time,
            "end_time_s": end_time,
            "time_step_s": time_step,
            "error_tolerance": error_tolerance,
            "frames_per_second": frames_per_second,
        }
        if (
            trace.get("schema") != _ASSEMBLY_SIMULATION_TRACE_SCHEMA
            or trace.get("assembly_output") != str(assembly_item["name"])
            or trace.get("simulation_output") != simulation_name
            or trace.get("component_outputs") != component_names
            or trace.get("motion_outputs") != graph_motion_names
            or trace.get("parameters") != parameters
        ):
            raise ValueError(f"{context} does not match the declared graph.")
        raw_frames = trace.get("frames")
        if (
            not isinstance(raw_frames, list)
            or not 2 <= len(raw_frames) <= estimated_frame_limit
            or len(raw_frames) * len(component_names) > 100_000
        ):
            raise ValueError(f"{context} has an invalid frame or pose count.")
        frames: list[dict[str, Any]] = []
        for frame_index, raw_frame in enumerate(raw_frames):
            if not isinstance(raw_frame, dict) or set(raw_frame) != {
                "frame_index",
                "frame_kind",
                "nominal_time_s",
                "component_placements",
                "collisions",
            }:
                raise ValueError(f"{context} frame {frame_index} is malformed.")
            expected_kind = "input" if frame_index == 0 else "solver_output"
            expected_time = (
                None
                if frame_index == 0
                else min(end_time, start_time + (frame_index - 1) * time_step)
            )
            placements = raw_frame.get("component_placements")
            if (
                raw_frame.get("frame_index") != frame_index
                or raw_frame.get("frame_kind") != expected_kind
                or raw_frame.get("nominal_time_s") != expected_time
                or not isinstance(placements, dict)
                or set(placements) != set(component_names)
                or not isinstance(raw_frame.get("collisions"), list)
                or len(raw_frame["collisions"])
                > (len(component_names) * (len(component_names) - 1)) // 2
            ):
                raise ValueError(
                    f"{context} frame {frame_index} changed its schedule or components."
                )
            frames.append(
                {
                    **raw_frame,
                    "component_placements": {
                        name: _assembly_compact_placement(
                            placements[name],
                            f"{context} frame {frame_index} component {name!r}",
                        )
                        for name in component_names
                    },
                    "collisions": list(raw_frame["collisions"]),
                }
            )
        observations = _assembly_motion_observations(
            frames, motion_records, joint_records
        )
        if trace.get("motion_observations") != observations:
            raise ValueError(
                f"{context} motion observations do not match its component poses."
            )
        # The version-bound external worker performs the expensive OCCT common
        # operations away from the GUI thread. The host authenticates its trace
        # artifact and component inputs, validates every pair record below, and
        # independently derives the complete summary from those frame records.
        expected_collision_summary = summarize_dynamic_collision_frames(
            component_names,
            [
                {
                    "frame_index": int(frame["frame_index"]),
                    "nominal_time_s": frame["nominal_time_s"],
                    "collisions": list(frame["collisions"]),
                }
                for frame in frames[1:]
            ],
            evaluation_warnings=trace.get("collision_warnings"),
        )
        if (
            trace.get("collision_summary") != expected_collision_summary
            or frames[0]["collisions"] != []
        ):
            raise ValueError(
                f"{context} collision summary does not match its authenticated "
                "per-frame exact evidence."
            )
        for observation in observations:
            change = (
                float(observation["maximum_relative_rotation_degrees"])
                if observation["motion_type"] == "angular"
                else float(observation["maximum_relative_translation_mm"])
            )
            tolerance = 1.0e-7 if observation["motion_type"] == "angular" else 1.0e-8
            if observation["time_dependent"] and change <= tolerance:
                raise ValueError(
                    f"Motion output {observation['motion_output']!r} uses time but "
                    "has no measurable authenticated movement."
                )
        simulation_summary = {
            "simulation_output": simulation_name,
            "motion_outputs": graph_motion_names,
            "parameters": parameters,
            "native_code": 0,
            "frame_count": len(frames),
            "pose_count": len(frames) * len(component_names),
            "motion_observations": observations,
            "collision_summary": expected_collision_summary,
            "artifact_schema": _ASSEMBLY_SIMULATION_TRACE_SCHEMA,
            "artifact_sha256": artifact_digest,
            "artifact_bytes": artifact_bytes,
        }
        if (
            simulation_item.get("frame_count") != len(frames)
            or simulation_item.get("pose_count") != len(frames) * len(component_names)
            or simulation_item.get("assembly_data")
            != {"assembly_output": str(assembly_item["name"]), **simulation_summary}
        ):
            raise ValueError(
                f"Simulation output {simulation_name!r} summary is inconsistent."
            )
        preview_indices = sorted({0, len(frames) // 2, len(frames) - 1})
        simulation_item["simulation_trace_preview"] = [
            frames[index] for index in preview_indices
        ]

    diagnostics = diagnostics_item.get("diagnostics")
    if not isinstance(diagnostics, dict):
        raise ValueError("The solver_diagnostics output has no native diagnostics.")
    try:
        solver_code = int(diagnostics.get("solver_code"))
    except (TypeError, ValueError) as exc:
        raise ValueError("The Assembly diagnostics solver code is invalid.") from exc
    if solver_code != int(validation.get("solver_code", -998)):
        raise ValueError(
            "The Assembly solver code is inconsistent across worker outputs."
        )
    if int(diagnostics.get("component_count", -1)) != len(components):
        raise ValueError("The Assembly diagnostics component count is inconsistent.")
    if int(diagnostics.get("joint_count", -1)) != len(joints):
        raise ValueError("The Assembly diagnostics joint count is inconsistent.")
    grounded = [name for name in component_names if name in grounded_set]
    if list(diagnostics.get("grounded_components") or []) != grounded:
        raise ValueError(
            "The Assembly diagnostics grounded-component list is inconsistent."
        )
    if list(diagnostics.get("joint_outputs") or []) != joint_names:
        raise ValueError("The Assembly diagnostics joint-output list is inconsistent.")
    if diagnostics.get("component_placements") != component_placements:
        raise ValueError(
            "The Assembly diagnostics solved placements do not match component outputs."
        )
    if diagnostics.get("component_placement_deltas") != component_placement_deltas:
        raise ValueError(
            "The Assembly diagnostics placement deltas do not match component outputs."
        )
    expected_occurrence_counts = {
        name: int(data.get("occurrence_path_count", 0))
        for name, data in component_metadata.items()
        if str(data.get("hierarchy_sha256") or "")
    }
    if diagnostics.get("component_occurrence_counts") != expected_occurrence_counts:
        raise ValueError(
            "The Assembly diagnostics stable-occurrence counts do not match "
            "component outputs."
        )
    require_solved = diagnostics_properties["require_solved"]
    if diagnostics.get("require_solved") is not require_solved:
        raise ValueError(
            "The Assembly diagnostics changed the declared require_solved policy."
        )
    native = diagnostics.get("native")
    if not isinstance(native, dict):
        raise ValueError("The Assembly diagnostics have no native solver report.")
    invalid_solution = any(
        bool(native.get(name))
        for name in (
            "has_conflicts",
            "has_malformed_constraints",
        )
    )
    dependency_issues = diagnostics.get("joint_dependency_issues")
    if not isinstance(dependency_issues, list):
        raise ValueError("The Assembly diagnostics have no joint-dependency report.")
    expected_dependency_issues = _assembly_joint_dependency_issues(joint_records)
    if dependency_issues != expected_dependency_issues:
        raise ValueError(
            "The Assembly joint-dependency report does not match the returned joint graph."
        )
    if dependency_issues != list(validation.get("joint_dependency_issues") or []):
        raise ValueError(
            "The Assembly joint-dependency report is inconsistent across worker outputs."
        )
    if simulation_summary is not None:
        if diagnostics.get("simulation") != simulation_summary:
            raise ValueError(
                "The Assembly diagnostics simulation summary is inconsistent."
            )
    elif "simulation" in diagnostics or "simulation" in validation:
        raise ValueError("The Assembly diagnostics report an undeclared simulation.")
    if exploded_view_summaries:
        if (
            diagnostics.get("exploded_views") != exploded_view_summaries
            or validation.get("exploded_views") != exploded_view_summaries
        ):
            raise ValueError(
                "The Assembly exploded-view summaries are inconsistent across "
                "worker outputs."
            )
    elif "exploded_views" in diagnostics or "exploded_views" in validation:
        raise ValueError("The Assembly diagnostics report undeclared exploded views.")
    if bom_summaries:
        if (
            diagnostics.get("boms") != bom_summaries
            or validation.get("boms") != bom_summaries
        ):
            raise ValueError(
                "The Assembly BOM summaries are inconsistent across worker outputs."
            )
    elif "boms" in diagnostics or "boms" in validation:
        raise ValueError("The Assembly diagnostics report undeclared BOM outputs.")
    expected_status = (
        "solved"
        if solver_code == 0 and not invalid_solution and not dependency_issues
        else "failed"
    )
    if diagnostics.get("status") != expected_status:
        raise ValueError(
            "The Assembly diagnostics status does not match the native solver result."
        )
    solver_verdicts = {
        0: "solved",
        -1: "solver_error",
        -2: "redundant_constraints",
        -3: "conflicting_constraints",
        -4: "over_constrained",
        -5: "malformed_constraints",
        -6: "no_grounded_component",
    }
    expected_verdict = solver_verdicts.get(solver_code, f"unknown_status_{solver_code}")
    if diagnostics.get("solver_verdict") != expected_verdict:
        raise ValueError(
            "The Assembly diagnostics verdict does not match the native solver code."
        )
    if require_solved and (
        solver_code != 0
        or invalid_solution
        or dependency_issues
        or diagnostics.get("status") != "solved"
    ):
        raise ValueError(
            "The Assembly worker claimed a required solution without a clean native "
            "solver result."
        )
    expected_solver_scope = solver_validation_scope(
        constraints_consistent=(
            expected_status == "solved"
            and solver_code == 0
            and not invalid_solution
            and not expected_dependency_issues
        )
    )
    if diagnostics.get("validation_scope") != expected_solver_scope:
        raise ValueError(
            "The Assembly diagnostics misstate what the native solver validated."
        )
    mechanism_scenario = _assembly_shared_mechanism_scenario(
        assembly_item=assembly_item,
        diagnostics_item=diagnostics_item,
        component_names=component_names,
        joint_names=joint_names,
        motion_names=graph_motion_names,
        simulation_item=(simulations[0] if simulations else None),
        by_name=by_name,
        joint_records=joint_records,
    )
    mechanism_solve_report = normalize_mechanism_solve_report(
        mechanism_scenario,
        {
            "schema": MECHANISM_SOLVE_REPORT_SCHEMA,
            "scenario_sha256": mechanism_scenario_sha256(mechanism_scenario),
            "status": expected_status,
            "solver_code": solver_code,
            "solver_verdict": expected_verdict,
            "require_solved": require_solved,
            "component_count": len(components),
            "joint_count": len(joints),
            "grounded_components": grounded,
            "native_diagnostics": native,
            "component_placements": component_placements,
            "component_occurrences": {
                name: list(component_metadata[name].get("solved_occurrences") or [])
                for name in component_names
            },
            "joint_dependency_issues": expected_dependency_issues,
        },
    )
    verification_summaries = _validate_assembly_mechanism_verifications(
        prepared,
        verifications,
        scenario=mechanism_scenario,
        solve_report=mechanism_solve_report,
        assembly_item=assembly_item,
        assembly_definition=assembly_definition,
        by_name=by_name,
        component_names=component_names,
        component_placements=component_placements,
        component_sources=component_sources,
        component_metadata=component_metadata,
    )
    if verification_summaries:
        if (
            diagnostics.get("verifications") != verification_summaries
            or validation.get("verifications") != verification_summaries
        ):
            raise ValueError(
                "The Assembly mechanism-verification summaries are inconsistent "
                "across worker outputs."
            )
    elif "verifications" in diagnostics or "verifications" in validation:
        raise ValueError(
            "The Assembly diagnostics report undeclared mechanism verifications."
        )
    expected_validation = {
        "status": expected_status,
        "solver_code": solver_code,
        "solver_verdict": expected_verdict,
        "component_count": len(components),
        "joint_count": len(joints),
        "grounded_components": grounded,
        "native_diagnostics": native,
        "component_placements": component_placements,
        "component_placement_deltas": component_placement_deltas,
        "component_occurrence_counts": expected_occurrence_counts,
        "joint_dependency_issues": expected_dependency_issues,
        "internal_member_outputs": [
            str(item["name"]) for item in outputs if item.get("internal") is True
        ],
        "validation_scope": expected_solver_scope,
    }
    if simulation_summary is not None:
        expected_validation["simulation"] = simulation_summary
    if exploded_view_summaries:
        expected_validation["exploded_views"] = exploded_view_summaries
    if bom_summaries:
        expected_validation["boms"] = bom_summaries
    if verification_summaries:
        expected_validation["verifications"] = verification_summaries
    for field, expected_value in expected_validation.items():
        if validation.get(field) != expected_value:
            raise ValueError(
                f"The Assembly worker validation field {field!r} is inconsistent."
            )
    for item in outputs:
        data = item.get("assembly_data")
        _validate_definition_value(
            data,
            prepared,
            f"outputs.{item['name']}.assembly_data",
        )
        encoded = json.dumps(
            data,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
        if len(encoded) > _STRUCTURED_DEFINITION_LIMIT:
            raise ValueError(f"Output {item['name']!r} assembly metadata is too large.")
    return dict(validation)


def _exact_mapping(
    value: Any,
    *,
    path: str,
    keys: set[str],
) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError(f"{path} must be an object.")
    if set(value) != keys:
        missing = sorted(keys - set(value))
        unexpected = sorted(set(value) - keys)
        raise ValueError(
            f"{path} has the wrong fields (missing={missing}, unexpected={unexpected})."
        )
    return dict(value)


def _sketcher_payload(
    value: Any,
    *,
    path: str,
    operation: str | None = None,
    output_type: str | None = None,
) -> tuple[dict[str, Any], list[Any], dict[str, Any]]:
    payload = _exact_mapping(
        value,
        path=path,
        keys={"domain", "operation", "output_type", "arguments", "properties"},
    )
    if payload["domain"] != "sketcher":
        raise ValueError(f"{path} belongs to a different VibeScript domain.")
    if operation is not None and payload["operation"] != operation:
        raise ValueError(f"{path} must come from api.{operation}.")
    if output_type is not None and payload["output_type"] != output_type:
        raise ValueError(f"{path} must have output type {output_type!r}.")
    arguments = payload["arguments"]
    properties = payload["properties"]
    if not isinstance(arguments, list) or not isinstance(properties, dict):
        raise ValueError(f"{path} arguments/properties are malformed.")
    return payload, list(arguments), dict(properties)


def _validate_sketcher_diagnostic_reference(
    value: Any,
    *,
    path: str,
    geometry_readback: list[dict[str, Any]],
    allowed_points: set[str],
) -> tuple[str, str]:
    data = _exact_mapping(
        value,
        path=path,
        keys={
            "graph_id",
            "name",
            "source_index",
            "operation",
            "construction",
            "point",
        },
    )
    source_index = data["source_index"]
    if type(source_index) is not int or not 0 <= source_index < len(geometry_readback):
        raise ValueError(f"{path}.source_index is outside the source geometry graph.")
    expected = geometry_readback[source_index]
    for field in ("graph_id", "name", "operation", "construction"):
        if data[field] != expected[field]:
            raise ValueError(f"{path}.{field} differs from the source geometry graph.")
    point = data["point"]
    if point not in allowed_points:
        raise ValueError(f"{path}.point is invalid for this diagnostic.")
    return str(data["graph_id"]), str(point)


def _validate_sketcher_underconstraint_guidance(
    value: Any,
    *,
    degrees_of_freedom: int,
    geometry_readback: list[dict[str, Any]],
) -> None:
    guidance = _exact_mapping(
        value,
        path="sketch_validation.underconstraint_guidance",
        keys={
            "status",
            "canonical_operation",
            "automatic_application",
            "workflow",
            "position_tolerance_mm",
            "angle_tolerance_degrees",
            "equality_tolerance_mm",
            "equality_geometry_limit",
            "detected_counts",
            "filtered_existing_count",
            "skipped_detectors",
            "suggestions",
            "suggestions_truncated",
            "native_error",
        },
    )
    if guidance["canonical_operation"] != "api.constraint":
        raise ValueError(
            "Sketcher guidance must use the canonical constraint operation."
        )
    if guidance["automatic_application"] is not False:
        raise ValueError("Sketcher heuristic constraints must never be auto-applied.")
    if guidance["workflow"] != [
        "connectivity",
        "orientation",
        "equality",
        "dimensions",
    ]:
        raise ValueError("Sketcher underconstraint workflow is inconsistent.")
    numeric_contract = {
        "position_tolerance_mm": _SKETCHER_SUGGESTION_POSITION_TOLERANCE_MM,
        "angle_tolerance_degrees": _SKETCHER_SUGGESTION_ANGLE_TOLERANCE_DEGREES,
        "equality_tolerance_mm": _SKETCHER_SUGGESTION_EQUALITY_TOLERANCE_MM,
    }
    for field, expected in numeric_contract.items():
        if guidance[field] != expected:
            raise ValueError(f"Sketcher guidance {field} is inconsistent.")
    if (
        guidance["equality_geometry_limit"]
        != _SKETCHER_MAX_EQUALITY_DIAGNOSTIC_GEOMETRY
    ):
        raise ValueError("Sketcher equality diagnostic limit is inconsistent.")
    counts = _exact_mapping(
        guidance["detected_counts"],
        path="sketch_validation.underconstraint_guidance.detected_counts",
        keys={"connectivity", "orientation", "equality"},
    )
    if any(type(counts[field]) is not int or counts[field] < 0 for field in counts):
        raise ValueError("Sketcher detected suggestion counts are invalid.")
    if (
        type(guidance["filtered_existing_count"]) is not int
        or guidance["filtered_existing_count"] < 0
    ):
        raise ValueError("Sketcher filtered suggestion count is invalid.")
    skipped = guidance["skipped_detectors"]
    if (
        not isinstance(skipped, list)
        or len(skipped) != len(set(skipped))
        or any(item != "equality_size_guard" for item in skipped)
    ):
        raise ValueError("Sketcher skipped-detector diagnostics are invalid.")
    suggestions = guidance["suggestions"]
    if (
        not isinstance(suggestions, list)
        or len(suggestions) > _SKETCHER_MAX_UNDERCONSTRAINT_SUGGESTIONS
    ):
        raise ValueError("Sketcher underconstraint suggestions are not bounded.")
    if not isinstance(guidance["suggestions_truncated"], bool):
        raise ValueError("Sketcher suggestion truncation metadata is invalid.")
    if (
        not isinstance(guidance["native_error"], str)
        or len(guidance["native_error"]) > 512
    ):
        raise ValueError("Sketcher suggestion native error is invalid.")

    forms = {
        ("coincident", "connectivity", "native_missing_endpoint_coincidence"): (
            2,
            {"start", "end"},
        ),
        ("horizontal", "orientation", "native_near_horizontal"): (1, {"none"}),
        ("vertical", "orientation", "native_near_vertical"): (1, {"none"}),
        ("equal", "equality", "native_equal_line_length"): (2, {"none"}),
        ("equal", "equality", "native_equal_radius"): (2, {"none"}),
    }
    seen: set[tuple[str, tuple[tuple[str, str], ...]]] = set()
    category_counts = {"connectivity": 0, "orientation": 0, "equality": 0}
    for index, raw in enumerate(suggestions):
        suggestion = _exact_mapping(
            raw,
            path=f"sketch_validation.underconstraint_guidance.suggestions[{index}]",
            keys={"kind", "category", "reason", "intent_required", "entities"},
        )
        form = (
            str(suggestion["kind"]),
            str(suggestion["category"]),
            str(suggestion["reason"]),
        )
        contract = forms.get(form)
        if contract is None or suggestion["intent_required"] is not True:
            raise ValueError("Sketcher underconstraint suggestion form is invalid.")
        expected_count, allowed_points = contract
        entities = suggestion["entities"]
        if not isinstance(entities, list) or len(entities) != expected_count:
            raise ValueError("Sketcher underconstraint suggestion arity is invalid.")
        entity_keys = tuple(
            _validate_sketcher_diagnostic_reference(
                entity,
                path=(
                    "sketch_validation.underconstraint_guidance."
                    f"suggestions[{index}].entities[{entity_index}]"
                ),
                geometry_readback=geometry_readback,
                allowed_points=allowed_points,
            )
            for entity_index, entity in enumerate(entities)
        )
        if suggestion["kind"] in {"coincident", "equal"}:
            entity_keys = tuple(sorted(entity_keys))
        key = (str(suggestion["kind"]), entity_keys)
        if key in seen:
            raise ValueError("Sketcher underconstraint suggestion is duplicated.")
        seen.add(key)
        category_counts[str(suggestion["category"])] += 1
        operations = [
            str(entity["operation"]) for entity in entities if isinstance(entity, dict)
        ]
        if suggestion["kind"] in {"horizontal", "vertical"} and operations != ["line"]:
            raise ValueError("Sketcher orientation suggestion must reference a line.")
        if suggestion["reason"] == "native_equal_line_length" and any(
            operation != "line" for operation in operations
        ):
            raise ValueError(
                "Sketcher line equality suggestion references another type."
            )
        if suggestion["reason"] == "native_equal_radius" and any(
            operation not in {"arc", "circle"} for operation in operations
        ):
            raise ValueError(
                "Sketcher radius equality suggestion references another type."
            )
    if any(category_counts[field] > counts[field] for field in category_counts):
        raise ValueError("Sketcher suggestion counts exceed native detections.")
    if guidance["filtered_existing_count"] > sum(counts.values()):
        raise ValueError("Sketcher filtered suggestions exceed native detections.")
    if (
        guidance["suggestions_truncated"]
        and len(suggestions) != _SKETCHER_MAX_UNDERCONSTRAINT_SUGGESTIONS
    ):
        raise ValueError(
            "Truncated Sketcher suggestions do not fill the bounded window."
        )

    status = guidance["status"]
    if degrees_of_freedom == 0:
        if (
            status != "not_needed"
            or suggestions
            or any(counts.values())
            or guidance["filtered_existing_count"]
            or skipped
            or guidance["native_error"]
            or guidance["suggestions_truncated"]
        ):
            raise ValueError("Fully constrained Sketcher guidance is inconsistent.")
    elif status == "available":
        if guidance["native_error"]:
            raise ValueError("Available Sketcher guidance contains a native error.")
        equality_eligible = sum(
            str(item.get("operation") or "") in {"line", "arc", "circle"}
            and str(item.get("operation") or "") != "external_geometry"
            for item in geometry_readback
        )
        expected_skipped = (
            ["equality_size_guard"]
            if equality_eligible > _SKETCHER_MAX_EQUALITY_DIAGNOSTIC_GEOMETRY
            else []
        )
        if skipped != expected_skipped:
            raise ValueError("Sketcher equality size-guard metadata is inconsistent.")
        if skipped and counts["equality"] != 0:
            raise ValueError("Skipped Sketcher equality diagnostics report detections.")
    elif status == "native_diagnostics_unavailable":
        if suggestions or not guidance["native_error"]:
            raise ValueError("Unavailable Sketcher guidance is inconsistent.")
    else:
        raise ValueError("Sketcher underconstraint guidance has an invalid status.")


def _validate_sketcher_profile_open_vertices(
    value: Any,
    *,
    open_wire_count: int,
    geometry_readback: list[dict[str, Any]],
) -> None:
    diagnostics = _exact_mapping(
        value,
        path="sketch_validation.profile_open_vertices",
        keys={
            "status",
            "match_tolerance_mm",
            "vertices",
            "truncated",
            "native_error",
        },
    )
    if (
        diagnostics["match_tolerance_mm"]
        != _SKETCHER_PROFILE_ENDPOINT_MATCH_TOLERANCE_MM
    ):
        raise ValueError("Sketcher open-vertex match tolerance is inconsistent.")
    vertices = diagnostics["vertices"]
    if (
        not isinstance(vertices, list)
        or len(vertices) > _SKETCHER_MAX_PROFILE_OPEN_VERTICES
    ):
        raise ValueError("Sketcher open-vertex diagnostics are not bounded.")
    if not isinstance(diagnostics["truncated"], bool):
        raise ValueError("Sketcher open-vertex truncation metadata is invalid.")
    if (
        not isinstance(diagnostics["native_error"], str)
        or len(diagnostics["native_error"]) > 512
    ):
        raise ValueError("Sketcher open-vertex native error is invalid.")
    for index, raw in enumerate(vertices):
        vertex = _exact_mapping(
            raw,
            path=f"sketch_validation.profile_open_vertices.vertices[{index}]",
            keys={"position_mm", "candidate_endpoints", "matches_truncated"},
        )
        position = vertex["position_mm"]
        if (
            not isinstance(position, list)
            or len(position) != 2
            or any(
                isinstance(item, bool)
                or not isinstance(item, (int, float))
                or not math.isfinite(item)
                for item in position
            )
        ):
            raise ValueError("Sketcher open-vertex position is invalid.")
        matches = vertex["candidate_endpoints"]
        if (
            not isinstance(matches, list)
            or len(matches) > _SKETCHER_MAX_PROFILE_ENDPOINT_MATCHES
        ):
            raise ValueError("Sketcher open-vertex endpoint matches are not bounded.")
        if not isinstance(vertex["matches_truncated"], bool):
            raise ValueError("Sketcher endpoint-match truncation metadata is invalid.")
        if (
            vertex["matches_truncated"]
            and len(matches) != _SKETCHER_MAX_PROFILE_ENDPOINT_MATCHES
        ):
            raise ValueError(
                "Truncated Sketcher endpoint matches do not fill the window."
            )
        seen_matches: set[tuple[str, str]] = set()
        for match_index, match in enumerate(matches):
            key = _validate_sketcher_diagnostic_reference(
                match,
                path=(
                    "sketch_validation.profile_open_vertices."
                    f"vertices[{index}].candidate_endpoints[{match_index}]"
                ),
                geometry_readback=geometry_readback,
                allowed_points={"start", "end"},
            )
            if key in seen_matches:
                raise ValueError("Sketcher open-vertex endpoint match is duplicated.")
            seen_matches.add(key)
            if bool(match["construction"]) or str(match["operation"]) not in {
                "line",
                "arc",
                "elliptic_arc",
                "hyperbolic_arc",
                "parabolic_arc",
                "bspline",
            }:
                raise ValueError("Sketcher open-vertex endpoint type is invalid.")
    status = diagnostics["status"]
    if open_wire_count == 0:
        if (
            status != "not_needed"
            or vertices
            or diagnostics["truncated"]
            or diagnostics["native_error"]
        ):
            raise ValueError("Closed Sketcher profile diagnostics are inconsistent.")
    elif status == "available":
        if diagnostics["native_error"] or not vertices:
            raise ValueError(
                "Available Sketcher open-vertex diagnostics contain an error."
            )
        if (
            diagnostics["truncated"]
            and len(vertices) != _SKETCHER_MAX_PROFILE_OPEN_VERTICES
        ):
            raise ValueError("Truncated Sketcher open vertices do not fill the window.")
    elif status == "native_diagnostics_unavailable":
        if vertices or not diagnostics["native_error"]:
            raise ValueError(
                "Unavailable Sketcher open-vertex diagnostics are inconsistent."
            )
    else:
        raise ValueError("Sketcher open-vertex diagnostics have an invalid status.")


def _validate_sketcher_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    """Reauthorize an isolated native Sketcher solve and its exact graph."""

    if len(outputs) != 1 or str(outputs[0].get("type") or "") != "sketch":
        raise ValueError("A Sketcher candidate must contain exactly one sketch output.")
    item = outputs[0]
    _payload, arguments, properties = _sketcher_payload(
        item.get("definition"),
        path=f"outputs.{item['name']}.definition",
        operation="sketch",
        output_type="sketch",
    )
    if len(arguments) != 2:
        raise ValueError("api.sketch must serialize exactly geometry and constraints.")
    geometry = arguments[0]
    constraints = arguments[1]
    if not isinstance(geometry, list) or not 1 <= len(geometry) <= 4096:
        raise ValueError("A Sketcher definition must contain 1-4096 geometry values.")
    if not isinstance(constraints, list) or len(constraints) > 16384:
        raise ValueError("A Sketcher definition may contain at most 16384 constraints.")
    _exact_mapping(
        properties,
        path="api.sketch.properties",
        keys={
            "support",
            "map_mode",
            "attachment_offset",
            "require_fully_constrained",
            "require_closed_profile",
            "label",
        },
    )
    if not isinstance(properties["map_mode"], str) or not properties["map_mode"]:
        raise ValueError("api.sketch.map_mode must be a non-empty string.")
    if not isinstance(properties["label"], str) or len(properties["label"]) > 256:
        raise ValueError("api.sketch.label is invalid.")
    for field in ("require_fully_constrained", "require_closed_profile"):
        if not isinstance(properties[field], bool):
            raise ValueError(f"api.sketch.{field} must be a boolean.")
    attachment = _exact_mapping(
        properties["attachment_offset"],
        path="api.sketch.attachment_offset",
        keys={"position", "rotation"},
    )
    if not isinstance(attachment["position"], list) or len(attachment["position"]) != 3:
        raise ValueError(
            "api.sketch.attachment_offset.position must contain three values."
        )
    if not isinstance(attachment["rotation"], list) or len(attachment["rotation"]) != 4:
        raise ValueError(
            "api.sketch.attachment_offset.rotation must contain four values."
        )
    rotation_magnitude = math.sqrt(
        sum(float(value) ** 2 for value in attachment["rotation"])
    )
    if not math.isclose(rotation_magnitude, 1.0, rel_tol=0.0, abs_tol=1.0e-12):
        raise ValueError("api.sketch attachment quaternion is not normalized.")

    resolved_reference_metadata = {
        (
            str(value.get("document_uid") or ""),
            str(value.get("object_name") or ""),
        ): value
        for value in list(prepared.get("resolved_references") or [])
    }
    support = properties["support"]
    expected_support_validation: dict[str, Any] | None = None
    if support is not None:
        support_data = _exact_mapping(
            support,
            path="api.sketch.support",
            keys={"reference", "selection"},
        )
        reference = _exact_mapping(
            support_data["reference"],
            path="api.sketch.support.reference",
            keys={"document_uid", "object_name"},
        )
        reference_key = (str(reference["document_uid"]), str(reference["object_name"]))
        reference_metadata = resolved_reference_metadata.get(reference_key)
        if reference_metadata is None:
            raise ValueError(
                "Sketch support was not authenticated as a staged input reference."
            )
        selection = support_data["selection"]
        if not isinstance(selection, dict):
            raise ValueError("Sketch support selection must be an object.")
        selection_type = str(selection.get("type") or "")
        interface_name = ""
        if selection_type == "subelements":
            _exact_mapping(
                selection,
                path="api.sketch.support.selection",
                keys={"type", "subelements"},
            )
            if bool(reference_metadata.get("transient_topology")) or bool(
                reference_metadata.get("requires_semantic_interfaces")
            ):
                raise ValueError(
                    "A regenerating Sketch support must use a published semantic interface."
                )
            subelements = selection["subelements"]
        elif selection_type == "published_interface":
            _exact_mapping(
                selection,
                path="api.sketch.support.selection",
                keys={"type", "interface_name"},
            )
            interface_name = str(selection["interface_name"] or "")
            interfaces = reference_metadata.get("published_interfaces")
            interface = (
                interfaces.get(interface_name) if isinstance(interfaces, dict) else None
            )
            if not isinstance(interface, dict):
                raise ValueError(
                    f"Sketch support interface {interface_name!r} is not in the host contract."
                )
            subelements = interface.get("subelements")
        else:
            raise ValueError(
                f"Sketch support selection type {selection_type!r} is invalid."
            )
        if not isinstance(subelements, list) or not 1 <= len(subelements) <= 4:
            raise ValueError(
                "Sketch support must resolve to one through four subelements."
            )
        if any(
            re.fullmatch(r"(?:Face|Edge|Vertex)[1-9][0-9]*", str(value or "")) is None
            for value in subelements
        ):
            raise ValueError("Sketch support contains an invalid subelement name.")
        if len(set(str(value) for value in subelements)) != len(subelements):
            raise ValueError("Sketch support contains duplicate subelement names.")
        expected_support_validation = {
            "reference": dict(reference),
            "requested_selection": dict(selection),
            "resolved_subelements": [str(value) for value in subelements],
            "source_kind": str(reference_metadata.get("source_kind") or "native"),
            "source_revision": str(reference_metadata.get("source_revision") or ""),
            "interface_name": interface_name,
            "map_mode": properties["map_mode"],
            "attachment_offset": dict(attachment),
        }

    geometry_by_id: dict[str, dict[str, Any]] = {}
    geometry_readback_expected: list[dict[str, Any]] = []
    geometry_property_keys = {
        "point": {"construction", "name", "graph_id"},
        "line": {"construction", "name", "graph_id"},
        "arc": {"construction", "name", "graph_id"},
        "circle": {"construction", "name", "graph_id"},
        "ellipse": {"rotation_degrees", "construction", "name", "graph_id"},
        "elliptic_arc": {
            "rotation_degrees",
            "construction",
            "name",
            "graph_id",
        },
        "hyperbolic_arc": {
            "rotation_degrees",
            "construction",
            "name",
            "graph_id",
        },
        "parabolic_arc": {
            "rotation_degrees",
            "construction",
            "name",
            "graph_id",
        },
        "bspline": {
            "degree",
            "knots",
            "multiplicities",
            "weights",
            "periodic",
            "tolerance",
            "construction",
            "name",
            "graph_id",
        },
        "external_geometry": {
            "construction",
            "defining",
            "intersection",
            "name",
            "graph_id",
        },
    }
    geometry_argument_counts = {
        "point": 1,
        "line": 2,
        "arc": 3,
        "circle": 2,
        "ellipse": 3,
        "elliptic_arc": 5,
        "hyperbolic_arc": 5,
        "parabolic_arc": 4,
        "bspline": 1,
        "external_geometry": 2,
    }
    external_geometry_expected: list[dict[str, Any]] = []
    for index, raw in enumerate(geometry):
        payload, geometry_arguments, geometry_properties = _sketcher_payload(
            raw,
            path=f"api.sketch.geometry[{index}]",
            output_type="sketch_geometry",
        )
        operation = str(payload["operation"])
        if operation not in _SKETCHER_GEOMETRY_OPERATIONS:
            raise ValueError(
                f"Sketch geometry {index} has unsupported operation {operation!r}."
            )
        if len(geometry_arguments) != geometry_argument_counts[operation]:
            raise ValueError(f"api.{operation} serialized the wrong argument count.")
        _exact_mapping(
            geometry_properties,
            path=f"api.sketch.geometry[{index}].properties",
            keys=geometry_property_keys[operation],
        )
        graph_id = str(geometry_properties["graph_id"] or "")
        if not _SKETCHER_GRAPH_ID.fullmatch(graph_id) or not graph_id.startswith("g"):
            raise ValueError(
                "Sketch geometry graph ids must be positive gN identifiers."
            )
        if graph_id in geometry_by_id:
            raise ValueError(f"Sketch geometry graph id {graph_id!r} is duplicated.")
        if not isinstance(geometry_properties["construction"], bool):
            raise ValueError(
                f"Sketch geometry {graph_id!r} construction must be boolean."
            )
        if not isinstance(geometry_properties["name"], str):
            raise ValueError(f"Sketch geometry {graph_id!r} name must be a string.")
        if operation == "external_geometry":
            for field in ("defining", "intersection"):
                if not isinstance(geometry_properties[field], bool):
                    raise ValueError(
                        f"Sketch external geometry {graph_id!r} {field} must be boolean."
                    )
            if geometry_properties["construction"] is not True:
                raise ValueError("External Sketcher geometry must be profile-excluded.")
            reference = _exact_mapping(
                geometry_arguments[0],
                path=f"api.sketch.geometry[{index}].reference",
                keys={"document_uid", "object_name"},
            )
            reference_key = (
                str(reference["document_uid"]),
                str(reference["object_name"]),
            )
            reference_metadata = resolved_reference_metadata.get(reference_key)
            if reference_metadata is None:
                raise ValueError(
                    f"External geometry {graph_id!r} was not authenticated as an input."
                )
            selection = geometry_arguments[1]
            if not isinstance(selection, dict):
                raise ValueError(
                    f"External geometry {graph_id!r} selection must be an object."
                )
            selection_type = str(selection.get("type") or "")
            interface_name = ""
            if selection_type == "subelements":
                _exact_mapping(
                    selection,
                    path=f"api.sketch.geometry[{index}].selection",
                    keys={"type", "subelements"},
                )
                if bool(reference_metadata.get("transient_topology")) or bool(
                    reference_metadata.get("requires_semantic_interfaces")
                ):
                    raise ValueError(
                        f"External geometry {graph_id!r} on a regenerating source must "
                        "use a published semantic interface."
                    )
                subelements = selection["subelements"]
            elif selection_type == "published_interface":
                _exact_mapping(
                    selection,
                    path=f"api.sketch.geometry[{index}].selection",
                    keys={"type", "interface_name"},
                )
                interface_name = str(selection["interface_name"] or "")
                interfaces = reference_metadata.get("published_interfaces")
                interface = (
                    interfaces.get(interface_name)
                    if isinstance(interfaces, dict)
                    else None
                )
                if not isinstance(interface, dict):
                    raise ValueError(
                        f"External geometry interface {interface_name!r} is not in the "
                        "host reference contract."
                    )
                subelements = interface.get("subelements")
            else:
                raise ValueError(
                    f"External geometry {graph_id!r} selection type is invalid."
                )
            if (
                not isinstance(subelements, list)
                or len(subelements) != 1
                or re.fullmatch(
                    r"(?:Edge|Vertex)[1-9][0-9]*",
                    str(subelements[0] or ""),
                )
                is None
            ):
                raise ValueError(
                    f"External geometry {graph_id!r} must resolve to one EdgeN or VertexN."
                )
            external_geometry_expected.append(
                {
                    "reference": dict(reference),
                    "requested_selection": dict(selection),
                    "resolved_subelement": str(subelements[0]),
                    "source_kind": str(
                        reference_metadata.get("source_kind") or "native"
                    ),
                    "source_revision": str(
                        reference_metadata.get("source_revision") or ""
                    ),
                    "interface_name": interface_name,
                    "graph_id": graph_id,
                    "native_geometry_id": -3 - len(external_geometry_expected),
                    "defining": geometry_properties["defining"],
                    "intersection": geometry_properties["intersection"],
                }
            )
        geometry_by_id[graph_id] = payload
        geometry_readback_expected.append(
            {
                "index": index,
                "graph_id": graph_id,
                "name": geometry_properties["name"],
                "operation": operation,
                "construction": geometry_properties["construction"],
            }
        )

    constraint_readback_expected: list[dict[str, Any]] = []
    constraint_names: set[str] = set()
    constraint_property_keys = {
        "value",
        "name",
        "expression",
        "driving",
        "active",
        "virtual",
        "alignment",
        "internal_index",
        "text",
        "font",
        "text_height",
        "graph_id",
    }
    for index, raw in enumerate(constraints):
        _constraint_payload, constraint_arguments, constraint_properties = (
            _sketcher_payload(
                raw,
                path=f"api.sketch.constraints[{index}]",
                operation="constraint",
                output_type="sketch_constraint",
            )
        )
        if len(constraint_arguments) != 2 or not isinstance(
            constraint_arguments[1], list
        ):
            raise ValueError(f"Sketch constraint {index} has malformed arguments.")
        kind = str(constraint_arguments[0] or "")
        if kind not in _SKETCHER_CONSTRAINT_KINDS:
            raise ValueError(
                f"Sketch constraint {index} has unsupported kind {kind!r}."
            )
        _exact_mapping(
            constraint_properties,
            path=f"api.sketch.constraints[{index}].properties",
            keys=constraint_property_keys,
        )
        graph_id = str(constraint_properties["graph_id"] or "")
        if not _SKETCHER_GRAPH_ID.fullmatch(graph_id) or not graph_id.startswith("c"):
            raise ValueError(
                "Sketch constraint graph ids must be positive cN identifiers."
            )
        for field in ("driving", "active", "virtual", "text_height"):
            if not isinstance(constraint_properties[field], bool):
                raise ValueError(
                    f"Sketch constraint {graph_id!r} {field} must be boolean."
                )
        name = constraint_properties["name"]
        expression = constraint_properties["expression"]
        if not isinstance(name, str) or not isinstance(expression, str):
            raise ValueError(
                f"Sketch constraint {graph_id!r} name/expression is malformed."
            )
        if name and name in constraint_names:
            raise ValueError(f"Sketch constraint name {name!r} is duplicated.")
        constraint_names.add(name)
        for entity_index, entity in enumerate(constraint_arguments[1]):
            if not isinstance(entity, dict):
                raise ValueError(
                    f"Sketch constraint {graph_id!r} entity {entity_index} is malformed."
                )
            if set(entity) == {"external", "point"}:
                if entity["external"] not in {"x_axis", "y_axis", "origin"}:
                    raise ValueError(
                        f"Sketch constraint {graph_id!r} has invalid external entity."
                    )
            elif set(entity) == {"geometry", "point"}:
                nested = entity["geometry"]
                if not isinstance(nested, dict):
                    raise ValueError(
                        f"Sketch constraint {graph_id!r} geometry is malformed."
                    )
                nested_properties = nested.get("properties")
                nested_id = (
                    str(nested_properties.get("graph_id") or "")
                    if isinstance(nested_properties, dict)
                    else ""
                )
                if (
                    nested_id not in geometry_by_id
                    or nested != geometry_by_id[nested_id]
                ):
                    raise ValueError(
                        f"Sketch constraint {graph_id!r} does not reference an exact graph value."
                    )
            else:
                raise ValueError(
                    f"Sketch constraint {graph_id!r} entity fields are malformed."
                )
        constraint_readback_expected.append(
            {
                "index": index,
                "graph_id": graph_id,
                "name": name,
                "kind": kind,
                "driving": constraint_properties["driving"],
                "active": constraint_properties["active"],
                "virtual": constraint_properties["virtual"],
                "expression": expression,
                "expression_bound": bool(expression),
            }
        )

    validation = execution.get("sketch_validation")
    if not isinstance(validation, dict) or item.get("sketch_validation") != validation:
        raise ValueError("The Sketcher worker returned inconsistent native validation.")
    required_validation_keys = {
        "solver_code",
        "geometry_count",
        "native_geometry_count",
        "external_geometry_count",
        "constraint_count",
        "degrees_of_freedom",
        "fully_constrained",
        "conflicting_constraints",
        "redundant_constraints",
        "partially_redundant_constraints",
        "malformed_constraints",
        "edge_count",
        "wire_count",
        "closed_wire_count",
        "open_wire_count",
        "profile_ready",
        "construction_geometry_count",
        "geometry",
        "external_geometry",
        "constraints",
        "constraint_errors",
        "constraint_error_unavailable",
        "constraint_errors_truncated",
        "underconstraint_guidance",
        "profile_open_vertices",
        "constraint_issues",
        "requirements",
        "support",
    }
    if set(validation) != required_validation_keys:
        raise ValueError("The Sketcher native validation has an unexpected schema.")
    integer_fields = (
        "solver_code",
        "geometry_count",
        "native_geometry_count",
        "external_geometry_count",
        "constraint_count",
        "degrees_of_freedom",
        "edge_count",
        "wire_count",
        "closed_wire_count",
        "open_wire_count",
        "construction_geometry_count",
    )
    if any(type(validation.get(field)) is not int for field in integer_fields):
        raise ValueError("The Sketcher native validation contains non-integer counts.")
    if int(validation["solver_code"]) != 0:
        raise ValueError(
            "The Sketcher candidate does not have a clean native solver result."
        )
    if int(validation["geometry_count"]) != len(geometry):
        raise ValueError("The Sketcher native geometry count is inconsistent.")
    local_geometry_count = len(geometry) - len(external_geometry_expected)
    if int(validation["native_geometry_count"]) != local_geometry_count:
        raise ValueError("The Sketcher local native geometry count is inconsistent.")
    if int(validation["external_geometry_count"]) != len(external_geometry_expected):
        raise ValueError("The Sketcher external geometry count is inconsistent.")
    if int(validation["constraint_count"]) != len(constraints):
        raise ValueError("The Sketcher native constraint count is inconsistent.")
    if int(validation["degrees_of_freedom"]) < 0:
        raise ValueError("The Sketcher native DoF count is invalid.")
    for field in (
        "fully_constrained",
        "profile_ready",
        "constraint_errors_truncated",
    ):
        if not isinstance(validation[field], bool):
            raise ValueError(f"The Sketcher native {field} value must be boolean.")
    for field in (
        "conflicting_constraints",
        "redundant_constraints",
        "partially_redundant_constraints",
        "malformed_constraints",
    ):
        if validation[field] != []:
            raise ValueError(
                f"The accepted Sketcher candidate has {field.replace('_', ' ')}."
            )
    if validation["geometry"] != geometry_readback_expected:
        raise ValueError(
            "The native Sketcher geometry readback differs from the source graph."
        )
    if validation["external_geometry"] != external_geometry_expected:
        raise ValueError(
            "The native Sketcher external-geometry readback differs from the host contract."
        )
    native_constraints = validation["constraints"]
    if not isinstance(native_constraints, list) or len(native_constraints) != len(
        constraint_readback_expected
    ):
        raise ValueError(
            "The native Sketcher constraint readback has the wrong length."
        )
    for expected_readback, native_readback in zip(
        constraint_readback_expected, native_constraints
    ):
        if not isinstance(native_readback, dict):
            raise ValueError("The native Sketcher constraint readback is malformed.")
        for field, expected_value in expected_readback.items():
            if native_readback.get(field) != expected_value:
                raise ValueError(
                    f"Native Sketcher constraint {expected_readback['graph_id']!r} "
                    f"changed {field}."
                )
        if not str(native_readback.get("native_type") or ""):
            raise ValueError("A native Sketcher constraint has no type readback.")
        value = native_readback.get("value")
        if (
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or not math.isfinite(value)
        ):
            raise ValueError(
                "A native Sketcher constraint has a non-finite value readback."
            )
    requirements = _exact_mapping(
        validation["requirements"],
        path="sketch_validation.requirements",
        keys={"fully_constrained", "closed_profile"},
    )
    if requirements != {
        "fully_constrained": properties["require_fully_constrained"],
        "closed_profile": properties["require_closed_profile"],
    }:
        raise ValueError("Sketcher validation requirements differ from api.sketch.")
    if requirements["fully_constrained"] and not validation["fully_constrained"]:
        raise ValueError(
            "The Sketcher worker did not enforce fully constrained output."
        )
    if validation["support"] != expected_support_validation:
        raise ValueError(
            "Sketcher support resolution differs from the host reference contract."
        )
    if int(validation["closed_wire_count"]) + int(validation["open_wire_count"]) != int(
        validation["wire_count"]
    ):
        raise ValueError("The Sketcher wire diagnostics are inconsistent.")
    profile_ready = bool(
        int(validation["wire_count"]) > 0
        and int(validation["closed_wire_count"]) == int(validation["wire_count"])
    )
    if validation["profile_ready"] != profile_ready:
        raise ValueError("The Sketcher profile-readiness result is inconsistent.")
    if requirements["closed_profile"] and not profile_ready:
        raise ValueError("The Sketcher worker did not enforce a closed profile.")
    if int(validation["construction_geometry_count"]) != sum(
        bool(value["construction"]) for value in geometry_readback_expected
    ):
        raise ValueError("The Sketcher construction-geometry count is inconsistent.")
    errors = validation["constraint_errors"]
    if not isinstance(errors, list) or len(errors) > min(len(constraints), 512):
        raise ValueError("The Sketcher constraint-error diagnostics are malformed.")
    seen_error_indexes: set[int] = set()
    for diagnostic in errors:
        data = _exact_mapping(
            diagnostic,
            path="sketch_validation.constraint_errors[]",
            keys={"index", "error"},
        )
        index = data["index"]
        error = data["error"]
        if type(index) is not int or not 0 <= index < len(constraints):
            raise ValueError("A Sketcher constraint-error index is out of range.")
        if index in seen_error_indexes:
            raise ValueError("A Sketcher constraint-error index is duplicated.")
        seen_error_indexes.add(index)
        if (
            isinstance(error, bool)
            or not isinstance(error, (int, float))
            or not math.isfinite(error)
        ):
            raise ValueError("A Sketcher constraint error must be finite.")
    unavailable_errors = validation["constraint_error_unavailable"]
    if not isinstance(unavailable_errors, list) or len(unavailable_errors) > min(
        len(constraints), 512
    ):
        raise ValueError("The unavailable Sketcher residual diagnostics are malformed.")
    for diagnostic in unavailable_errors:
        data = _exact_mapping(
            diagnostic,
            path="sketch_validation.constraint_error_unavailable[]",
            keys={"index", "reason", "message"},
        )
        index = data["index"]
        if type(index) is not int or not 0 <= index < len(constraints):
            raise ValueError("An unavailable Sketcher residual index is out of range.")
        if index in seen_error_indexes:
            raise ValueError(
                "A Sketcher residual index is accounted for more than once."
            )
        if data["reason"] not in {"native_error", "non_finite"}:
            raise ValueError("An unavailable Sketcher residual has an invalid reason.")
        if not isinstance(data["message"], str) or len(data["message"]) > 512:
            raise ValueError("An unavailable Sketcher residual message is invalid.")
        seen_error_indexes.add(index)
    checked_constraint_count = min(len(constraints), 512)
    if seen_error_indexes != set(range(checked_constraint_count)):
        raise ValueError(
            "Sketcher residual diagnostics do not account for every checked constraint."
        )
    if validation["constraint_errors_truncated"] != (len(constraints) > 512):
        raise ValueError("Sketcher residual truncation metadata is inconsistent.")
    _validate_sketcher_underconstraint_guidance(
        validation["underconstraint_guidance"],
        degrees_of_freedom=int(validation["degrees_of_freedom"]),
        geometry_readback=geometry_readback_expected,
    )
    _validate_sketcher_profile_open_vertices(
        validation["profile_open_vertices"],
        open_wire_count=int(validation["open_wire_count"]),
        geometry_readback=geometry_readback_expected,
    )
    constraint_issues = _exact_mapping(
        validation["constraint_issues"],
        path="sketch_validation.constraint_issues",
        keys={"conflicting", "redundant", "partially_redundant", "malformed"},
    )
    if any(constraint_issues.values()):
        raise ValueError("An accepted Sketcher candidate reports constraint issues.")
    encoded = json.dumps(
        validation,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    if len(encoded) > _STRUCTURED_DEFINITION_LIMIT:
        raise ValueError("The Sketcher native validation is too large.")
    item["sketch_validation"] = dict(validation)
    return dict(validation)


_DRAFT_OUTPUT_CONTRACTS: dict[str, tuple[str, str, str]] = {
    "wire": ("Part::FeaturePython", "Wire", "Wire"),
    "circle": ("Part::Part2DObjectPython", "Circle", "Circle"),
    "rectangle": ("Part::Part2DObjectPython", "Rectangle", "Rectangle"),
    "bspline": ("Part::FeaturePython", "BSpline", "BSpline"),
    "array": ("Part::FeaturePython", "Array", "Array"),
    "text": ("App::FeaturePython", "Text", "Text"),
}
_DRAFT_SHAPE_OUTPUT_TYPES = frozenset(
    {"wire", "circle", "rectangle", "bspline", "array"}
)


def _draft_payload(
    value: Any,
    *,
    path: str,
    output_type: str | None = None,
) -> tuple[dict[str, Any], list[Any], dict[str, Any]]:
    payload = _exact_mapping(
        value,
        path=path,
        keys={"domain", "operation", "output_type", "arguments", "properties"},
    )
    if payload["domain"] != "draft":
        raise ValueError(f"{path} belongs to a different VibeScript domain.")
    operation = str(payload["operation"] or "")
    declared = str(payload["output_type"] or "")
    if operation not in _DRAFT_OUTPUT_CONTRACTS or declared != operation:
        raise ValueError(
            f"{path} has unsupported Draft operation/type {operation!r}/{declared!r}."
        )
    if output_type is not None and declared != output_type:
        raise ValueError(f"{path} must have Draft output type {output_type!r}.")
    arguments = payload["arguments"]
    properties = payload["properties"]
    if not isinstance(arguments, list) or not isinstance(properties, dict):
        raise ValueError(f"{path} arguments/properties are malformed.")
    return payload, list(arguments), dict(properties)


def _draft_exact_properties(
    properties: Mapping[str, Any],
    *,
    path: str,
    names: set[str],
    defaults: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    values = dict(properties)
    required = names | {"graph_id"}
    optional = dict(defaults or {})
    allowed = required | set(optional)
    if not required <= set(values) or not set(values) <= allowed:
        missing = sorted(required - set(values))
        unexpected = sorted(set(values) - allowed)
        raise ValueError(
            f"{path} has the wrong fields (missing={missing}, "
            f"unexpected={unexpected}, optional={sorted(optional)})."
        )
    for name, default in optional.items():
        values.setdefault(name, default)
    return values


def _draft_float(value: Any, *, path: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{path} must be a finite number.")
    result = float(value)
    if not math.isfinite(result):
        raise ValueError(f"{path} must be finite.")
    return result


def _draft_close(
    left: Any, right: Any, *, path: str, tolerance: float = 1.0e-9
) -> None:
    first = _draft_float(left, path=path)
    second = _draft_float(right, path=path)
    if not math.isclose(first, second, rel_tol=tolerance, abs_tol=tolerance):
        raise ValueError(
            f"{path} changed in native Draft readback ({first} != {second})."
        )


def _draft_vector(value: Any, expected: Any, *, path: str, length: int = 3) -> None:
    if not isinstance(value, list) or len(value) != length:
        raise ValueError(f"{path} must contain exactly {length} finite values.")
    if not isinstance(expected, list) or len(expected) != length:
        raise ValueError(f"{path} has malformed source data.")
    for index, (observed, requested) in enumerate(zip(value, expected)):
        _draft_close(observed, requested, path=f"{path}[{index}]")


def _draft_placement(value: Any, expected: Any, *, path: str) -> None:
    observed = _exact_mapping(
        value,
        path=path,
        keys={"position", "rotation"},
    )
    requested = _exact_mapping(
        expected,
        path=f"{path}.source",
        keys={"position", "rotation"},
    )
    _draft_vector(observed["position"], requested["position"], path=f"{path}.position")
    observed_rotation = observed["rotation"]
    requested_rotation = requested["rotation"]
    if not isinstance(observed_rotation, list) or len(observed_rotation) != 4:
        raise ValueError(f"{path}.rotation must be a quaternion.")
    if not isinstance(requested_rotation, list) or len(requested_rotation) != 4:
        raise ValueError(f"{path}.source.rotation must be a quaternion.")
    direct = all(
        math.isclose(float(left), float(right), rel_tol=1.0e-9, abs_tol=1.0e-9)
        for left, right in zip(observed_rotation, requested_rotation)
    )
    inverse = all(
        math.isclose(float(left), -float(right), rel_tol=1.0e-9, abs_tol=1.0e-9)
        for left, right in zip(observed_rotation, requested_rotation)
    )
    if not (direct or inverse):
        raise ValueError(f"{path}.rotation changed in native Draft readback.")


def _draft_native_angle(value: Any, *, path: str) -> float:
    angle = _draft_float(value, path=path)
    return math.copysign(abs(angle) % 360.0, angle)


def _validate_draft_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    """Reauthorize exact native Draft objects, links, properties, and artifacts."""

    validation = execution.get("draft_validation")
    if not isinstance(validation, dict):
        raise ValueError("The Draft worker returned no native validation summary.")
    if not outputs or len(outputs) > contracts.MAX_OUTPUTS:
        raise ValueError("A Draft candidate must contain 1-64 outputs.")
    by_graph: dict[str, dict[str, Any]] = {}
    parsed: dict[str, tuple[dict[str, Any], list[Any], dict[str, Any]]] = {}
    for item in outputs:
        name = str(item["name"])
        output_type = str(item["type"])
        payload, arguments, properties = _draft_payload(
            item.get("definition"),
            path=f"outputs.{name}.definition",
            output_type=output_type,
        )
        property_names = {
            "wire": {"closed", "make_face", "placement", "label"},
            "circle": {
                "start_angle",
                "end_angle",
                "make_face",
                "placement",
                "label",
            },
            "rectangle": {"make_face", "placement", "label"},
            "bspline": {
                "closed",
                "make_face",
                "parameterization",
                "placement",
                "label",
            },
            "array": {
                "kind",
                "interval_x",
                "interval_y",
                "interval_z",
                "count_x",
                "count_y",
                "count_z",
                "count",
                "total_angle_degrees",
                "center",
                "axis",
                "use_link",
                "fuse",
                "label",
            },
            "text": {
                "placement",
                "screen",
                "height",
                "line_spacing",
                "label",
            },
        }[output_type]
        property_defaults = {
            "wire": {
                "fillet_radius": 0.0,
                "chamfer_size": 0.0,
                "subdivisions": 0,
            },
            "rectangle": {
                "fillet_radius": 0.0,
                "chamfer_size": 0.0,
            },
            "array": {
                "interval_axis": [0.0, 0.0, 0.0],
                "radial_distance": 100.0,
                "tangential_distance": 50.0,
                "number_circles": 3,
                "symmetry": 1,
            },
        }.get(output_type)
        properties = _draft_exact_properties(
            properties,
            path=f"outputs.{name}.definition.properties",
            names=property_names,
            defaults=property_defaults,
        )
        expected_argument_count = 2 if output_type == "rectangle" else 1
        if len(arguments) != expected_argument_count:
            raise ValueError(
                f"outputs.{name}.definition must serialize exactly "
                f"{expected_argument_count} positional argument(s)."
            )
        graph_id = str(properties.get("graph_id") or "")
        if not re.fullmatch(r"d[1-9][0-9]*", graph_id) or graph_id in by_graph:
            raise ValueError(
                f"Draft graph id {graph_id!r} on output {name!r} is missing or duplicated."
            )
        by_graph[graph_id] = item
        parsed[name] = (payload, arguments, properties)

    references = {
        (str(item.get("document_uid") or ""), str(item.get("object_name") or "")): item
        for item in list(prepared.get("resolved_references") or [])
    }
    for item in outputs:
        name = str(item["name"])
        output_type = str(item["type"])
        _payload, arguments, properties = parsed[name]
        data = item.get("draft_data")
        if not isinstance(data, dict):
            raise ValueError(f"Draft output {name!r} has no native object readback.")
        common_data = {
            "graph_id",
            "native_type",
            "proxy_class",
            "draft_type",
            "label",
            "placement",
        }
        operation_data = {
            "wire": {
                "points",
                "closed",
                "make_face",
                "fillet_radius",
                "chamfer_size",
                "subdivisions",
            },
            "circle": {"radius", "start_angle", "end_angle", "make_face"},
            "rectangle": {
                "length",
                "height",
                "make_face",
                "fillet_radius",
                "chamfer_size",
            },
            "bspline": {
                "points",
                "closed",
                "make_face",
                "parameterization",
            },
            "array": {
                "source",
                "array_kind",
                "use_link",
                "fuse",
                "count",
                "placement_matrices",
                "number_x",
                "number_y",
                "number_z",
                "interval_x",
                "interval_y",
                "interval_z",
                "interval_axis",
                "number_polar",
                "angle_degrees",
                "center",
                "axis",
                "radial_distance",
                "tangential_distance",
                "number_circles",
                "symmetry",
            },
            "text": {
                "lines",
                "screen",
                "height",
                "line_spacing",
                "display_validation",
            },
        }[output_type]
        data = _exact_mapping(
            data,
            path=f"outputs.{name}.draft_data",
            keys=common_data | operation_data,
        )
        expected_native, expected_proxy, expected_draft_type = _DRAFT_OUTPUT_CONTRACTS[
            output_type
        ]
        for field, expected_value in (
            ("graph_id", properties["graph_id"]),
            ("native_type", expected_native),
            ("proxy_class", expected_proxy),
            ("draft_type", expected_draft_type),
            ("label", str(properties["label"] or name)),
        ):
            if str(data.get(field) or "") != str(expected_value):
                raise ValueError(
                    f"Draft output {name!r} native {field} changed: "
                    f"expected {expected_value!r}, received {data.get(field)!r}."
                )
        expected_placement = (
            properties["placement"]
            if output_type != "array"
            else {"position": [0.0, 0.0, 0.0], "rotation": [0.0, 0.0, 0.0, 1.0]}
        )
        _draft_placement(
            data["placement"],
            expected_placement,
            path=f"outputs.{name}.draft_data.placement",
        )
        if output_type in {"wire", "bspline"}:
            if data["points"] != arguments[0]:
                raise ValueError(
                    f"Draft output {name!r} changed its local control points."
                )
            if bool(data["closed"]) != bool(properties["closed"]):
                raise ValueError(f"Draft output {name!r} changed Closed state.")
            if bool(data["make_face"]) != bool(properties["make_face"]):
                raise ValueError(f"Draft output {name!r} changed MakeFace state.")
            if output_type == "bspline":
                _draft_close(
                    data["parameterization"],
                    properties["parameterization"],
                    path=f"outputs.{name}.draft_data.parameterization",
                )
            else:
                _draft_close(
                    data["fillet_radius"],
                    properties["fillet_radius"],
                    path=f"outputs.{name}.draft_data.fillet_radius",
                )
                _draft_close(
                    data["chamfer_size"],
                    properties["chamfer_size"],
                    path=f"outputs.{name}.draft_data.chamfer_size",
                )
                if type(data["subdivisions"]) is not int or int(
                    data["subdivisions"]
                ) != int(properties["subdivisions"]):
                    raise ValueError(
                        f"Draft output {name!r} changed wire Subdivisions."
                    )
        elif output_type == "circle":
            _draft_close(
                data["radius"],
                arguments[0],
                path=f"outputs.{name}.draft_data.radius",
            )
            _draft_close(
                data["start_angle"],
                _draft_native_angle(
                    properties["start_angle"], path=f"outputs.{name}.start_angle"
                ),
                path=f"outputs.{name}.draft_data.start_angle",
            )
            _draft_close(
                data["end_angle"],
                _draft_native_angle(
                    properties["end_angle"], path=f"outputs.{name}.end_angle"
                ),
                path=f"outputs.{name}.draft_data.end_angle",
            )
            if bool(data["make_face"]) != bool(properties["make_face"]):
                raise ValueError(f"Draft output {name!r} changed MakeFace state.")
        elif output_type == "rectangle":
            _draft_close(
                data["length"], arguments[0], path=f"outputs.{name}.draft_data.length"
            )
            _draft_close(
                data["height"], arguments[1], path=f"outputs.{name}.draft_data.height"
            )
            if bool(data["make_face"]) != bool(properties["make_face"]):
                raise ValueError(f"Draft output {name!r} changed MakeFace state.")
            _draft_close(
                data["fillet_radius"],
                properties["fillet_radius"],
                path=f"outputs.{name}.draft_data.fillet_radius",
            )
            _draft_close(
                data["chamfer_size"],
                properties["chamfer_size"],
                path=f"outputs.{name}.draft_data.chamfer_size",
            )
        elif output_type == "text":
            if data["lines"] != arguments[0]:
                raise ValueError(f"Draft output {name!r} changed Text lines.")
            if bool(data["screen"]) != bool(properties["screen"]):
                raise ValueError(f"Draft output {name!r} changed screen mode.")
            _draft_close(
                data["height"], properties["height"], path=f"outputs.{name}.height"
            )
            _draft_close(
                data["line_spacing"],
                properties["line_spacing"],
                path=f"outputs.{name}.line_spacing",
            )
            if data["display_validation"] != "deferred_to_gui_publication":
                raise ValueError(
                    f"Draft output {name!r} has invalid display validation state."
                )
        else:
            expected_kind = {
                "orthogonal": "ortho",
                "polar": "polar",
                "circular": "circular",
            }.get(str(properties["kind"]))
            if expected_kind is None:
                raise ValueError(
                    f"Draft array {name!r} has unsupported kind {properties['kind']!r}."
                )
            if str(data["array_kind"]) != expected_kind:
                raise ValueError(f"Draft array {name!r} changed native ArrayType.")
            if bool(data["use_link"]) != bool(properties["use_link"]):
                raise ValueError(f"Draft array {name!r} changed link/copy mode.")
            if bool(data["fuse"]) != bool(properties["fuse"]):
                raise ValueError(f"Draft array {name!r} changed Fuse state.")
            if properties["kind"] == "orthogonal":
                expected_count = (
                    int(properties["count_x"])
                    * int(properties["count_y"])
                    * int(properties["count_z"])
                )
            elif properties["kind"] == "polar":
                expected_count = int(properties["count"])
            else:
                radial_distance = _draft_float(
                    properties["radial_distance"],
                    path=f"outputs.{name}.radial_distance",
                )
                tangential_distance = _draft_float(
                    properties["tangential_distance"],
                    path=f"outputs.{name}.tangential_distance",
                )
                number_circles = properties["number_circles"]
                symmetry = properties["symmetry"]
                if (
                    radial_distance <= 0.0
                    or tangential_distance <= 0.0
                    or type(number_circles) is not int
                    or number_circles < 2
                    or type(symmetry) is not int
                    or symmetry < 1
                ):
                    raise ValueError(
                        f"Draft circular array {name!r} has invalid ring parameters."
                    )
                expected_count = 1
                for ring in range(1, number_circles):
                    ring_count = math.floor(
                        2.0 * math.pi * ring * radial_distance / tangential_distance
                    )
                    expected_count += math.floor(ring_count / symmetry) * symmetry
            if int(data["count"]) != expected_count:
                raise ValueError(f"Draft array {name!r} changed native element count.")
            placements = data["placement_matrices"]
            if not isinstance(placements, list) or len(placements) != expected_count:
                raise ValueError(
                    f"Draft array {name!r} must return one placement per element."
                )
            for index, matrix in enumerate(placements):
                _finite_matrix(matrix, f"Draft array {name!r} placement {index}")
            for field, requested in (
                ("number_x", properties["count_x"]),
                ("number_y", properties["count_y"]),
                ("number_z", properties["count_z"]),
                ("number_polar", properties["count"]),
                ("number_circles", properties["number_circles"]),
                ("symmetry", properties["symmetry"]),
            ):
                if type(data[field]) is not int or int(data[field]) != int(requested):
                    raise ValueError(f"Draft array {name!r} changed {field}.")
            for field in (
                "interval_x",
                "interval_y",
                "interval_z",
                "interval_axis",
                "center",
                "axis",
            ):
                _draft_vector(
                    data[field],
                    properties[field],
                    path=f"outputs.{name}.draft_data.{field}",
                )
            _draft_close(
                data["angle_degrees"],
                properties["total_angle_degrees"],
                path=f"outputs.{name}.draft_data.angle_degrees",
            )
            for field in ("radial_distance", "tangential_distance"):
                _draft_close(
                    data[field],
                    properties[field],
                    path=f"outputs.{name}.draft_data.{field}",
                )
            source = arguments[0]
            source_data = data["source"]
            if isinstance(source, dict) and "domain" in source:
                _nested, _nested_arguments, nested_properties = _draft_payload(
                    source,
                    path=f"outputs.{name}.definition.arguments[0]",
                )
                source_graph = str(nested_properties.get("graph_id") or "")
                source_item = by_graph.get(source_graph)
                if (
                    source_item is None
                    or str(source_item["type"]) not in _DRAFT_SHAPE_OUTPUT_TYPES
                ):
                    raise ValueError(
                        f"Draft array {name!r} source graph {source_graph!r} is not a "
                        "returned stable shape output."
                    )
                expected_source = {
                    "kind": "program_output",
                    "graph_id": source_graph,
                    "output_name": str(source_item["name"]),
                }
            else:
                reference = _exact_mapping(
                    source,
                    path=f"outputs.{name}.definition.arguments[0]",
                    keys={"document_uid", "object_name"},
                )
                key = (str(reference["document_uid"]), str(reference["object_name"]))
                resolved = references.get(key)
                if resolved is None:
                    raise ValueError(
                        f"Draft array {name!r} uses unauthenticated source {key[1]!r}."
                    )
                expected_source = {
                    "kind": "document_reference",
                    "document_uid": key[0],
                    "object_name": key[1],
                    "brep_sha256": str(resolved.get("brep_sha256") or ""),
                    "shape_type": str(resolved.get("shape_type") or ""),
                }
            if source_data != expected_source:
                raise ValueError(
                    f"Draft array {name!r} changed its authenticated Base link."
                )

        if output_type in _DRAFT_SHAPE_OUTPUT_TYPES:
            if (
                item.get("artifact_kind") != "brep"
                or item.get("detached_shape") is None
            ):
                raise ValueError(f"Draft shape output {name!r} has no detached BREP.")
            facts = item.get("facts")
            if not isinstance(facts, dict) or facts.get("shape_type") != facts.get(
                "artifact_shape_type"
            ):
                raise ValueError(
                    f"Draft shape output {name!r} changed OCC class in transfer."
                )
        elif (
            item.get("artifact_kind") is not None
            or item.get("detached_shape") is not None
        ):
            raise ValueError(
                f"Draft text output {name!r} cannot publish a BREP artifact."
            )
        _validate_definition_value(
            data,
            prepared,
            f"outputs.{name}.draft_data",
        )
        encoded = json.dumps(
            data,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
        if len(encoded) > _STRUCTURED_DEFINITION_LIMIT:
            raise ValueError(f"Draft output {name!r} native readback is too large.")

    expected_summary = [
        {
            "name": str(item["name"]),
            "type": str(item["type"]),
            "graph_id": str(item["draft_data"]["graph_id"]),
            "native_type": str(item["draft_data"]["native_type"]),
            "proxy_class": str(item["draft_data"]["proxy_class"]),
            "draft_type": str(item["draft_data"]["draft_type"]),
        }
        for item in outputs
    ]
    expected_validation = {
        "native_object_count": len(outputs),
        "shape_output_count": sum(
            str(item["type"]) in _DRAFT_SHAPE_OUTPUT_TYPES for item in outputs
        ),
        "text_output_count": sum(str(item["type"]) == "text" for item in outputs),
        "array_output_count": sum(str(item["type"]) == "array" for item in outputs),
        "referenced_object_count": len(
            {
                (
                    str(item["draft_data"]["source"].get("document_uid") or ""),
                    str(item["draft_data"]["source"].get("object_name") or ""),
                )
                for item in outputs
                if str(item["type"]) == "array"
                and item["draft_data"]["source"].get("kind") == "document_reference"
            }
        ),
        "outputs": expected_summary,
    }
    if validation != expected_validation:
        raise ValueError("The Draft worker native validation summary is inconsistent.")
    return dict(validation)


def _surface_definition_references(
    value: Any,
    *,
    path: str,
) -> list[tuple[dict[str, Any], str]]:
    """Collect every explicit Surface reference operation from one validated graph."""

    found: list[tuple[dict[str, Any], str]] = []

    def visit(raw: Any, current: str, depth: int) -> None:
        if depth > 64:
            raise ValueError(f"{path} exceeds 64 nested Surface operations.")
        if isinstance(raw, list):
            for index, item in enumerate(raw):
                visit(item, f"{current}[{index}]", depth)
            return
        if not isinstance(raw, dict):
            return
        if raw.get("domain") == "surface":
            if raw.get("operation") == "from_object":
                found.append((raw, current))
            for index, item in enumerate(list(raw.get("arguments") or [])):
                visit(item, f"{current}.arguments[{index}]", depth + 1)
            for name, item in dict(raw.get("properties") or {}).items():
                visit(item, f"{current}.properties.{name}", depth + 1)
            return
        for name, item in raw.items():
            visit(item, f"{current}.{name}", depth)

    visit(value, path, 0)
    return found


def _surface_close(left: Any, right: Any, *, path: str) -> None:
    if (
        isinstance(left, bool)
        or not isinstance(left, (int, float))
        or isinstance(right, bool)
        or not isinstance(right, (int, float))
        or not math.isfinite(float(left))
        or not math.isfinite(float(right))
        or not math.isclose(float(left), float(right), rel_tol=1.0e-9, abs_tol=1.0e-9)
    ):
        raise ValueError(f"{path} changed in native Surface readback.")


def _surface_int(
    value: Any,
    *,
    path: str,
    minimum: int = 0,
    maximum: int = 1_000_000,
) -> int:
    if type(value) is not int or not minimum <= value <= maximum:
        raise ValueError(
            f"{path} must be an integer in the inclusive range {minimum}-{maximum}."
        )
    return value


def _surface_native_state(value: Any, *, path: str) -> list[str]:
    if (
        not isinstance(value, list)
        or len(value) > 64
        or any(not isinstance(item, str) or len(item) > 512 for item in value)
    ):
        raise ValueError(f"{path} is malformed or too large.")
    return list(value)


def _surface_native_properties(
    value: Any,
    expected: Mapping[str, Any],
    *,
    path: str,
) -> dict[str, Any]:
    observed = _exact_mapping(value, path=path, keys=set(expected))
    for name, requested in expected.items():
        actual = observed[name]
        if isinstance(requested, bool):
            if type(actual) is not bool or actual is not requested:
                raise ValueError(f"{path}.{name} changed in native Surface readback.")
        elif type(requested) is int:
            if type(actual) is not int or actual != requested:
                raise ValueError(f"{path}.{name} changed in native Surface readback.")
        elif isinstance(requested, (int, float)):
            _surface_close(actual, requested, path=f"{path}.{name}")
        elif actual != requested:
            raise ValueError(f"{path}.{name} changed in native Surface readback.")
    return observed


def _validate_surface_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    """Independently reauthorize typed Surface graphs and native worker readback."""

    from vibescript_surface_worker import validate_surface_definition

    validation = execution.get("surface_validation")
    if not isinstance(validation, dict):
        raise ValueError("The Surface worker returned no native validation summary.")
    if set(validation) != {"schema", "output_count", "operation_count", "outputs"}:
        raise ValueError("The Surface worker validation summary has malformed fields.")
    if validation.get("schema") != "vibecad-vibescript-surface-validation-v1":
        raise ValueError("The Surface worker validation schema is unsupported.")
    if int(validation.get("output_count", -1)) != len(outputs):
        raise ValueError("The Surface worker validation output count is inconsistent.")
    operation_count = int(validation.get("operation_count", -1))
    if not len(outputs) <= operation_count <= 8192:
        raise ValueError("The Surface worker reported an invalid operation count.")
    summaries = validation.get("outputs")
    if not isinstance(summaries, list) or len(summaries) != len(outputs):
        raise ValueError("The Surface worker validation output list is inconsistent.")

    references = {
        (str(item.get("document_uid") or ""), str(item.get("object_name") or "")): item
        for item in list(prepared.get("resolved_references") or [])
    }
    exact_shape_types = {
        "surface": {"Face"},
        "face": {"Face"},
        "shell": {"Shell"},
        "fill": {"Face"},
        "blend": {"Face"},
        "extension": {"Face"},
        "loft": {"Face", "Shell"},
        "solid": {"Solid"},
    }
    operation_engines = {
        "from_object": {"authenticated detached BREP selection"},
        "face": {"Part.Face"},
        "surface": {
            "Part.BSplineSurface.interpolate",
            "Part.BSplineSurface.approximate",
        },
        "fill": {"Surface::Filling"},
        "blend": {"Surface::GeomFillSurface"},
        "extend": {"Surface::Extend"},
        "loft": {"Part.makeLoft"},
        "thicken": {
            "TopoShape.makeOffsetShape(fill=True)",
            "TopoShape.makeThickness",
        },
        "shell": {"Surface::Sewing"},
    }
    count_fields = {
        "Vertex": "vertices",
        "Edge": "edges",
        "Wire": "wires",
        "Face": "faces",
        "Shell": "shells",
        "Solid": "solids",
    }
    expected_summaries = []
    for item, raw_summary in zip(outputs, summaries):
        name = str(item["name"])
        output_type = str(item["type"])
        definition = validate_surface_definition(
            item.get("definition"), context=f"outputs.{name}.definition"
        )
        operation = str(definition["operation"])
        arguments = list(definition["arguments"])
        properties = dict(definition["properties"])
        if operation not in operation_engines:
            raise ValueError(
                f"Surface output {name!r} cannot publish intermediate api.{operation}."
            )
        if str(definition["output_type"]) != output_type:
            raise ValueError(
                f"Surface output {name!r} definition changed its declared type."
            )
        facts = item.get("facts")
        if not isinstance(facts, dict):
            raise ValueError(f"Surface output {name!r} has no detached topology facts.")
        shape_type = str(facts.get("shape_type") or "")
        artifact_shape_type = str(facts.get("artifact_shape_type") or "")
        if (
            shape_type not in exact_shape_types[output_type]
            or artifact_shape_type != shape_type
        ):
            raise ValueError(
                f"Surface output {name!r} type {output_type!r} requires OCC ShapeType "
                f"{sorted(exact_shape_types[output_type])}, not "
                f"{artifact_shape_type or shape_type or '<missing>'}."
            )
        data = item.get("surface_data")
        if not isinstance(data, dict):
            raise ValueError(
                f"Surface output {name!r} has no native operation readback."
            )
        common_data = {
            "operation",
            "output_type",
            "engine",
            "shape_type",
            "face_surface_types",
            "face_surface_types_truncated",
        }
        operation_data = {
            "from_object": {
                "reference",
                "selection",
                "resolved_subelement",
                "semantic_interface",
            },
            "face": {"hole_count"},
            "surface": {
                "grid_rows",
                "grid_columns",
                "u_degree",
                "v_degree",
                "u_periodic",
                "v_periodic",
            },
            "fill": {
                "native_type",
                "native_state",
                "boundary_edge_count",
                "curve_constraint_edge_count",
                "face_constraint_count",
                "point_constraint_count",
                "has_initial_face",
                "native_properties",
            },
            "blend": {
                "native_type",
                "native_state",
                "boundary_count",
                "preconditioned_boundary_count",
                "fill_type",
                "reversed",
            },
            "extend": {"native_type", "native_state", "native_properties"},
            "loft": {
                "section_count",
                "section_types",
                "solid",
                "ruled",
                "closed",
                "max_degree",
            },
            "thicken": {
                "source_shape_type",
                "removed_face_indices",
                "thickness",
                "tolerance",
                "join",
            },
            "shell": {
                "native_type",
                "native_state",
                "input_face_count",
                "native_shape_type",
                "native_shell_count",
                "make_solid",
                "native_properties",
            },
        }[operation]
        data = _exact_mapping(
            data,
            path=f"outputs.{name}.surface_data",
            keys=common_data | operation_data,
        )
        item["surface_data"] = data
        if (
            str(data["operation"]) != operation
            or str(data["output_type"]) != output_type
            or str(data["shape_type"]) != shape_type
        ):
            raise ValueError(
                f"Surface output {name!r} native readback disagrees with its contract."
            )
        engine = str(data["engine"] or "")
        if engine not in operation_engines[operation]:
            raise ValueError(
                f"Surface output {name!r} reported undeclared engine {engine!r}."
            )
        surface_types = data["face_surface_types"]
        if not isinstance(surface_types, list) or any(
            not isinstance(value, str) or not value for value in surface_types
        ):
            raise ValueError(
                f"Surface output {name!r} has invalid underlying surface-type readback."
            )
        face_count = int(facts.get("faces") or 0)
        if len(surface_types) != min(face_count, 64) or bool(
            data["face_surface_types_truncated"]
        ) != (face_count > 64):
            raise ValueError(
                f"Surface output {name!r} underlying surface readback is incomplete."
            )
        data_path = f"outputs.{name}.surface_data"
        if operation == "from_object":
            reference = _exact_mapping(
                arguments[0],
                path=f"outputs.{name}.definition.arguments[0]",
                keys={"document_uid", "object_name"},
            )
            key = (
                str(reference["document_uid"]),
                str(reference["object_name"]),
            )
            metadata = references.get(key)
            if metadata is None:
                raise ValueError(
                    f"Surface output {name!r} uses unauthenticated object {key[1]!r}."
                )
            expected_reference = {
                "document_uid": key[0],
                "object_name": key[1],
                "brep_sha256": str(metadata.get("brep_sha256") or ""),
            }
            if data["reference"] != expected_reference:
                raise ValueError(
                    f"Surface output {name!r} changed its authenticated reference."
                )
            selection = properties["selection"]
            if data["selection"] != selection:
                raise ValueError(
                    f"Surface output {name!r} changed its topology selection."
                )
            selection_mode = str(dict(selection).get("type") or "")
            expected_resolved = ""
            expected_semantic = None
            if selection_mode == "exact_subelement":
                expected_resolved = str(selection["subelement"])
            elif selection_mode == "published_interface":
                interface_name = str(selection["interface_name"])
                interface = dict(metadata.get("published_interfaces") or {}).get(
                    interface_name
                )
                if not isinstance(interface, dict):
                    raise ValueError(
                        f"Surface output {name!r} uses missing semantic interface "
                        f"{interface_name!r}."
                    )
                subelements = [
                    str(value) for value in list(interface.get("subelements") or [])
                ]
                expected_resolved = subelements[0] if len(subelements) == 1 else ""
                expected_semantic = {
                    "interface_name": interface_name,
                    "model_id": str(interface.get("model_id") or ""),
                    "publication_name": str(interface.get("publication_name") or ""),
                    "output_key": str(interface.get("output_key") or ""),
                }
            if (
                str(data["resolved_subelement"]) != expected_resolved
                or data["semantic_interface"] != expected_semantic
            ):
                raise ValueError(
                    f"Surface output {name!r} changed resolved topology identity."
                )
        elif operation == "face":
            if _surface_int(
                data["hole_count"], path=f"{data_path}.hole_count", maximum=256
            ) != len(properties["holes"]):
                raise ValueError(f"Surface output {name!r} changed its hole count.")
        elif operation == "surface":
            rows = len(arguments[0])
            columns = len(arguments[0][0]) if rows else 0
            if (
                _surface_int(
                    data["grid_rows"],
                    path=f"{data_path}.grid_rows",
                    minimum=2,
                    maximum=128,
                )
                != rows
                or _surface_int(
                    data["grid_columns"],
                    path=f"{data_path}.grid_columns",
                    minimum=2,
                    maximum=128,
                )
                != columns
            ):
                raise ValueError(
                    f"Surface output {name!r} changed its point-grid dimensions."
                )
            expected_engine = {
                "interpolate": "Part.BSplineSurface.interpolate",
                "approximate": "Part.BSplineSurface.approximate",
            }[str(properties["mode"])]
            if engine != expected_engine:
                raise ValueError(f"Surface output {name!r} changed interpolation mode.")
            u_degree = _surface_int(
                data["u_degree"],
                path=f"{data_path}.u_degree",
                minimum=1,
                maximum=25,
            )
            v_degree = _surface_int(
                data["v_degree"],
                path=f"{data_path}.v_degree",
                minimum=1,
                maximum=25,
            )
            if str(properties["mode"]) == "approximate" and not all(
                int(properties["degree_min"]) <= degree <= int(properties["degree_max"])
                for degree in (u_degree, v_degree)
            ):
                raise ValueError(
                    f"Surface output {name!r} native degree left the requested range."
                )
            if (
                type(data["u_periodic"]) is not bool
                or type(data["v_periodic"]) is not bool
            ):
                raise ValueError(
                    f"Surface output {name!r} periodic readback is malformed."
                )
        elif operation == "fill":
            if data["native_type"] != "Surface::Filling":
                raise ValueError(
                    f"Surface fill {name!r} changed its native feature type."
                )
            _surface_native_state(
                data["native_state"], path=f"{data_path}.native_state"
            )
            for field, source_field in (
                ("boundary_edge_count", "boundaries"),
                ("curve_constraint_edge_count", "curve_constraints"),
            ):
                count = _surface_int(
                    data[field], path=f"{data_path}.{field}", maximum=8192
                )
                if count < len(
                    arguments[0]
                    if source_field == "boundaries"
                    else properties[source_field]
                ):
                    raise ValueError(f"Surface fill {name!r} under-reported {field}.")
            for field, source_field in (
                ("face_constraint_count", "face_constraints"),
                ("point_constraint_count", "point_constraints"),
            ):
                if _surface_int(
                    data[field], path=f"{data_path}.{field}", maximum=256
                ) != len(properties[source_field]):
                    raise ValueError(f"Surface fill {name!r} changed {field}.")
            if type(data["has_initial_face"]) is not bool or data[
                "has_initial_face"
            ] is not (properties["initial_face"] is not None):
                raise ValueError(
                    f"Surface fill {name!r} changed its initial-face state."
                )
            _surface_native_properties(
                data["native_properties"],
                {
                    key: properties[key]
                    for key in (
                        "degree",
                        "points_on_curve",
                        "iterations",
                        "anisotropy",
                        "tolerance_2d",
                        "tolerance_3d",
                        "angular_tolerance",
                        "curvature_tolerance",
                        "maximum_degree",
                        "maximum_segments",
                    )
                },
                path=f"{data_path}.native_properties",
            )
        elif operation == "blend":
            if data["native_type"] != "Surface::GeomFillSurface":
                raise ValueError(
                    f"Surface blend {name!r} changed its native feature type."
                )
            _surface_native_state(
                data["native_state"], path=f"{data_path}.native_state"
            )
            boundary_count = len(arguments[0])
            if (
                _surface_int(
                    data["boundary_count"],
                    path=f"{data_path}.boundary_count",
                    minimum=2,
                    maximum=4,
                )
                != boundary_count
            ):
                raise ValueError(f"Surface blend {name!r} changed its boundary count.")
            preconditioned = _surface_int(
                data["preconditioned_boundary_count"],
                path=f"{data_path}.preconditioned_boundary_count",
                maximum=boundary_count,
            )
            if preconditioned > boundary_count:
                raise ValueError(
                    f"Surface blend {name!r} has impossible preconditioning metadata."
                )
            expected_style = {
                "stretched": "Stretched",
                "coons": "Coons",
                "curved": "Curved",
            }[str(properties["style"])]
            if (
                data["fill_type"] != expected_style
                or data["reversed"] != properties["reversed"]
            ):
                raise ValueError(
                    f"Surface blend {name!r} changed style or boundary reversal."
                )
        elif operation == "extend":
            if data["native_type"] != "Surface::Extend":
                raise ValueError(
                    f"Surface extension {name!r} changed its native feature type."
                )
            _surface_native_state(
                data["native_state"], path=f"{data_path}.native_state"
            )
            _surface_native_properties(
                data["native_properties"],
                {
                    key: properties[key]
                    for key in (
                        "u_negative",
                        "u_positive",
                        "v_negative",
                        "v_positive",
                        "tolerance",
                        "samples_u",
                        "samples_v",
                    )
                },
                path=f"{data_path}.native_properties",
            )
        elif operation == "loft":
            section_count = len(arguments[0])
            if (
                _surface_int(
                    data["section_count"],
                    path=f"{data_path}.section_count",
                    minimum=2,
                    maximum=256,
                )
                != section_count
            ):
                raise ValueError(f"Surface loft {name!r} changed its section count.")
            if (
                not isinstance(data["section_types"], list)
                or len(data["section_types"]) != section_count
                or any(value not in {"Edge", "Wire"} for value in data["section_types"])
            ):
                raise ValueError(
                    f"Surface loft {name!r} has malformed section-type readback."
                )
            for field in ("solid", "ruled", "closed"):
                if (
                    type(data[field]) is not bool
                    or data[field] is not properties[field]
                ):
                    raise ValueError(f"Surface loft {name!r} changed {field}.")
            if (
                type(data["max_degree"]) is not int
                or data["max_degree"] != properties["max_degree"]
            ):
                raise ValueError(f"Surface loft {name!r} changed maximum degree.")
        elif operation == "thicken":
            source_type = str(data["source_shape_type"])
            source_output_type = str(arguments[0].get("output_type") or "")
            allowed_source_types = {
                "face": {"Face"},
                "surface": {"Face"},
                "fill": {"Face"},
                "blend": {"Face"},
                "extension": {"Face"},
                "loft": {"Face", "Shell"},
                "shell": {"Shell"},
                "solid": {"Solid"},
            }.get(source_output_type, set())
            if source_type not in allowed_source_types:
                raise ValueError(
                    f"Surface thickness {name!r} changed source ShapeType."
                )
            if data["removed_face_indices"] != properties["remove_faces"]:
                raise ValueError(
                    f"Surface thickness {name!r} changed removed-face selection."
                )
            _surface_close(
                data["thickness"], arguments[1], path=f"{data_path}.thickness"
            )
            _surface_close(
                data["tolerance"],
                properties["tolerance"],
                path=f"{data_path}.tolerance",
            )
            if data["join"] != properties["join"]:
                raise ValueError(f"Surface thickness {name!r} changed join mode.")
            expected_thickness_engine = (
                "TopoShape.makeOffsetShape(fill=True)"
                if source_type == "Face" and not properties["remove_faces"]
                else "TopoShape.makeThickness"
            )
            if engine != expected_thickness_engine:
                raise ValueError(
                    f"Surface thickness {name!r} changed native algorithm."
                )
        else:
            if data["native_type"] != "Surface::Sewing":
                raise ValueError(
                    f"Surface shell {name!r} changed its native feature type."
                )
            _surface_native_state(
                data["native_state"], path=f"{data_path}.native_state"
            )
            input_face_count = _surface_int(
                data["input_face_count"],
                path=f"{data_path}.input_face_count",
                minimum=1,
                maximum=8192,
            )
            if input_face_count < len(arguments[0]):
                raise ValueError(f"Surface shell {name!r} under-reported input faces.")
            native_shape_type = str(data["native_shape_type"])
            if native_shape_type not in {"Face", "Shell", "Compound"}:
                raise ValueError(
                    f"Surface shell {name!r} has unsupported native sewing result."
                )
            native_shell_count = _surface_int(
                data["native_shell_count"],
                path=f"{data_path}.native_shell_count",
                maximum=1,
            )
            if native_shape_type == "Face" and native_shell_count != 0:
                raise ValueError(
                    f"Surface shell {name!r} has inconsistent shell-count readback."
                )
            if (
                type(data["make_solid"]) is not bool
                or data["make_solid"] is not properties["make_solid"]
            ):
                raise ValueError(
                    f"Surface shell {name!r} changed solid promotion state."
                )
            _surface_native_properties(
                data["native_properties"],
                {
                    "tolerance": properties["tolerance"],
                    "sewing_option": True,
                    "degenerate_shape": False,
                    "cut_free_edges": properties["cut_free_edges"],
                    "nonmanifold": properties["nonmanifold"],
                },
                path=f"{data_path}.native_properties",
            )
        _validate_definition_value(
            data,
            prepared,
            f"outputs.{name}.surface_data",
        )
        encoded_data = json.dumps(
            data,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
        if len(encoded_data) > _STRUCTURED_DEFINITION_LIMIT:
            raise ValueError(f"Surface output {name!r} native readback is too large.")

        for reference_payload, reference_path in _surface_definition_references(
            definition,
            path=f"outputs.{name}.definition",
        ):
            arguments = list(reference_payload.get("arguments") or [])
            properties = dict(reference_payload.get("properties") or {})
            if len(arguments) != 1 or not isinstance(arguments[0], dict):
                raise ValueError(f"{reference_path} has a malformed stable reference.")
            reference = arguments[0]
            key = (
                str(reference.get("document_uid") or ""),
                str(reference.get("object_name") or ""),
            )
            metadata = references.get(key)
            if metadata is None:
                raise ValueError(
                    f"{reference_path} uses unauthenticated object {key[1]!r}."
                )
            selection = properties.get("selection")
            if not isinstance(selection, dict):
                raise ValueError(f"{reference_path}.selection must be an object.")
            mode = str(selection.get("type") or "")
            selected_type = str(reference_payload.get("output_type") or "")
            expected_prefix = {
                "vertex": "Vertex",
                "edge": "Edge",
                "wire": "Wire",
                "face": "Face",
                "shell": "Shell",
                "solid": "Solid",
            }[selected_type]
            if mode == "whole_shape" and set(selection) == {"type"}:
                if str(metadata.get("shape_type") or "") != expected_prefix:
                    raise ValueError(
                        f"{reference_path} whole Shape does not have requested type "
                        f"{selected_type!r}."
                    )
            elif mode == "exact_subelement" and set(selection) == {
                "type",
                "subelement",
            }:
                if bool(metadata.get("transient_topology")) or bool(
                    metadata.get("requires_semantic_interfaces")
                ):
                    raise ValueError(
                        f"{reference_path} uses transient topology on a regenerating source."
                    )
                element = str(selection["subelement"] or "")
                match = re.fullmatch(rf"{expected_prefix}([1-9][0-9]*)", element)
                available = int(
                    dict(metadata.get("facts") or {}).get(count_fields[expected_prefix])
                    or 0
                )
                if match is None or int(match.group(1)) > available:
                    raise ValueError(
                        f"{reference_path} selects unavailable {element!r}; "
                        f"the source has {available} {expected_prefix} values."
                    )
            elif mode == "published_interface" and set(selection) == {
                "type",
                "interface_name",
            }:
                interface_name = str(selection["interface_name"] or "")
                interface = dict(metadata.get("published_interfaces") or {}).get(
                    interface_name
                )
                if not isinstance(interface, dict):
                    raise ValueError(
                        f"{reference_path} uses missing interface {interface_name!r}."
                    )
                subelements = [
                    str(value) for value in list(interface.get("subelements") or [])
                ]
                if len(subelements) > 1 or (
                    subelements
                    and re.fullmatch(rf"{expected_prefix}[1-9][0-9]*", subelements[0])
                    is None
                ):
                    raise ValueError(
                        f"{reference_path} interface {interface_name!r} does not resolve "
                        f"to one {expected_prefix}."
                    )
                if (
                    not subelements
                    and str(metadata.get("shape_type") or "") != expected_prefix
                ):
                    raise ValueError(
                        f"{reference_path} whole-object interface has the wrong Shape type."
                    )
            else:
                raise ValueError(
                    f"{reference_path} has malformed selection mode {mode!r}."
                )

        expected_summary = {
            "name": name,
            "type": output_type,
            "operation": operation,
            "engine": engine,
            "shape_type": shape_type,
            "solids": int(facts.get("solids") or 0),
            "shells": int(facts.get("shells") or 0),
            "faces": face_count,
            "edges": int(facts.get("edges") or 0),
        }
        if raw_summary != expected_summary:
            raise ValueError(
                f"Surface output {name!r} worker validation summary is inconsistent."
            )
        expected_summaries.append(expected_summary)
    if summaries != expected_summaries:
        raise ValueError("The Surface worker validation output order is inconsistent.")
    return dict(validation)


def _validate_definition_value(
    value: Any,
    prepared: Mapping[str, Any],
    path: str,
    depth: int = 0,
) -> None:
    extra_depth = {
        # Complex mechanical definitions remain bounded by the 256 KiB source
        # and input limits, graph validation, and worker resource limits. A
        # twelve-level Part Design ceiling rejected ordinary nested feature
        # graphs long before those real safety boundaries were approached.
        "partdesign": 56,
        "assembly": 12,
        "surface": 64,
        "mesh": 32,
        "inspection": 16,
        "fem": 16,
        "cam": 16,
        "techdraw": 16,
    }.get(prepared["pack"].domain, 4)
    if depth > contracts.MAX_INPUT_DEPTH + extra_depth:
        raise ValueError(f"{path} exceeds the supported definition depth.")
    if value is None or isinstance(value, bool | int):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError(f"{path} must be finite.")
        return
    if isinstance(value, str):
        if value.startswith(("/", "\\")) or _DRIVE_PATH.match(value):
            raise ValueError(f"{path} cannot contain a raw filesystem path.")
        if ".." in Path(value.replace("\\", "/")).parts:
            raise ValueError(f"{path} cannot traverse a filesystem path.")
        return
    if isinstance(value, list):
        for index, item in enumerate(value):
            _validate_definition_value(item, prepared, f"{path}[{index}]", depth + 1)
        return
    if isinstance(value, dict):
        if is_document_reference(value):
            clean_reference = normalize_document_reference(value)
            if (
                prepared["pack"].domain == "assembly"
                and clean_reference["document_uid"] == "freecad-fasteners"
                and re.fullmatch(
                    r"freecad-fasteners:[0-9a-f]{64}",
                    clean_reference["object_name"],
                )
            ):
                # This non-document identity is independently bound to an exact
                # bundled catalog definition and generated BREP by
                # _validate_assembly_execution before structured-data traversal.
                return
            if prepared["pack"].domain in {"partdesign", "assembly", "robot"}:
                authenticated = next(
                    (
                        item
                        for item in list(prepared.get("resolved_references") or [])
                        if str(item.get("document_uid") or "")
                        == clean_reference["document_uid"]
                        and str(item.get("object_name") or "")
                        == clean_reference["object_name"]
                    ),
                    None,
                )
                if authenticated is None:
                    raise ValueError(
                        f"{path} refers to an unauthenticated reusable component."
                    )
                if (
                    clean_reference.get("document_path")
                    and str(authenticated.get("document_path") or "")
                    != clean_reference["document_path"]
                ):
                    raise ValueError(
                        f"{path} changed the authenticated component document_path."
                    )
                return
            if clean_reference["document_uid"] != str(prepared["document_uid"]):
                raise ValueError(f"{path} refers to a different document.")
            names = {
                str(item.get("name") or "") for item in prepared["document_objects"]
            }
            if clean_reference["object_name"] not in names:
                raise ValueError(
                    f"{path} refers to missing object "
                    f"{clean_reference['object_name']!r}."
                )
            return
        for key, item in value.items():
            _validate_definition_value(item, prepared, f"{path}.{key}", depth + 1)
        return
    raise ValueError(f"{path} contains unsupported value {type(value).__name__}.")


def _validate_robot_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    """Replay the exact native Robot graph and authenticate simulation artifacts."""

    import FreeCAD as App
    from vibescript_robot_worker import (
        SIMULATION_SCHEMA,
        VALIDATION_SCHEMA,
        _inflate,
        validate_and_build_robot,
        validate_robot_definition,
    )
    from vibescript_component_worker import (
        configure_component_references,
        validate_component_definition,
    )

    configure_component_references(
        [
            dict(item)
            for item in list(prepared.get("resolved_references") or [])
            if isinstance(item, Mapping)
            and item.get("document_uid")
            and item.get("object_name")
        ]
    )

    validation = execution.get("robot_validation")
    if not isinstance(validation, dict):
        raise ValueError("The Robot worker returned no native validation summary.")
    if set(validation) != {"schema", "output_count", "outputs"}:
        raise ValueError("The Robot worker validation summary has malformed fields.")
    if validation.get("schema") != VALIDATION_SCHEMA:
        raise ValueError("The Robot worker validation schema is unsupported.")
    if type(validation.get("output_count")) is not int or validation[
        "output_count"
    ] != len(outputs):
        raise ValueError("The Robot worker validation output count is inconsistent.")
    summaries = validation.get("outputs")
    if not isinstance(summaries, list) or len(summaries) != len(outputs):
        raise ValueError("The Robot worker validation output list is inconsistent.")

    staging = Path(str(prepared["staging"])).resolve()
    raw_result: dict[str, Any] = {}
    for item in outputs:
        name = str(item["name"])
        if str(item["type"]) == "component_link":
            definition, _component_data = validate_component_definition(
                item.get("definition"),
                domain="robot",
                output_name=name,
            )
        else:
            definition = validate_robot_definition(
                item.get("definition"),
                expected_output_type=str(item["type"]),
                require_domain_value=False,
                context=f"outputs.{name}.definition",
            )
        item["definition"] = definition
        raw_result[name] = _inflate(definition)
        if str(item["type"]) == "component_link":
            continue
        data = item.get("robot_data")
        if not isinstance(data, dict):
            raise ValueError(f"Robot output {name!r} has no native readback.")
        _validate_definition_value(data, prepared, f"outputs.{name}.robot_data")
        if (
            data.get("schema") != VALIDATION_SCHEMA
            or data.get("operation") != definition["operation"]
        ):
            raise ValueError(
                f"Robot output {name!r} native readback disagrees with its definition."
            )
        encoded = json.dumps(
            data,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
        if len(encoded) > _STRUCTURED_DEFINITION_LIMIT:
            raise ValueError(f"Robot output {name!r} native readback is too large.")
        if str(item["type"]) != "simulation":
            continue
        if (
            item.get("artifact_kind") != "robot_simulation_f64le"
            or item.get("artifact_schema") != SIMULATION_SCHEMA
            or type(item.get("sample_count")) is not int
            or type(item.get("sample_width")) is not int
            or int(item["sample_width"]) != 15
            or int(item["sample_count"]) != int(data.get("sample_count", -1))
            or type(item.get("artifact_bytes")) is not int
            or int(item["artifact_bytes"])
            != int(item["sample_count"]) * int(item["sample_width"]) * 8
        ):
            raise ValueError(
                f"Robot simulation output {name!r} has malformed artifact metadata."
            )
        path = (staging / str(item.get("artifact_path") or "")).resolve()
        if (
            staging not in path.parents
            or not path.is_file()
            or path.is_symlink()
            or path.stat().st_size != int(item["artifact_bytes"])
            or _sha256_file(path) != item.get("artifact_sha256")
        ):
            raise ValueError(
                f"Robot simulation output {name!r} artifact is missing or unauthenticated."
            )
        values = array("d")
        with path.open("rb") as handle:
            values.fromfile(handle, int(item["sample_count"]) * 15)
            if handle.read(1):
                raise ValueError(
                    f"Robot simulation output {name!r} artifact has trailing bytes."
                )
        if sys.byteorder != "little":
            values.byteswap()
        if len(values) != int(item["sample_count"]) * 15 or any(
            not math.isfinite(value) for value in values
        ):
            raise ValueError(
                f"Robot simulation output {name!r} artifact contains malformed samples."
            )
        rows = [
            [float(value) for value in values[index : index + 15]]
            for index in range(0, len(values), 15)
        ]
        if (
            len(rows) < 2
            or not math.isclose(rows[0][0], 0.0, abs_tol=1.0e-12)
            or not math.isclose(
                rows[-1][0], float(data.get("duration", -1.0)), abs_tol=1.0e-9
            )
            or any(left[0] >= right[0] for left, right in zip(rows, rows[1:]))
            or any(row[1] not in {0.0, 1.0} for row in rows)
        ):
            raise ValueError(
                f"Robot simulation output {name!r} sample timeline is inconsistent."
            )

    replay_outputs: list[dict[str, Any]]
    replay_validation: dict[str, Any]
    replay_document = App.newDocument(
        f"VibeCADRobotValidation{uuid.uuid4().hex}",
        "VibeCAD Robot Validation",
        True,
        True,
    )
    try:
        with tempfile.TemporaryDirectory(
            prefix="vibecad-robot-validation-"
        ) as directory:
            replay_root = Path(directory)
            (replay_root / "outputs").mkdir()
            replay_outputs, replay_validation = validate_and_build_robot(
                replay_document,
                raw_result,
                [dict(item) for item in prepared["expected_outputs"]],
                replay_root,
            )
            for index, (reported, replayed) in enumerate(zip(outputs, replay_outputs)):
                name = str(reported["name"])
                if set(reported) != set(replayed):
                    raise ValueError(
                        f"Robot output {name!r} fields differ from native replay."
                    )
                _mesh_values_match(
                    reported,
                    replayed,
                    path=f"outputs.{name}",
                )
                output_type = str(reported["type"])
                if output_type in {"trajectory", "dressup"}:
                    native_name = (
                        f"TrajectoryCandidate{index:03d}"
                        if output_type == "trajectory"
                        else f"DressUpCandidate{index:03d}"
                    )
                    native = replay_document.getObject(native_name)
                    if native is None:
                        raise ValueError(
                            f"Robot output {name!r} native replay object disappeared."
                        )
                    reported["detached_trajectory"] = native.Trajectory
    finally:
        App.closeDocument(replay_document.Name)
    if replay_validation != validation:
        raise ValueError(
            "The Robot worker validation summary differs from native replay."
        )
    return dict(validation)


def _validate_fem_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    """Authenticate one exact native FEM graph and its detached mesh state."""

    from vibescript_fem_worker import (
        VALIDATION_SCHEMA,
        _RESULT_FLOAT_LISTS,
        _RESULT_VECTOR_LISTS,
        _build_inline_mesh,
        _mesh_topology,
        build_fem_mesh,
        validate_fem_definition,
    )

    validation = execution.get("fem_validation")
    required_validation = {
        "schema",
        "output_count",
        "outputs",
        "analysis_outputs",
        "result_outputs",
        "analysis_output",
        "result_output",
        "solver_executed",
    }
    if not isinstance(validation, dict) or set(validation) != required_validation:
        raise ValueError(
            "The FEM worker returned a malformed native validation summary."
        )
    if validation.get("schema") != VALIDATION_SCHEMA:
        raise ValueError("The FEM worker validation schema is unsupported.")
    if type(validation.get("output_count")) is not int or int(
        validation["output_count"]
    ) != len(outputs):
        raise ValueError("The FEM worker validation output count is inconsistent.")
    summaries = validation.get("outputs")
    if not isinstance(summaries, list) or len(summaries) != len(outputs):
        raise ValueError("The FEM worker validation output list is inconsistent.")
    analysis_outputs = validation.get("analysis_outputs")
    result_outputs = validation.get("result_outputs")
    output_names_by_type = {
        output_type: [
            str(item["name"]) for item in outputs if str(item["type"]) == output_type
        ]
        for output_type in ("analysis", "result")
    }
    if (
        not isinstance(analysis_outputs, list)
        or not analysis_outputs
        or not all(isinstance(name, str) for name in analysis_outputs)
        or len(analysis_outputs) != len(set(analysis_outputs))
        or analysis_outputs != output_names_by_type["analysis"]
        or not isinstance(result_outputs, list)
        or not result_outputs
        or not all(isinstance(name, str) for name in result_outputs)
        or len(result_outputs) != len(set(result_outputs))
        or result_outputs != output_names_by_type["result"]
    ):
        raise ValueError("The FEM worker study output lists are inconsistent.")
    if not isinstance(validation.get("analysis_output"), str) or not isinstance(
        validation.get("result_output"), str
    ):
        raise ValueError("The FEM worker legacy output aliases are malformed.")
    if type(validation.get("solver_executed")) is not bool:
        raise ValueError("The FEM worker solver-executed verdict is malformed.")

    expected_native = {
        "analysis": {"Fem::FemAnalysis"},
        "solver": {"Fem::FemSolverObjectPython"},
        "material": {"App::MaterialObjectPython"},
        "constraint": {
            "Fem::ConstraintFixed",
            "Fem::ConstraintForce",
            "Fem::ConstraintPressure",
        },
        "load_case": {"App::DocumentObjectGroup"},
        "mesh": {"Fem::FemMeshShapeBaseObjectPython"},
        "result": {"Fem::FemResultObjectPython"},
    }
    output_types = {str(item["name"]): str(item["type"]) for item in outputs}
    worker_references = list(
        dict(prepared.get("worker_request") or {}).get("document_references") or []
    )
    reference_by_key: dict[tuple[str, str], dict[str, Any]] = {}
    for index, raw in enumerate(worker_references):
        if not isinstance(raw, dict):
            raise ValueError(f"Prepared FEM reference {index} is malformed.")
        key = (
            str(raw.get("document_uid") or ""),
            str(raw.get("object_name") or ""),
        )
        if not all(key) or key in reference_by_key:
            raise ValueError("Prepared FEM references have invalid identities.")
        if raw.get("artifact_kind") != "brep":
            raise ValueError("A FEM input reference is not an authenticated BREP.")
        reference_by_key[key] = raw
    resolved_by_key = {
        (
            str(raw.get("document_uid") or ""),
            str(raw.get("object_name") or ""),
        ): raw
        for raw in list(prepared.get("resolved_references") or [])
        if isinstance(raw, dict) and raw.get("artifact_kind") == "brep"
    }
    if not reference_by_key or set(reference_by_key) != set(resolved_by_key):
        raise ValueError("The finalized FEM reference contract is inconsistent.")
    for key, worker_reference in reference_by_key.items():
        resolved = resolved_by_key[key]
        if (
            worker_reference.get("brep_sha256") != resolved.get("brep_sha256")
            or worker_reference.get("type_id") != resolved.get("type_id")
            or str(worker_reference.get("source_kind") or "shape")
            != str(resolved.get("source_kind") or "shape")
            or str(worker_reference.get("source_revision") or "")
            != str(resolved.get("source_revision") or "")
        ):
            raise ValueError(
                f"Finalized FEM reference {key[1]!r} changed between host and worker contracts."
            )

    def expected_reference_identity(
        reference: Any,
        *,
        context: str,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        if not isinstance(reference, dict) or set(reference) != {
            "document_uid",
            "object_name",
        }:
            raise ValueError(f"{context} has a malformed document reference.")
        key = (
            str(reference["document_uid"]),
            str(reference["object_name"]),
        )
        descriptor = reference_by_key.get(key)
        if descriptor is None:
            raise ValueError(f"{context} was not finalized as an input reference.")
        return (
            {
                "document_uid": key[0],
                "object_name": key[1],
                "artifact_sha256": str(descriptor.get("brep_sha256") or ""),
                "source_type_id": str(descriptor.get("type_id") or ""),
                "source_kind": str(descriptor.get("source_kind") or "shape"),
                "source_revision": str(descriptor.get("source_revision") or ""),
            },
            descriptor,
        )

    def expected_selection(
        descriptor: Mapping[str, Any],
        selector: Mapping[str, Any],
        *,
        context: str,
    ) -> list[str]:
        selection_type = str(selector.get("type") or "")
        if selection_type == "subelement":
            if bool(descriptor.get("transient_topology")) or bool(
                descriptor.get("requires_semantic_interfaces")
            ):
                raise ValueError(
                    f"{context} uses an exact subelement on a regenerating source."
                )
            return [str(selector.get("name") or "")]
        if selection_type != "published_interface":
            raise ValueError(f"{context} has an unsupported selection type.")
        interfaces = descriptor.get("published_interfaces")
        interface = (
            interfaces.get(str(selector.get("interface_name") or ""))
            if isinstance(interfaces, dict)
            else None
        )
        if not isinstance(interface, dict):
            raise ValueError(f"{context} names an undeclared semantic interface.")
        subelements = interface.get("subelements")
        if not isinstance(subelements, list):
            raise ValueError(f"{context} semantic interface is malformed.")
        return [str(value) for value in subelements]

    def definition_sha256(value: Mapping[str, Any]) -> str:
        return hashlib.sha256(
            json.dumps(
                value,
                ensure_ascii=True,
                sort_keys=True,
                separators=(",", ":"),
                allow_nan=False,
            ).encode("utf-8")
        ).hexdigest()

    definitions: dict[str, dict[str, Any]] = {}
    output_by_definition: dict[str, str] = {}
    for item in outputs:
        name = str(item["name"])
        output_type = str(item["type"])
        if set(item) != {"name", "type", "definition", "fem_data"}:
            raise ValueError(f"FEM output {name!r} has malformed fields.")
        definition = validate_fem_definition(
            item.get("definition"),
            expected_output_type=output_type,
            require_domain_value=False,
            context=f"outputs.{name}.definition",
        )
        key = definition_sha256(definition)
        if key in output_by_definition:
            raise ValueError(
                f"FEM outputs {output_by_definition[key]!r} and {name!r} duplicate a definition."
            )
        definitions[name] = definition
        output_by_definition[key] = name
        item["definition"] = definition

    def output_for_definition(
        value: Any,
        expected_type: str,
        *,
        context: str,
    ) -> str:
        if not isinstance(value, dict):
            raise ValueError(f"{context} is not a FEM definition.")
        name = output_by_definition.get(definition_sha256(value))
        if name is None or output_types.get(name) != expected_type:
            raise ValueError(
                f"{context} does not reference a returned {expected_type} output."
            )
        return name

    expected_load_case_members = {
        name: [
            output_for_definition(
                member,
                "constraint",
                context=f"outputs.{name}.constraints[{index}]",
            )
            for index, member in enumerate(definition["arguments"][0])
        ]
        for name, definition in definitions.items()
        if output_types[name] == "load_case"
    }

    def validate_material_mapping(
        value: Any,
        analysis_definition: Mapping[str, Any],
        *,
        context: str,
    ) -> dict[str, Any]:
        if not isinstance(value, dict) or set(value) != {
            "active_element_count",
            "default_material_output",
            "materials",
            "overlap_count",
            "unassigned_count",
        }:
            raise ValueError(f"{context} has malformed fields.")
        material_names = [
            output_for_definition(
                definition,
                "material",
                context=f"{context}.analysis.materials[{index}]",
            )
            for index, definition in enumerate(analysis_definition["arguments"][1])
        ]
        rows = value.get("materials")
        if (
            type(value.get("active_element_count")) is not int
            or int(value["active_element_count"]) <= 0
            or type(value.get("default_material_output")) is not str
            or type(value.get("overlap_count")) is not int
            or int(value["overlap_count"]) != 0
            or type(value.get("unassigned_count")) is not int
            or int(value["unassigned_count"]) != 0
            or not isinstance(rows, list)
            or len(rows) != len(material_names)
        ):
            raise ValueError(f"{context} has an inconsistent coverage verdict.")
        expected_modes = []
        unassigned = []
        for material_name in material_names:
            assignments = list(
                definitions[material_name]["properties"].get("assignments") or []
            )
            if len(material_names) == 1:
                if assignments:
                    raise ValueError(
                        f"{context} assigns the only material despite native global semantics."
                    )
                expected_modes.append("global")
            elif assignments:
                expected_modes.append("explicit")
            else:
                expected_modes.append("remainder")
                unassigned.append(material_name)
        expected_default = (
            material_names[0]
            if len(material_names) == 1
            else (unassigned[0] if len(unassigned) == 1 else "")
        )
        if len(unassigned) > 1 or value["default_material_output"] != expected_default:
            raise ValueError(f"{context} has an ambiguous default material.")
        element_total = 0
        for index, (row, material_name, mode) in enumerate(
            zip(rows, material_names, expected_modes)
        ):
            if (
                not isinstance(row, dict)
                or set(row) != {"output", "assignment_mode", "element_count"}
                or row.get("output") != material_name
                or row.get("assignment_mode") != mode
                or type(row.get("element_count")) is not int
                or int(row["element_count"]) <= 0
            ):
                raise ValueError(
                    f"{context}.materials[{index}] is inconsistent with its definition."
                )
            element_total += int(row["element_count"])
        if element_total != int(value["active_element_count"]):
            raise ValueError(f"{context} element counts do not cover the active mesh.")
        return dict(value)

    staging = Path(str(prepared["staging"])).resolve()
    expected_summaries = []
    analysis_names = []
    result_names = []
    solver_executed = False
    for item in outputs:
        name = str(item["name"])
        output_type = str(item["type"])
        definition = definitions[name]
        data = item.get("fem_data")
        if not isinstance(data, dict):
            raise ValueError(f"FEM output {name!r} has no native readback.")
        _validate_definition_value(data, prepared, f"outputs.{name}.fem_data")
        encoded = json.dumps(
            data,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
        if len(encoded) > 256 * 1024 * 1024:
            raise ValueError(f"FEM output {name!r} native readback is too large.")
        native_type = str(data.get("native_type") or "")
        if native_type not in expected_native[output_type]:
            raise ValueError(
                f"FEM output {name!r} returned native type {native_type!r}, not a "
                f"declared {output_type} type."
            )
        if output_type == "solver":
            if set(data) != {
                "native_type",
                "analysis_type",
                "matrix_solver",
                "geometrical_nonlinearity",
                "material_nonlinearity",
                "reduced_integration",
            }:
                raise ValueError(f"FEM solver output {name!r} has malformed readback.")
            properties = definition["properties"]
            expected_solver = {
                "native_type": native_type,
                "analysis_type": properties["analysis_type"],
                "matrix_solver": properties["matrix_solver"],
                "geometrical_nonlinearity": properties["geometrical_nonlinearity"],
                "material_nonlinearity": properties["material_nonlinearity"],
                "reduced_integration": properties["reduced_integration"],
            }
            if data != expected_solver:
                raise ValueError(
                    f"FEM solver output {name!r} disagrees with its definition."
                )
        elif output_type == "material":
            if set(data) != {
                "native_type",
                "category",
                "material",
                "assignments",
            }:
                raise ValueError(
                    f"FEM material output {name!r} has malformed readback."
                )
            material = data.get("material")
            if data.get("category") != "Solid" or not isinstance(material, dict):
                raise ValueError(
                    f"FEM material output {name!r} is not a solid material."
                )
            required_material = {
                "Name",
                "YoungsModulus",
                "PoissonRatio",
                "Density",
                "ThermalExpansionCoefficient",
            }
            if set(material) != required_material:
                raise ValueError(
                    f"FEM material output {name!r} has malformed properties."
                )
            properties = definition["properties"]
            expected_material = {
                "Name": str(properties["name"]),
                "YoungsModulus": (
                    f"{float(properties['youngs_modulus_mpa']):.17g} MPa"
                ),
                "PoissonRatio": f"{float(properties['poisson_ratio']):.17g}",
                "Density": f"{float(properties['density_kg_m3']):.17g} kg/m^3",
                "ThermalExpansionCoefficient": (
                    f"{float(properties['thermal_expansion_per_k']):.17g} 1/K"
                ),
            }
            if material != expected_material:
                raise ValueError(
                    f"FEM material output {name!r} disagrees with its definition."
                )
            expected_assignments = []
            for index, assignment in enumerate(properties.get("assignments") or []):
                target, descriptor = expected_reference_identity(
                    assignment["target"],
                    context=f"outputs.{name}.assignments[{index}].target",
                )
                expected_assignments.append(
                    {
                        "target": target,
                        "selection": assignment["selection"],
                        "resolved_subelements": expected_selection(
                            descriptor,
                            assignment["selection"],
                            context=(f"outputs.{name}.assignments[{index}].selection"),
                        ),
                    }
                )
            if data.get("assignments") != expected_assignments:
                raise ValueError(
                    f"FEM material output {name!r} changed its region assignments."
                )
        elif output_type == "constraint":
            required = {
                "native_type",
                "kind",
                "target",
                "selection",
                "resolved_subelements",
                "magnitude",
                "direction",
                "reversed",
            }
            if set(data) != required:
                raise ValueError(
                    f"FEM constraint output {name!r} has malformed readback."
                )
            properties = definition["properties"]
            if (
                data.get("kind") != properties["kind"]
                or data.get("magnitude") != properties["magnitude"]
                or data.get("direction") != properties["direction"]
                or data.get("reversed") != properties["reversed"]
                or data.get("selection") != definition["arguments"][1]
            ):
                raise ValueError(
                    f"FEM constraint output {name!r} disagrees with its definition."
                )
            target = data.get("target")
            if not isinstance(target, dict) or {
                "document_uid",
                "object_name",
                "artifact_sha256",
                "source_type_id",
                "source_kind",
                "source_revision",
            } != set(target):
                raise ValueError(f"FEM constraint output {name!r} target is malformed.")
            if {
                "document_uid": target["document_uid"],
                "object_name": target["object_name"],
            } != definition["arguments"][0]:
                raise ValueError(f"FEM constraint output {name!r} target changed.")
            expected_target, descriptor = expected_reference_identity(
                definition["arguments"][0],
                context=f"outputs.{name}.target",
            )
            if target != expected_target:
                raise ValueError(
                    f"FEM constraint output {name!r} target authentication changed."
                )
            expected_constraint_type = {
                "fixed": "Fem::ConstraintFixed",
                "force": "Fem::ConstraintForce",
                "pressure": "Fem::ConstraintPressure",
            }[str(properties["kind"])]
            if native_type != expected_constraint_type:
                raise ValueError(
                    f"FEM constraint output {name!r} has the wrong native kind."
                )
            subelements = data.get("resolved_subelements")
            if (
                not isinstance(subelements, list)
                or not 1 <= len(subelements) <= 64
                or len(subelements) != len(set(subelements))
                or any(
                    not isinstance(value, str)
                    or re.fullmatch(r"(?:Solid|Face|Edge|Vertex)[1-9][0-9]*", value)
                    is None
                    for value in subelements
                )
            ):
                raise ValueError(
                    f"FEM constraint output {name!r} resolved selection is malformed."
                )
            expected_subelements = expected_selection(
                descriptor,
                definition["arguments"][1],
                context=f"outputs.{name}.selection",
            )
            if subelements != expected_subelements:
                raise ValueError(
                    f"FEM constraint output {name!r} changed its resolved semantic selection."
                )
        elif output_type == "load_case":
            if set(data) != {"native_type", "constraint_outputs"}:
                raise ValueError(
                    f"FEM load case output {name!r} has malformed readback."
                )
            members = data.get("constraint_outputs")
            if (
                not isinstance(members, list)
                or not members
                or len(members) != len(set(members))
                or any(
                    output_types.get(str(member)) != "constraint" for member in members
                )
            ):
                raise ValueError(f"FEM load case output {name!r} has invalid members.")
            if members != expected_load_case_members[name]:
                raise ValueError(
                    f"FEM load case output {name!r} disagrees with its definition graph."
                )
        elif output_type == "analysis":
            required = {
                "native_type",
                "solver_output",
                "material_outputs",
                "constraint_outputs",
                "load_case_outputs",
                "mesh_output",
                "material_mesh_mapping",
            }
            if set(data) != required:
                raise ValueError(
                    f"FEM analysis output {name!r} has malformed readback."
                )
            if (
                output_types.get(str(data["solver_output"])) != "solver"
                or output_types.get(str(data["mesh_output"])) != "mesh"
            ):
                raise ValueError(f"FEM analysis output {name!r} graph is incomplete.")
            for key, expected_type in (
                ("material_outputs", "material"),
                ("constraint_outputs", "constraint"),
                ("load_case_outputs", "load_case"),
            ):
                values = data.get(key)
                if (
                    not isinstance(values, list)
                    or not values
                    or len(values) != len(set(values))
                    or any(
                        output_types.get(str(value)) != expected_type
                        for value in values
                    )
                ):
                    raise ValueError(f"FEM analysis output {name!r} has invalid {key}.")
            expected_solver = output_for_definition(
                definition["arguments"][0],
                "solver",
                context=f"outputs.{name}.solver",
            )
            expected_materials = [
                output_for_definition(
                    value,
                    "material",
                    context=f"outputs.{name}.materials[{index}]",
                )
                for index, value in enumerate(definition["arguments"][1])
            ]
            expected_load_cases = [
                output_for_definition(
                    value,
                    "load_case",
                    context=f"outputs.{name}.load_cases[{index}]",
                )
                for index, value in enumerate(definition["arguments"][2])
            ]
            expected_constraints = sorted(
                {
                    constraint
                    for load_case in expected_load_cases
                    for constraint in expected_load_case_members[load_case]
                }
            )
            expected_mesh = output_for_definition(
                definition["arguments"][3],
                "mesh",
                context=f"outputs.{name}.mesh",
            )
            expected_graph = {
                "native_type": native_type,
                "solver_output": expected_solver,
                "material_outputs": expected_materials,
                "constraint_outputs": expected_constraints,
                "load_case_outputs": expected_load_cases,
                "mesh_output": expected_mesh,
                "material_mesh_mapping": validate_material_mapping(
                    data.get("material_mesh_mapping"),
                    definition,
                    context=f"outputs.{name}.material_mesh_mapping",
                ),
            }
            if data != expected_graph:
                raise ValueError(
                    f"FEM analysis output {name!r} disagrees with its definition graph."
                )
            analysis_names.append(name)
        elif output_type == "mesh":
            required = {
                "native_type",
                "method",
                "source",
                "order",
                "nodes",
                "elements",
                "facts",
            }
            if set(data) != required or data.get("method") not in {"inline", "gmsh"}:
                raise ValueError(f"FEM mesh output {name!r} has malformed readback.")
            properties = definition["properties"]
            expected_source, _descriptor = expected_reference_identity(
                definition["arguments"][0],
                context=f"outputs.{name}.source",
            )
            if (
                data.get("method") != properties["method"]
                or data.get("order") != properties["order"]
                or data.get("source") != expected_source
            ):
                raise ValueError(
                    f"FEM mesh output {name!r} disagrees with its definition."
                )
            topology = {
                "nodes": data["nodes"],
                "elements": data["elements"],
                "facts": data["facts"],
            }
            detached = build_fem_mesh(topology)
            if _mesh_topology(detached) != topology:
                raise ValueError(
                    f"FEM mesh output {name!r} changed during native reconstruction."
                )
            if properties["method"] == "inline":
                expected_topology = _mesh_topology(_build_inline_mesh(definition))
                if topology != expected_topology:
                    raise ValueError(
                        f"FEM mesh output {name!r} differs from native reconstruction "
                        "of its inline definition."
                    )
            item["detached_fem_mesh"] = detached
        else:
            required = {
                "native_type",
                "status",
                "execution",
                "solver_executed",
                "input_deck",
                "result_values",
                "mesh_constraint_mapping",
                "material_mesh_mapping",
                "analysis_output",
                "mesh_output",
            }
            if set(data) != required:
                raise ValueError(f"FEM result output {name!r} has malformed readback.")
            execution_mode = definition["properties"]["execution"]
            expected_status = (
                "solved" if execution_mode == "calculix" else "input_validated"
            )
            expected_analysis = output_for_definition(
                definition["arguments"][0],
                "analysis",
                context=f"outputs.{name}.analysis",
            )
            expected_analysis_definition = definitions[expected_analysis]
            expected_mesh = output_for_definition(
                expected_analysis_definition["arguments"][3],
                "mesh",
                context=f"outputs.{name}.analysis.mesh",
            )
            if (
                data.get("execution") != execution_mode
                or data.get("status") != expected_status
                or type(data.get("solver_executed")) is not bool
                or bool(data["solver_executed"]) != (execution_mode == "calculix")
                or data.get("analysis_output") != expected_analysis
                or data.get("mesh_output") != expected_mesh
            ):
                raise ValueError(
                    f"FEM result output {name!r} has an inconsistent verdict."
                )
            solver_executed = solver_executed or bool(data["solver_executed"])
            deck = data.get("input_deck")
            if not isinstance(deck, dict) or set(deck) != {
                "artifact_kind",
                "artifact_path",
                "artifact_sha256",
                "artifact_bytes",
            }:
                raise ValueError(f"FEM result output {name!r} input deck is malformed.")
            path = (staging / str(deck.get("artifact_path") or "")).resolve()
            if (
                deck.get("artifact_kind") != "calculix_input"
                or staging not in path.parents
                or not path.is_file()
                or path.is_symlink()
                or type(deck.get("artifact_bytes")) is not int
                or path.stat().st_size != int(deck["artifact_bytes"])
                or _sha256_file(path) != deck.get("artifact_sha256")
            ):
                raise ValueError(
                    f"FEM result output {name!r} input deck is unauthenticated."
                )
            result_values = data.get("result_values")
            if not isinstance(result_values, dict) or set(result_values) != {
                "node_numbers",
                "float_lists",
                "vector_lists",
                "time",
                "eigenmode",
                "eigenmode_frequency",
                "scalar_value_count",
            }:
                raise ValueError(
                    f"FEM result output {name!r} result data is malformed."
                )
            node_numbers = result_values["node_numbers"]
            float_lists = result_values["float_lists"]
            vector_lists = result_values["vector_lists"]
            field_errors = []
            if not isinstance(node_numbers, list):
                field_errors.append("node_numbers is not an array")
            elif any(type(value) is not int or value <= 0 for value in node_numbers):
                field_errors.append("node_numbers contains a non-positive integer")
            elif len(node_numbers) != len(set(node_numbers)):
                field_errors.append("node_numbers contains duplicates")
            if not isinstance(float_lists, dict):
                field_errors.append("float_lists is not an object")
            else:
                unexpected = sorted(set(float_lists) - set(_RESULT_FLOAT_LISTS))
                if unexpected:
                    field_errors.append(f"unexpected float fields {unexpected!r}")
            if not isinstance(vector_lists, dict):
                field_errors.append("vector_lists is not an object")
            else:
                unexpected = sorted(set(vector_lists) - set(_RESULT_VECTOR_LISTS))
                if unexpected:
                    field_errors.append(f"unexpected vector fields {unexpected!r}")
            if field_errors:
                raise ValueError(
                    f"FEM result output {name!r} contains malformed native result "
                    f"fields: {'; '.join(field_errors)}."
                )
            scalar_count = len(node_numbers)
            for field, values in float_lists.items():
                if not isinstance(values, list) or any(
                    isinstance(value, bool)
                    or not isinstance(value, (int, float))
                    or not math.isfinite(float(value))
                    for value in values
                ):
                    raise ValueError(
                        f"FEM result output {name!r} field {field!r} is malformed."
                    )
                scalar_count += len(values)
            for field, values in vector_lists.items():
                if not isinstance(values, list) or any(
                    not isinstance(vector, list)
                    or len(vector) != 3
                    or any(
                        isinstance(value, bool)
                        or not isinstance(value, (int, float))
                        or not math.isfinite(float(value))
                        for value in vector
                    )
                    for vector in values
                ):
                    raise ValueError(
                        f"FEM result output {name!r} vector field {field!r} is malformed."
                    )
                scalar_count += 3 * len(values)
            if (
                type(result_values["scalar_value_count"]) is not int
                or result_values["scalar_value_count"] != scalar_count
                or isinstance(result_values["time"], bool)
                or not isinstance(result_values["time"], (int, float))
                or not math.isfinite(float(result_values["time"]))
                or type(result_values["eigenmode"]) is not int
                or isinstance(result_values["eigenmode_frequency"], bool)
                or not isinstance(result_values["eigenmode_frequency"], (int, float))
                or not math.isfinite(float(result_values["eigenmode_frequency"]))
            ):
                raise ValueError(
                    f"FEM result output {name!r} has inconsistent result metadata."
                )
            if execution_mode == "validate_only" and scalar_count:
                raise ValueError(
                    f"FEM result output {name!r} fabricated solver values in validate-only mode."
                )
            if execution_mode == "calculix" and not node_numbers:
                raise ValueError(
                    f"FEM result output {name!r} has no solved node identifiers."
                )
            material_mapping = validate_material_mapping(
                data.get("material_mesh_mapping"),
                expected_analysis_definition,
                context=f"outputs.{name}.material_mesh_mapping",
            )
            analysis_data = next(
                item["fem_data"]
                for item in outputs
                if item["name"] == expected_analysis
            )
            if material_mapping != analysis_data.get("material_mesh_mapping"):
                raise ValueError(
                    f"FEM result output {name!r} changed the analysis material mapping."
                )
            mapping = data.get("mesh_constraint_mapping")
            if not isinstance(mapping, dict) or set(mapping) != {
                "constraint_count",
                "constraints",
            }:
                raise ValueError(
                    f"FEM result output {name!r} mesh-constraint mapping is malformed."
                )
            mapping_rows = mapping.get("constraints")
            if (
                type(mapping.get("constraint_count")) is not int
                or not isinstance(mapping_rows, list)
                or int(mapping["constraint_count"]) != len(mapping_rows)
                or len(mapping_rows)
                != len(
                    next(
                        item["fem_data"]["constraint_outputs"]
                        for item in outputs
                        if item["name"] == expected_analysis
                    )
                )
            ):
                raise ValueError(
                    f"FEM result output {name!r} mesh-constraint mapping is inconsistent."
                )
            expected_load_cases = [
                output_for_definition(
                    value,
                    "load_case",
                    context=f"outputs.{name}.analysis.load_cases[{index}]",
                )
                for index, value in enumerate(
                    expected_analysis_definition["arguments"][2]
                )
            ]
            ordered_constraints = list(
                dict.fromkeys(
                    constraint
                    for load_case in expected_load_cases
                    for constraint in expected_load_case_members[load_case]
                )
            )
            expected_kinds = [
                str(definitions[constraint]["properties"]["kind"])
                for constraint in ordered_constraints
            ]
            for index, (row, expected_kind) in enumerate(
                zip(mapping_rows, expected_kinds)
            ):
                if not isinstance(row, dict) or set(row) != {
                    "kind",
                    "node_count",
                    "mapped_area_mm2",
                    "reference_area_mm2",
                }:
                    raise ValueError(
                        f"FEM result output {name!r} mapping row {index} is malformed."
                    )
                mapped_area = row["mapped_area_mm2"]
                reference_area = row["reference_area_mm2"]
                if (
                    row["kind"] != expected_kind
                    or type(row["node_count"]) is not int
                    or row["node_count"] <= 0
                    or isinstance(mapped_area, bool)
                    or not isinstance(mapped_area, (int, float))
                    or not math.isfinite(float(mapped_area))
                    or float(mapped_area) < 0.0
                    or isinstance(reference_area, bool)
                    or not isinstance(reference_area, (int, float))
                    or not math.isfinite(float(reference_area))
                    or float(reference_area) < 0.0
                    or not math.isclose(
                        float(mapped_area),
                        float(reference_area),
                        rel_tol=0.01,
                        abs_tol=1.0e-8,
                    )
                ):
                    raise ValueError(
                        f"FEM result output {name!r} mapping row {index} is inconsistent."
                    )
            result_names.append(name)
        expected_summaries.append(
            {
                "name": name,
                "type": output_type,
                "operation": str(definition["operation"]),
                "definition_sha256": definition_sha256(definition),
                "native_type": native_type,
                "status": str(data.get("status") or "validated"),
            }
        )
    if summaries != expected_summaries:
        raise ValueError("The FEM worker validation output order is inconsistent.")
    if analysis_names != analysis_outputs or result_names != result_outputs:
        raise ValueError("The FEM worker study output order is inconsistent.")
    if (
        validation["analysis_output"]
        != (analysis_names[0] if len(analysis_names) == 1 else "")
        or validation["result_output"]
        != (result_names[0] if len(result_names) == 1 else "")
        or validation["solver_executed"] != solver_executed
    ):
        raise ValueError("The FEM worker graph summary is inconsistent.")
    owned_resources: dict[str, str] = {}
    for analysis_name in analysis_names:
        analysis_data = next(
            item["fem_data"] for item in outputs if item["name"] == analysis_name
        )
        for field in (
            "solver_output",
            "material_outputs",
            "constraint_outputs",
            "load_case_outputs",
            "mesh_output",
        ):
            values = (
                [analysis_data[field]]
                if field in {"solver_output", "mesh_output"}
                else list(analysis_data[field])
            )
            for resource_name in values:
                previous = owned_resources.get(str(resource_name))
                if previous is not None and previous != analysis_name:
                    raise ValueError(
                        f"FEM resource {resource_name!r} is shared by independent "
                        f"analyses {previous!r} and {analysis_name!r}."
                    )
                owned_resources[str(resource_name)] = analysis_name
    return dict(validation)


def _validate_cam_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    """Independently replay and authenticate one exact native CAM graph."""

    from vibescript_cam_worker import (
        VALIDATION_SCHEMA,
        _canonical_graph,
        _inflate,
        _path_summary,
        _validated_operation_selections,
        configure_cam_references,
        path_from_records,
        validate_cam_definition,
    )

    validation = execution.get("cam_validation")
    validation_fields = {
        "schema",
        "output_count",
        "outputs",
        "job_output",
        "stock_output",
        "toolpath_output",
        "tool_count",
        "operation_count",
        "collision_free",
        "postprocessor",
    }
    if not isinstance(validation, dict) or set(validation) != validation_fields:
        raise ValueError("The CAM worker returned a malformed validation summary.")
    if validation.get("schema") != VALIDATION_SCHEMA:
        raise ValueError("The CAM worker validation schema is unsupported.")
    if (
        type(validation.get("output_count")) is not int
        or int(validation["output_count"]) != len(outputs)
        or type(validation.get("tool_count")) is not int
        or int(validation["tool_count"]) < 1
        or type(validation.get("operation_count")) is not int
        or int(validation["operation_count"]) < 1
        or type(validation.get("collision_free")) is not bool
        or validation.get("postprocessor") not in {"grbl", "linuxcnc"}
    ):
        raise ValueError("The CAM worker validation verdict is inconsistent.")

    staging = Path(str(prepared["staging"])).resolve()
    worker_references = list(
        dict(prepared.get("worker_request") or {}).get("document_references") or []
    )
    resolved_references = list(prepared.get("resolved_references") or [])
    worker_by_key: dict[tuple[str, str], dict[str, Any]] = {}
    resolved_by_key: dict[tuple[str, str], dict[str, Any]] = {}
    for label, values, target in (
        ("worker", worker_references, worker_by_key),
        ("resolved", resolved_references, resolved_by_key),
    ):
        for index, raw in enumerate(values):
            if not isinstance(raw, dict):
                raise ValueError(
                    f"Prepared CAM {label} reference {index} is malformed."
                )
            key = (
                str(raw.get("document_uid") or ""),
                str(raw.get("object_name") or ""),
            )
            if not all(key) or key in target or raw.get("artifact_kind") != "brep":
                raise ValueError(f"Prepared CAM {label} references are inconsistent.")
            target[key] = raw
    if not worker_by_key or set(worker_by_key) != set(resolved_by_key):
        raise ValueError("The finalized CAM reference contract is inconsistent.")
    for key, worker_reference in worker_by_key.items():
        resolved = resolved_by_key[key]
        if (
            worker_reference.get("brep_sha256") != resolved.get("brep_sha256")
            or worker_reference.get("type_id") != resolved.get("type_id")
            or str(worker_reference.get("source_kind") or "shape")
            != str(resolved.get("source_kind") or "shape")
            or str(worker_reference.get("source_revision") or "")
            != str(resolved.get("source_revision") or "")
            or bool(worker_reference.get("transient_topology"))
            is not bool(resolved.get("transient_topology"))
        ):
            raise ValueError(
                f"Finalized CAM reference {key[1]!r} changed between host and worker contracts."
            )
        reference_path = (
            staging / str(worker_reference.get("artifact_path") or "")
        ).resolve()
        if (
            staging not in reference_path.parents
            or not reference_path.is_file()
            or reference_path.is_symlink()
            or _sha256_file(reference_path) != worker_reference.get("brep_sha256")
        ):
            raise ValueError(f"CAM input reference {key[1]!r} is unauthenticated.")

    expected_fields = {
        "job": {"name", "type", "definition", "cam_data"},
        "stock": {
            "name",
            "type",
            "definition",
            "cam_data",
            "artifact_kind",
            "artifact_path",
            "artifact_sha256",
            "artifact_bytes",
            "facts",
            "detached_shape",
        },
        "tool": {
            "name",
            "type",
            "definition",
            "cam_data",
            "artifact_kind",
            "artifact_path",
            "artifact_sha256",
            "artifact_bytes",
            "facts",
            "detached_shape",
        },
        "operation": {"name", "type", "definition", "cam_data"},
        "toolpath": {"name", "type", "definition", "cam_data"},
    }
    expected_native = {
        "job": "Path::FeaturePython",
        "stock": "Part::FeaturePython",
        "tool": "Path::FeaturePython",
        "operation": "Path::FeaturePython",
        "toolpath": "Path::Feature",
    }
    canonical_definitions: dict[str, dict[str, Any]] = {}
    definitions: dict[str, Any] = {}
    output_types: dict[str, str] = {}
    for output_index, item in enumerate(outputs):
        name = str(item.get("name") or "")
        output_type = str(item.get("type") or "")
        if (
            output_type not in expected_fields
            or set(item) != expected_fields[output_type]
        ):
            raise ValueError(f"CAM output {name!r} has malformed fields.")
        definition = validate_cam_definition(
            item.get("definition"),
            expected_output_type=output_type,
            require_domain_value=False,
            context=f"outputs.{name}.definition",
        )
        data = item.get("cam_data")
        if (
            not isinstance(data, dict)
            or data.get("native_type") != expected_native[output_type]
        ):
            raise ValueError(
                f"CAM output {name!r} has the wrong native type or no readback."
            )
        try:
            encoded = json.dumps(
                data,
                ensure_ascii=True,
                sort_keys=True,
                separators=(",", ":"),
                allow_nan=False,
            ).encode("utf-8")
        except (TypeError, ValueError) as exc:
            raise ValueError(
                f"CAM output {name!r} native readback is not bounded JSON: {exc}"
            ) from exc
        if len(encoded) > 256 * 1024 * 1024:
            raise ValueError(f"CAM output {name!r} native readback is too large.")
        item["definition"] = definition
        item["cam_data"] = data
        canonical_definitions[name] = definition
        definitions[name] = _inflate(definition)
        output_types[name] = output_type

        if output_type in {"stock", "tool"}:
            path = (staging / str(item.get("artifact_path") or "")).resolve()
            expected_artifact_path = (
                f"outputs/cam_{output_index:03d}_{output_type}.brep"
            )
            if (
                item.get("artifact_kind") != "brep"
                or item.get("artifact_path") != expected_artifact_path
                or staging not in path.parents
                or not path.is_file()
                or path.is_symlink()
                or type(item.get("artifact_bytes")) is not int
                or path.stat().st_size != int(item["artifact_bytes"])
                or _sha256_file(path) != item.get("artifact_sha256")
            ):
                raise ValueError(
                    f"CAM {output_type} output {name!r} is unauthenticated."
                )
            if item.get("detached_shape") is None:
                raise ValueError(
                    f"CAM {output_type} output {name!r} has no detached BREP."
                )
        if output_type in {"operation", "toolpath"}:
            records = data.get("path_commands")
            item["detached_path"] = path_from_records(records)

    expected_outputs = [dict(item) for item in prepared["expected_outputs"]]
    if list(definitions) != [str(item["name"]) for item in expected_outputs]:
        raise ValueError("The CAM definition graph changed output order before replay.")
    configure_cam_references(staging, worker_references)
    graph = _canonical_graph(definitions, expected_outputs)

    by_name = {str(item["name"]): item for item in outputs}

    def require_fields(value: Any, fields: set[str], *, context: str) -> dict[str, Any]:
        if not isinstance(value, dict) or set(value) != fields:
            raise ValueError(f"{context} has malformed fields.")
        return value

    def finite_number(
        value: Any,
        *,
        context: str,
        minimum: float | None = None,
    ) -> float:
        if (
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or not math.isfinite(float(value))
            or (minimum is not None and float(value) < minimum)
        ):
            raise ValueError(f"{context} is not a valid bounded number.")
        return float(value)

    def validate_bounds(
        value: Any,
        *,
        context: str,
        include_size: bool,
        allow_none: bool,
    ) -> None:
        if value is None and allow_none:
            return
        fields = {"min", "max", "size"} if include_size else {"min", "max"}
        bounds = require_fields(value, fields, context=context)
        minimum = bounds.get("min")
        maximum = bounds.get("max")
        if (
            not isinstance(minimum, list)
            or not isinstance(maximum, list)
            or len(minimum) != 3
            or len(maximum) != 3
        ):
            raise ValueError(f"{context} coordinates are malformed.")
        clean_minimum = [
            finite_number(item, context=f"{context}.min[{index}]")
            for index, item in enumerate(minimum)
        ]
        clean_maximum = [
            finite_number(item, context=f"{context}.max[{index}]")
            for index, item in enumerate(maximum)
        ]
        if any(left > right for left, right in zip(clean_minimum, clean_maximum)):
            raise ValueError(f"{context} has inverted coordinates.")
        if include_size:
            size = bounds.get("size")
            if not isinstance(size, list) or len(size) != 3:
                raise ValueError(f"{context}.size is malformed.")
            for index, item in enumerate(size):
                observed = finite_number(
                    item,
                    context=f"{context}.size[{index}]",
                    minimum=0.0,
                )
                if not math.isclose(
                    observed,
                    clean_maximum[index] - clean_minimum[index],
                    rel_tol=1.0e-9,
                    abs_tol=1.0e-8,
                ):
                    raise ValueError(f"{context}.size[{index}] is inconsistent.")

    def source_identity(value: Any, *, context: str) -> dict[str, Any]:
        if not isinstance(value, Mapping) or set(value) != {
            "document_uid",
            "object_name",
        }:
            raise ValueError(f"{context} is not an exact CAM document reference.")
        key = (str(value["document_uid"]), str(value["object_name"]))
        reference = worker_by_key.get(key)
        if reference is None:
            raise ValueError(f"{context} is not an authenticated CAM reference.")
        return {
            "document_uid": key[0],
            "object_name": key[1],
            "artifact_sha256": str(reference["brep_sha256"]),
            "source_type_id": str(reference.get("type_id") or ""),
            "source_kind": str(reference.get("source_kind") or "shape"),
            "source_revision": str(reference.get("source_revision") or ""),
        }

    job_name = str(graph["job_name"])
    stock_name = str(graph["stock_name"])
    toolpath_name = str(graph["toolpath_name"])
    tool_names = [str(item) for item in graph["tool_names"]]
    operation_names = [str(item) for item in graph["operation_names"]]

    job_definition = canonical_definitions[job_name]
    job_properties = dict(job_definition["properties"])
    job_data = require_fields(
        by_name[job_name]["cam_data"],
        {
            "native_type",
            "proxy_module",
            "proxy_class",
            "label",
            "geometry_tolerance_mm",
            "fixtures",
            "description",
            "model_references",
            "model_count",
            "operations_group_type",
            "setup_sheet_type",
            "model_group_type",
            "tools_group_type",
            "stock_output",
            "tool_outputs",
            "operation_outputs",
            "toolpath_output",
            "combined_path_summary",
        },
        context=f"outputs.{job_name}.cam_data",
    )
    expected_job = {
        "native_type": "Path::FeaturePython",
        "proxy_module": "Path.Main.Job",
        "proxy_class": "ObjectJob",
        "label": str(job_properties["label"] or "CAM Job"),
        "geometry_tolerance_mm": float(job_properties["geometry_tolerance_mm"]),
        "fixtures": list(job_properties["fixtures"]),
        "description": str(job_properties["description"]),
        "model_references": [
            source_identity(item, context=f"{job_name}.models[{index}]")
            for index, item in enumerate(job_definition["arguments"][0])
        ],
        "model_count": len(job_definition["arguments"][0]),
        "operations_group_type": "App::DocumentObjectGroup",
        "setup_sheet_type": "App::FeaturePython",
        "model_group_type": "App::DocumentObjectGroup",
        "tools_group_type": "App::DocumentObjectGroup",
        "stock_output": stock_name,
        "tool_outputs": tool_names,
        "operation_outputs": operation_names,
        "toolpath_output": toolpath_name,
        "combined_path_summary": by_name[toolpath_name]["cam_data"].get("path_summary"),
    }
    _mesh_values_match(job_data, expected_job, path=f"outputs.{job_name}.cam_data")

    stock_definition = canonical_definitions[stock_name]
    stock_properties = dict(stock_definition["properties"])
    stock_data = require_fields(
        by_name[stock_name]["cam_data"],
        {
            "native_type",
            "proxy_module",
            "proxy_class",
            "label",
            "model_references",
            "margins_mm",
            "job_output",
        },
        context=f"outputs.{stock_name}.cam_data",
    )
    expected_stock = {
        "native_type": "Part::FeaturePython",
        "proxy_module": "Path.Main.Stock",
        "proxy_class": "StockFromBase",
        "label": str(stock_properties["label"] or "Stock"),
        "model_references": [
            source_identity(item, context=f"{stock_name}.models[{index}]")
            for index, item in enumerate(stock_definition["arguments"][0])
        ],
        "margins_mm": {
            "x_negative": float(stock_properties["x_negative_mm"]),
            "x_positive": float(stock_properties["x_positive_mm"]),
            "y_negative": float(stock_properties["y_negative_mm"]),
            "y_positive": float(stock_properties["y_positive_mm"]),
            "z_negative": float(stock_properties["z_negative_mm"]),
            "z_positive": float(stock_properties["z_positive_mm"]),
        },
        "job_output": job_name,
    }
    _mesh_values_match(
        stock_data,
        expected_stock,
        path=f"outputs.{stock_name}.cam_data",
    )

    tool_proxy_classes = {
        "endmill": "ToolBitEndmill",
        "ballend": "ToolBitBallend",
        "drill": "ToolBitDrill",
        "chamfer": "ToolBitChamfer",
        "vbit": "ToolBitVBit",
    }
    shape_ids = {
        "endmill": "endmill",
        "ballend": "ballend",
        "drill": "drill",
        "chamfer": "chamfer",
        "vbit": "v-bit",
    }
    tool_output_by_key = {str(graph["keys"][name]): name for name in tool_names}
    for name in tool_names:
        definition = canonical_definitions[name]
        properties = dict(definition["properties"])
        kind = str(definition["arguments"][0])
        data = require_fields(
            by_name[name]["cam_data"],
            {
                "native_type",
                "proxy_module",
                "proxy_class",
                "tool_bit_native_type",
                "tool_bit_proxy_module",
                "tool_bit_proxy_class",
                "kind",
                "label",
                "tool_bit_label",
                "shape_id",
                "shape_type",
                "geometry",
                "controller",
                "job_output",
            },
            context=f"outputs.{name}.cam_data",
        )
        geometry = {
            "Diameter": float(properties["diameter_mm"]),
            "Length": float(properties["length_mm"]),
            "Flutes": int(properties["flutes"]),
            "SpindleDirection": (
                "Forward" if properties["spindle_direction"] == "forward" else "Reverse"
            ),
        }
        for property_name, source_name in (
            ("CuttingEdgeHeight", "cutting_edge_height_mm"),
            ("ShankDiameter", "shank_diameter_mm"),
            ("TipAngle", "tip_angle_deg"),
            ("CuttingEdgeAngle", "cutting_edge_angle_deg"),
            ("TipDiameter", "tip_diameter_mm"),
        ):
            if properties[source_name] is not None:
                geometry[property_name] = float(properties[source_name])
        expected_controller = {
            "tool_number": int(properties["tool_number"]),
            "spindle_rpm": float(properties["spindle_rpm"]),
            "spindle_direction": (
                "Forward" if properties["spindle_direction"] == "forward" else "Reverse"
            ),
            "horizontal_feed_mm_per_min": float(
                properties["horizontal_feed_mm_per_min"]
            ),
            "vertical_feed_mm_per_min": float(properties["vertical_feed_mm_per_min"]),
        }
        expected = {
            "native_type": "Path::FeaturePython",
            "proxy_module": "Path.Tool.Controller",
            "proxy_class": "ToolController",
            "tool_bit_native_type": "Part::FeaturePython",
            "tool_bit_proxy_module": data["tool_bit_proxy_module"],
            "tool_bit_proxy_class": tool_proxy_classes[kind],
            "kind": kind,
            "label": str(properties["label"] or f"Tool {properties['tool_number']}"),
            "tool_bit_label": str(
                f"{properties['label']} Tool Bit"
                if properties["label"]
                else f"{kind.title()} Tool Bit"
            ),
            "shape_id": data["shape_id"],
            "shape_type": data["shape_type"],
            "geometry": geometry,
            "controller": expected_controller,
            "job_output": job_name,
        }
        if (
            not isinstance(data["tool_bit_proxy_module"], str)
            or not data["tool_bit_proxy_module"]
            or not isinstance(data["shape_id"], str)
            or shape_ids[kind] not in data["shape_id"].lower()
            or not isinstance(data["shape_type"], str)
            or not data["shape_type"]
        ):
            raise ValueError(f"CAM tool output {name!r} has invalid native identity.")
        _mesh_values_match(data, expected, path=f"outputs.{name}.cam_data")

    operation_proxy = {
        "profile": ("Path.Op.Profile", "ObjectProfile"),
        "pocket": ("Path.Op.PocketShape", "ObjectPocket"),
        "drilling": ("Path.Op.Drilling", "ObjectDrilling"),
        "face": ("Path.Op.MillFace", "ObjectFace"),
    }
    generated_contract_properties = dict(graph["generated_definition"]["properties"])
    requested_simulation_resolution = float(
        generated_contract_properties["simulation_resolution_mm"]
    )
    operation_simulations = []
    for name in operation_names:
        definition = canonical_definitions[name]
        properties = dict(definition["properties"])
        strategy = str(definition["arguments"][0])
        data = require_fields(
            by_name[name]["cam_data"],
            {
                "native_type",
                "proxy_module",
                "proxy_class",
                "strategy",
                "label",
                "tool_output",
                "selections",
                "properties",
                "path_commands",
                "path_summary",
                "generation",
                "simulation",
                "job_output",
            },
            context=f"outputs.{name}.cam_data",
        )
        tool_key = _definition_sha256(definition["arguments"][1])
        if tool_key not in tool_output_by_key:
            raise ValueError(f"CAM operation {name!r} lost its returned tool binding.")
        _grouped, expected_selections = _validated_operation_selections(
            definition,
            output_name=name,
        )
        expected_properties = {
            "start_depth_mm": float(properties["start_depth_mm"]),
            "final_depth_mm": float(properties["final_depth_mm"]),
            "coolant": {
                "none": "None",
                "flood": "Flood",
                "mist": "Mist",
            }[str(properties["coolant"])],
        }
        if strategy in {"profile", "pocket", "face"}:
            expected_properties["step_down_mm"] = float(properties["step_down_mm"])
        if strategy in {"pocket", "face"}:
            expected_properties["step_over_percent"] = int(
                properties["step_over_percent"]
            )
        if strategy == "profile":
            expected_properties["side"] = (
                "Outside" if properties["side"] == "outside" else "Inside"
            )
        if strategy == "face":
            expected_properties["boundary"] = {
                "boundbox": "Boundbox",
                "stock": "Stock",
                "perimeter": "Perimeter",
            }[str(properties["boundary"])]
        if strategy == "drilling":
            expected_properties["peck_depth_mm"] = float(properties["peck_depth_mm"])
            expected_properties["peck_enabled"] = (
                float(properties["peck_depth_mm"]) > 0.0
            )
        expected_operation = {
            "native_type": "Path::FeaturePython",
            "proxy_module": operation_proxy[strategy][0],
            "proxy_class": operation_proxy[strategy][1],
            "strategy": strategy,
            "label": str(properties["label"] or f"{strategy.title()} Operation"),
            "tool_output": tool_output_by_key[tool_key],
            "selections": expected_selections,
            "properties": expected_properties,
            "path_commands": data["path_commands"],
            "path_summary": _path_summary(data["path_commands"]),
            "generation": data["generation"],
            "simulation": data["simulation"],
            "job_output": job_name,
        }
        generation = data["generation"]
        if not isinstance(generation, dict) or generation.get("status") != "succeeded":
            raise ValueError(f"CAM operation {name!r} did not report native success.")
        simulation = require_fields(
            data["simulation"],
            {
                "complete",
                "stage",
                "error",
                "simulation_scope",
                "command_count",
                "executed_sweeps",
                "cutting_sweeps",
                "unsupported_commands",
                "stock",
                "collision",
            },
            context=f"outputs.{name}.cam_data.simulation",
        )
        collision = simulation.get("collision")
        if (
            simulation.get("complete") is not True
            or simulation.get("stage") != "complete"
            or simulation.get("error") is not None
            or simulation.get("simulation_scope")
            != "single_operation_against_initial_job_stock"
            or simulation.get("command_count") != len(data["path_commands"])
            or type(simulation.get("executed_sweeps")) is not int
            or type(simulation.get("cutting_sweeps")) is not int
            or int(simulation["cutting_sweeps"]) <= 0
            or int(simulation["executed_sweeps"]) < int(simulation["cutting_sweeps"])
            or int(simulation["executed_sweeps"]) > 4 * int(simulation["command_count"])
            or simulation.get("unsupported_commands") != []
            or not isinstance(collision, dict)
            or type(collision.get("protected_model_collision")) is not bool
            or collision.get("protected_model_checked") is not True
        ):
            raise ValueError(f"CAM operation {name!r} has malformed simulation facts.")
        stock_simulation = require_fields(
            simulation.get("stock"),
            {
                "object",
                "method",
                "volume_method",
                "endpoint_tolerance_mm",
                "resolution_mm",
                "grid",
                "initial_volume_mm3",
                "removed_volume_mm3",
                "remaining_volume_mm3",
                "modified_cells",
                "cut_commands",
                "rapid_commands",
                "unsupported_commands",
                "removed_bounds",
            },
            context=f"outputs.{name}.cam_data.simulation.stock",
        )
        grid = stock_simulation.get("grid")
        if (
            not isinstance(stock_simulation.get("object"), str)
            or not stock_simulation["object"]
            or stock_simulation.get("method") != "PathSimulator height field"
            or stock_simulation.get("volume_method") != "height_field_cell_quadrature"
            or not isinstance(grid, list)
            or len(grid) != 2
            or any(type(item) is not int or item < 1 for item in grid)
            or int(grid[0]) * int(grid[1]) > 4_000_000
            or type(stock_simulation.get("modified_cells")) is not int
            or not 0
            <= int(stock_simulation["modified_cells"])
            <= int(grid[0]) * int(grid[1])
            or type(stock_simulation.get("cut_commands")) is not int
            or int(stock_simulation["cut_commands"])
            != int(simulation["cutting_sweeps"])
            or type(stock_simulation.get("rapid_commands")) is not int
            or int(stock_simulation["rapid_commands"]) < 0
            or stock_simulation.get("unsupported_commands") != 0
        ):
            raise ValueError(
                f"CAM operation {name!r} native stock simulation is inconsistent."
            )
        endpoint_tolerance = finite_number(
            stock_simulation["endpoint_tolerance_mm"],
            context=f"outputs.{name}.simulation.stock.endpoint_tolerance_mm",
            minimum=0.0,
        )
        resolution = finite_number(
            stock_simulation["resolution_mm"],
            context=f"outputs.{name}.simulation.stock.resolution_mm",
            minimum=0.0,
        )
        if endpoint_tolerance <= 0.0 or not math.isclose(
            resolution,
            requested_simulation_resolution,
            rel_tol=1.0e-6,
            abs_tol=1.0e-7,
        ):
            raise ValueError(
                f"CAM operation {name!r} changed its simulation resolution."
            )
        initial_volume = finite_number(
            stock_simulation["initial_volume_mm3"],
            context=f"outputs.{name}.simulation.stock.initial_volume_mm3",
            minimum=0.0,
        )
        removed_volume = finite_number(
            stock_simulation["removed_volume_mm3"],
            context=f"outputs.{name}.simulation.stock.removed_volume_mm3",
            minimum=0.0,
        )
        remaining_volume = finite_number(
            stock_simulation["remaining_volume_mm3"],
            context=f"outputs.{name}.simulation.stock.remaining_volume_mm3",
            minimum=0.0,
        )
        if initial_volume <= 0.0 or not math.isclose(
            initial_volume,
            removed_volume + remaining_volume,
            rel_tol=1.0e-6,
            abs_tol=max(1.0e-7, requested_simulation_resolution**3),
        ):
            raise ValueError(
                f"CAM operation {name!r} stock-volume accounting is inconsistent."
            )
        validate_bounds(
            stock_simulation.get("removed_bounds"),
            context=f"outputs.{name}.simulation.stock.removed_bounds",
            include_size=False,
            allow_none=True,
        )
        collision = require_fields(
            collision,
            {
                "protected_model_checked",
                "method",
                "volume_tolerance_mm3",
                "protected_model_collision",
                "protected_model_volume_mm3",
                "protected_model_volume_aggregation",
                "protected_model_aggregation_warning",
                "protected_model_bounds",
                "commands",
                "holder_checked",
                "fixture_checked",
                "unavailable_checks",
            },
            context=f"outputs.{name}.cam_data.simulation.collision",
        )
        collision_tolerance = finite_number(
            collision["volume_tolerance_mm3"],
            context=f"outputs.{name}.simulation.collision.volume_tolerance_mm3",
            minimum=0.0,
        )
        collision_volume = finite_number(
            collision["protected_model_volume_mm3"],
            context=f"outputs.{name}.simulation.collision.protected_model_volume_mm3",
            minimum=0.0,
        )
        collision_commands = collision.get("commands")
        if (
            collision.get("method") != "OpenCascade cutter-sweep intersection"
            or collision.get("protected_model_collision")
            is not (collision_volume > collision_tolerance)
            or collision.get("protected_model_volume_aggregation")
            not in {"none", "occ_union", "per_command_sum_conservative"}
            or not isinstance(collision.get("protected_model_aggregation_warning"), str)
            or not isinstance(collision_commands, list)
            or len(collision_commands) > 4 * int(simulation["command_count"])
            or collision.get("holder_checked") is not False
            or collision.get("fixture_checked") is not False
            or collision.get("unavailable_checks")
            != [
                "holder collision: the job has no holder shape",
                "fixture collision: the job has no fixture shapes",
            ]
        ):
            raise ValueError(
                f"CAM operation {name!r} collision evidence is inconsistent."
            )
        for collision_index, row in enumerate(collision_commands):
            row = require_fields(
                row,
                {
                    "command_index",
                    "command",
                    "rapid",
                    "protected_model_volume_mm3",
                    "bounds",
                },
                context=(
                    f"outputs.{name}.simulation.collision.commands[{collision_index}]"
                ),
            )
            if (
                type(row.get("command_index")) is not int
                or not 0 <= int(row["command_index"]) < len(data["path_commands"])
                or not isinstance(row.get("command"), str)
                or not row["command"]
                or type(row.get("rapid")) is not bool
                or finite_number(
                    row.get("protected_model_volume_mm3"),
                    context=(
                        f"outputs.{name}.simulation.collision.commands"
                        f"[{collision_index}].protected_model_volume_mm3"
                    ),
                    minimum=0.0,
                )
                <= collision_tolerance
            ):
                raise ValueError(
                    f"CAM operation {name!r} collision row {collision_index} is invalid."
                )
            validate_bounds(
                row.get("bounds"),
                context=(
                    f"outputs.{name}.simulation.collision.commands[{collision_index}].bounds"
                ),
                include_size=True,
                allow_none=False,
            )
        collision_verdict = bool(collision["protected_model_collision"])
        if collision_verdict != bool(collision_commands):
            raise ValueError(
                f"CAM operation {name!r} collision rows disagree with its verdict."
            )
        validate_bounds(
            collision.get("protected_model_bounds"),
            context=f"outputs.{name}.simulation.collision.protected_model_bounds",
            include_size=True,
            allow_none=not collision_verdict,
        )
        _mesh_values_match(
            data,
            expected_operation,
            path=f"outputs.{name}.cam_data",
        )
        operation_simulations.append(
            {
                "operation_output": name,
                "complete": True,
                "protected_model_collision": bool(
                    collision["protected_model_collision"]
                ),
            }
        )

    toolpath_definition = canonical_definitions[toolpath_name]
    generated_definition = dict(toolpath_definition["arguments"][0])
    generated_properties = dict(generated_definition["properties"])
    post_properties = dict(toolpath_definition["properties"])
    toolpath_data = require_fields(
        by_name[toolpath_name]["cam_data"],
        {
            "native_type",
            "label",
            "job_output",
            "stock_output",
            "operation_outputs",
            "path_commands",
            "path_summary",
            "simulation_resolution_mm",
            "require_collision_free",
            "collision_free",
            "simulations",
            "postprocess",
        },
        context=f"outputs.{toolpath_name}.cam_data",
    )
    collision_free = all(
        item["protected_model_collision"] is False for item in operation_simulations
    )
    if bool(generated_properties["require_collision_free"]) and not collision_free:
        raise ValueError(
            "The CAM worker accepted protected-model collision despite the required guard."
        )
    expected_toolpath = {
        "native_type": "Path::Feature",
        "label": "Validated CAM Toolpath",
        "job_output": job_name,
        "stock_output": stock_name,
        "operation_outputs": operation_names,
        "path_commands": toolpath_data["path_commands"],
        "path_summary": _path_summary(toolpath_data["path_commands"]),
        "simulation_resolution_mm": float(
            generated_properties["simulation_resolution_mm"]
        ),
        "require_collision_free": bool(generated_properties["require_collision_free"]),
        "collision_free": collision_free,
        "simulations": operation_simulations,
        "postprocess": toolpath_data["postprocess"],
    }
    _mesh_values_match(
        toolpath_data,
        expected_toolpath,
        path=f"outputs.{toolpath_name}.cam_data",
    )

    expected_summaries = [
        {
            "name": str(item["name"]),
            "type": str(item["type"]),
            "operation": str(canonical_definitions[str(item["name"])]["operation"]),
            "definition_sha256": str(graph["keys"][str(item["name"])]),
            "native_state_sha256": _definition_sha256(
                by_name[str(item["name"])]["cam_data"]
            ),
            "artifact_sha256": str(
                by_name[str(item["name"])].get("artifact_sha256") or ""
            ),
            "native_type": str(by_name[str(item["name"])]["cam_data"]["native_type"]),
            "status": "validated",
        }
        for item in expected_outputs
    ]
    expected_validation = {
        "schema": VALIDATION_SCHEMA,
        "output_count": len(outputs),
        "outputs": expected_summaries,
        "job_output": job_name,
        "stock_output": stock_name,
        "toolpath_output": toolpath_name,
        "tool_count": len(tool_names),
        "operation_count": len(operation_names),
        "collision_free": collision_free,
        "postprocessor": str(post_properties["processor"]),
    }
    _mesh_values_match(validation, expected_validation, path="cam_validation")

    postprocess = toolpath_data.get("postprocess")
    post_fields = {
        "artifact_kind",
        "artifact_path",
        "artifact_sha256",
        "artifact_bytes",
        "line_count",
        "processor",
        "processor_module",
        "processor_class",
        "units",
        "comments",
        "line_numbers",
        "arguments",
        "sections",
        "machine_configured",
        "machine_name",
        "machine_limits_checked",
        "configuration_scope",
    }
    if not isinstance(postprocess, dict) or set(postprocess) != post_fields:
        raise ValueError("The CAM postprocessed artifact descriptor is malformed.")
    post_path = (staging / str(postprocess.get("artifact_path") or "")).resolve()
    toolpath_index = next(
        index
        for index, item in enumerate(expected_outputs)
        if item["name"] == toolpath_name
    )
    expected_arguments = [
        "--no-show-editor",
        "--no-header",
        "--metric" if post_properties["units"] == "metric" else "--inches",
        "--comments" if post_properties["comments"] else "--no-comments",
        "--line-numbers" if post_properties["line_numbers"] else "--no-line-numbers",
    ]
    expected_processor_class = {
        "grbl": "Grbl",
        "linuxcnc": "Linuxcnc",
    }[str(post_properties["processor"])]
    if (
        postprocess.get("artifact_kind") != "gcode"
        or postprocess.get("artifact_path")
        != f"outputs/cam_{toolpath_index:03d}_toolpath.nc"
        or staging not in post_path.parents
        or not post_path.is_file()
        or post_path.is_symlink()
        or type(postprocess.get("artifact_bytes")) is not int
        or post_path.stat().st_size != int(postprocess["artifact_bytes"])
        or _sha256_file(post_path) != postprocess.get("artifact_sha256")
        or postprocess.get("processor") != post_properties["processor"]
        or postprocess.get("processor_module") != f"{post_properties['processor']}_post"
        or postprocess.get("processor_class") != expected_processor_class
        or postprocess.get("units") != post_properties["units"]
        or postprocess.get("comments") is not post_properties["comments"]
        or postprocess.get("line_numbers") is not post_properties["line_numbers"]
        or postprocess.get("arguments") != expected_arguments
        or postprocess.get("machine_configured") is not False
        or postprocess.get("machine_name") != ""
        or postprocess.get("machine_limits_checked") is not False
        or postprocess.get("configuration_scope") != "generic_postprocessor_defaults"
    ):
        raise ValueError("The CAM postprocessed artifact is unauthenticated.")
    sections = postprocess.get("sections")
    if not isinstance(sections, list) or not sections:
        raise ValueError("The CAM postprocessed artifact has no native sections.")
    section_bytes = 0
    for index, section in enumerate(sections):
        if (
            not isinstance(section, dict)
            or set(section) != {"name", "bytes", "sha256"}
            or not isinstance(section.get("name"), str)
            or not section["name"]
            or "\0" in section["name"]
            or type(section.get("bytes")) is not int
            or not 1 <= int(section["bytes"]) <= int(postprocess["artifact_bytes"])
            or not isinstance(section.get("sha256"), str)
            or re.fullmatch(r"[0-9a-f]{64}", section["sha256"]) is None
        ):
            raise ValueError(f"CAM postprocessor section {index} is malformed.")
        section_bytes += int(section["bytes"])
    if (
        not section_bytes
        <= int(postprocess["artifact_bytes"])
        <= (section_bytes + len(sections))
    ):
        raise ValueError("The CAM postprocessor section sizes are inconsistent.")
    try:
        gcode = post_path.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        raise ValueError(
            f"The CAM postprocessed artifact is not UTF-8 text: {exc}"
        ) from exc
    if (
        "\0" in gcode
        or type(postprocess.get("line_count")) is not int
        or not 1 <= int(postprocess["line_count"]) <= 5_000_000
        or len(gcode.splitlines()) != postprocess["line_count"]
    ):
        raise ValueError("The CAM postprocessed artifact text contract changed.")
    return dict(validation)


def _techdraw_finite_vector(value: Any, *, path: str) -> list[float]:
    if not isinstance(value, list) or len(value) != 3:
        raise ValueError(f"{path} must contain exactly three coordinates.")
    result = []
    for index, item in enumerate(value):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise ValueError(f"{path}[{index}] must be a number.")
        clean = float(item)
        if not math.isfinite(clean):
            raise ValueError(f"{path}[{index}] must be finite.")
        result.append(clean)
    return result


def _techdraw_projection_artifact(
    staging: Path,
    descriptor: Any,
    *,
    expected_path: str,
    expected_count: int,
    topology: str,
    path: str,
) -> tuple[Any, dict[str, Any]]:
    import Part

    fields = {
        "artifact_kind",
        "artifact_path",
        "artifact_sha256",
        "artifact_bytes",
        "shape_type",
    }
    if not isinstance(descriptor, dict) or set(descriptor) != fields:
        raise ValueError(f"{path} has malformed artifact fields.")
    relative = str(descriptor.get("artifact_path") or "")
    artifact = (staging / relative).resolve()
    digest = str(descriptor.get("artifact_sha256") or "")
    if (
        descriptor.get("artifact_kind") != "brep"
        or relative != expected_path
        or descriptor.get("shape_type") != "Compound"
        or staging not in artifact.parents
        or not artifact.is_file()
        or artifact.is_symlink()
        or type(descriptor.get("artifact_bytes")) is not int
        or not 1 <= int(descriptor["artifact_bytes"]) <= 256 * 1024 * 1024
        or artifact.stat().st_size != int(descriptor["artifact_bytes"])
        or re.fullmatch(r"[0-9a-f]{64}", digest) is None
        or _sha256_file(artifact) != digest
    ):
        raise ValueError(f"{path} is not an authenticated TechDraw BREP.")
    shape = Part.Shape()
    shape.importBrep(str(artifact))
    if shape.isNull() or not shape.isValid() or str(shape.ShapeType) != "Compound":
        raise ValueError(f"{path} is not a valid compound BREP.")
    count = len(shape.Edges) if topology == "edges" else len(shape.Faces)
    if count != expected_count:
        raise ValueError(
            f"{path} changed {topology} count during transfer: "
            f"worker={expected_count}, detached={count}."
        )
    sanitized = {
        "artifact_kind": "brep",
        "artifact_sha256": digest,
        "artifact_bytes": int(descriptor["artifact_bytes"]),
        "shape_type": "Compound",
    }
    return shape, sanitized


def _techdraw_descriptor_number(
    value: Any,
    *,
    path: str,
    minimum: float = -1.0e12,
    maximum: float = 1.0e12,
) -> float:
    if (
        isinstance(value, bool)
        or not isinstance(value, (int, float))
        or not math.isfinite(float(value))
        or not minimum <= float(value) <= maximum
    ):
        raise ValueError(
            f"{path} must be a finite number from {minimum:g} to {maximum:g}."
        )
    return float(value)


def _techdraw_descriptor_point(value: Any, *, path: str) -> dict[str, float]:
    if not isinstance(value, dict) or set(value) != {"x", "y"}:
        raise ValueError(f"{path} must contain exactly finite x and y coordinates.")
    return {
        "x": _techdraw_descriptor_number(value["x"], path=f"{path}.x"),
        "y": _techdraw_descriptor_number(value["y"], path=f"{path}.y"),
    }


def _techdraw_descriptor_mapping(value: Any, *, path: str) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != {"status", "candidates"}:
        raise ValueError(f"{path} has malformed projected-source mapping fields.")
    status = value.get("status")
    if status not in {
        "exact",
        "ambiguous",
        "generated_projection",
        "generated_center",
        "unmapped",
    }:
        raise ValueError(f"{path}.status is unsupported.")
    raw_candidates = value.get("candidates")
    if not isinstance(raw_candidates, list) or len(raw_candidates) > 128:
        raise ValueError(f"{path}.candidates is not a bounded array.")
    candidates = []
    for index, raw in enumerate(raw_candidates):
        candidate_path = f"{path}.candidates[{index}]"
        if not isinstance(raw, dict) or set(raw) != {"object_name", "subelement"}:
            raise ValueError(f"{candidate_path} has malformed fields.")
        object_name = raw.get("object_name")
        subelement = raw.get("subelement")
        if (
            not isinstance(object_name, str)
            or not object_name
            or len(object_name) > 128
            or "\0" in object_name
            or not isinstance(subelement, str)
            or re.fullmatch(r"(?:Edge|Vertex)[1-9][0-9]*", subelement) is None
        ):
            raise ValueError(f"{candidate_path} is not an exact source subelement.")
        candidates.append({"object_name": object_name, "subelement": subelement})
    if (
        (status == "exact" and len(candidates) != 1)
        or (status == "ambiguous" and len(candidates) < 2)
        or (status not in {"exact", "ambiguous"} and candidates)
    ):
        raise ValueError(f"{path} status/candidate cardinality is inconsistent.")
    return {"status": str(status), "candidates": candidates}


def _techdraw_validate_edge_descriptor(
    value: Any,
    *,
    index: int,
    edge_class: int,
    visible: bool,
    source_index: int,
    path: str,
) -> dict[str, Any]:
    required = {
        "name",
        "element_type",
        "geometry_type",
        "edge_class",
        "visible",
        "closed",
        "length_view_mm",
        "bounds_2d",
        "start_2d",
        "end_2d",
        "midpoint_2d",
        "hlr_source_index",
        "source_mapping",
    }
    optional = {"center_2d", "radius_view_mm"}
    if (
        not isinstance(value, dict)
        or not required <= set(value)
        or set(value) - required - optional
    ):
        raise ValueError(f"{path} has malformed projected-edge fields.")
    geometry_type = value.get("geometry_type")
    if geometry_type not in {
        "NotDefined",
        "Circle",
        "ArcOfCircle",
        "Ellipse",
        "ArcOfEllipse",
        "Bezier",
        "BSpline",
        "Line",
    }:
        raise ValueError(f"{path}.geometry_type is unsupported.")
    class_names = {
        0: "none",
        1: "iso",
        2: "outline",
        3: "smooth",
        4: "seam",
        5: "hard",
    }
    if (
        value.get("name") != f"Edge{index}"
        or value.get("element_type") != "edge"
        or value.get("edge_class") != class_names.get(edge_class)
        or type(value.get("visible")) is not bool
        or bool(value["visible"]) is not visible
        or type(value.get("closed")) is not bool
        or type(value.get("hlr_source_index")) is not int
        or int(value["hlr_source_index"]) != source_index
    ):
        raise ValueError(f"{path} disagrees with aligned native edge metadata.")
    clean = dict(value)
    clean["length_view_mm"] = _techdraw_descriptor_number(
        value["length_view_mm"],
        path=f"{path}.length_view_mm",
        minimum=0.0,
    )
    bounds = value.get("bounds_2d")
    bound_fields = {"min_x", "min_y", "max_x", "max_y", "width", "height"}
    if not isinstance(bounds, dict) or set(bounds) != bound_fields:
        raise ValueError(f"{path}.bounds_2d has malformed fields.")
    clean_bounds = {
        name: _techdraw_descriptor_number(
            bounds[name],
            path=f"{path}.bounds_2d.{name}",
            minimum=0.0 if name in {"width", "height"} else -1.0e12,
        )
        for name in bound_fields
    }
    if not (
        math.isclose(
            clean_bounds["max_x"] - clean_bounds["min_x"],
            clean_bounds["width"],
            rel_tol=1.0e-9,
            abs_tol=1.0e-7,
        )
        and math.isclose(
            clean_bounds["max_y"] - clean_bounds["min_y"],
            clean_bounds["height"],
            rel_tol=1.0e-9,
            abs_tol=1.0e-7,
        )
    ):
        raise ValueError(f"{path}.bounds_2d extents are inconsistent.")
    clean["bounds_2d"] = clean_bounds
    for field in ("start_2d", "end_2d", "midpoint_2d"):
        clean[field] = _techdraw_descriptor_point(value[field], path=f"{path}.{field}")
    clean["source_mapping"] = _techdraw_descriptor_mapping(
        value["source_mapping"], path=f"{path}.source_mapping"
    )
    if "center_2d" in value:
        clean["center_2d"] = _techdraw_descriptor_point(
            value["center_2d"], path=f"{path}.center_2d"
        )
    if "radius_view_mm" in value:
        clean["radius_view_mm"] = _techdraw_descriptor_number(
            value["radius_view_mm"],
            path=f"{path}.radius_view_mm",
            minimum=0.0,
        )
    if ("center_2d" in value) is not ("radius_view_mm" in value):
        raise ValueError(f"{path} must report circle center and radius together.")
    return clean


def _techdraw_validate_vertex_descriptor(
    value: Any,
    *,
    index: int,
    path: str,
) -> dict[str, Any]:
    fields = {
        "name",
        "element_type",
        "point_2d",
        "visible",
        "is_center",
        "is_reference",
        "source_mapping",
    }
    if (
        not isinstance(value, dict)
        or set(value) != fields
        or value.get("name") != f"Vertex{index}"
        or value.get("element_type") != "vertex"
        or any(
            type(value.get(name)) is not bool
            for name in ("visible", "is_center", "is_reference")
        )
    ):
        raise ValueError(f"{path} has malformed projected-vertex fields.")
    clean = dict(value)
    clean["point_2d"] = _techdraw_descriptor_point(
        value["point_2d"], path=f"{path}.point_2d"
    )
    clean["source_mapping"] = _techdraw_descriptor_mapping(
        value["source_mapping"], path=f"{path}.source_mapping"
    )
    return clean


def _techdraw_projection_state(
    staging: Path,
    data: Any,
    *,
    expected_prefix: str,
    path: str,
) -> tuple[dict[str, Any], dict[str, Any]]:
    from vibescript_techdraw_worker import PROJECTION_SCHEMA

    fields = {
        "schema",
        "native_type",
        "direction",
        "x_direction",
        "position_mm",
        "scale",
        "edge_count",
        "face_count",
        "vertex_count",
        "bounds_2d",
        "edge_classes",
        "edge_visibility",
        "source_indices",
        "centroid",
        "descriptors",
        "source_identities",
        "edges_artifact",
        "faces_artifact",
    }
    if not isinstance(data, dict) or set(data) != fields:
        raise ValueError(f"{path} has malformed projection fields.")
    if data.get("schema") != PROJECTION_SCHEMA or data.get("native_type") not in {
        "TechDraw::DrawViewPart",
        "TechDraw::DrawProjGroupItem",
    }:
        raise ValueError(f"{path} has an unsupported projection contract.")
    for count_field, maximum in (
        ("edge_count", 200_000),
        ("face_count", 50_000),
        ("vertex_count", 250_000),
    ):
        value = data.get(count_field)
        minimum = 1 if count_field == "edge_count" else 0
        if type(value) is not int or not minimum <= int(value) <= maximum:
            raise ValueError(f"{path}.{count_field} is outside its bounded range.")
    edge_count = int(data["edge_count"])
    face_count = int(data["face_count"])
    classes = data.get("edge_classes")
    visibility = data.get("edge_visibility")
    source_indices = data.get("source_indices")
    if (
        not isinstance(classes, list)
        or not isinstance(visibility, list)
        or not isinstance(source_indices, list)
        or not len(classes) == len(visibility) == len(source_indices) == edge_count
        or any(type(value) is not int or not 0 <= value <= 255 for value in classes)
        or any(type(value) is not bool for value in visibility)
        or any(type(value) is not int or value < 0 for value in source_indices)
    ):
        raise ValueError(f"{path} edge metadata is not aligned or bounded.")
    descriptors = data.get("descriptors")
    if not isinstance(descriptors, dict) or set(descriptors) != {
        "coordinate_space",
        "view_scale",
        "edges",
        "vertices",
    }:
        raise ValueError(f"{path}.descriptors has malformed fields.")
    descriptor_edges = descriptors.get("edges")
    descriptor_vertices = descriptors.get("vertices")
    if (
        descriptors.get("coordinate_space") != "view_projection_scaled_centered"
        or not isinstance(descriptor_edges, list)
        or len(descriptor_edges) != edge_count
        or not isinstance(descriptor_vertices, list)
        or len(descriptor_vertices) != int(data["vertex_count"])
    ):
        raise ValueError(f"{path}.descriptors is inconsistent with native counts.")
    descriptor_scale = _techdraw_descriptor_number(
        descriptors.get("view_scale"),
        path=f"{path}.descriptors.view_scale",
        minimum=1.0e-12,
        maximum=1.0e6,
    )
    clean_descriptor_edges = [
        _techdraw_validate_edge_descriptor(
            descriptor,
            index=index,
            edge_class=int(classes[index]),
            visible=bool(visibility[index]),
            source_index=int(source_indices[index]),
            path=f"{path}.descriptors.edges[{index}]",
        )
        for index, descriptor in enumerate(descriptor_edges)
    ]
    clean_descriptor_vertices = [
        _techdraw_validate_vertex_descriptor(
            descriptor,
            index=index,
            path=f"{path}.descriptors.vertices[{index}]",
        )
        for index, descriptor in enumerate(descriptor_vertices)
    ]
    direction = _techdraw_finite_vector(data["direction"], path=f"{path}.direction")
    x_direction = _techdraw_finite_vector(
        data["x_direction"], path=f"{path}.x_direction"
    )
    centroid = _techdraw_finite_vector(data["centroid"], path=f"{path}.centroid")
    position = data.get("position_mm")
    if (
        not isinstance(position, list)
        or len(position) != 2
        or any(
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or not math.isfinite(float(value))
            for value in position
        )
        or isinstance(data.get("scale"), bool)
        or not isinstance(data.get("scale"), (int, float))
        or not 0.0 < float(data["scale"]) <= 1.0e6
        or not math.isclose(
            descriptor_scale,
            float(data["scale"]),
            rel_tol=1.0e-9,
            abs_tol=1.0e-12,
        )
    ):
        raise ValueError(f"{path} position/scale readback is invalid.")
    raw_bounds = data.get("bounds_2d")
    if not isinstance(raw_bounds, dict) or set(raw_bounds) != {"min", "max", "size"}:
        raise ValueError(f"{path}.bounds_2d has malformed fields.")
    bounds = {}
    for name in ("min", "max", "size"):
        values = raw_bounds[name]
        if not isinstance(values, list) or len(values) != 2:
            raise ValueError(f"{path}.bounds_2d.{name} must contain two coordinates.")
        bounds[name] = [
            _techdraw_descriptor_number(
                item,
                path=f"{path}.bounds_2d.{name}[{index}]",
                minimum=0.0 if name == "size" else -1.0e12,
            )
            for index, item in enumerate(values)
        ]
    if any(
        not math.isclose(
            bounds["max"][index] - bounds["min"][index],
            bounds["size"][index],
            rel_tol=1.0e-9,
            abs_tol=1.0e-7,
        )
        for index in range(2)
    ):
        raise ValueError(f"{path}.bounds_2d extents are inconsistent.")
    edges, edges_artifact = _techdraw_projection_artifact(
        staging,
        data["edges_artifact"],
        expected_path=f"{expected_prefix}-edges.brep",
        expected_count=edge_count,
        topology="edges",
        path=f"{path}.edges_artifact",
    )
    faces, faces_artifact = _techdraw_projection_artifact(
        staging,
        data["faces_artifact"],
        expected_path=f"{expected_prefix}-faces.brep",
        expected_count=face_count,
        topology="faces",
        path=f"{path}.faces_artifact",
    )
    import FreeCAD as App

    detached = {
        "edges": edges,
        "faces": faces,
        "edge_classes": list(classes),
        "edge_visibility": list(visibility),
        "source_indices": list(source_indices),
        "centroid": App.Vector(*centroid),
    }
    sanitized = dict(data)
    sanitized["direction"] = direction
    sanitized["x_direction"] = x_direction
    sanitized["centroid"] = centroid
    sanitized["bounds_2d"] = bounds
    sanitized["descriptors"] = {
        "coordinate_space": "view_projection_scaled_centered",
        "view_scale": descriptor_scale,
        "edges": clean_descriptor_edges,
        "vertices": clean_descriptor_vertices,
    }
    sanitized["edges_artifact"] = edges_artifact
    sanitized["faces_artifact"] = faces_artifact
    return detached, sanitized


def _validate_techdraw_execution(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
    outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    """Authenticate worker-precomputed TechDraw state without regenerating it."""

    from vibescript_techdraw_worker import (
        DIMENSION_SCHEMA,
        VALIDATION_SCHEMA,
        _VIEW_DIRECTIONS,
        _definition_key,
        _inflate,
        _sheet_geometry,
        _validate_graph,
        validate_techdraw_definition,
    )

    validation = execution.get("techdraw_validation")
    if not isinstance(validation, dict) or set(validation) != {
        "schema",
        "output_count",
        "outputs",
    }:
        raise ValueError("The TechDraw worker returned a malformed validation summary.")
    if validation.get("schema") != VALIDATION_SCHEMA:
        raise ValueError("The TechDraw worker validation schema is unsupported.")
    summaries = validation.get("outputs")
    if (
        type(validation.get("output_count")) is not int
        or int(validation["output_count"]) != len(outputs)
        or not isinstance(summaries, list)
        or len(summaries) != len(outputs)
    ):
        raise ValueError("The TechDraw worker validation output count is inconsistent.")

    staging = Path(str(prepared["staging"])).resolve()
    worker_references = list(
        dict(prepared.get("worker_request") or {}).get("document_references") or []
    )
    resolved_references = list(prepared.get("resolved_references") or [])
    worker_by_key: dict[tuple[str, str], dict[str, Any]] = {}
    resolved_by_key: dict[tuple[str, str], dict[str, Any]] = {}
    for label, values, target in (
        ("worker", worker_references, worker_by_key),
        ("resolved", resolved_references, resolved_by_key),
    ):
        for index, raw in enumerate(values):
            if not isinstance(raw, dict):
                raise ValueError(
                    f"Prepared TechDraw {label} reference {index} is malformed."
                )
            key = (
                str(raw.get("document_uid") or ""),
                str(raw.get("object_name") or ""),
            )
            if not all(key) or key in target or raw.get("artifact_kind") != "brep":
                raise ValueError(
                    f"Prepared TechDraw {label} references are inconsistent."
                )
            target[key] = raw
    if not worker_by_key or set(worker_by_key) != set(resolved_by_key):
        raise ValueError("The finalized TechDraw reference contract is inconsistent.")
    for key, worker_reference in worker_by_key.items():
        resolved = resolved_by_key[key]
        reference_path = (
            staging / str(worker_reference.get("artifact_path") or "")
        ).resolve()
        if (
            worker_reference.get("brep_sha256") != resolved.get("brep_sha256")
            or worker_reference.get("type_id") != resolved.get("type_id")
            or staging not in reference_path.parents
            or not reference_path.is_file()
            or reference_path.is_symlink()
            or _sha256_file(reference_path) != worker_reference.get("brep_sha256")
        ):
            raise ValueError(f"TechDraw input reference {key[1]!r} is unauthenticated.")

    expected_outputs = [dict(item) for item in prepared["expected_outputs"]]
    definitions: dict[str, dict[str, Any]] = {}
    raw_graph: dict[str, Any] = {}
    expected_native = {
        "page": "TechDraw::DrawPage",
        "template": "TechDraw::DrawTemplate",
        "view": "TechDraw::DrawViewPart",
        "projection": "TechDraw::DrawProjGroup",
        "dimension": "TechDraw::DrawViewDimension",
        "annotation": "TechDraw::DrawViewAnnotation",
    }
    expected_summaries = []
    by_name: dict[str, dict[str, Any]] = {}
    for item, expected in zip(outputs, expected_outputs):
        name = str(expected["name"])
        output_type = str(expected["type"])
        if set(item) != {"name", "type", "definition", "techdraw_data"}:
            raise ValueError(f"TechDraw output {name!r} has undeclared worker fields.")
        definition = validate_techdraw_definition(
            item.get("definition"),
            expected_output_type=output_type,
            require_domain_value=False,
            context=f"outputs.{name}.definition",
        )
        data = item.get("techdraw_data")
        if (
            not isinstance(data, dict)
            or data.get("operation") != definition["operation"]
            or data.get("native_type") != expected_native[output_type]
        ):
            raise ValueError(
                f"TechDraw output {name!r} has no valid native operation readback."
            )
        encoded = json.dumps(
            data,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
        if len(encoded) > 64 * 1024 * 1024:
            raise ValueError(f"TechDraw output {name!r} readback is too large.")
        item["definition"] = definition
        definitions[name] = definition
        raw_graph[name] = _inflate(definition)
        by_name[name] = item
        expected_summaries.append(
            {
                "name": name,
                "type": output_type,
                "operation": str(definition["operation"]),
                "definition_sha256": _definition_key(definition),
                "native_type": expected_native[output_type],
            }
        )
    if summaries != expected_summaries:
        raise ValueError("The TechDraw worker validation summary is inconsistent.")
    _definitions, keys, output_by_key, page_by_key = _validate_graph(
        raw_graph, expected_outputs
    )

    def expected_source_identities(
        definition: Mapping[str, Any],
    ) -> list[dict[str, Any]]:
        result = []
        for reference in list(definition["arguments"][0]):
            key = (
                str(reference.get("document_uid") or ""),
                str(reference.get("object_name") or ""),
            )
            worker_reference = worker_by_key.get(key)
            if worker_reference is None:
                raise ValueError(
                    f"TechDraw definition uses unauthenticated object {key[1]!r}."
                )
            result.append(
                {
                    "document_uid": key[0],
                    "object_name": key[1],
                    "artifact_sha256": str(worker_reference["brep_sha256"]),
                    "source_type_id": str(worker_reference.get("type_id") or ""),
                    "source_kind": str(worker_reference.get("source_kind") or "shape"),
                    "source_revision": str(
                        worker_reference.get("source_revision") or ""
                    ),
                }
            )
        return result

    for output_index, expected in enumerate(expected_outputs):
        name = str(expected["name"])
        output_type = str(expected["type"])
        definition = definitions[name]
        properties = dict(definition["properties"])
        data = dict(by_name[name]["techdraw_data"])
        path = f"outputs.{name}.techdraw_data"
        if output_type == "view":
            projection_fields = {
                "schema",
                "native_type",
                "direction",
                "x_direction",
                "position_mm",
                "scale",
                "edge_count",
                "face_count",
                "vertex_count",
                "bounds_2d",
                "edge_classes",
                "edge_visibility",
                "source_indices",
                "centroid",
                "descriptors",
                "source_identities",
                "edges_artifact",
                "faces_artifact",
            }
            if set(data) != projection_fields | {
                "operation",
                "orientation",
                "hidden_lines",
                "smooth_lines",
            }:
                raise ValueError(f"{path} has malformed view fields.")
            base = {key: data[key] for key in projection_fields}
            detached, sanitized = _techdraw_projection_state(
                staging,
                base,
                expected_prefix=f"outputs/output-{output_index:03d}-view",
                path=path,
            )
            direction, x_direction = _VIEW_DIRECTIONS[str(properties["orientation"])]
            _mesh_values_match(
                sanitized["direction"], list(direction), path=f"{path}.direction"
            )
            _mesh_values_match(
                sanitized["x_direction"],
                list(x_direction),
                path=f"{path}.x_direction",
            )
            _mesh_values_match(
                sanitized["position_mm"],
                [float(properties["x_mm"]), float(properties["y_mm"])],
                path=f"{path}.position_mm",
            )
            if (
                str(data["orientation"]) != str(properties["orientation"])
                or bool(data["hidden_lines"]) is not bool(properties["hidden_lines"])
                or bool(data["smooth_lines"]) is not bool(properties["smooth_lines"])
                or sanitized["source_identities"]
                != expected_source_identities(definition)
            ):
                raise ValueError(f"{path} disagrees with the declared view.")
            by_name[name]["detached_projection"] = detached
            by_name[name]["techdraw_data"] = {
                **sanitized,
                "operation": "view",
                "orientation": str(data["orientation"]),
                "hidden_lines": bool(data["hidden_lines"]),
                "smooth_lines": bool(data["smooth_lines"]),
            }
        elif output_type == "projection":
            fields = {
                "schema",
                "operation",
                "native_type",
                "convention",
                "position_mm",
                "scale",
                "spacing_mm",
                "directions",
                "children",
                "source_identities",
            }
            if set(data) != fields or data.get("schema") != VALIDATION_SCHEMA:
                raise ValueError(f"{path} has malformed projection-group fields.")
            directions = [str(value) for value in list(properties["directions"])]
            children = data.get("children")
            if (
                data.get("directions") != directions
                or not isinstance(children, dict)
                or list(children) != directions
                or data.get("convention") != properties["convention"]
                or data.get("source_identities")
                != expected_source_identities(definition)
            ):
                raise ValueError(
                    f"{path} disagrees with the declared projection group."
                )
            _mesh_values_match(
                data["position_mm"],
                [float(properties["x_mm"]), float(properties["y_mm"])],
                path=f"{path}.position_mm",
            )
            _mesh_values_match(
                data["spacing_mm"],
                [
                    float(properties["spacing_x_mm"]),
                    float(properties["spacing_y_mm"]),
                ],
                path=f"{path}.spacing_mm",
            )
            detached_children = {}
            sanitized_children = {}
            for direction in directions:
                detached, sanitized = _techdraw_projection_state(
                    staging,
                    children[direction],
                    expected_prefix=(
                        f"outputs/output-{output_index:03d}-projection-{direction}"
                    ),
                    path=f"{path}.children.{direction}",
                )
                if sanitized["source_identities"] != expected_source_identities(
                    definition
                ):
                    raise ValueError(
                        f"{path}.children.{direction} changed source identities."
                    )
                detached_children[direction] = detached
                sanitized_children[direction] = sanitized
            data["children"] = sanitized_children
            by_name[name]["detached_projection_children"] = detached_children
            by_name[name]["techdraw_data"] = data
        elif output_type == "dimension":
            fields = {
                "schema",
                "native_type",
                "vectors",
                "scalars",
                "flags",
                "raw_value",
                "display_text",
                "references",
                "native_state",
                "operation",
                "kind",
                "measure",
                "source_output",
                "projection_direction",
                "position_mm",
                "format_spec",
                "over_tolerance",
                "under_tolerance",
                "show_units",
            }
            if set(data) != fields or data.get("schema") != DIMENSION_SCHEMA:
                raise ValueError(f"{path} has malformed dimension fields.")
            vectors = [
                _techdraw_finite_vector(value, path=f"{path}.vectors[{index}]")
                for index, value in enumerate(list(data.get("vectors") or []))
            ]
            scalars = data.get("scalars")
            flags = data.get("flags")
            references = data.get("references")
            if (
                len(vectors) != 18
                or not isinstance(scalars, list)
                or len(scalars) != 3
                or any(
                    isinstance(value, bool)
                    or not isinstance(value, (int, float))
                    or not math.isfinite(float(value))
                    for value in scalars
                )
                or not isinstance(flags, list)
                or len(flags) != 4
                or any(type(value) is not bool for value in flags)
                or not isinstance(references, list)
                or [item.get("subelement") for item in references]
                != list(properties["references"])
                or not references
                or len({str(item.get("view") or "") for item in references}) != 1
                or not str(references[0].get("view") or "")
                or {"Invalid", "Error"} & set(data.get("native_state") or [])
            ):
                raise ValueError(f"{path} has inconsistent native dimension state.")
            source_key = _definition_key(definition["arguments"][0])
            source_output = output_by_key[source_key][0]
            if (
                data.get("kind") != definition["arguments"][1]
                or data.get("measure") != properties["measure"]
                or data.get("source_output") != source_output
                or data.get("projection_direction")
                != properties["projection_direction"]
                or type(data.get("show_units")) is not bool
                or data["show_units"] is not properties["show_units"]
                or not isinstance(data.get("display_text"), str)
                or isinstance(data.get("raw_value"), bool)
                or not isinstance(data.get("raw_value"), (int, float))
                or not math.isfinite(float(data["raw_value"]))
            ):
                raise ValueError(f"{path} disagrees with the dimension definition.")
            import FreeCAD as App

            by_name[name]["detached_dimension"] = {
                "vectors": [App.Vector(*value) for value in vectors],
                "scalars": [float(value) for value in scalars],
                "flags": list(flags),
            }
        elif output_type == "template":
            fields = {
                "schema",
                "operation",
                "native_type",
                "sheet_size",
                "width_mm",
                "height_mm",
                "orientation",
                "editable_texts",
            }
            width, height, orientation = _sheet_geometry(str(properties["sheet_size"]))
            if set(data) != fields or data.get("schema") != VALIDATION_SCHEMA:
                raise ValueError(f"{path} has malformed template fields.")
            _mesh_values_match(
                data,
                {
                    "schema": VALIDATION_SCHEMA,
                    "operation": "template",
                    "native_type": "TechDraw::DrawTemplate",
                    "sheet_size": str(properties["sheet_size"]),
                    "width_mm": width,
                    "height_mm": height,
                    "orientation": orientation,
                    "editable_texts": dict(properties["editable_texts"]),
                },
                path=path,
            )
        elif output_type == "annotation":
            fields = {
                "schema",
                "operation",
                "native_type",
                "text",
                "position_mm",
                "text_size_mm",
                "alignment",
                "native_state",
            }
            if set(data) != fields or data.get("schema") != VALIDATION_SCHEMA:
                raise ValueError(f"{path} has malformed annotation fields.")
            if (
                data.get("text") != list(definition["arguments"][0])
                or data.get("alignment") != properties["alignment"]
                or {"Invalid", "Error"} & set(data.get("native_state") or [])
            ):
                raise ValueError(f"{path} disagrees with the annotation definition.")
            _mesh_values_match(
                data["position_mm"],
                [float(properties["x_mm"]), float(properties["y_mm"])],
                path=f"{path}.position_mm",
            )
        else:
            fields = {
                "schema",
                "operation",
                "native_type",
                "template_output",
                "content_outputs",
                "native_template",
                "native_members",
                "convention",
                "scale",
                "keep_updated",
            }
            if set(data) != fields or data.get("schema") != VALIDATION_SCHEMA:
                raise ValueError(f"{path} has malformed page fields.")
            template_output = output_by_key[
                _definition_key(definition["arguments"][0])
            ][0]
            content_outputs = [
                output_by_key[_definition_key(item)][0]
                for item in definition["arguments"][1]
            ]
            if (
                data.get("template_output") != template_output
                or data.get("content_outputs") != content_outputs
                or not isinstance(data.get("native_members"), list)
                or len(data["native_members"]) != len(content_outputs)
                or len(set(data["native_members"])) != len(content_outputs)
                or not str(data.get("native_template") or "")
                or data.get("convention") != properties["convention"]
                or data.get("keep_updated") is not True
            ):
                raise ValueError(f"{path} disagrees with the exact page graph.")

    if set(page_by_key.values()) != {
        str(item["name"]) for item in expected_outputs if item["type"] == "page"
    }:
        raise ValueError("The TechDraw graph contains an empty or unowned page.")
    return dict(validation)


def _validated_partdesign_history_reference(
    value: Any,
    *,
    object_names: set[str],
    external_references: Mapping[tuple[str, str], Mapping[str, Any]],
    path: str,
) -> dict[str, Any] | None:
    if value is None:
        return None
    if not isinstance(value, Mapping):
        raise ValueError(f"{path} must be an object or null.")
    scope = str(value.get("scope") or "")
    if scope in {"body", "origin"}:
        if set(value) != {"scope"}:
            raise ValueError(f"{path} has unexpected {scope} reference fields.")
        return {"scope": scope}
    if scope == "origin_feature":
        if set(value) != {"scope", "index", "role"}:
            raise ValueError(f"{path} has malformed origin-feature fields.")
        index = value.get("index")
        if (
            isinstance(index, bool)
            or not isinstance(index, int)
            or not 0 <= index <= 31
        ):
            raise ValueError(f"{path}.index is invalid.")
        role = str(value.get("role") or "")
        if not role or len(role) > 128:
            raise ValueError(f"{path}.role is invalid.")
        return {"scope": scope, "index": index, "role": role}
    if scope == "history":
        if set(value) != {"scope", "name"}:
            raise ValueError(f"{path} has malformed history-reference fields.")
        name = str(value.get("name") or "")
        if name not in object_names:
            raise ValueError(f"{path} refers to unknown history object {name!r}.")
        return {"scope": scope, "name": name}
    if scope == "external_reference":
        if set(value) != {
            "scope",
            "document_uid",
            "object_name",
            "selection",
        }:
            raise ValueError(f"{path} has malformed external-reference fields.")
        document_uid = str(value.get("document_uid") or "")
        object_name = str(value.get("object_name") or "")
        reference = external_references.get((document_uid, object_name))
        if reference is None:
            raise ValueError(
                f"{path} was not authenticated as a prepared input reference."
            )
        selection = value.get("selection")
        if not isinstance(selection, Mapping):
            raise ValueError(f"{path}.selection must be an object.")
        selection_type = str(selection.get("type") or "")
        if selection_type == "subelements":
            if set(selection) != {"type", "subelements"} or bool(
                reference.get("transient_topology")
            ):
                raise ValueError(
                    f"{path}.selection is not a stable subelement contract."
                )
            subelements = selection.get("subelements")
            if not isinstance(subelements, list) or not 1 <= len(subelements) <= 4:
                raise ValueError(f"{path}.selection.subelements is invalid.")
        elif selection_type == "published_interface":
            if set(selection) != {"type", "interface_name"}:
                raise ValueError(f"{path}.selection has malformed interface fields.")
            interfaces = reference.get("published_interfaces")
            if (
                not isinstance(interfaces, Mapping)
                or str(selection.get("interface_name") or "") not in interfaces
            ):
                raise ValueError(f"{path}.selection names an unavailable interface.")
        else:
            raise ValueError(
                f"{path}.selection has unsupported type {selection_type!r}."
            )
        return {
            "scope": scope,
            "document_uid": document_uid,
            "object_name": object_name,
            "selection": dict(selection),
        }
    raise ValueError(f"{path} has unsupported reference scope {scope!r}.")


def _validated_partdesign_history_subelements(
    value: Any,
    *,
    object_names: set[str],
    external_references: Mapping[tuple[str, str], Mapping[str, Any]],
    path: str,
) -> dict[str, Any]:
    if not isinstance(value, Mapping) or set(value) != {
        "target",
        "subelements",
    }:
        raise ValueError(f"{path} must contain target and subelements.")
    raw_subelements = value.get("subelements")
    if not isinstance(raw_subelements, list) or len(raw_subelements) > 256:
        raise ValueError(f"{path}.subelements is invalid.")
    subelements = [str(item) for item in raw_subelements]
    if any(len(item) > 1024 for item in subelements):
        raise ValueError(f"{path}.subelements contains an oversized name.")
    return {
        "target": _validated_partdesign_history_reference(
            value.get("target"),
            object_names=object_names,
            external_references=external_references,
            path=f"{path}.target",
        ),
        "subelements": subelements,
    }


def _validated_partdesign_history_links(
    value: Any,
    *,
    object_names: set[str],
    external_references: Mapping[tuple[str, str], Mapping[str, Any]],
    path: str,
) -> dict[str, Any]:
    if not isinstance(value, Mapping) or len(value) > 512:
        raise ValueError(f"{path} must be a bounded object.")
    result: dict[str, Any] = {}
    for raw_name, raw_specification in value.items():
        name = str(raw_name)
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name):
            raise ValueError(f"{path} has invalid property name {name!r}.")
        if not isinstance(raw_specification, Mapping) or set(raw_specification) != {
            "kind",
            "read_only",
            "value",
        }:
            raise ValueError(f"{path}.{name} has malformed fields.")
        kind = str(raw_specification.get("kind") or "")
        read_only = raw_specification.get("read_only")
        if not isinstance(read_only, bool):
            raise ValueError(f"{path}.{name}.read_only must be boolean.")
        raw = raw_specification.get("value")
        if kind == "link":
            clean = _validated_partdesign_history_reference(
                raw,
                object_names=object_names,
                external_references=external_references,
                path=f"{path}.{name}.value",
            )
        elif kind == "link_list":
            if not isinstance(raw, list) or len(raw) > 4096:
                raise ValueError(f"{path}.{name}.value is invalid.")
            clean = [
                _validated_partdesign_history_reference(
                    item,
                    object_names=object_names,
                    external_references=external_references,
                    path=f"{path}.{name}.value[{index}]",
                )
                for index, item in enumerate(raw)
            ]
        elif kind == "link_sub":
            clean = (
                None
                if raw is None
                else _validated_partdesign_history_subelements(
                    raw,
                    object_names=object_names,
                    external_references=external_references,
                    path=f"{path}.{name}.value",
                )
            )
        elif kind == "link_sub_list":
            if not isinstance(raw, list) or len(raw) > 4096:
                raise ValueError(f"{path}.{name}.value is invalid.")
            clean = [
                _validated_partdesign_history_subelements(
                    item,
                    object_names=object_names,
                    external_references=external_references,
                    path=f"{path}.{name}.value[{index}]",
                )
                for index, item in enumerate(raw)
            ]
        else:
            raise ValueError(f"{path}.{name} has unsupported link kind {kind!r}.")
        result[name] = {
            "kind": kind,
            "read_only": read_only,
            "value": clean,
        }
    return result


def _validate_partdesign_native_history(
    prepared: Mapping[str, Any],
    execution: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Load the worker's native Body snapshots before entering the document thread."""

    metadata = execution.get("partdesign_native_history")
    if metadata is None:
        # Additive compatibility for attempts made by a pre-history worker.
        return None
    expected_fields = {
        "schema",
        "artifact_path",
        "artifact_sha256",
        "artifact_bytes",
        "outputs",
    }
    if not isinstance(metadata, Mapping) or set(metadata) != expected_fields:
        raise ValueError("Part Design native-history metadata is malformed.")
    if metadata.get("schema") != _PARTDESIGN_NATIVE_HISTORY_SCHEMA:
        raise ValueError("Part Design native-history schema is unsupported.")
    expected_names = [
        str(item["name"])
        for item in list(prepared["expected_outputs"])
        if str(item.get("type") or "") != "component_link"
    ]
    if metadata.get("outputs") != expected_names:
        raise ValueError("Part Design native history changed output identity.")

    staging = Path(str(prepared["staging"])).resolve()
    raw_relative = Path(str(metadata.get("artifact_path") or ""))
    if raw_relative.is_absolute():
        raise ValueError("Part Design native-history path must be relative.")
    artifact = (staging / raw_relative).resolve()
    if staging not in artifact.parents or not artifact.is_file():
        raise ValueError("Part Design native-history artifact is missing.")
    artifact_size = artifact.stat().st_size
    reported_size = metadata.get("artifact_bytes")
    if (
        isinstance(reported_size, bool)
        or not isinstance(reported_size, int)
        or reported_size != artifact_size
        or not 0 < artifact_size <= _MAX_PARTDESIGN_NATIVE_HISTORY_BYTES
    ):
        raise ValueError("Part Design native-history artifact size is invalid.")
    encoded = artifact.read_bytes()
    digest = hashlib.sha256(encoded).hexdigest()
    if (
        not re.fullmatch(r"[0-9a-f]{64}", str(metadata.get("artifact_sha256") or ""))
        or digest != metadata["artifact_sha256"]
    ):
        raise ValueError("Part Design native-history artifact digest changed.")
    try:
        payload = json.loads(encoded.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError(
            f"Part Design native-history artifact is invalid JSON: {exc}"
        ) from exc
    if (
        not isinstance(payload, Mapping)
        or set(payload) != {"schema", "outputs"}
        or payload.get("schema") != _PARTDESIGN_NATIVE_HISTORY_SCHEMA
        or not isinstance(payload.get("outputs"), list)
    ):
        raise ValueError("Part Design native-history payload is malformed.")
    histories = list(payload["outputs"])
    if len(histories) != len(expected_names) or any(
        not isinstance(item, Mapping) for item in histories
    ):
        raise ValueError("Part Design native-history outputs are malformed.")
    if [str(item.get("output_name") or "") for item in histories] != expected_names:
        raise ValueError("Part Design native-history payload changed output order.")

    clean_histories: list[dict[str, Any]] = []
    external_references = {
        (
            str(item.get("document_uid") or ""),
            str(item.get("object_name") or ""),
        ): item
        for item in list(prepared.get("resolved_references") or [])
        if isinstance(item, Mapping)
    }
    body_names: set[str] = set()
    document_object_names: set[str] = set()
    total_objects = 0
    total_content_bytes = 0
    for history_index, history in enumerate(histories):
        path = f"partdesign_native_history.outputs[{history_index}]"
        if not isinstance(history, Mapping) or set(history) != {
            "output_name",
            "body_name",
            "body_label",
            "representation",
            "tip_name",
            "objects",
        }:
            raise ValueError(f"{path} has malformed fields.")
        body_name = str(history.get("body_name") or "")
        if (
            not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", body_name)
            or body_name in body_names
            or body_name in document_object_names
        ):
            raise ValueError(f"{path}.body_name is invalid or duplicated.")
        body_names.add(body_name)
        document_object_names.add(body_name)
        body_label = str(history.get("body_label") or "")
        if not body_label or len(body_label) > 4096:
            raise ValueError(f"{path}.body_label is invalid.")
        representation = str(history.get("representation") or "")
        if representation not in {"body", "publish"}:
            raise ValueError(f"{path}.representation is invalid.")
        raw_objects = history.get("objects")
        if not isinstance(raw_objects, list):
            raise ValueError(f"{path}.objects must be an array.")
        total_objects += len(raw_objects)
        if total_objects > _MAX_PARTDESIGN_NATIVE_HISTORY_OBJECTS:
            raise ValueError("Part Design native history contains too many objects.")

        if any(not isinstance(item, Mapping) for item in raw_objects):
            raise ValueError(f"{path}.objects contains a malformed entry.")
        names = [str(item.get("name") or "") for item in raw_objects]
        object_names = set(names)
        if (
            len(object_names) != len(names)
            or bool(document_object_names.intersection(object_names))
            or any(not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name) for name in names)
        ):
            raise ValueError(f"{path}.objects has invalid or duplicate names.")
        document_object_names.update(object_names)
        tip_name = str(history.get("tip_name") or "")
        if tip_name and tip_name not in object_names:
            raise ValueError(f"{path}.tip_name is not a history object.")

        clean_objects = []
        for object_index, item in enumerate(raw_objects):
            object_path = f"{path}.objects[{object_index}]"
            if not isinstance(item, Mapping) or set(item) != {
                "name",
                "label",
                "type_id",
                "content",
                "content_sha256",
                "links",
                "visible",
            }:
                raise ValueError(f"{object_path} has malformed fields.")
            type_id = str(item.get("type_id") or "")
            if type_id not in _PARTDESIGN_NATIVE_HISTORY_TYPES:
                raise ValueError(
                    f"{object_path}.type_id {type_id!r} is not a native Body object."
                )
            label = str(item.get("label") or "")
            if len(label) > 4096:
                raise ValueError(f"{object_path}.label is oversized.")
            raw_content = item.get("content")
            if not isinstance(raw_content, str):
                raise ValueError(f"{object_path}.content must be base64 text.")
            try:
                content = base64.b64decode(raw_content, validate=True)
            except (binascii.Error, ValueError) as exc:
                raise ValueError(f"{object_path}.content is invalid base64.") from exc
            total_content_bytes += len(content)
            if (
                not content
                or total_content_bytes > _MAX_PARTDESIGN_NATIVE_HISTORY_BYTES
                or hashlib.sha256(content).hexdigest()
                != str(item.get("content_sha256") or "")
            ):
                raise ValueError(
                    f"{object_path}.content failed bounded digest validation."
                )
            if not isinstance(item.get("visible"), bool):
                raise ValueError(f"{object_path}.visible must be boolean.")
            clean_objects.append(
                {
                    "name": names[object_index],
                    "label": label,
                    "type_id": type_id,
                    "content": content,
                    "links": _validated_partdesign_history_links(
                        item.get("links"),
                        object_names=object_names,
                        external_references=external_references,
                        path=f"{object_path}.links",
                    ),
                    "visible": bool(item["visible"]),
                }
            )
        clean_histories.append(
            {
                "output_name": expected_names[history_index],
                "body_name": body_name,
                "body_label": body_label,
                "representation": representation,
                "tip_name": tip_name,
                "objects": clean_objects,
            }
        )
    return {
        "schema": _PARTDESIGN_NATIVE_HISTORY_SCHEMA,
        "artifact_sha256": digest,
        "artifact_bytes": artifact_size,
        "outputs": clean_histories,
    }


def validate_candidate(
    prepared: Mapping[str, Any], execution: Mapping[str, Any]
) -> dict[str, Any]:
    """Import and validate detached worker values off the document thread."""

    if execution.get("ok") is not True:
        raise DomainRuntimeFailure(dict(execution))
    pack: contracts.VibeScriptWorkbenchPack = prepared["pack"]
    if (
        execution.get("schema") != WORKER_SCHEMA
        or execution.get("domain") != pack.domain
    ):
        raise ValueError(
            "The worker result does not match the prepared domain contract."
        )
    outputs = execution.get("outputs")
    expected = list(prepared["expected_outputs"])
    if not isinstance(outputs, list) or [item.get("name") for item in outputs] != [
        item["name"] for item in expected
    ]:
        raise ValueError(
            "Worker outputs do not exactly match the declared output order."
        )
    staging = Path(str(prepared["staging"])).resolve()
    validated: list[dict[str, Any]] = []
    partdesign_material_resolver = None
    if pack.domain == "partdesign":
        from vibescript_partdesign_worker import PartDesignMaterialResolver

        partdesign_material_resolver = PartDesignMaterialResolver()
    for declaration, raw in zip(expected, outputs):
        if not isinstance(raw, dict) or raw.get("type") != declaration["type"]:
            raise ValueError(f"Output {declaration['name']!r} has the wrong type.")
        item = dict(raw)
        definition = item.get("definition")
        _validate_definition_value(
            definition, prepared, f"outputs.{declaration['name']}.definition"
        )
        operation_diagnostics = item.get("operation_diagnostics")
        if operation_diagnostics is not None:
            if not isinstance(operation_diagnostics, dict):
                raise ValueError(
                    f"Output {declaration['name']!r} operation diagnostics must be an object."
                )
            _validate_definition_value(
                operation_diagnostics,
                prepared,
                f"outputs.{declaration['name']}.operation_diagnostics",
            )
        encoded = json.dumps(
            definition,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
        if len(encoded) > _STRUCTURED_DEFINITION_LIMIT:
            raise ValueError(f"Output {declaration['name']!r} definition is too large.")
        output_type = str(item["type"])
        if item.get("artifact_kind") == "brep":
            import Part

            path = (staging / str(item.get("artifact_path") or "")).resolve()
            if staging not in path.parents or not path.is_file():
                raise ValueError(f"BREP output {declaration['name']!r} is missing.")
            shape = Part.Shape()
            shape.importBrep(str(path))
            if shape.isNull() or not shape.isValid():
                raise ValueError(f"BREP output {declaration['name']!r} is invalid.")
            reported_facts = dict(item.get("facts") or {})
            detail_limit = int(reported_facts.get("subelement_detail_limit", -1))
            if not 0 <= detail_limit <= 256:
                raise ValueError(
                    f"BREP output {declaration['name']!r} reported an invalid topology "
                    "detail limit."
                )
            facts = _detached_shape_facts(shape, max_subelements=detail_limit)
            for key in ("solids", "shells", "faces", "wires", "edges", "vertices"):
                if int(reported_facts.get(key, -1)) != int(facts[key]):
                    raise ValueError(
                        f"BREP output {declaration['name']!r} changed topology during "
                        f"artifact transfer ({key}: worker={reported_facts.get(key)!r}, "
                        f"detached={facts[key]!r})."
                    )
            facts["artifact_shape_type"] = facts["shape_type"]
            facts["shape_type"] = str(
                reported_facts.get("shape_type") or facts["shape_type"]
            )
            if output_type in _BREP_OUTPUT_TYPES and pack.domain != "draft":
                _validate_shape_class(output_type, facts)
            if pack.domain == "partdesign":
                data = item.get("partdesign_data")
                if not isinstance(data, dict):
                    raise ValueError(
                        f"Part Design output {declaration['name']!r} has no native "
                        "Body/feature validation evidence."
                    )
                if str(data.get("brep_sha256") or "") != _sha256_file(path):
                    raise ValueError(
                        f"Part Design output {declaration['name']!r} BREP digest changed."
                    )
                history = data.get("feature_history")
                sketches = data.get("sketches")
                interfaces = data.get("interfaces")
                feature_count = data.get("feature_count")
                if (
                    not isinstance(history, list)
                    or isinstance(feature_count, bool)
                    or not isinstance(feature_count, int)
                    or feature_count < 0
                    or feature_count != len(history)
                    or not isinstance(sketches, list)
                    or not isinstance(interfaces, dict)
                    or any(
                        not isinstance(sketch, dict)
                        or int(sketch.get("solver_code") or 0) != 0
                        or sketch.get("conflicting_constraints")
                        or sketch.get("redundant_constraints")
                        or sketch.get("malformed_constraints")
                        for sketch in sketches
                    )
                ):
                    raise ValueError(
                        f"Part Design output {declaration['name']!r} has malformed "
                        "native feature or sketch evidence."
                    )
                assert partdesign_material_resolver is not None
                expected_presentation, native_material = (
                    partdesign_material_resolver.resolve(
                        definition,
                        output_name=str(declaration["name"]),
                    )
                )
                if data.get("presentation") != expected_presentation:
                    raise ValueError(
                        f"Part Design output {declaration['name']!r} Material/"
                        "appearance evidence differs between worker and host."
                    )
                item["partdesign_presentation"] = expected_presentation
                item["partdesign_native_material"] = native_material
            item["facts"] = facts
            item["detached_shape"] = shape
        elif output_type == "component_link" and pack.domain in {
            "partdesign",
            "robot",
        }:
            data = item.get("component_data")
            required_component_fields = {
                "schema",
                "source",
                "source_metadata",
                "placement",
                "placement_authored",
                "label",
            }
            if pack.domain == "partdesign":
                required_component_fields.add("interfaces")
            if not isinstance(data, Mapping) or set(data) != required_component_fields:
                raise ValueError(
                    f"Component output {declaration['name']!r} has malformed validation evidence."
                )
            if data.get("schema") != "vibecad-component-occurrence-v1":
                raise ValueError(
                    f"Component output {declaration['name']!r} has an unsupported schema."
                )
            source = data.get("source")
            placement = data.get("placement")
            if not isinstance(source, Mapping) or not isinstance(placement, Mapping):
                raise ValueError(
                    f"Component output {declaration['name']!r} is missing source or placement."
                )
            key = (
                str(source.get("document_uid") or ""),
                str(source.get("object_name") or ""),
            )
            authenticated = {
                (
                    str(reference.get("document_uid") or ""),
                    str(reference.get("object_name") or ""),
                )
                for reference in list(prepared.get("resolved_references") or [])
                if isinstance(reference, Mapping)
            }
            if not all(key) or key not in authenticated:
                raise ValueError(
                    f"Component output {declaration['name']!r} source was not authenticated."
                )
            if set(placement) != {"position", "rotation"} or len(
                list(placement.get("position") or [])
            ) != 3 or len(list(placement.get("rotation") or [])) != 4:
                raise ValueError(
                    f"Component output {declaration['name']!r} placement is malformed."
                )
            if type(data.get("placement_authored")) is not bool:
                raise ValueError(
                    f"Component output {declaration['name']!r} placement authorship is malformed."
                )
            if pack.domain == "partdesign" and not isinstance(
                data.get("interfaces"), Mapping
            ):
                raise ValueError(
                    f"Component output {declaration['name']!r} interfaces are malformed."
                )
        elif output_type == "mesh" and pack.domain != "fem":
            if item.get("artifact_kind") == "mesh_bms":
                path = (staging / str(item.get("artifact_path") or "")).resolve()
                if staging not in path.parents or not path.is_file():
                    raise ValueError(f"Mesh output {declaration['name']!r} is missing.")
                import Mesh

                detached_mesh = Mesh.Mesh(str(path))
                if int(detached_mesh.CountFacets) <= 0:
                    raise ValueError(
                        f"Mesh output {declaration['name']!r} contains no facets."
                    )
                item["artifact_sha256"] = hashlib.sha256(path.read_bytes()).hexdigest()
                item["detached_mesh"] = detached_mesh
            else:
                triangles = list((item.get("mesh") or {}).get("triangles") or [])
                if len(triangles) > 5_000_000:
                    raise ValueError("Mesh output exceeds five million facets.")
                clean_triangles = []
                for index, triangle in enumerate(triangles):
                    if not isinstance(triangle, (list, tuple)) or len(triangle) != 3:
                        raise ValueError(
                            f"Mesh triangle {index} must contain three vertices."
                        )
                    clean_triangles.append(
                        [
                            _finite_vector(vertex, f"triangles[{index}]")
                            for vertex in triangle
                        ]
                    )
                import Mesh

                item["detached_mesh"] = Mesh.Mesh(clean_triangles)
        elif output_type == "points":
            if item.get("artifact_kind") == "points_asc":
                from vibescript_points_worker import (
                    load_point_attribute_artifacts,
                    point_facts,
                )

                path = (staging / str(item.get("artifact_path") or "")).resolve()
                if staging not in path.parents or not path.is_file():
                    raise ValueError(
                        f"Points output {declaration['name']!r} artifact is missing."
                    )
                digest = _sha256_file(path)
                if digest != item.get("artifact_sha256"):
                    raise ValueError(
                        f"Points output {declaration['name']!r} SHA-256 changed."
                    )
                import Points

                detached_points = Points.Points(str(path))
                count = int(detached_points.CountPoints)
                if not 1 <= count <= _MAX_REFERENCE_POINTS:
                    raise ValueError(
                        f"Points output {declaration['name']!r} must contain "
                        f"1-{_MAX_REFERENCE_POINTS} points."
                    )
                attributes = load_point_attribute_artifacts(
                    staging,
                    item.get("attribute_artifacts", []),
                    point_count=count,
                    context=(f"outputs.{declaration['name']}.attribute_artifacts"),
                )
                reported_facts = item.get("facts")
                structured = (
                    reported_facts.get("structured")
                    if isinstance(reported_facts, Mapping)
                    else None
                )
                observed_facts = point_facts(
                    detached_points,
                    attributes=attributes,
                    structured=structured,
                )
                if not isinstance(reported_facts, Mapping) or not _point_facts_match(
                    reported_facts, observed_facts
                ):
                    raise ValueError(
                        f"Points output {declaration['name']!r} native facts changed "
                        "during artifact transfer."
                    )
                item["artifact_sha256"] = digest
                item["detached_points"] = detached_points
                item["point_attributes"] = attributes
                item["facts"] = observed_facts
            else:
                values = list(item.get("points") or [])
                if len(values) > 10_000_000:
                    raise ValueError("Point output exceeds ten million points.")
                import FreeCAD as App
                import Points

                clean_points = [_finite_vector(value, "point") for value in values]
                item["detached_points"] = Points.Points(
                    [App.Vector(*value) for value in clean_points]
                )
        elif pack.domain == "spreadsheet" and output_type == "sheet":
            if not isinstance(item.get("sheet_validation"), dict):
                raise ValueError(
                    f"Spreadsheet output {declaration['name']!r} has no native validation."
                )
        validated.append(item)
    partdesign_validation = None
    partdesign_native_history = None
    assembly_validation = None
    assembly_members: list[dict[str, Any]] = []
    sketch_validation = None
    draft_validation = None
    surface_validation = None
    spreadsheet_validation = None
    material_validation = None
    mesh_validation = None
    meshpart_validation = None
    points_validation = None
    reverse_engineering_validation = None
    inspection_validation = None
    robot_validation = None
    fem_validation = None
    cam_validation = None
    cam_publication_state = None
    techdraw_validation = None
    techdraw_publication_state = None
    if pack.domain == "partdesign":
        partdesign_validation = execution.get("partdesign_validation")
        if not isinstance(partdesign_validation, dict):
            raise ValueError("The Part Design worker returned no domain validation.")
        reported = partdesign_validation.get("outputs")
        if not isinstance(reported, list) or [
            item.get("name") for item in reported
        ] != [item["name"] for item in validated]:
            raise ValueError("Part Design domain validation changed output identity.")
        partdesign_native_history = _validate_partdesign_native_history(
            prepared,
            execution,
        )
    elif pack.domain == "assembly":
        raw_members = execution.get("assembly_members", [])
        if not isinstance(raw_members, list) or len(raw_members) > 8192:
            raise ValueError("The Assembly worker returned malformed owned members.")
        public_names = {str(item["name"]) for item in validated}
        member_names: set[str] = set()
        allowed_member_types = {"component_link", "joint", "motion"}
        allowed_fields = {
            "component_link": {
                "name",
                "type",
                "definition",
                "internal",
                "assembly_data",
                "solved_placement_matrix",
            },
            "joint": {
                "name",
                "type",
                "definition",
                "internal",
                "assembly_data",
                "connector_frames",
            },
            "motion": {
                "name",
                "type",
                "definition",
                "internal",
                "assembly_data",
            },
        }
        for index, raw_member in enumerate(raw_members):
            if not isinstance(raw_member, dict):
                raise ValueError(f"Assembly-owned member {index} is malformed.")
            member = dict(raw_member)
            name = str(member.get("name") or "")
            output_type = str(member.get("type") or "")
            if (
                not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,63}", name)
                or name in public_names
                or name in member_names
                or output_type not in allowed_member_types
                or member.get("internal") is not True
                or set(member) != allowed_fields[output_type]
            ):
                raise ValueError(
                    f"Assembly-owned member {index} has an invalid identity or shape."
                )
            definition = member.get("definition")
            _validate_definition_value(
                definition,
                prepared,
                f"assembly_members.{name}.definition",
            )
            if (
                not isinstance(definition, dict)
                or definition.get("domain") != "assembly"
                or definition.get("output_type") != output_type
            ):
                raise ValueError(
                    f"Assembly-owned member {name!r} has the wrong definition type."
                )
            encoded = json.dumps(
                definition,
                ensure_ascii=True,
                sort_keys=True,
                separators=(",", ":"),
                allow_nan=False,
            ).encode("utf-8")
            if len(encoded) > _STRUCTURED_DEFINITION_LIMIT:
                raise ValueError(
                    f"Assembly-owned member {name!r} definition is too large."
                )
            member_names.add(name)
            assembly_members.append(member)
        assembly_validation = _validate_assembly_execution(
            prepared,
            execution,
            [*validated, *assembly_members],
        )
    elif pack.domain == "sketcher":
        sketch_validation = _validate_sketcher_execution(
            prepared,
            execution,
            validated,
        )
    elif pack.domain == "draft":
        draft_validation = _validate_draft_execution(
            prepared,
            execution,
            validated,
        )
    elif pack.domain == "surface":
        surface_validation = _validate_surface_execution(
            prepared,
            execution,
            validated,
        )
    elif pack.domain == "spreadsheet":
        spreadsheet_validation = _validate_spreadsheet_execution(
            prepared,
            execution,
            validated,
        )
    elif pack.domain == "material":
        material_validation = _validate_material_execution(
            prepared,
            execution,
            validated,
        )
    elif pack.domain == "mesh":
        mesh_validation, meshpart_validation = _validate_mesh_workbench_execution(
            prepared,
            execution,
            validated,
        )
    elif pack.domain == "meshpart":
        meshpart_validation = _validate_meshpart_execution(
            prepared,
            execution,
            validated,
        )
    elif pack.domain == "points":
        points_validation = _validate_points_execution(
            prepared,
            execution,
            validated,
        )
    elif pack.domain == "reverse_engineering":
        reverse_engineering_validation = _validate_reverse_engineering_execution(
            prepared,
            execution,
            validated,
        )
    elif pack.domain == "inspection":
        inspection_validation = _validate_inspection_execution(
            prepared,
            execution,
            validated,
        )
    elif pack.domain == "robot":
        robot_validation = _validate_robot_execution(
            prepared,
            execution,
            validated,
        )
    elif pack.domain == "fem":
        fem_validation = _validate_fem_execution(
            prepared,
            execution,
            validated,
        )
    elif pack.domain == "cam":
        cam_validation = _validate_cam_execution(
            prepared,
            execution,
            validated,
        )
        from vibescript_cam_worker import cam_publication_references

        cam_publication_state = {
            "references": cam_publication_references(),
        }
    elif pack.domain == "techdraw":
        techdraw_validation = _validate_techdraw_execution(
            prepared,
            execution,
            validated,
        )
        techdraw_publication_state = {
            "references": [
                {
                    key: reference.get(key)
                    for key in (
                        "document_uid",
                        "object_name",
                        "label",
                        "type_id",
                        "shape_type",
                        "brep_sha256",
                        "source_kind",
                        "source_revision",
                    )
                }
                for reference in list(prepared.get("resolved_references") or [])
            ]
        }
    result = {
        "ok": True,
        "outputs": validated,
        "stdout": str(execution.get("stdout") or ""),
        "budget": dict(execution.get("budget") or {}),
        "process": dict(execution.get("process") or {}),
    }
    if partdesign_validation is not None:
        result["partdesign_validation"] = partdesign_validation
    if partdesign_native_history is not None:
        result["partdesign_native_history"] = partdesign_native_history
    if assembly_validation is not None:
        result["assembly_validation"] = assembly_validation
    if assembly_members:
        result["assembly_members"] = assembly_members
    if sketch_validation is not None:
        result["sketch_validation"] = sketch_validation
    if draft_validation is not None:
        result["draft_validation"] = draft_validation
    if surface_validation is not None:
        result["surface_validation"] = surface_validation
    if spreadsheet_validation is not None:
        result["spreadsheet_validation"] = spreadsheet_validation
    if material_validation is not None:
        result["material_validation"] = material_validation
    if mesh_validation is not None:
        result["mesh_validation"] = mesh_validation
    if meshpart_validation is not None:
        result["meshpart_validation"] = meshpart_validation
    if points_validation is not None:
        result["points_validation"] = points_validation
    if reverse_engineering_validation is not None:
        result["reverse_engineering_validation"] = reverse_engineering_validation
    if inspection_validation is not None:
        result["inspection_validation"] = inspection_validation
    if robot_validation is not None:
        result["robot_validation"] = robot_validation
    if fem_validation is not None:
        result["fem_validation"] = fem_validation
    if cam_validation is not None:
        result["cam_validation"] = cam_validation
    if cam_publication_state is not None:
        result["cam_publication_state"] = cam_publication_state
    if techdraw_validation is not None:
        result["techdraw_validation"] = techdraw_validation
    if techdraw_publication_state is not None:
        result["techdraw_publication_state"] = techdraw_publication_state
    return result


def _attempt_destination(prepared: Mapping[str, Any]) -> Path:
    return (
        Path(str(prepared["program_directory"]))
        / "attempts"
        / str(prepared["attempt_id"])
    )


def retain_candidate(
    prepared: Mapping[str, Any],
    *,
    status: str,
    failure: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Move staging into the durable attempt history and update working state."""

    staging = Path(str(prepared["staging"]))
    destination = _attempt_destination(prepared)
    destination.parent.mkdir(parents=True, exist_ok=True)
    if staging.exists() and not destination.exists():
        staging.replace(destination)
    manifest_path = Path(str(prepared["program_directory"])) / "program.json"
    manifest = _read_json(manifest_path, "VibeScript program manifest")
    candidate = dict(manifest.get("latest_candidate") or {})
    candidate.update(
        {
            "attempt_id": str(prepared["attempt_id"]),
            "revision": str(prepared["revision"]),
            "status": status,
            "completed_at": time.time(),
            "artifact_directory": str(destination),
        }
    )
    if failure:
        candidate["failure"] = {
            key: failure.get(key)
            for key in ("failure_code", "failure_stage", "error", "observed")
            if failure.get(key) not in (None, "", {}, [])
        }
    manifest["latest_candidate"] = candidate
    manifest["updated_at"] = time.time()
    _atomic_json(manifest_path, manifest)
    return {"attempt_directory": str(destination), "manifest": manifest}


def accept_candidate(
    prepared: Mapping[str, Any],
    publication: Mapping[str, Any],
) -> dict[str, Any]:
    manifest_path = Path(str(prepared["program_directory"])) / "program.json"
    manifest = _read_json(manifest_path, "VibeScript program manifest")
    candidate = dict(manifest.get("latest_candidate") or {})
    candidate["status"] = "accepted"
    candidate["accepted_at"] = time.time()
    manifest["latest_candidate"] = candidate
    manifest["accepted_revision"] = str(prepared["revision"])
    manifest["accepted_contract"] = {
        key: prepared[key]
        for key in ("source", "input_schema", "inputs", "expected_outputs", "revision")
    }
    if prepared.get("resolved_references"):
        manifest["accepted_contract"]["resolved_references"] = list(
            prepared["resolved_references"]
        )
        manifest["resolved_references"] = list(prepared["resolved_references"])
    else:
        manifest.pop("resolved_references", None)
    manifest["live_outputs"] = dict(publication.get("live_outputs") or {})
    manifest["updated_at"] = time.time()
    _atomic_json(manifest_path, manifest)
    domain = prepared["pack"].domain
    program_id = str(prepared["program_id"])
    revision = str(prepared["revision"])
    return {
        "ok": True,
        "program_id": program_id,
        "program_name": str(prepared["program_name"]),
        "domain": domain,
        "workbench": prepared["pack"].workbench,
        "working_revision": revision,
        "accepted_revision": revision,
        "outputs": list(publication.get("outputs") or []),
        "live_outputs": dict(publication.get("live_outputs") or {}),
        "attempt_directory": str(candidate.get("artifact_directory") or ""),
        "stdout": str(publication.get("stdout") or ""),
        "budget": dict(publication.get("budget") or {}),
        "model_state": {
            "status": "accepted",
            "accepted_is_current": True,
            "next_write_expected_revision": revision,
        },
    }


def describe_api(pack: contracts.VibeScriptWorkbenchPack) -> dict[str, Any]:
    adapter = contracts.get_domain_adapter(pack.domain)
    if adapter is None:
        return _failure(
            f"vibescript.{pack.domain}.describe_api",
            "DOMAIN_UNAVAILABLE",
            "surface",
            f"The {pack.title} domain adapter is unavailable.",
        )
    return adapter.describe_api()


def capture_inspection_state(
    service: Any, tool_name: str, program_id: str
) -> dict[str, Any]:
    captured = capture_operation_state(service, tool_name, {"program_id": program_id})
    clean = str(program_id or "").strip().lower()
    if not _PROGRAM_ID.fullmatch(clean):
        _raise(tool_name, "INVALID_PROGRAM_ID", "schema", "Invalid program_id.")
    captured["program_id"] = clean
    return captured


def capture_editor_inspection_state(
    service: Any, domain: str, program_id: str
) -> dict[str, Any]:
    """Capture the minimum live state required by the human source editor.

    Provider inspection intentionally captures the broader operation contract.
    The editor only needs one persisted manifest plus its stable live output
    identities, so it must not enumerate unrelated document objects or resolve
    input geometry merely to display source text.
    """

    clean_domain = str(domain or "").strip().lower()
    clean_program_id = str(program_id or "").strip().lower()
    tool_name = f"vibescript.{clean_domain}.inspect_program"
    if not _PROGRAM_ID.fullmatch(clean_program_id):
        _raise(tool_name, "INVALID_PROGRAM_ID", "schema", "Invalid program_id.")
    doc = service._active_document()
    if doc is None:
        _raise(tool_name, "NO_DOCUMENT", "precondition", "No active FreeCAD document.")
    pack = contracts.get_vibescript_pack(service.active_workbench_name())
    if pack is None or pack.domain != clean_domain:
        _raise(
            tool_name,
            "DOMAIN_SURFACE_CHANGED",
            "surface",
            "The active workbench no longer authorizes this editor domain.",
        )
    from VibeCADModelingSurface import resolve_service_surface

    resolution = resolve_service_surface(service, service.active_workbench_name())
    if (
        resolution.engine != "vibescript"
        or resolution.workbench != pack.workbench
        or resolution.domain != clean_domain
        or not resolution.available
    ):
        _raise(
            tool_name,
            "DOMAIN_SURFACE_CHANGED",
            "surface",
            "The active workbench no longer authorizes this editor API.",
            observed=resolution.summary(),
        )
    scope = service.project_scope_snapshot()
    document_program = contracts.capture_document_program_payload(
        doc,
        clean_domain,
        clean_program_id,
    )
    return {
        "tool_name": tool_name,
        "pack": pack,
        "program_id": clean_program_id,
        "project_root": str(scope.get("root") or ""),
        "live_programs": _live_programs(doc, clean_domain),
        "document_program": document_program,
    }


def capture_history_delete_state(
    service: Any,
    domain: str,
    program_id: str,
    expected_revision: str,
    reason: str,
) -> dict[str, Any]:
    """Capture one human History deletion independently of the active ribbon.

    History is document-global. Deleting its exact source operation must not
    become unavailable merely because the user switched from Model to another
    workbench after selecting it.
    """

    clean_domain = str(domain or "").strip().lower()
    clean_program_id = str(program_id or "").strip().lower()
    if not _PROGRAM_ID.fullmatch(clean_program_id):
        raise ValueError("A History VibeScript operation has an invalid program id.")
    packs = [
        pack
        for pack in contracts.VIBESCRIPT_WORKBENCH_PACKS.values()
        if pack.domain == clean_domain
    ]
    if len(packs) != 1:
        raise ValueError(
            f"No unique VibeScript domain is registered for {clean_domain!r}."
        )
    pack = packs[0]
    doc = service._active_document()
    if doc is None:
        raise RuntimeError("No active document is available for History deletion.")
    live_programs = _live_programs(doc, clean_domain)
    live = [
        item
        for item in live_programs
        if str(item.get("program_id") or "") == clean_program_id
    ]
    if len(live) != 1:
        raise RuntimeError(
            "The selected History operation does not resolve to one live "
            "VibeScript program."
        )
    revisions = list(live[0].get("revisions") or [])
    if len(revisions) != 1 or str(revisions[0]) != str(expected_revision or ""):
        raise RuntimeError(
            "The selected VibeScript program changed before History deletion."
        )
    scope = service.project_scope_snapshot()
    return {
        "tool_name": f"vibescript.{clean_domain}.delete_program",
        "operation": "delete_program",
        "arguments": {
            "program_id": clean_program_id,
            "expected_revision": str(expected_revision or ""),
            "reason": str(reason or ""),
        },
        "pack": pack,
        "project_root": str(scope.get("root") or ""),
        "project_id": str(scope.get("project_id") or ""),
        "document_name": str(getattr(doc, "Name", "") or ""),
        "document_uid": str(getattr(doc, "Uid", "") or ""),
        "document_revision": str(service.provider_document_revision()),
        "live_programs": live_programs,
        "document_program": contracts.capture_document_program_payload(
            doc,
            clean_domain,
            clean_program_id,
        ),
        "surface": {"history_lifecycle": True},
        "history_lifecycle": True,
    }


def complete_inspection(captured: Mapping[str, Any]) -> dict[str, Any]:
    pack: contracts.VibeScriptWorkbenchPack = captured["pack"]
    program_id = str(captured["program_id"])
    try:
        manifest = _load_captured_manifest(captured, pack, program_id)
    except Exception as exc:
        return _failure(
            str(captured["tool_name"]),
            "PROGRAM_NOT_FOUND",
            "precondition",
            str(exc),
            observed={"program_id": program_id},
        )
    live = next(
        (
            item
            for item in captured["live_programs"]
            if item["program_id"] == program_id
        ),
        None,
    )
    adapter = contracts.get_domain_adapter(pack.domain)
    assert adapter is not None
    inspected = adapter.inspect(dict(captured), manifest | {"live_state": live})
    document_program = captured.get("document_program")
    raw_draft = (
        str(document_program.get("editor_draft") or "")
        if isinstance(document_program, Mapping)
        else ""
    )
    if raw_draft and inspected.get("ok") is True:
        try:
            draft = contracts.decode_editor_draft(
                raw_draft,
                expected_program_id=program_id,
                expected_domain=pack.domain,
            )
        except Exception as exc:
            inspected["editor_draft_error"] = str(exc)
        else:
            program = inspected.get("program")
            if isinstance(program, dict):
                program["editor_draft"] = draft
    return inspected


def prepare_delete(captured: Mapping[str, Any]) -> dict[str, Any]:
    pack: contracts.VibeScriptWorkbenchPack = captured["pack"]
    arguments = dict(captured["arguments"])
    program_id = str(arguments.get("program_id") or "").strip().lower()
    try:
        manifest = _load_captured_manifest(
            captured,
            pack,
            program_id,
            hydrate_document_contract=True,
        )
    except Exception as exc:
        _raise(
            str(captured["tool_name"]),
            "PROGRAM_NOT_FOUND",
            "precondition",
            str(exc),
        )
    expected = str(arguments.get("expected_revision") or "")
    current = str(manifest.get("working_revision") or "")
    if expected != current:
        _raise(
            str(captured["tool_name"]),
            "STALE_PROGRAM_REVISION",
            "precondition",
            "The program changed after inspection.",
            requested={"expected_revision": expected},
            observed={"current_revision": current},
        )
    directory = _program_directory(captured["project_root"], pack.domain, program_id)
    trash = directory.parent / ".trash" / f"{program_id}-{uuid.uuid4().hex}"
    trash.parent.mkdir(parents=True, exist_ok=True)
    directory.replace(trash)
    return {
        **dict(captured),
        "program_id": program_id,
        "manifest": manifest,
        "program_directory": str(directory),
        "trash_directory": str(trash),
    }


def restore_prepared_delete(prepared: Mapping[str, Any]) -> None:
    trash = Path(str(prepared["trash_directory"]))
    original = Path(str(prepared["program_directory"]))
    if trash.exists() and not original.exists():
        trash.replace(original)


def _ignore_missing_artifact_cleanup_error(
    _function: Callable[..., Any],
    _path: str,
    exc_info: tuple[type[BaseException], BaseException, Any],
) -> None:
    error = exc_info[1]
    if isinstance(error, FileNotFoundError):
        return
    raise error.with_traceback(exc_info[2])


def _deleted_program_cleanup_path(trash: Path) -> str | Path:
    if os.name != "nt":
        return trash
    # Packaged Windows Python can report WinError 3 for descendants beyond
    # MAX_PATH unless recursive cleanup starts from an extended-length path.
    absolute = os.path.abspath(os.fspath(trash))
    if absolute.startswith("\\\\?\\"):
        return absolute
    if absolute.startswith("\\\\"):
        return f"\\\\?\\UNC\\{absolute[2:]}"
    return f"\\\\?\\{absolute}"


def _remove_deleted_program_artifacts(trash: Path) -> None:
    cleanup_path = _deleted_program_cleanup_path(trash)
    last_transient_error: OSError | None = None
    # A worker or filesystem scanner can still create a final cache entry
    # between rmtree's directory scan and its parent-directory removal.
    for attempt in range(5):
        try:
            shutil.rmtree(
                cleanup_path,
                onerror=_ignore_missing_artifact_cleanup_error,
            )
        except OSError as exc:
            retryable = isinstance(exc, FileNotFoundError) or (
                exc.errno == errno.ENOTEMPTY or getattr(exc, "winerror", None) == 145
            )
            if not retryable:
                raise
            if not os.path.exists(cleanup_path):
                return
            last_transient_error = exc
        else:
            if not os.path.exists(cleanup_path):
                return
            last_transient_error = OSError(
                errno.ENOTEMPTY,
                "Deleted-program artifacts remain after cleanup",
                trash,
            )
        if attempt < 4:
            time.sleep(0.05 * (attempt + 1))
    assert last_transient_error is not None
    raise last_transient_error


def finish_delete(
    prepared: Mapping[str, Any], publication: Mapping[str, Any]
) -> dict[str, Any]:
    trash = Path(str(prepared["trash_directory"]))
    _remove_deleted_program_artifacts(trash)
    deleted_objects = list(publication.get("deleted_objects") or [])
    return {
        "ok": True,
        "program_id": str(prepared["program_id"]),
        "domain": prepared["pack"].domain,
        "source_deleted": True,
        "deleted_objects": deleted_objects,
        "cad_objects_removed": len(deleted_objects),
        "reason": str(prepared["arguments"].get("reason") or ""),
        "artifacts_deleted": True,
    }


@dataclass
class DeclarativeDomainAdapter:
    pack: contracts.VibeScriptWorkbenchPack
    production_ready: bool = False

    def describe_api(self) -> dict[str, Any]:
        api = create_domain_api(
            self.pack.domain, self.pack.api_exports, self.pack.output_types
        )
        exports = []
        for name in api.exported_names:
            member = getattr(api, name)
            exports.append(
                {
                    "name": name,
                    "signature": str(inspect.signature(member)),
                    "description": str(inspect.getdoc(member) or ""),
                }
            )
        return {
            "ok": True,
            "domain": self.pack.domain,
            "workbench": self.pack.workbench,
            "program_schema": contracts.PROGRAM_SCHEMA,
            "runtime_exports": exports,
            "api_groups": contracts.api_groups(self.pack),
            "accepted_output_types": list(self.pack.output_types),
            "source_globals": ["doc", "inputs", "api"],
            "source_global_contracts": {
                "inputs": (
                    "Immutable values validated against this program's input_schema. "
                    "Stable document-reference inputs contain only authenticated identity."
                ),
                "api": (
                    "Immutable workbench API selected by the active ribbon. Read exact "
                    "callables with vibescript.read_api(names=[...])."
                ),
                "doc": {
                    "purpose": (
                        "Read-only names and labels in the isolated candidate document. "
                        "It does not expose Shapes, mutation, FreeCAD, or the live GUI document."
                    ),
                    "members": [
                        "doc.Name",
                        "doc.Objects",
                        "doc.getObject(exact_name)",
                        "object.Name",
                        "object.Label",
                        "object.TypeId",
                    ],
                },
            },
            "source_value_contract": {
                "type": "DomainValue",
                "purpose": (
                    "Every api call returns an immutable declarative graph value; it is not "
                    "live FreeCAD geometry and is evaluated only when reachable from result."
                ),
                "readable_fields": [
                    "domain",
                    "operation",
                    "output_type",
                    "arguments",
                    "properties",
                ],
                "output_type_rule": (
                    "Use output_type to distinguish profiles, Body features, standalone "
                    "topology, checks, materials, occurrences, and other domain values. "
                    "Pass only the exact types named by a callable signature or error."
                ),
                "identity_rule": (
                    "Bind a returned value once and reuse that exact variable downstream. "
                    "Recreating equivalent calls creates a different graph node."
                ),
            },
            "result_contract": (
                "Assign result to a dict whose keys exactly match expected_outputs "
                "in declared order and whose values come from this domain api."
            ),
            "instructions": self.pack.instructions,
            "model_operating_contract": {
                "context_first": (
                    "Use editable_sources and vibescript.read_source before editing code. "
                    "Use vibescript.read_api for exact signatures and "
                    "vibescript.read_geometry for exact native or imported shape facts. "
                    "vibescript.read_placement resolves planned frames. "
                    "Never invent IDs, revisions, or API calls."
                ),
                "mutation_selection": {
                    "edit_source": (
                        "Use for code edits. Include changed inputs, input_schema, or "
                        "expected_outputs in the same call."
                    ),
                    "set_inputs": (
                        "Use only for an RFC 7396 value patch while source, input_schema, "
                        "and expected_outputs stay unchanged."
                    ),
                    "reconfigure_program": (
                        "Alias: edit_source."
                    ),
                },
                "revision_rule": (
                    "Guard every mutation with the latest working_revision returned by a write "
                    "or vibescript.read_source. After a failed candidate this is the failed candidate "
                    "revision, not the still-live accepted_revision."
                ),
                "input_schema_templates": {
                    "no_inputs": {
                        "type": "object",
                        "properties": {},
                        "additionalProperties": False,
                    },
                    "stable_reference_property": {
                        "type": "object",
                        "x-vibecad-reference": True,
                        "properties": {
                            "document_uid": {"type": "string"},
                            "object_name": {"type": "string"},
                            "document_path": {"type": "string"},
                        },
                        "required": ["document_uid", "object_name"],
                        "additionalProperties": False,
                    },
                },
            },
        }

    def validate_source(self, source: str) -> None:
        contracts.validate_program_source(source)

    def execute_candidate(
        self,
        prepared: dict[str, Any],
        *,
        cancellation_check: Callable[[], bool] | None,
    ) -> dict[str, Any]:
        return execute_candidate(prepared, cancellation_check=cancellation_check)

    def validate_result(
        self, prepared: dict[str, Any], execution: dict[str, Any]
    ) -> dict[str, Any]:
        return validate_candidate(prepared, execution)

    def publish(
        self,
        service: Any,
        prepared: dict[str, Any],
        validated: dict[str, Any],
    ) -> dict[str, Any]:
        return publish_candidate(service, prepared, validated)

    def inspect(
        self, captured: dict[str, Any], contract: dict[str, Any]
    ) -> dict[str, Any]:
        program = {
            key: contract.get(key)
            for key in (
                "program_id",
                "domain",
                "workbench",
                "label",
                "source",
                "input_schema",
                "inputs",
                "expected_outputs",
                "working_revision",
                "accepted_revision",
                "accepted_contract",
                "resolved_references",
                "live_outputs",
                "latest_candidate",
                "artifact_directory",
                "imported_from_schema",
                "migration_required",
                "migration_reason",
                "migration_action",
                "live_state",
            )
            if contract.get(key) not in (None, "", [], {})
        }
        working_revision = str(contract.get("working_revision") or "")
        accepted_revision = str(contract.get("accepted_revision") or "")
        latest_candidate = contract.get("latest_candidate")
        candidate_status = (
            str(latest_candidate.get("status") or "")
            if isinstance(latest_candidate, Mapping)
            else ""
        )
        accepted_is_current = bool(
            working_revision
            and accepted_revision
            and working_revision == accepted_revision
            and candidate_status == "accepted"
        )
        migration_required = bool(contract.get("migration_required"))
        return {
            "ok": True,
            "program": program,
            "model_state": {
                "status": (
                    "reconfiguration_required"
                    if migration_required
                    else "accepted_current"
                    if accepted_is_current
                    else "working_candidate_not_accepted"
                ),
                "candidate_status": candidate_status,
                "accepted_is_current": accepted_is_current,
                "accepted_live_state_preserved": bool(accepted_revision),
                **({"migration_required": True} if migration_required else {}),
                "next_write_expected_revision": working_revision,
                "mutation_selection": {
                    "source_only": "vibescript.edit_source",
                    "input_values_only": f"vibescript.{self.pack.domain}.set_inputs",
                    "contract_or_outputs": "vibescript.edit_source",
                },
                "instruction": (
                    "Replace the complete program contract with vibescript.edit_source, "
                    "including input_schema, inputs, and expected_outputs in the same call. "
                    "The prior accepted live objects remain available until a valid v2 "
                    "candidate is accepted."
                    if migration_required
                    else "If this candidate is not accepted, use latest_candidate.failure and "
                    "the accepted contract as the repair baseline, then make the narrowest "
                    "guarded mutation using next_write_expected_revision."
                    if not accepted_is_current
                    else "The accepted contract is current; verify domain-specific live evidence."
                ),
            },
        }

    def delete(
        self, service: Any, captured: dict[str, Any], contract: dict[str, Any]
    ) -> dict[str, Any]:
        del contract
        return delete_live_program(service, captured)


