def install_builtin_adapters() -> None:
    for pack in contracts.VIBESCRIPT_WORKBENCH_PACKS.values():
        if contracts.get_domain_adapter(pack.domain) is not None:
            continue
        if pack.domain == "partdesign":
            adapter = PartDesignDomainAdapter(pack)
        elif pack.domain == "part":
            adapter = PartDomainAdapter(pack)
        elif pack.domain == "sketcher":
            adapter = SketcherDomainAdapter(pack)
        elif pack.domain == "draft":
            adapter = DraftDomainAdapter(pack)
        elif pack.domain == "surface":
            adapter = SurfaceDomainAdapter(pack)
        elif pack.domain == "spreadsheet":
            adapter = SpreadsheetDomainAdapter(pack)
        elif pack.domain == "material":
            adapter = MaterialDomainAdapter(pack)
        elif pack.domain == "mesh":
            adapter = MeshDomainAdapter(pack)
        elif pack.domain == "meshpart":
            adapter = MeshPartDomainAdapter(pack)
        elif pack.domain == "points":
            adapter = PointsDomainAdapter(pack)
        elif pack.domain == "reverse_engineering":
            adapter = ReverseEngineeringDomainAdapter(pack)
        elif pack.domain == "inspection":
            adapter = InspectionDomainAdapter(pack)
        elif pack.domain == "robot":
            adapter = RobotDomainAdapter(pack)
        elif pack.domain == "fem":
            adapter = FEMDomainAdapter(pack)
        elif pack.domain == "cam":
            adapter = CAMDomainAdapter(pack)
        elif pack.domain == "techdraw":
            adapter = TechDrawDomainAdapter(pack)
        elif pack.domain == "assembly":
            adapter = AssemblyDomainAdapter(pack)
        else:
            adapter = DeclarativeDomainAdapter(pack)
        contracts.register_domain_adapter(pack.domain, adapter)


